type SignupRequiredResult = {
  status: "signup_required";
  reason: "file_upload_requires_signup";
  signup_required: true;
  message: string;
};

type CliArgs = {
  positionals: string[];
  flags: Record<string, string | boolean>;
};

async function main(): Promise<void> {
  const parsed = parseArgs(process.argv.slice(2));
  const [command, subcommand, ...rest] = parsed.positionals;
  const accountGuardRequired = process.env.OPENMATES_ACCOUNT_GUARD === "required";
  if (accountGuardRequired && parsed.flags.help !== true) {
    assertTrustedAccountGuardEnvironment(parsed.flags);
    assertTrustedAccountCommandAllowed(command);
  }
  if (parsed.flags.profile !== undefined) {
    const profile = parsed.flags.profile;
    if (typeof profile !== "string" || !profile) throw new Error("--profile requires a profile name");
    // Validate before loading keys or session state. Never silently fall back.
    resolveStateDir({ profile, stateDir: "" });
    if (process.env.OPENMATES_STATE_DIR?.trim()) {
      throw new Error("--profile cannot be combined with OPENMATES_STATE_DIR");
    }
    process.env.OPENMATES_PROFILE = profile;
  }
  // Help, maintenance, and fresh pairing must remain reachable when a saved
  // keyring entry is unavailable. Keep protected commands strict.
  const sessionFree = parsed.flags.help === true
    || ["help", "version", "update", "upgrade", "login"].includes(command ?? "")
    || (!command && parsed.flags.version !== undefined);
  const client = OpenMatesClient.load({
    loadStoredSession: !sessionFree,
    apiUrl:
      typeof parsed.flags["api-url"] === "string"
        ? parsed.flags["api-url"]
        : undefined,
  });

  if (
    accountGuardRequired
    && parsed.flags.help !== true
    && shouldRequireTrustedAccountGuard(command)
  ) {
    await enforceTrustedAccount(client);
  }

  const redactor = new OutputRedactor();

  if (!command) {
    if (parsed.flags.version !== undefined) {
      handleCliVersion(parsed.flags);
      return;
    }
    if (parsed.flags.help === true) {
      printHelp();
      return;
    }
    if (defaultModeForStreams(process.stdin, process.stdout) === "quickstart") {
      printProgrammaticQuickstart();
      return;
    }
    const result = await runTui(client);
    if (result.action === "signup") {
      await handleSignup(client, parsed.flags);
    } else if (result.action === "restart") {
      const { spawn } = await import("node:child_process");
      process.exitCode = await new Promise<number>((resolve, reject) => {
        const child = spawn(process.execPath, [...process.execArgv, ...process.argv.slice(1)], { stdio: "inherit" });
        child.once("error", reject);
        child.once("exit", (code) => resolve(code ?? 1));
      });
    }
    return;
  }

  if (command === "help") {
    printHelp();
    return;
  }

  if (command === "version") {
    if (parsed.flags.help === true) {
      printVersionHelp();
      return;
    }
    handleCliVersion(parsed.flags);
    return;
  }

  // --help with a command shows that command's help, not the global one
  if (parsed.flags.help === true && !subcommand) {
    // e.g. `openmates chats --help` → show chats help
    if (command === "chat") {
      printGoalChatHelp();
      return;
    }
    if (command === "chats") {
      printChatsHelp();
      return;
    }
    if (command === "drafts") {
      printDraftsHelp();
      return;
    }
    if (command === "ideabucket") {
      printIdeaBucketHelp();
      return;
    }
    if (command === "apps") {
      printAppsHelp();
      return;
    }
    if (command === "settings") {
      printSettingsHelp(client);
      return;
    }
    if (command === "account") {
      printSettingsHelp(client, ["account"]);
      return;
    }
    if (command === "workflows") {
      printWorkflowsHelp();
      return;
    }
    if (command === "tasks") {
      printTasksHelp();
      return;
    }
    if (command === "plans") {
      printPlansHelp();
      return;
    }
    if (command === "projects") {
      printProjectsHelp();
      return;
    }
    if (command === "recovery") {
      console.log("Recovery commands: full-sync --project <id> --root <external-root>; validate --file <projection.yml>; restore --file <projection.yml> --dry-run|--confirm-restore.");
      return;
    }
    if (command === "teams") {
      printTeamsHelp();
      return;
    }
    if (command === "switch-to") {
      printSwitchToHelp();
      return;
    }
    if (command === "connected-accounts") {
      printConnectedAccountsHelp();
      return;
    }
    if (command === "finance") {
      printFinanceHelp();
      return;
    }
    if (command === "connect-account") {
      printConnectAccountHelp();
      return;
    }
    if (command === "learning-mode") {
      printLearningModeHelp();
      return;
    }
    if (command === "signup") {
      printSignupHelp();
      return;
    }
    if (command === "e2e") {
      printE2EHelp();
      return;
    }
    if (command === "mentions") {
      printMentionsHelp();
      return;
    }
    if (command === "embeds") {
      printEmbedsHelp();
      return;
    }
    if (command === "inspirations") {
      printInspirationsHelp();
      return;
    }
    if (command === "newchatsuggestions") {
      printNewChatSuggestionsHelp();
      return;
    }
    if (command === "server") {
      printServerHelp();
      return;
    }
    if (command === "update" || command === "upgrade") {
      printSelfUpdateHelp();
      return;
    }
    if (command === "version") {
      printVersionHelp();
      return;
    }
    if (command === "feedback") {
      printFeedbackHelp();
      return;
    }
    if (command === "wiki") {
      printWikiHelp();
      return;
    }
    if (command === "docs") {
      printDocsHelp();
      return;
    }
    if (command === "benchmark") {
      printBenchmarkHelp();
      return;
    }
    if (command === "remote-access") {
      printRemoteAccessHelp();
      return;
    }
    if (command === "connect-account") {
      printConnectAccountHelp();
      return;
    }
    if (command === "privacy") { process.stdout.write(PRIVACY_HELP); return; }
    printHelp();
    return;
  }

  if (command === "privacy") {
    let lastProgress = 0;
    const output = await runPrivacyCommand(parsed.flags.help ? "help" : subcommand, {
      yes: parsed.flags.yes === true, json: parsed.flags.json === true,
      downloadOnly: parsed.flags["download-only"] === true,
      modelFile: typeof parsed.flags["model-file"] === "string" ? parsed.flags["model-file"] : undefined,
      documents: parsed.flags.documents === true,
      project: typeof parsed.flags.project === "string" ? parsed.flags.project : undefined,
      progress: (done, total) => { if (Date.now() - lastProgress > 1000) { process.stderr.write(`Offline model download: ${Math.floor(done * 100 / total)}%\n`); lastProgress = Date.now(); } },
    });
    process.stdout.write(output + "\n"); return;
  }
  // Server and docs commands don't need login
  if (command === "server") {
    await handleServer(client, subcommand, rest, parsed.flags);
    return;
  }

  if (command === "wiki") {
    await handleWiki(client, subcommand, rest, parsed.flags);
    return;
  }

  if (command === "docs") {
    await handleDocs(client, subcommand, rest, parsed.flags);
    return;
  }

  if (command === "support") {
    handleSupport(parsed.flags);
    return;
  }

  if (command === "update" || command === "upgrade") {
    await handleSelfUpdate(command, parsed.flags);
    return;
  }

  if (command === "login") {
    await client.loginWithPairAuth();
    if (accountGuardRequired) {
      try {
        const user = await client.whoAmI();
        saveTrustedAccountId(accountIdFromWhoAmI(user));
      } catch (error) {
        await client.logout();
        throw error;
      }
    }
    console.log("Login successful.");
    const storageMode = getCredentialStorageMode();
    console.log(storageMode === "os-keyring"
      ? "Credential storage: OS keyring."
      : "Credential storage: owner-only local file (this host can read chat keys).");
    const profile = process.env.OPENMATES_PROFILE?.trim();
    const nextCommand = profile ? `openmates --profile ${profile}` : "openmates";
    console.log(`Run \`${nextCommand}\` to start chatting.`);
    return;
  }

  if (command === "signup") {
    await handleSignup(client, parsed.flags);
    return;
  }

  if (command === "e2e") {
    await handleE2E(client, subcommand, rest, parsed.flags);
    return;
  }

  if (command === "logout") {
    await client.logout();
    console.log("Logged out.");
    return;
  }

  if (command === "whoami") {
    const user = await client.whoAmI();
    if (parsed.flags.json === true) {
      printJson(user);
    } else {
      await printWhoAmI(user as Record<string, unknown>, client);
    }
    return;
  }

  if (command === "switch-to") {
    await handleSwitchTo(client, subcommand, parsed.flags);
    return;
  }

  if (command === "credits") {
    await handleCredits(client, parsed.flags);
    return;
  }

  if (command === "chats") {
    await handleChats(client, subcommand, rest, parsed.flags, redactor);
    return;
  }

  if (command === "chat" && parsed.flags.goal) {
    await handleGoalChat(client, parsed.flags, redactor);
    return;
  }

  if (command === "tasks") {
