  if (command === "remote-access") {
    await handleRemoteAccess(client, subcommand, rest, parsed.flags);
    return;
  }

  throw new Error(`Unknown command '${command}'. Run 'openmates help'.`);
}

const TRUST_GUARD_EXEMPT_COMMANDS = new Set([
  "login",
  "logout",
  "whoami",
  "help",
  "version",
  "server",
  "docs",
  "support",
  "update",
  "upgrade",
]);
const TRUST_GUARD_BLOCKED_COMMANDS = new Set(["signup", "e2e"]);
const TRUST_GUARD_PROFILE = "codex-personal";
const TRUST_GUARD_API_URL = "https://api.dev.openmates.org";

export function shouldRequireTrustedAccountGuard(command: string | undefined): boolean {
  return !command || !TRUST_GUARD_EXEMPT_COMMANDS.has(command);
}

export function assertTrustedAccountCommandAllowed(command: string | undefined): void {
  if (command && TRUST_GUARD_BLOCKED_COMMANDS.has(command)) {
    throw new Error(`The '${command}' command is disabled for the trusted Codex CLI profile.`);
  }
}

export function assertTrustedAccountGuardEnvironment(
  flags: Record<string, string | boolean>,
  environment: NodeJS.ProcessEnv = process.env,
): void {
  if (flags.profile !== undefined && flags.profile !== TRUST_GUARD_PROFILE) {
    throw new Error(`Trusted Codex CLI commands cannot override profile ${TRUST_GUARD_PROFILE}.`);
  }
  if (environment.OPENMATES_PROFILE !== TRUST_GUARD_PROFILE) {
    throw new Error(`Trusted Codex CLI commands require OPENMATES_PROFILE=${TRUST_GUARD_PROFILE}.`);
  }
  if (environment.OPENMATES_STATE_DIR) {
    throw new Error("Trusted Codex CLI commands cannot override OPENMATES_STATE_DIR.");
  }
  if (environment.OPENMATES_API_URL?.replace(/\/$/, "") !== TRUST_GUARD_API_URL) {
    throw new Error(`Trusted Codex CLI commands require ${TRUST_GUARD_API_URL}.`);
  }
  const requestedApiUrl = flags["api-url"];
  if (typeof requestedApiUrl === "string" && requestedApiUrl.replace(/\/$/, "") !== TRUST_GUARD_API_URL) {
    throw new Error("Trusted Codex CLI commands cannot override the configured dev API URL.");
  }
}

function accountIdFromWhoAmI(user: Record<string, unknown>): string {
  const accountId = typeof user.id === "string" ? user.id.trim() : "";
  if (!accountId) throw new Error("OpenMates account verification returned no account ID.");
  return accountId;
}

async function enforceTrustedAccount(client: OpenMatesClient): Promise<void> {
  const trustedAccountId = loadTrustedAccountId();
  if (!trustedAccountId) assertTrustedAccountId(null, "");
  const user = await client.whoAmI();
  assertTrustedAccountId(trustedAccountId, accountIdFromWhoAmI(user));
}

function handleSupport(flags: Record<string, string | boolean>): void {
  if (flags.json === true) {
    printJson({
      url: SUPPORT_URL,
      voluntary: true,
      message: SUPPORT_MESSAGE,
    });
    return;
  }

  console.log(renderSupportInfo());
}

async function handleSelfUpdate(command: string, flags: Record<string, string | boolean>): Promise<void> {
  if (flags["caddy-config"] === true) throw new Error("Provide --caddy-config <file>.");
  const reportCaddy = async () => {
    const caddy = await updateCaddyAfterCliUpgrade(flags);
    if (caddy) {
      console.log(`Caddy: ${caddy.status}`);
      if ("retryCommand" in caddy) console.log(`Run: ${caddy.retryCommand}`);
    }
  };
  let plan = buildSelfUpdatePlan(flags);
  const status = checkSelfUpdateStatus(plan);
  if (status.checkError) throw new Error(`Update check failed: ${status.checkError}`);
  const shouldInstall = status.updateAvailable === true;
  if (!plan.dryRun && shouldInstall && status.latestVersion) {
    plan = pinSelfUpdatePlan(plan, status.latestVersion);
  }
  if (flags.json === true) {
    if (!plan.dryRun && shouldInstall) runSelfUpdate(plan, { verbose: flags.verbose === true });
    persistSelfUpdateChannel(plan);
    const caddy = await updateCaddyAfterCliUpgrade(flags);
    printJson({
      command,
      channel: plan.channel,
      status: status.updateAvailable === false ? "up_to_date" : plan.dryRun ? "planned" : "success",
      current_version: plan.currentVersion,
      latest_version: status.latestVersion,
      update_available: status.updateAvailable,
      check_error: status.checkError,
      package_manager: plan.packageManager,
      package: plan.packageSpec,
      run: [plan.command, ...plan.args],
      dry_run: plan.dryRun,
      ...(caddy ? { caddy } : {}),
    });
    return;
  }
  console.log(renderOpenMatesAsciiLogo());
  console.log("");
  console.log("Checking for updates...");
  console.log("");
  console.log(`Release channel: ${plan.channel}`);
  console.log(`Current version: ${plan.currentVersion}`);
  console.log(`Latest version:  ${status.latestVersion ?? "unknown"}`);
  if (status.checkError) {
    console.log(`Update check failed: ${status.checkError}`);
  }
  console.log("");
  if (plan.dryRun) {
    if (status.updateAvailable === false) {
      console.log("OpenMates CLI is already up to date.");
      await reportCaddy();
      return;
    }
    console.log(`Would run: ${[plan.command, ...plan.args].join(" ")}`);
    await reportCaddy();
    return;
  }
  if (status.updateAvailable === false) {
    persistSelfUpdateChannel(plan);
    console.log("OpenMates CLI is already up to date.");
    await reportCaddy();
    return;
  }
  console.log(`Updating OpenMates CLI with ${plan.packageManager}...`);
  runSelfUpdate(plan, { verbose: flags.verbose === true });
  persistSelfUpdateChannel(plan);
  console.log(`Installed OpenMates CLI ${status.latestVersion ?? plan.target}.`);
  await reportCaddy();
  console.log("");
  console.log("OpenMates CLI is up to date.");
}

function handleCliVersion(flags: Record<string, string | boolean>): void {
  const planFlags: Record<string, string | boolean> = { ...flags, "dry-run": true };
  if (planFlags.version === true) delete planFlags.version;
  const plan = buildSelfUpdatePlan(planFlags);
  const status = checkSelfUpdateStatus(plan);
  if (flags.json === true) {
    printJson({
      command: "version",
      channel: plan.channel,
      current_version: status.currentVersion,
      latest_version: status.latestVersion,
      update_available: status.updateAvailable,
      check_error: status.checkError,
      upgrade_command: status.updateAvailable ? "openmates upgrade" : null,
    });
    return;
  }
  console.log(`OpenMates CLI ${status.currentVersion}`);
  console.log(`Release channel: ${plan.channel}`);
  if (status.checkError) {
    console.log(`Update check failed: ${status.checkError}`);
    return;
  }
  if (status.updateAvailable) {
    console.log(`Update available: ${status.latestVersion}`);
    console.log("Run: openmates upgrade");
    return;
  }
  console.log("OpenMates CLI is up to date.");
}

