  return findPlan(await loadPlans(client, masterKey, { ...scope, status: undefined }), id);
}

async function requiredResolvedPlan(
  client: OpenMatesClient,
  masterKey: Uint8Array,
  id: string | undefined,
  scope: { status?: UserPlanStatus; chatId?: string; projectId?: string; activeOnly?: boolean; teamId?: string | null; personal?: boolean },
  action: string,
): Promise<DecryptedUserPlan> {
  if (!id) throw new Error(`Missing plan ID. Usage: openmates plans ${action} <plan-id|short-id>`);
  return resolvePlan(client, masterKey, id, scope);
}

type DependencyTarget = { kind: "plan" | "task"; id: string };

async function resolveDependencyTarget(
  client: OpenMatesClient,
  masterKey: Uint8Array,
  raw: string | boolean | undefined,
  taskScope: Parameters<typeof resolveTask>[3],
  planScope: Parameters<typeof resolvePlan>[3],
): Promise<DependencyTarget> {
  if (typeof raw !== "string") throw new Error("Dependency target is required. Use --target plan:<id> or --target task:<id>.");
  const match = /^(plan|task):(.+)$/.exec(raw);
  if (!match) throw new Error("Dependency target must use plan:<id> or task:<id>.");
  if (match[1] === "plan") return { kind: "plan", id: (await resolvePlan(client, masterKey, match[2], { ...planScope, status: undefined })).planId };
  return { kind: "task", id: (await resolveTask(client, masterKey, match[2], { ...taskScope, status: undefined })).taskId };
}

function printDependencies(value: { dependencies: Array<{ target_ref: string; satisfied?: unknown }>; blockers: Array<{ source_ref: string; target_ref: string }> }): void {
  if (value.dependencies.length === 0 && value.blockers.length === 0) {
    console.log("No dependencies or blockers.");
    return;
  }
  for (const dependency of value.dependencies) console.log(`Depends on: ${dependency.target_ref} (${dependency.satisfied === true ? "satisfied" : "open"})`);
  for (const blocker of value.blockers) console.log(`Blocks: ${blocker.source_ref}`);
}

function parseAssumptionProofFlags(flags: Record<string, string | boolean>): Parameters<typeof serializeAssumptionProofInputs>[0] {
  const proof: Parameters<typeof serializeAssumptionProofInputs>[0] = [];
  for (const embedId of splitCsvFlag(flags["proof-embed"])) proof.push({ kind: "embed", embedId });
  for (const url of splitCsvFlag(flags["proof-url"])) proof.push({ kind: "url", url });
  for (const value of splitCsvFlag(flags["proof-file"])) {
    const [path, startLine, endLine] = value.split(":");
    proof.push({ kind: "file", path, ...(startLine ? { startLine: Number(startLine) } : {}), ...(endLine ? { endLine: Number(endLine) } : {}) });
  }
  return proof;
}

async function encryptPlanAssumptionSources(plan: DecryptedUserPlan, masterKey: Uint8Array, value: string | Parameters<typeof serializeAssumptionProofInputs>[0]): Promise<string> {
  const key = await planKeyFromRecord(plan.encrypted, masterKey);
  const plaintext = typeof value === "string" ? value : serializeAssumptionProofInputs(value);
  return encryptWithAesGcmCombined(plaintext, key);
}

async function projectWorkRecoveryIfConfigured(
  client: OpenMatesClient,
  masterKey: Uint8Array,
  flags: Record<string, string | boolean>,
  projectIds: string[],
): Promise<void> {
  const root = typeof flags["recovery-root"] === "string" ? flags["recovery-root"] : process.env.OPENMATES_WORK_RECOVERY_ROOT;
  if (!root || projectIds.length === 0) return;
  for (const projectId of projectIds) await writeProjectWorkRecovery(client, masterKey, projectId, root);
}

async function writeProjectWorkRecovery(client: OpenMatesClient, masterKey: Uint8Array, projectId: string, root: string): Promise<void> {
  writeWorkRecoveryAtomically(`${root.replace(/\/$/, "")}/${projectId}.yml`, await buildProjectWorkRecoveryDocument(client, masterKey, projectId));
}

async function handleWorkRecovery(client: OpenMatesClient, subcommand: string | undefined, rest: string[], flags: Record<string, string | boolean>): Promise<void> {
  const root = typeof flags.root === "string" ? flags.root : typeof flags["recovery-root"] === "string" ? flags["recovery-root"] : process.env.OPENMATES_WORK_RECOVERY_ROOT;
  if (!subcommand || flags.help === true) {
    console.log("Usage: openmates recovery full-sync --project <project-id> --root <external-root>; openmates recovery validate --file <path>; openmates recovery restore --file <path> --dry-run|--confirm-restore");
    return;
  }
  if (subcommand === "validate" || subcommand === "restore") {
    const path = requiredStringFlag(flags.file ?? rest[0], "--file <projection.yml>");
    if (!existsSync(path)) throw new Error(`Recovery projection does not exist: ${path}`);
    const document = parseYaml(readFileSync(path, "utf8"));
    validateWorkRecoveryDocument(document);
    if (subcommand === "validate") {
      if (flags.json === true) printJson({ valid: true }); else console.log("Recovery projection is valid; no data was changed.");
      return;
    }
    const projectId = requiredStringFlag(flags.project, "--project <project-id>");
    const masterKey = client.getMasterKeyBytes();
    const project = await requiredResolvedProject(client, masterKey, projectId, flags);
    if (document.project.project_id !== project.projectId) throw new Error("Recovery restore --project must exactly match document.project.project_id.");
    const [currentPlans, currentTasks] = await Promise.all([loadPlans(client, masterKey, { projectId: project.projectId }), loadTasks(client, masterKey, { projectId: project.projectId })]);
    const conflicts = findRecoveryConflicts(document, project.projectId, { planIds: currentPlans.map((plan) => plan.planId), taskIds: currentTasks.map((task) => task.taskId) });
    if (flags["dry-run"] === true) {
      const report = { valid: true, dry_run: true, project_id: project.projectId, conflicts, would_restore: conflicts.length === 0 ? { plans: document.plans.length, tasks: document.tasks.length, assumptions: document.assumptions.length, dependencies: document.dependencies.length, revisions: document.revisions.length } : null };
      if (flags.json === true) printJson(report); else console.log(JSON.stringify(report, null, 2));
      return;
    }
    if (flags["confirm-restore"] !== true) throw new Error("Recovery restore requires --confirm-restore and an explicit --project. Use --dry-run first.");
    if (conflicts.length > 0) throw new Error(`Recovery restore found conflicts and made no changes: ${JSON.stringify(conflicts)}`);
    const applied: string[] = [];
    try {
      for (const record of document.plans) {
        const linkContext = await resolvePlanLinkKeyContext(client, masterKey, flags, { primaryChatId: typeof record.primary_chat_id === "string" ? record.primary_chat_id : null, linkedProjectIds: [project.projectId] });
        const input = await buildCreateUserPlanInput(masterKey, recoveryPlanCreateOptions(record, linkContext));
        await client.createUserPlan(input); applied.push(`plan:${input.plan_id}`);
      }
      for (const record of document.tasks) {
        const input = await buildCreateUserTaskInput(masterKey, recoveryTaskCreateOptions(record, project.projectId));
        await client.createUserTask(input); applied.push(`task:${input.task_id}`);
      }
      const restoredPlans = await loadPlans(client, masterKey, { projectId: project.projectId });
      const planById = new Map(restoredPlans.map((plan) => [plan.planId, plan]));
      for (const record of document.assumptions) {
        const planId = recoveryString(record, "plan_id"); const plan = planById.get(planId);
        if (!plan) throw new Error(`Restored plan ${planId} was not available for its assumption.`);
        await client.createPlanAssumption(planId, await recoveryAssumptionInput(plan, masterKey, record)); applied.push(`assumption:${recoveryString(record, "assumption_id")}`);
      }
      for (const dependency of document.dependencies) {
        const [kind, id] = dependency.source_ref.split(":", 2);
        if (kind === "plan") await client.addPlanDependency(id, dependency.target_ref); else await client.addTaskDependency(id, dependency.target_ref);
        applied.push(`dependency:${dependency.source_ref}->${dependency.target_ref}`);
      }
      for (const record of document.revisions) {
        const planId = recoveryString(record, "plan_id"); const snapshot = JSON.stringify(record.snapshot);
        const plan = planById.get(planId); if (!plan) throw new Error(`Restored plan ${planId} was not available for its revision.`);
        await client.submitPlanRevision(planId, { fingerprint: recoveryString(record, "fingerprint"), encrypted_snapshot: await encryptPlanAssumptionSources(plan, masterKey, snapshot), created_at: nowSeconds() }); applied.push(`revision:${recoveryString(record, "revision_id")}`);
      }
    } catch (error) {
      throw new Error(`Recovery restore partially applied (${applied.join(", ") || "nothing"}); it is not cross-object atomic. ${error instanceof Error ? error.message : String(error)}`);
    }
    const restored = await buildProjectWorkRecoveryDocument(client, masterKey, project.projectId);
    if (!recoveryDocumentsSemanticallyEqual(document, restored)) {
      throw new Error(`Recovery restore completed but regenerated YAML is not semantically equal at: ${recoveryDocumentSemanticMismatchPaths(document, restored).join(", ")}.`);
    }
    if (flags.json === true) printJson({ restored: true, project_id: project.projectId, applied }); else console.log(`Recovery restored and verified: ${project.projectId}`);
    return;
  }
  if (subcommand !== "full-sync") throw new Error("Unknown recovery command. Use full-sync, validate, or restore.");
  if (!root) throw new Error("Recovery full-sync requires --root <external-root> or OPENMATES_WORK_RECOVERY_ROOT.");
  const masterKey = client.getMasterKeyBytes();
  const project = await requiredResolvedProject(client, masterKey, requiredStringFlag(flags.project ?? rest[0], "--project <project-id>"), flags);
  await writeProjectWorkRecovery(client, masterKey, project.projectId, root);
  if (flags.json === true) printJson({ project_id: project.projectId, path: `${root.replace(/\/$/, "")}/${project.projectId}.yml` });
  else console.log(`Recovery projection synced: ${root.replace(/\/$/, "")}/${project.projectId}.yml`);
}

async function buildProjectWorkRecoveryDocument(client: OpenMatesClient, masterKey: Uint8Array, projectId: string): Promise<WorkRecoveryDocument> {
  const [plans, tasks] = await Promise.all([loadPlans(client, masterKey, { projectId }), loadTasks(client, masterKey, { projectId })]);
  const dependencies: WorkRecoveryDocument["dependencies"] = []; const assumptions: WorkRecoveryDocument["assumptions"] = []; const revisions: WorkRecoveryDocument["revisions"] = [];
  for (const plan of plans) {
    const [edges, rawAssumptions, rawRevisions] = await Promise.all([client.getPlanDependencies(plan.planId), client.listPlanAssumptions(plan.planId), client.listPlanRevisions(plan.planId)]);
    dependencies.push(...edges.dependencies.map((edge) => ({ source_ref: `plan:${plan.planId}`, target_ref: edge.target_ref })));
    assumptions.push(...await Promise.all(rawAssumptions.map((entry) => projectPlanAssumption(plan, masterKey, entry))));
    revisions.push(...await Promise.all(rawRevisions.map((entry) => projectPlanRevision(plan, masterKey, entry))));
  }
  for (const task of tasks) { const edges = await client.getTaskDependencies(task.taskId); dependencies.push(...edges.dependencies.map((edge) => ({ source_ref: `task:${task.taskId}`, target_ref: edge.target_ref }))); }
  return { schema_version: 1, project: { project_id: projectId }, plans: plans.map(planToJson), tasks: tasks.map(taskToJson), dependencies, assumptions, revisions };
}

function recoveryString(record: Record<string, unknown>, key: string): string {
  const value = record[key];
  if (typeof value !== "string") throw new Error(`Recovery record requires ${key}.`);
  return value;
}

function recoveryStrings(record: Record<string, unknown>, key: string): string[] {
  const value = record[key];
  if (!Array.isArray(value) || !value.every((item) => typeof item === "string")) throw new Error(`Recovery record requires ${key} string array.`);
  return value;
}

function parsePlanUserFlowsFlag(value: unknown): Parameters<typeof buildCreateUserPlanInput>[1]["userFlows"] {
  if (value === undefined) return undefined;
  if (typeof value !== "string") throw new Error("--user-flows must be a JSON array.");
  const parsed = JSON.parse(value) as unknown;
  if (!Array.isArray(parsed)) throw new Error("--user-flows must be a JSON array.");
  return parsed as Parameters<typeof buildCreateUserPlanInput>[1]["userFlows"];
}

function recoveryPlanUserFlows(record: Record<string, unknown>): Parameters<typeof buildCreateUserPlanInput>[1]["userFlows"] {
  const flows = record.user_flows;
  if (!Array.isArray(flows)) throw new Error("Recovery record requires user_flows array.");
  return flows as Parameters<typeof buildCreateUserPlanInput>[1]["userFlows"];
}

function requiredPlanGoal(flags: Record<string, unknown>): string {
  if (typeof flags.goal !== "string" || !flags.goal.trim()) throw new Error("Creating a plan requires --goal.");
  return flags.goal;
}

function requiredPlanProjectFlags(flags: Record<string, string | boolean>): string[] {
  const projectIds = splitCsvFlag(flags.project ?? flags.projects);
  if (projectIds.length === 0) throw new Error("Creating a Plan requires --project <id>.");
  return projectIds;
}

function recoveryPlanCreateOptions(record: Record<string, unknown>, linkContext: PlanLinkKeyContext): Parameters<typeof buildCreateUserPlanInput>[1] {
  return {
    planId: recoveryString(record, "plan_id"), title: recoveryString(record, "title"), goal: recoveryString(record, "goal"),
    scopeIn: recoveryString(record, "scope_in"), scopeOut: recoveryString(record, "scope_out"), userFlows: recoveryPlanUserFlows(record),
    assumptions: recoveryString(record, "assumptions"), openQuestions: recoveryString(record, "open_questions"), constraints: recoveryString(record, "constraints"), decisions: recoveryString(record, "decisions"),
    risks: recoveryString(record, "risks"), referencePatterns: recoveryString(record, "reference_patterns"), context: recoveryString(record, "context"),
    status: recoveryString(record, "status") as UserPlanStatus, slug: typeof record.slug === "string" ? record.slug : undefined,
    primaryChatId: linkContext.primaryChatId, primaryChatKey: linkContext.primaryChatKey,
    linkedProjectIds: linkContext.linkedProjectIds, linkedProjectKeys: linkContext.linkedProjectKeys,
    plannerFocusId: typeof record.planner_focus_id === "string" ? record.planner_focus_id : null,
  };
}

function recoveryTaskCreateOptions(record: Record<string, unknown>, projectId: string): TaskCreateOptions {
  return {
    taskId: recoveryString(record, "task_id"), title: recoveryString(record, "title"), description: recoveryString(record, "description"), labels: recoveryStrings(record, "labels"),
    status: recoveryString(record, "status") as UserTaskStatus, assign: typeof record.assignee_hash === "string" ? record.assignee_hash : recoveryString(record, "assignee_type"),
    chatId: typeof record.primary_chat_id === "string" ? record.primary_chat_id : null, projectIds: [projectId], planId: typeof record.plan_id === "string" ? record.plan_id : null,
    dueAt: typeof record.due_at === "number" ? record.due_at : null, priority: typeof record.priority === "number" ? record.priority : null, slug: typeof record.slug === "string" ? record.slug : undefined,
  };
}

async function recoveryAssumptionInput(plan: DecryptedUserPlan, masterKey: Uint8Array, record: Record<string, unknown>): Promise<UserPlanAssumptionRecord> {
  const encrypt = (key: string): Promise<string> => encryptPlanAssumptionSources(plan, masterKey, typeof record[key] === "string" ? record[key] as string : "");
  return {
    assumption_id: recoveryString(record, "assumption_id"), encrypted_text: await encrypt("text"), category: typeof record.category === "string" ? record.category : undefined,
    status: typeof record.status === "string" ? record.status : undefined, required_before: typeof record.required_before === "string" ? record.required_before : undefined,
    linked_sub_chat_id: typeof record.linked_sub_chat_id === "string" ? record.linked_sub_chat_id : null, linked_task_id: typeof record.linked_task_id === "string" ? record.linked_task_id : null,
    linked_criterion_ids: Array.isArray(record.linked_criterion_ids) ? record.linked_criterion_ids as string[] : [],
    encrypted_corrected_text: await encrypt("corrected_text"), encrypted_evidence_summary: await encrypt("evidence_summary"), encrypted_blocker_reason: await encrypt("blocker_reason"),
    encrypted_waiver_reason: await encrypt("waiver_reason"), encrypted_sources: await encryptPlanAssumptionSources(plan, masterKey, JSON.stringify(record.sources)), created_at: nowSeconds(), updated_at: nowSeconds(),
  };
}

type PlanTextSection = {
  label: string;
  option: "goal" | "scopeIn" | "scopeOut" | "assumptions" | "openQuestions" | "constraints" | "decisions" | "risks" | "referencePatterns" | "context";
  read: (plan: DecryptedUserPlan) => string;
};

const PLAN_TEXT_SECTIONS: Record<string, PlanTextSection> = {
  goal: { label: "Goal", option: "goal", read: (plan) => plan.goal },
  "scope-in": { label: "Scope in", option: "scopeIn", read: (plan) => plan.scopeIn },
  "scope-out": { label: "Scope out", option: "scopeOut", read: (plan) => plan.scopeOut },
  assumptions: { label: "Assumptions", option: "assumptions", read: (plan) => plan.assumptions },
  "open-questions": { label: "Open questions", option: "openQuestions", read: (plan) => plan.openQuestions },
  constraints: { label: "Constraints", option: "constraints", read: (plan) => plan.constraints },
  decisions: { label: "Decisions", option: "decisions", read: (plan) => plan.decisions },
  risks: { label: "Risks", option: "risks", read: (plan) => plan.risks },
  "reference-patterns": { label: "Reference patterns", option: "referencePatterns", read: (plan) => plan.referencePatterns },
  context: { label: "Context", option: "context", read: (plan) => plan.context },
};

async function handlePlanTextSection(
  client: OpenMatesClient,
  masterKey: Uint8Array,
  section: PlanTextSection,
  rest: string[],
  flags: Record<string, string | boolean>,
  scope: { status?: UserPlanStatus; chatId?: string; projectId?: string; activeOnly?: boolean; teamId?: string | null; personal?: boolean },
): Promise<void> {
  const action = rest[0];
  if (!["set", "clear", "add", "edit", "update", "remove", "answer", "supersede"].includes(action ?? "")) {
    throw new Error(`Usage: openmates plans ${section.label.toLowerCase()} set|add|edit|remove <plan-id> --text <text>`);
  }
  const plan = await requiredResolvedPlan(client, masterKey, rest[1], scope, `${section.label.toLowerCase()} ${action}`);
  const current = section.read(plan).trim();
  const rawText = typeof flags.text === "string" ? flags.text : rest.slice(2).join(" ").trim();
  const next = action === "clear" || action === "remove"
    ? ""
    : action === "add" || action === "answer" || action === "supersede"
      ? appendPlanSectionText(current, requiredStringFlag(rawText, "--text <text>"))
      : requiredStringFlag(rawText, "--text <text>");
  const patch = await buildUpdateUserPlanInput(plan, masterKey, { [section.option]: next });
  const updated = await client.updateUserPlan(plan.planId, patch);
  printPlanOutput(await decryptUserPlan(updated, masterKey), flags);
}

function appendPlanSectionText(current: string, addition: string): string {
  return current ? `${current}\n- ${addition}` : `- ${addition}`;
}

function printPlanOutput(plan: DecryptedUserPlan, flags: Record<string, string | boolean>): void {
  if (flags.json === true) printJson({ plan: planToJson(plan) });
  else {
    console.log(renderPlanDetail(plan));
    printHistoryCommands(plan.encrypted.history ?? null);
  }
}

function normalizeGoalFlag(value: string | boolean | undefined): string {
  if (typeof value !== "string" || !value.trim()) {
    throw new Error("Missing goal. Usage: openmates chat --goal <goal>");
  }
  return value.trim();
}

async function handleGoalChat(
  client: OpenMatesClient,
  flags: Record<string, string | boolean>,
  redactor?: OutputRedactor,
): Promise<void> {
  if (resolveApiKey(flags)) {
    throw new Error("openmates chat --goal uses your paired CLI session. For API-key clients, use the npm or pip SDK chats.send(..., { goal }).");
  }
  if (!client.hasSession()) {
    throw new Error("openmates chat --goal requires login. Run 'openmates login' first.");
  }
  const goal = normalizeGoalFlag(flags.goal);
  const requestedProjectIds = requiredPlanProjectFlags(flags);
  const result = await sendMessageStreaming(
    client,
    {
      message: typeof flags.message === "string" && flags.message.trim() ? flags.message.trim() : goal,
      chatId: undefined,
      incognito: false,
      json: flags.json === true,
      autoApproveSubChats: flags["auto-approve"] === true,
      autoApproveMemories: flags["auto-approve-memories"] === true,
      acceptTaskProposals: flags["accept-task-proposals"] === true,
      piiDetection: flags["no-pii-detection"] !== true,
      responseTimeoutMs: parseResponseTimeoutMs(flags),
      ...teamContextFromFlags(flags),
    },
    redactor,
  );
  if (!("chatId" in result) || !result.chatId) {
    throw new Error("Goal chat did not return a saved chat id.");
  }

  const masterKey = client.getMasterKeyBytes();
  const linkContext = await resolvePlanLinkKeyContext(client, masterKey, flags, {
    primaryChatId: result.chatId,
    linkedProjectIds: requestedProjectIds,
  });
  const planInput = await buildCreateUserPlanInput(masterKey, {
    title: typeof flags.title === "string" && flags.title.trim() ? flags.title.trim() : goal,
    goal,
    status: normalizePlanStatus(typeof flags.status === "string" ? flags.status : undefined),
    primaryChatId: linkContext.primaryChatId,
    primaryChatKey: linkContext.primaryChatKey,
    linkedProjectIds: linkContext.linkedProjectIds,
    linkedProjectKeys: linkContext.linkedProjectKeys,
  });
  const plan = await decryptUserPlan(await client.createUserPlan(planInput), masterKey);
  if (flags.json === true) {
    printJson({ ...result, chat_id: result.chatId, plan: planToJson(plan) });
    return;
  }
  const shortChatId = result.chatId.slice(0, 8);
  process.stdout.write(
    `${SEP}\n` +
      `\x1b[2mPlan attached: ${plan.shortId} (${plan.status.replaceAll("_", " ")})\x1b[0m\n` +
      `\x1b[2mPlan:     openmates plans show ${plan.shortId}\x1b[0m\n` +
      `\x1b[2mContinue: openmates chats send --chat ${shortChatId} "your message"\x1b[0m\n`,
  );
}

// ---------------------------------------------------------------------------
// Projects
// ---------------------------------------------------------------------------

async function handleProjects(
  client: OpenMatesClient,
  subcommand: string | undefined,
  rest: string[],
  flags: Record<string, string | boolean>,
  redactor?: OutputRedactor,
): Promise<void> {
  if (!subcommand || subcommand === "help" || flags.help === true) {
    printProjectsHelp();
    return;
  }

  if (subcommand === "delete" && (flags.json === true || !process.stdin.isTTY) && typeof flags.confirm !== "string") {
    throw new CliContractError("confirmation_required", "Project deletion requires --confirm <exact-project-id>.");
  }
  if (subcommand === "sources" && rest[0] === "remove" && (flags.json === true || !process.stdin.isTTY) && typeof flags.confirm !== "string") {
    throw new CliContractError("confirmation_required", "Project source removal requires --confirm <source-id>.");
  }
  if (subcommand === "items" && rest[0] === "remove" && (flags.json === true || !process.stdin.isTTY) && flags.confirm !== true) {
    throw new CliContractError("confirmation_required", "Project item removal requires --confirm.");
  }
  if (subcommand === "files" && (flags.json === true || !process.stdin.isTTY) && !hasExplicitProjectContext(flags)) {
    throw new CliContractError("context_confirmation_required", "Live file requests require --personal or --team <team>.");
  }
  if (subcommand === "create" && (flags.json === true || !process.stdin.isTTY) && flags["write-policy"] === undefined) {
    throw new CliContractError("write_policy_required", "Project creation requires --write-policy apply_and_show|always_ask in non-interactive mode.");
  }

  const context = await resolveProjectContext(client, flags, subcommand === "files");
  const masterKey = client.getMasterKeyBytes();

  if (subcommand === "plans" || subcommand === "tasks") {
    const project = await requiredResolvedProject(client, masterKey, requiredProjectTarget(rest, subcommand), flags, context);
    if (subcommand === "plans") {
      const plans = await loadPlans(client, masterKey, { projectId: project.projectId, ...teamContextFromFlags(flags) });
      if (flags.json === true) printJson({ project_id: project.projectId, plans: plans.map(planToJson) });
      else console.log(renderPlanList(plans));
    } else {
      const tasks = await loadTasks(client, masterKey, { projectId: project.projectId, ...teamContextFromFlags(flags) });
      if (flags.json === true) printJson({ project_id: project.projectId, tasks: tasks.map(taskToJson) });
      else console.log(renderTaskList(tasks));
    }
    return;
  }

  if (subcommand === "list") {
    const projects = await loadProjects(client, masterKey, flags, context);
    const filtered = flags["include-archived"] === true ? projects : projects.filter((project) => !project.archived);
    printProjectsOutput(filtered, flags);
    return;
  }

  if (subcommand === "show" || subcommand === "open") {
    const project = await requiredResolvedProject(client, masterKey, requiredProjectTarget(rest, subcommand), flags, context);
    if (subcommand === "open") {
      await client.updateProject(project.projectId, { last_opened_at: nowSeconds(), ...(project.version !== null ? { version: project.version } : {}) }, context);
    }
    printProjectOutput(project, flags);
    return;
  }

  if (subcommand === "create") {
    const name = requiredStringFlag(rest[0] ?? flags.name, "project name");
    const writeMode = await resolveProjectWriteMode(flags, `Choose how OpenMates may change files in ${JSON.stringify(name)}:`);
    const projectKey = randomBytes(32);
    const wrapping = await client.projectWrappingKey(context);
    const projectId = randomUUID();
    const timestamp = nowSeconds();
    const defaultFocus = buildProjectDefaultFocus(name);
    const slugMetadata = await buildEncryptedObjectSlugMetadata({
      value: typeof flags.slug === "string" ? flags.slug : name,
      encryptionKey: projectKey,
      lookupKey: wrapping.key,
    });
    const payload: Record<string, unknown> = {
      project_id: projectId,
      encrypted_project_key: wrapping.teamId ? null : await encryptBytesWithAesGcm(projectKey, wrapping.key),
      encrypted_slug: slugMetadata.encrypted_slug,
      slug_lookup_hash: slugMetadata.slug_lookup_hash,
      encrypted_name: await encryptWithAesGcmCombined(name, projectKey),
      encrypted_description: await encryptWithAesGcmCombined(typeof flags.description === "string" ? flags.description : "", projectKey),
      encrypted_icon: await encryptWithAesGcmCombined(typeof flags.icon === "string" ? flags.icon : "folder", projectKey),
      encrypted_color: await encryptWithAesGcmCombined(typeof flags.color === "string" ? flags.color : "default", projectKey),
      pinned: flags.pinned === true,
      created_at: timestamp,
      updated_at: timestamp,
      last_opened_at: timestamp,
      write_mode: writeMode,
      default_focus_id: defaultFocus.focus_id,
      encrypted_settings: await encryptWithAesGcmCombined(JSON.stringify({ default_focus: defaultFocus }), projectKey),
      key_wrappers: wrapping.teamId ? [{
        key_type: "team",
        hashed_team_id: createHash("sha256").update(wrapping.teamId).digest("hex"),
        team_key_epoch: 1,
        encrypted_project_key: await encryptBytesWithAesGcm(projectKey, wrapping.key),
        wrapper_version: 1,
        created_at: timestamp,
      }] : [],
    };
    const result = await client.createProject(payload, context);
    const record = { ...payload, ...((result.project ?? {}) as Record<string, unknown>) } as ProjectRecord;
    printProjectOutput(await decryptProject(client, record, masterKey, context), flags);
    return;
  }

  if (subcommand === "settings") {
    const project = await requiredResolvedProject(client, masterKey, requiredProjectTarget(rest, subcommand), flags, context);
    if (rest[1] === "command" && rest[2] === "stop") {
      const executionId = requiredStringFlag(rest[3], "execution ID");
      const chatTarget = requiredStringFlag(flags.chat, "--chat <chat-id>");
      const chatId = await client.resolveFullChatId(chatTarget, context);
      if (!chatId) throw new CliContractError("chat_not_found", `Chat '${chatTarget}' not found.`);
      const result = await client.stopRemoteCommand({
        execution_id: executionId,
        chat_id: chatId,
        project_id: project.projectId,
      }, context);
      if (flags.json === true) printJson(result);
      else console.log(`Command stop requested: ${executionId} (${String(result.state ?? result.status ?? "acknowledged")})`);
      return;
    }
    if (rest[1] === "command-presets") {
      const action = rest[2] ?? "list";
      const candidates = listRemoteAccessSources().filter((source) =>
        source.projectId === project.projectId
        && (typeof flags.source !== "string" || source.sourceId === flags.source)
        && (typeof flags.path !== "string" || source.rootPath === flags.path));
      if (candidates.length !== 1) {
        throw new CliContractError("source_selection_required", "Select one attached local source with --source <source-id> or --path <folder>.");
      }
      const source = candidates[0];
      const permissions = loadRemoteCommandPermissions(source.rootPath);
      if (!permissions) throw new CliContractError("command_presets_missing", "This source has no .openmates/permissions.yml file.");
      if (action === "list") {
        const active = listRemoteCommandPresetGrants().filter((grant) => grant.project_id === project.projectId);
        const presets = permissions.presets.map((preset) => {
          const definitionDigest = remoteCommandPresetDigest(permissions, preset.id);
          return {
            id: preset.id,
            label: preset.label,
            enabled: active.some((grant) => grant.preset_id === preset.id && grant.definition_digest === definitionDigest),
            definition_digest: definitionDigest,
          };
        });
        if (flags.json === true) printJson({ project_id: project.projectId, source_id: source.sourceId, presets });
        else presets.forEach((preset) => console.log(`${preset.enabled ? "enabled" : "disabled"}  ${preset.id}  ${preset.label}`));
        return;
      }
      const presetId = requiredStringFlag(rest[3] ?? flags.preset, "preset ID");
      if (action === "enable") {
        await ensureRemoteCommandSetupForCli(flags);
        const grant = enableRemoteCommandPreset(project.projectId, source.rootPath, presetId);
        if (flags.json === true) printJson({ project_id: project.projectId, source_id: source.sourceId, grant });
        else console.log(`Command preset enabled: ${presetId}`);
        return;
      }
      if (action === "disable") {
        disableRemoteCommandPreset(project.projectId, presetId);
        if (flags.json === true) printJson({ project_id: project.projectId, source_id: source.sourceId, preset_id: presetId, enabled: false });
        else console.log(`Command preset disabled: ${presetId}`);
        return;
      }
      throw new CliContractError("invalid_command_preset_action", "Use command-presets list|enable|disable.");
    }
    if (rest[1] === "command-resources") {
      const action = rest[2] ?? "list";
      const candidates = listRemoteAccessSources().filter((source) =>
        source.projectId === project.projectId
        && (typeof flags.source !== "string" || source.sourceId === flags.source)
        && (typeof flags.path !== "string" || source.rootPath === flags.path));
      if (candidates.length !== 1) throw new CliContractError("source_selection_required", "Select one attached local source with --source <source-id> or --path <folder>.");
      const source = candidates[0];
      const permissions = loadRemoteCommandPermissions(source.rootPath);
      if (!permissions) throw new CliContractError("command_resources_missing", "This source has no .openmates/permissions.yml file.");
      if (action === "list") {
        const enabled = listRemoteCommandResourceGrants(project.projectId, source.sourceId);
        const resources = {
          writable: permissions.resource_profiles.writable.map((item) => ({ ...item, enabled: enabled.some((grant) => grant.kind === "writable" && grant.profile_id === item.id) })),
          network: permissions.resource_profiles.network.map((item) => ({ ...item, enabled: enabled.some((grant) => grant.kind === "network" && grant.profile_id === item.id) })),
          credentials: permissions.resource_profiles.credentials.map((item) => ({ ...item, enabled: enabled.some((grant) => grant.kind === "credential" && grant.profile_id === item.id) })),
        };
        if (flags.json === true) printJson({ project_id: project.projectId, source_id: source.sourceId, resources });
        else for (const [kind, definitions] of Object.entries(resources)) for (const item of definitions) console.log(`${item.enabled ? "enabled" : "disabled"}  ${kind}  ${item.id}`);
        return;
      }
      const kind = requiredStringFlag(rest[3], "resource kind") as "writable" | "network" | "credential";
      if (!["writable", "network", "credential"].includes(kind)) throw new CliContractError("invalid_command_resource_kind", "Resource kind must be writable, network, or credential.");
      const profileId = requiredStringFlag(rest[4] ?? flags.profile, "profile ID");
      if (action === "disable") {
        disableRemoteCommandResourceGrant(project.projectId, source.sourceId, kind, profileId);
      } else if (action === "enable" && kind === "writable") {
        enableRemoteCommandWritableGrant({ projectId: project.projectId, sourceId: source.sourceId, projectRoot: source.rootPath,
          permissions, profileId, hostPath: requiredStringFlag(flags["host-path"], "--host-path <absolute-folder>") });
      } else if (action === "enable" && kind === "network") {
        enableRemoteCommandNetworkGrant({ projectId: project.projectId, sourceId: source.sourceId, permissions, profileId });
      } else if (action === "enable" && kind === "credential") {
        enableRemoteCommandCredentialGrant({ projectId: project.projectId, sourceId: source.sourceId, permissions, profileId,
          environmentSources: parseCredentialEnvironmentMappings(requiredStringFlag(flags.environment, "--environment TARGET=LOCAL_ENV,...")) });
      } else {
        throw new CliContractError("invalid_command_resource_action", "Use command-resources list|enable|disable.");
      }
      if (flags.json === true) printJson({ project_id: project.projectId, source_id: source.sourceId, kind, profile_id: profileId, enabled: action === "enable" });
      else console.log(`Command ${kind} profile ${action === "enable" ? "enabled" : "disabled"}: ${profileId}`);
      return;
    }
    if (rest[1] === "focus") {
      const action = rest[2];
      if (action !== "activate" && action !== "deactivate") {
        throw new CliContractError(
          "project_focus_action_required",
          "Use 'projects settings <project> focus activate|deactivate --chat <chat-id>'.",
        );
      }
      const chatTarget = requiredStringFlag(flags.chat, "--chat <chat-id>");
      const chatId = await client.resolveFullChatId(chatTarget, context);
      if (!chatId) throw new CliContractError("chat_not_found", `Chat '${chatTarget}' not found.`);
      if (action === "deactivate") {
        const activeFocus = await client.getActiveProjectFocus(chatId);
        if (activeFocus && activeFocus.project_id !== project.projectId) {
          throw new CliContractError(
            "project_focus_conflict",
            `Chat '${chatTarget}' has a different Project focus active.`,
          );
        }
        await client.deactivateProjectFocus(chatId);
        if (flags.json === true) printJson({ active: false, project_id: project.projectId, chat_id: chatId });
        else console.log(`Project focus deactivated for chat ${chatId}.`);
        return;
      }
      const defaultFocus = await decryptProjectDefaultFocus(client, project, context);
      const activeFocus = await client.activateProjectFocus(project.projectId, {
        chat_id: chatId,
        focus_id: defaultFocus.focus_id,
        instruction: defaultFocus.instructions,
      }, context);
      if (flags.json === true) printJson({ focus: activeFocus });
      else console.log(`Project focus activated for ${project.name} in chat ${chatId}.`);
      return;
    }
    if (flags["write-policy"] === undefined && flags["auto-selection"] === undefined && flags["focus-activation"] === undefined) {
      const settings = await client.getProjectSettings(project.projectId, context);
      if (flags.json === true) printJson({ project_id: project.projectId, settings });
      else console.log(`Write policy: ${settings.write_mode ?? "selection required"}\nAutomatic focus selection: ${settings.auto_selection === false ? "off" : "on"}\nFocus activation: ${settings.focus_activation_policy ?? "delayed"}`);
      return;
    }
    const autoSelectionFlag = flags["auto-selection"];
    if (autoSelectionFlag !== undefined && autoSelectionFlag !== "on" && autoSelectionFlag !== "off") {
      throw new CliContractError("invalid_auto_selection", "--auto-selection must be on or off.");
    }
    const focusActivationFlag = flags["focus-activation"];
    if (focusActivationFlag !== undefined && focusActivationFlag !== "delayed" && focusActivationFlag !== "immediate" && focusActivationFlag !== "approval") {
      throw new CliContractError("invalid_focus_activation", "--focus-activation must be delayed, immediate, or approval.");
    }
    const writeMode = flags["write-policy"] === undefined ? undefined : await resolveProjectWriteMode(flags, "Choose the Project write policy:");
    const settings = await client.updateProjectSettings(project.projectId, {
      ...(writeMode === undefined ? {} : { write_mode: writeMode }),
      ...(autoSelectionFlag === undefined ? {} : { auto_selection: autoSelectionFlag === "on" }),
      ...(focusActivationFlag === undefined ? {} : { focus_activation_policy: focusActivationFlag }),
      updated_at: nowSeconds(),
    }, context);
    if (flags.json === true) printJson({ project_id: project.projectId, settings });
    else console.log(`Project settings saved. Write policy: ${settings.write_mode}; automatic focus selection: ${settings.auto_selection === false ? "off" : "on"}; focus activation: ${settings.focus_activation_policy ?? "delayed"}.`);
    return;
  }

  if (["update", "archive", "unarchive"].includes(subcommand)) {
    const project = await requiredResolvedProject(client, masterKey, requiredProjectTarget(rest, subcommand), flags, context);
    const patch: Record<string, unknown> = { updated_at: nowSeconds(), ...(project.version !== null ? { version: project.version } : {}) };
    if (subcommand === "archive" || subcommand === "unarchive") patch.archived = subcommand === "archive";
    if (typeof flags.slug === "string") {
      const slugMetadata = await buildEncryptedObjectSlugMetadata({
        value: flags.slug,
        encryptionKey: project.projectKey,
        lookupKey: (await client.projectWrappingKey(context)).key,
      });
      patch.encrypted_slug = slugMetadata.encrypted_slug;
      patch.slug_lookup_hash = slugMetadata.slug_lookup_hash;
    }
    if (typeof flags.name === "string") patch.encrypted_name = await encryptWithAesGcmCombined(flags.name, project.projectKey);
    if (typeof flags.description === "string") patch.encrypted_description = await encryptWithAesGcmCombined(flags.description, project.projectKey);
    if (typeof flags.icon === "string") patch.encrypted_icon = await encryptWithAesGcmCombined(flags.icon, project.projectKey);
    if (typeof flags.color === "string") patch.encrypted_color = await encryptWithAesGcmCombined(flags.color, project.projectKey);
    if (flags.pin === true) patch.pinned = true;
    if (flags.unpin === true) patch.pinned = false;
    if (Object.keys(patch).every((key) => ["updated_at", "version"].includes(key))) {
      throw new CliContractError("nothing_to_update", "Provide a Project field to update.");
    }
    const updated = await client.updateProject(project.projectId, patch, context);
    printProjectOutput(await decryptProject(client, { ...project.encrypted, ...updated }, masterKey, context), flags);
    return;
  }

  if (subcommand === "delete") {
    const project = await requiredResolvedProject(client, masterKey, requiredProjectTarget(rest, subcommand), flags, context);
    await requireExactConfirmation("Project deletion", project.projectId, flags);
    await client.deleteProject(project.projectId, project.projectId, context);
    if (flags.json === true) printJson({ deleted: true, project_id: project.projectId });
    else console.log(`Project deleted: ${project.name} (${project.projectId})`);
    return;
  }

  if (subcommand === "items") {
    await handleProjectItems(client, masterKey, rest, flags, context);
    return;
  }

  if (subcommand === "sources") {
    await handleProjectSources(client, masterKey, rest, flags, context);
    return;
  }

  if (subcommand === "files") {
    await handleProjectFiles(client, masterKey, rest, flags, context);
    return;
  }

  if (subcommand === "history") {
    const project = await requiredResolvedProject(client, masterKey, requiredProjectTarget(rest, subcommand), flags, context);
    printObjectHistory(await client.listObjectHistory("project", project.projectId, typeof flags.limit === "string" ? Number(flags.limit) : 50), flags);
    return;
  }

  if (subcommand === "restore") {
    const project = await requiredResolvedProject(client, masterKey, requiredProjectTarget(rest, subcommand), flags, context);
    const entryId = historyEntryIdFromFlagsOrRest(flags, rest, "openmates projects restore <project-id> --entry <history-entry-id>");
    const result = await client.restoreObjectHistory("project", project.projectId, entryId, parseHistoryRestoreState(flags.state));
    if (flags.json === true) printJson(result);
    else {
      console.log(`Project restored: ${project.name}`);
      printHistoryCommands(result.history as WorkspaceHistoryResult | null | undefined);
    }
    return;
  }

  if (subcommand === "ask") {
    const instruction = requiredAskInstruction(flags, rest, "openmates projects ask \"Launch workspace\"");
    const exactAsk = await buildExactProjectAsk(client, masterKey, instruction, flags);
    if (exactAsk) {
      const result = await client.askProject({ instruction, ...exactAsk });
      if (await handleWorkspaceAskFallbackChat(client, "project", instruction, result, flags, redactor)) return;
      printAskApplyResult("project", result, flags);
      return;
    }
    const proposal = isShortWorkspaceAsk(instruction)
      ? { name: instruction, description: "", icon: "folder", color: "default" }
      : extractRecord(await client.planProjectAsk({ instruction }), "proposed_project");
    const projectKey = randomBytes(32);
    const timestamp = Math.floor(Date.now() / 1000);
    const projectId = randomUUID();
    const name = requiredString(proposal, "name", instruction);
    const slugMetadata = await buildEncryptedObjectSlugMetadata({
      value: typeof flags.slug === "string" ? flags.slug : name,
      encryptionKey: projectKey,
      lookupKey: masterKey,
    });
    const encryptedCreate = {
      project_id: projectId,
      encrypted_project_key: await encryptBytesWithAesGcm(projectKey, masterKey),
      encrypted_slug: slugMetadata.encrypted_slug,
      slug_lookup_hash: slugMetadata.slug_lookup_hash,
      encrypted_name: await encryptWithAesGcmCombined(name, projectKey),
      encrypted_description: await encryptWithAesGcmCombined(typeof flags.description === "string" ? flags.description : optionalString(proposal, "description") ?? "", projectKey),
      encrypted_icon: await encryptWithAesGcmCombined(optionalString(proposal, "icon") ?? "folder", projectKey),
      encrypted_color: await encryptWithAesGcmCombined(optionalString(proposal, "color") ?? "default", projectKey),
      pinned: flags.pinned === true,
      created_at: timestamp,
      updated_at: timestamp,
      last_opened_at: timestamp,
    };
    const result = await client.askProject({ instruction, encryptedCreate });
    if (await handleWorkspaceAskFallbackChat(client, "project", instruction, result, flags, redactor)) return;
    printAskApplyResult("project", result, flags);
    return;
  }

  throw new Error(`Unknown projects command '${subcommand}'. Run 'openmates projects --help'.`);
}

async function handleProjectItems(
  client: OpenMatesClient,
  masterKey: Uint8Array,
  rest: string[],
  flags: Record<string, string | boolean>,
  context: { teamId?: string; personal?: boolean },
): Promise<void> {
  const action = rest[0];
  const project = await requiredResolvedProject(client, masterKey, requiredStringFlag(rest[1], "project"), flags, context);
  if (action === "list") {
    const result = await client.listProjectItems(project.projectId, context);
    const folders = await Promise.all(result.folders.map(async (folder) => ({
      folder_id: folder.folder_id,
      parent_folder_id: folder.hashed_parent_folder_id ?? null,
      name: await decryptOptionalProjectField(folder.encrypted_name as string | undefined, project.projectKey),
      position: folder.position ?? 0,
    })));
    const items = await Promise.all(result.items.map(async (item) => ({
      project_item_id: item.project_item_id,
      type: item.item_type,
      target_id: await decryptOptionalProjectField(item.target_id_encrypted, project.projectKey),
      display_name: await decryptOptionalProjectField(item.encrypted_display_name, project.projectKey),
      ownership_label: item.ownership_label ?? null,
      position: item.position ?? 0,
    })));
    if (flags.json === true) printJson({ project_id: project.projectId, folders, items });
    else printProjectItems(folders, items);
    return;
  }
  if (action === "remove") {
    const type = requiredStringFlag(flags.type, "--type <embed|chat|workflow>");
    if (!["embed", "chat", "workflow"].includes(type)) throw new CliContractError("invalid_item_type", "Item type must be embed, chat, or workflow.");
    const target = requiredStringFlag(flags.target, "--target <id>");
    if (flags.confirm !== true && (flags.json === true || !process.stdin.isTTY)) {
      throw new CliContractError("confirmation_required", "Project item removal requires --confirm.");
    }
    if (flags.confirm !== true && !await promptConfirmation(`Remove ${type} ${target} from this Project?`)) return;
    const result = await client.deleteProjectItemByTarget(project.projectId, type as "embed" | "chat" | "workflow", target, context);
    if (flags.json === true) printJson({ project_id: project.projectId, target_id: target, ...result });
    else console.log(result.deleted ? "Project item removed." : "Project item was not linked.");
    return;
  }
  throw new CliContractError("unknown_projects_items_command", "Use 'projects items list' or 'projects items remove'.");
}

async function handleProjectSources(
  client: OpenMatesClient,
  masterKey: Uint8Array,
  rest: string[],
  flags: Record<string, string | boolean>,
  context: { teamId?: string; personal?: boolean },
): Promise<void> {
  const action = rest[0];
  const project = await requiredResolvedProject(client, masterKey, requiredStringFlag(rest[1], "project"), flags, context);
  if (action === "list") {
    const sources = await safeProjectSources(client, project, context);
    if (flags.json === true) printJson({ project_id: project.projectId, sources });
    else printProjectSources(sources);
    return;
  }
  if (action === "remove") {
    const sourceId = requiredStringFlag(flags.source, "--source <source-id>");
    await requireExactConfirmation("Project source removal", sourceId, flags);
    const result = await client.deleteProjectSource(project.projectId, sourceId, sourceId, context);
    if (flags.json === true) printJson({ project_id: project.projectId, source_id: sourceId, ...result });
    else console.log(`Project source removed: ${sourceId}`);
    return;
  }
  throw new CliContractError("unknown_projects_sources_command", "Use 'projects sources list' or 'projects sources remove'.");
}

async function handleProjectFiles(
  client: OpenMatesClient,
  masterKey: Uint8Array,
  rest: string[],
  flags: Record<string, string | boolean>,
  context: { teamId?: string; personal?: boolean },
): Promise<void> {
  const action = rest[0];
  if (!action || !["list", "search", "read"].includes(action)) {
    throw new CliContractError("unknown_projects_files_command", "Use 'projects files list', 'search', or 'read'.");
  }
  if (flags["include-ignored"] === true && action !== "read") {
    throw new CliContractError("include_ignored_read_only", "--include-ignored is allowed only for one exact file read.");
  }
  if (flags["include-content"] === true && action !== "search") {
    throw new CliContractError("include_content_search_only", "--include-content is allowed only for filename search.");
  }
  const project = await requiredResolvedProject(client, masterKey, requiredStringFlag(rest[1], "project"), flags, context);
  const sources = await client.listProjectSources(project.projectId, context);
  const source = await selectProjectSource(sources, flags);
  let operation: "list" | "search" | "read_text";
  let argumentsValue: Record<string, unknown>;
  if (action === "list") {
    operation = "list";
    const relativePath = safeRelativeProjectPath(typeof flags.path === "string" ? flags.path : ".");
    const depth = parseBoundedInteger(flags.depth, "--depth", 1, 8, 1);
    argumentsValue = { path: relativePath, depth };
  } else if (action === "search") {
    operation = "search";
    const query = requiredStringFlag(rest[2], "search query");
    if (Buffer.byteLength(query, "utf8") > 256) throw new CliContractError("query_too_large", "Search query exceeds 256 bytes.");
    argumentsValue = { query, target: "files", mode: "literal", path: ".", include_content: flags["include-content"] === true };
  } else {
    operation = "read_text";
    argumentsValue = { path: safeRelativeProjectPath(requiredStringFlag(rest[2], "relative path")) };
  }
  const result = await requestProjectRemoteOperation({
    client,
    projectId: project.projectId,
    projectKey: project.projectKey,
    source,
    operation,
    arguments: argumentsValue,
    context,
    ...(flags["include-ignored"] === true ? {
      approvedIgnoredRead: {
        path: String(argumentsValue.path),
        chatId: `cli-direct-${randomUUID()}`,
        operationId: `cli-direct-${randomUUID()}`,
      },
    } : {}),
  });
  printProjectFileResult(action, project.projectId, source.source_id, result, flags);
}

class CliContractError extends Error {
  public readonly code: string;

  constructor(code: string, message: string) {
    super(message);
    this.code = code;
    this.name = "CliContractError";
  }
}

function hasExplicitProjectContext(flags: Record<string, string | boolean>): boolean {
  return flags.personal === true || typeof flags.team === "string" || typeof flags["team-id"] === "string";
}

export async function resolveProjectContext(
  client: OpenMatesClient,
  flags: Record<string, string | boolean>,
  requireExplicit: boolean,
): Promise<{ teamId?: string; personal?: boolean }> {
  if (flags.personal === true && (typeof flags.team === "string" || typeof flags["team-id"] === "string")) {
    throw new CliContractError("context_conflict", "Choose either --personal or --team <team>, not both.");
  }
  if (flags.personal === true) return { personal: true };
  const requested = typeof flags.team === "string" ? flags.team : typeof flags["team-id"] === "string" ? flags["team-id"] : null;
  if (requested) {
    const teams = await client.listTeams();
    const matches = [
      ...new Map(
        teams
          .filter((team) => team.team_id === requested || team.slug === requested)
          .map((team) => [team.team_id, team]),
      ).values(),
    ];
    if (matches.length !== 1 || !matches[0]?.team_id) {
      throw new CliContractError(matches.length > 1 ? "ambiguous_team" : "team_not_found", `Team '${requested}' was not found uniquely.`);
    }
    return { teamId: matches[0].team_id };
  }
  if (requireExplicit) throw new CliContractError("context_confirmation_required", "Live file requests require --personal or --team <team>.");
  const activeTeamId = client.getActiveTeamId();
  return activeTeamId ? { teamId: activeTeamId } : { personal: true };
}

function requiredProjectTarget(rest: string[], action: string): string {
  return requiredStringFlag(rest[0], `Project for '${action}'`);
}

function projectToJson(project: DecryptedProject): Record<string, unknown> {
  return {
    project_id: project.projectId,
    short_id: project.projectId.slice(0, 8),
    slug: project.slug || null,
    name: project.name,
    description: project.description,
    icon: project.icon,
    color: project.color,
    pinned: project.pinned,
    archived: project.archived,
    version: project.version,
    mutation_permissions: project.encrypted.mutation_permissions ?? null,
  };
}

function printProjectsOutput(projects: DecryptedProject[], flags: Record<string, string | boolean>): void {
  if (flags.json === true) {
    printJson({ projects: projects.map(projectToJson) });
    return;
  }
  if (projects.length === 0) {
    console.log("No Projects.");
    return;
  }
  for (const project of projects) {
    console.log(`${(project.slug || project.projectId.slice(0, 8)).padEnd(18)}  ${project.name}${project.archived ? "  [archived]" : ""}`);
  }
}

function printProjectOutput(project: DecryptedProject | null, flags: Record<string, string | boolean>): void {
  if (!project) throw new CliContractError("project_decryption_failed", "Project metadata could not be decrypted.");
  const value = projectToJson(project);
  if (flags.json === true) printJson({ project: value });
  else {
    console.log(`${project.name} (${project.slug || project.projectId})`);
    if (project.slug) kv("slug", project.slug);
    kv("project id", project.projectId);
    if (project.description) kv("description", project.description);
    kv("archived", String(project.archived));
    kv("pinned", String(project.pinned));
    const permissions = value.mutation_permissions;
    if (permissions) kv("permissions", JSON.stringify(permissions));
  }
}

async function safeProjectSources(
  client: OpenMatesClient,
  project: DecryptedProject,
  context: { teamId?: string; personal?: boolean },
): Promise<Array<Record<string, unknown>>> {
  return Promise.all((await client.listProjectSources(project.projectId, context)).map(async (source) => ({
    source_id: source.source_id,
    source_type: source.source_type,
    display_name: await decryptOptionalProjectField(source.encrypted_display_name, project.projectKey),
    capabilities: source.capabilities ?? [],
    status: source.status ?? "offline",
    ownership_label: source.ownership_label ?? null,
  })));
}

async function selectProjectSource(
  sources: ProjectSourceRecord[],
  flags: Record<string, string | boolean>,
): Promise<ProjectSourceRecord> {
  const requested = typeof flags.source === "string" ? flags.source : null;
  if (requested) {
    const source = sources.find((candidate) => candidate.source_id === requested);
    if (!source) throw new CliContractError("source_not_found", `Project source '${requested}' was not found.`);
    return source;
  }
  const eligible = sources.filter((source) => source.status === "connected");
  if (eligible.length === 1) return eligible[0];
  if (eligible.length === 0) throw new CliContractError("source_offline", "No online Project source is available.");
  if (flags.json === true || !process.stdin.isTTY) {
    throw new CliContractError("source_selection_required", "Multiple online Project sources require --source <source-id>.");
  }
  console.log("Online Project sources:");
  eligible.forEach((source, index) => console.log(`  ${index + 1}. ${source.source_id}`));
  const selected = Number((await promptLine("Select source number: ")).trim());
  if (!Number.isInteger(selected) || selected < 1 || selected > eligible.length) {
    throw new CliContractError("source_selection_invalid", "Project source selection was invalid.");
  }
  return eligible[selected - 1];
}

function safeRelativeProjectPath(value: string): string {
  const normalized = value.replaceAll("\\", "/");
  if (!normalized || normalized.startsWith("/") || normalized.includes("\0")) {
    throw new CliContractError("invalid_path", "Project file paths must be source-relative.");
  }
  const parts = normalized.split("/");
  if (parts.some((part) => part === "..")) throw new CliContractError("invalid_path", "Project file paths cannot traverse outside the source.");
  return normalized;
}

function parseBoundedInteger(
  value: string | boolean | undefined,
  flag: string,
  minimum: number,
  maximum: number,
  fallback: number,
): number {
  if (value === undefined) return fallback;
  if (typeof value !== "string" || !/^\d+$/.test(value)) throw new CliContractError("invalid_limit", `${flag} must be an integer.`);
  const parsed = Number(value);
  if (parsed < minimum || parsed > maximum) throw new CliContractError("invalid_limit", `${flag} must be between ${minimum} and ${maximum}.`);
  return parsed;
}

export async function requireExactConfirmation(
  label: string,
  exactValue: string,
  flags: Record<string, string | boolean>,
): Promise<void> {
  if (typeof flags.confirm === "string") {
    if (flags.confirm !== exactValue) throw new CliContractError("confirmation_mismatch", `${label} confirmation must exactly match '${exactValue}'.`);
    return;
  }
  if (flags.json === true || !process.stdin.isTTY) throw new CliContractError("confirmation_required", `${label} requires --confirm <exact-id>.`);
  const answer = (await promptLine(`${label}. Type ${exactValue} to continue: `)).trim();
  if (answer !== exactValue) throw new CliContractError("confirmation_cancelled", `${label} cancelled.`);
}

async function promptConfirmation(message: string): Promise<boolean> {
  const answer = (await promptLine(`${message} [y/N] `)).trim().toLowerCase();
  return answer === "y" || answer === "yes";
}

function printProjectItems(folders: Array<Record<string, unknown>>, items: Array<Record<string, unknown>>): void {
  if (folders.length === 0 && items.length === 0) {
    console.log("No Project items.");
    return;
  }
  for (const folder of folders) console.log(`folder  ${String(folder.name || folder.folder_id)}`);
  for (const item of items) console.log(`${String(item.type)}  ${String(item.display_name || item.target_id)}`);
}

function printProjectSources(sources: Array<Record<string, unknown>>): void {
  if (sources.length === 0) {
    console.log("No Project sources.");
    return;
  }
  for (const source of sources) console.log(`${String(source.source_id)}  ${String(source.display_name)}  ${String(source.status)}`);
}

function printProjectFileResult(
  action: string,
  projectId: string,
  sourceId: string,
  result: unknown,
  flags: Record<string, string | boolean>,
): void {
  if (flags.json === true) {
    printJson({ project_id: projectId, source_id: sourceId, operation: action, result });
    return;
  }
  if (action === "read" && result && typeof result === "object" && typeof (result as Record<string, unknown>).content === "string") {
    process.stdout.write(String((result as Record<string, unknown>).content));
    if (!String((result as Record<string, unknown>).content).endsWith("\n")) process.stdout.write("\n");
    return;
  }
  printJson(result);
}

async function handleHistory(
  client: OpenMatesClient,
  subcommand: string | undefined,
  rest: string[],
  flags: Record<string, string | boolean>,
): Promise<void> {
  if (!subcommand || subcommand === "list") {
    const changeSets = await client.listWorkspaceHistory({
      objectType: typeof flags.type === "string" ? flags.type : undefined,
      objectId: typeof flags.id === "string" ? flags.id : undefined,
      limit: typeof flags.limit === "string" ? Number(flags.limit) : undefined,
    });
    if (flags.json === true) printJson({ change_sets: changeSets });
    else {
      for (const item of changeSets) {
        console.log(`${String(item.change_set_id ?? "-")}  ${String(item.namespace ?? "-")}  ${String(item.action_type ?? "-")}  ${String(item.status ?? "-")}`);
      }
    }
    return;
  }
  if (subcommand === "show") {
    const changeSetId = rest[0];
    if (!changeSetId) throw new Error("Missing change set ID. Usage: openmates history show <change-set-id>");
    printJson(await client.getWorkspaceHistory(changeSetId));
    return;
  }
  if (subcommand === "undo") {
    const changeSetId = rest[0];
    if (!changeSetId) throw new Error("Missing change set ID. Usage: openmates history undo <change-set-id>");
    const result = await client.undoWorkspaceHistory(changeSetId);
    if (flags.json === true) printJson(result);
    else {
      console.log(`Undo change set created: ${String((result.change_set as Record<string, unknown> | undefined)?.change_set_id ?? "unknown")}`);
    }
    return;
  }
  throw new Error(`Unknown history command '${subcommand}'. Run 'openmates history --help'.`);
}

