function buyerAddressFromFlags(flags: Record<string, string | boolean>): BuyerAddress | undefined {
  const file = flags["billing-address-file"];
  if (file === undefined) return undefined;
  if (typeof file !== "string" || !file) throw new Error("Provide --billing-address-file <json-file>.");
  let value: unknown;
  try { value = JSON.parse(readFileSync(file, "utf8")); }
  catch { throw new Error("Could not read billing address JSON file."); }
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new Error("Billing address must be a JSON object.");
  const address = value as Record<string, unknown>;
  for (const key of ["name", "street_line_1", "postal_code", "city", "country"]) {
    if (typeof address[key] !== "string" || !(address[key] as string).trim()) {
      throw new Error(`Billing address requires ${key}.`);
    }
  }
  if (!/^[a-zA-Z]{2}$/.test(String(address.country))) throw new Error("Billing address country must be a two-letter country code.");
  return { ...address, country: String(address.country).toUpperCase() } as unknown as BuyerAddress;
}

function publicTeamMember(member: TeamMemberRecord): { user_id: string; hashed_user_id?: string; display_name: string; avatar: string | null; role: string; status: string; joined_at: number | null } {
  return { user_id: member.user_id, hashed_user_id: member.hashed_user_id,
    display_name: member.profile?.display_name ?? "", avatar: member.profile?.avatar ?? null,
    role: member.role, status: member.status ?? "", joined_at: member.joined_at ?? null };
}

async function handleTeams(
  client: OpenMatesClient,
  subcommand: string | undefined,
  rest: string[],
  flags: Record<string, string | boolean>,
): Promise<void> {
  if (!subcommand || subcommand === "help" || flags.help === true) {
    printTeamsHelp();
    return;
  }

  if (rest[0] === "switch-to") {
    await handleSwitchTo(client, subcommand, flags);
    return;
  }

  if (subcommand === "list") {
    const teams = await client.listTeams();
    printTeamsOutput(teams, client.getActiveTeamId(), flags);
    return;
  }

  if (subcommand === "switch") {
    await handleSwitchTo(client, requireTeamId(rest, flags), flags);
    return;
  }

  if (subcommand === "personal") {
    await handleSwitchTo(client, "personal", flags);
    return;
  }

  if (subcommand === "show") {
    const teamId = requireTeamId(rest, flags);
    const team = await client.getTeam(teamId);
    if (flags.json === true) printJson({ team, active_team_id: client.getActiveTeamId() });
    else printTeamRecord(team, client.getActiveTeamId());
    return;
  }

  if (subcommand === "members" || subcommand === "member") {
    const action = rest[0];
    const teamId = requiredStringFlag(rest[1], "<team-id>");
    if (action === "message") {
      const memberHash = requiredStringFlag(rest[2], "<member-hash>");
      const chat = await client.openTeamDirectChat(teamId, memberHash);
      const message = rest.slice(3).join(' ').trim();
      const response = message ? await client.sendMessage({ message, chatId: chat.id, teamId }) : undefined;
      if (flags.json === true) printJson({ chat_id: chat.id, chat, ...(response ? { response } : {}) });
      else console.log(message ? `Message sent in direct chat ${chat.id}` : `Direct chat: ${chat.id}`);
      return;
    }
    if (action === "list") {
      const members = (await client.listTeamMembers(teamId)).map(publicTeamMember);
      if (flags.json === true) printJson({ members });
      else if (!members.length) console.log("No Team members.");
      else for (const member of members) console.log(`${member.display_name || member.user_id}  ${member.role}  ${member.status || ""}  ${member.hashed_user_id || member.user_id}`.trim());
      return;
    }
    if (action === "show") {
      const userId = requiredStringFlag(rest[2], "<member-user-id>");
      const member = publicTeamMember(await client.getTeamMember(teamId, userId));
      if (flags.json === true) printJson({ member });
      else console.log(`${member.display_name || member.user_id}  ${member.role}  ${member.status || ""}  ${member.hashed_user_id || member.user_id}`.trim());
      return;
    }
    throw new Error("Use teams members list, show, or message <team-id> <member-hash> [text].");
  }

  if (subcommand === "profile") {
    const action = rest[0];
    const teamId = requiredStringFlag(rest[1], "<team-id>");
    const identity = await client.whoAmI();
    const ownUserId = requiredStringFlag(typeof identity.id === "string" ? identity.id : undefined, "authenticated user ID");
    if (action === "show" || action === "get") {
      const member = publicTeamMember(await client.getTeamMember(teamId, ownUserId));
      if (flags.json === true) printJson({ member });
      else console.log(`${member.display_name || member.user_id}  ${member.role}  ${member.user_id}`);
      return;
    }
    if (action === "edit") {
      const current = await client.getTeamMember(teamId, ownUserId);
      if (typeof flags.name !== "string" && typeof flags.avatar !== "string") throw new Error("Provide --name or --avatar.");
      const member = publicTeamMember(await client.updateOwnTeamMemberProfile(teamId, {
        display_name: typeof flags.name === "string" ? flags.name : current.profile?.display_name,
        avatar: typeof flags.avatar === "string" ? flags.avatar : current.profile?.avatar,
      }));
      if (flags.json === true) printJson({ member });
      else console.log(`Team profile saved: ${member.display_name || member.user_id}`);
      return;
    }
    throw new Error("Use teams profile show <team-id> or teams profile edit <team-id> [--name <name>] [--avatar <value>].");
  }

  if (subcommand === "create") {
    const name = requiredStringFlag(flags.name, "--name <name>");
    const team = await client.createTeam({
      name,
      description: typeof flags.description === "string" ? flags.description : undefined,
      slug: typeof flags.slug === "string" ? flags.slug : undefined,
    });
    if (flags.switch === true || flags.activate === true) {
      const teamId = team.team_id ?? team.id;
      if (typeof teamId === "string") client.setActiveTeamId(teamId);
    }
    if (flags.json === true) printJson({ team, active_team_id: client.getActiveTeamId() });
    else printTeamRecord(team, client.getActiveTeamId());
    return;
  }

  if (subcommand === "update") {
    const teamId = requireTeamId(rest, flags);
    const patch: Record<string, unknown> = {};
    if (typeof flags.name === "string") patch.name = flags.name;
    if (typeof flags.description === "string") patch.description = flags.description;
    if (typeof flags.slug === "string") patch.slug = flags.slug;
    if (Object.keys(patch).length === 0) throw new Error("Nothing to update. Provide --name, --description, or --slug.");
    const team = await client.updateTeam(teamId, patch);
    if (flags.json === true) printJson({ team });
    else printTeamRecord(team, client.getActiveTeamId());
    return;
  }

  if (subcommand === "profile-image") {
    const action = requiredStringFlag(rest[0], "profile-image action <generated|upload|get>");
    const teamId = requireTeamId(rest.slice(1), flags);
    if (action === "generated") {
      const team = await client.updateTeamGeneratedProfileImage(teamId, {
        iconName: typeof flags.icon === "string" ? flags.icon : typeof flags["icon-name"] === "string" ? flags["icon-name"] : undefined,
        backgroundColor: typeof flags.background === "string" ? flags.background : typeof flags["background-color"] === "string" ? flags["background-color"] : undefined,
      });
      if (flags.json === true) printJson({ team });
      else printTeamRecord(team, client.getActiveTeamId());
      return;
    }
    if (action === "upload") {
      const file = requiredStringFlag(flags.file ?? flags.path ?? rest[2], "--file <path>");
      const result = await client.updateTeamProfileImage(teamId, file);
      if (flags.json === true) printJson(result);
      else console.log(`Team profile image uploaded: ${result.url}`);
      return;
    }
    if (action === "get") {
      const output = requiredStringFlag(flags.output ?? flags.file ?? rest[2], "--output <path>");
      const image = await client.getTeamProfileImage(teamId);
      writeFileSync(output, image.data, { mode: 0o600 });
      if (flags.json === true) printJson({ output, content_type: image.contentType, size_bytes: image.data.byteLength });
      else console.log(`Team profile image written: ${output}`);
      return;
    }
    throw new Error("Unknown team profile-image action. Use generated, upload, or get.");
  }

  if (subcommand === "delete") {
    const teamId = requireTeamId(rest, flags);
    if (flags["email-code"] !== undefined || flags["totp-code"] !== undefined) {
      throw new Error("Team deletion verification codes must be entered through interactive prompts, not command-line flags.");
    }
    if (flags.yes !== true && flags.confirm !== true) throw new Error("Deleting a team requires --yes.");
    const authMethods = await client.getAuthMethodsStatus();
    if (authMethods.has_2fa) {
      const totpCode = await promptLine("Enter 2FA code to delete this team: ");
      await client.verifyTotpForCurrentSession(totpCode);
    } else {
      await client.requestActionEmailCode("delete_team");
      const emailCode = await promptLine("Enter email verification code to delete this team: ");
      await client.verifyActionEmailCode("delete_team", emailCode);
    }
    const result = await client.deleteTeam(teamId);
    if (client.getActiveTeamId() === teamId) client.setActiveTeamId(null);
    if (flags.json === true) printJson(result);
    else console.log(`Team deleted: ${teamId}`);
    return;
  }

  if (subcommand === "invite") {
    const teamId = requireTeamId(rest, flags);
    const input: Record<string, unknown> = {};
    if (typeof flags.email === "string") input.recipient_email = flags.email;
    if (typeof flags.user === "string") input.invitee_user_id = flags.user;
    if (typeof flags["encrypted-recipient-hint"] === "string") input.encrypted_recipient_hint = flags["encrypted-recipient-hint"];
    if (typeof flags["expires-at"] === "string") input.expires_at = Number.parseInt(flags["expires-at"], 10);
    input.role = parseTeamInviteRole(flags.role);
    if (typeof flags.email === "string") await client.getTeam(teamId);
    const invite = await client.createTeamInvite(teamId, input);
    if (flags.json === true) printJson({ invite });
    else printJson(invite);
    return;
  }

  if (subcommand === "accept-invite") {
    const inviteInput = parseTeamInviteInput(requiredStringFlag(flags.invite ?? rest[0], "<invite-id-or-url>"));
    const inviteSecret = typeof flags.key === "string" ? flags.key : inviteInput.inviteSecret;
    const recipientEmail = typeof flags.email === "string" ? flags.email : undefined;
    const result = await client.acceptTeamInvite(inviteInput.inviteId, { inviteSecret, recipientEmail });
    if (flags.json === true) printJson(result);
    else printJson(result);
    return;
  }

  if (subcommand === "decline-invite") {
    const inviteId = requiredStringFlag(flags.invite ?? rest[0], "<invite-id>");
    const result = await client.declineTeamInvite(inviteId, typeof flags.email === "string" ? flags.email : undefined);
    if (flags.json === true) printJson(result);
    else console.log("Team invite declined.");
    return;
  }

  if (subcommand === "access-requests") {
    const teamId = requireTeamId(rest, flags);
    const status = typeof flags.status === "string" ? flags.status : undefined;
    const accessRequests = await client.listTeamAccessRequests(teamId, status);
    if (flags.json === true) printJson({ access_requests: accessRequests });
    else printJson(accessRequests);
    return;
  }

  if (subcommand === "approve-access") {
    const teamId = requireTeamId(rest, flags);
    const accessRequestId = requiredStringFlag(flags.request ?? flags["access-request"] ?? rest[1], "<access-request-id>");
    const encryptedTeamKey = typeof flags["encrypted-team-key"] === "string" ? flags["encrypted-team-key"] : undefined;
    const membership = await client.approveTeamAccessRequest(teamId, accessRequestId, encryptedTeamKey);
    if (flags.json === true) printJson({ membership });
    else printJson(membership);
    return;
  }

  if (subcommand === "reject-access") {
    const teamId = requireTeamId(rest, flags);
    const accessRequestId = requiredStringFlag(flags.request ?? flags["access-request"] ?? rest[1], "<access-request-id>");
    const result = await client.rejectTeamAccessRequest(teamId, accessRequestId);
    if (flags.json === true) printJson(result);
    else console.log(`Team access request rejected: ${accessRequestId}`);
    return;
  }

  if (subcommand === "role") {
    const teamId = requireTeamId(rest, flags);
    const memberUserId = requiredStringFlag(flags.user ?? rest[1], "--user <user-id>");
    const role = parseTeamAssignableRole(flags.role);
    const membership = await client.updateTeamMemberRole(teamId, memberUserId, role);
    if (flags.json === true) printJson({ membership });
    else printJson(membership);
    return;
  }

  if (subcommand === "remove-member") {
    const teamId = requireTeamId(rest, flags);
    const memberUserId = requiredStringFlag(flags.user ?? rest[1], "--user <user-id>");
    const result = await client.removeTeamMember(teamId, memberUserId);
    if (flags.json === true) printJson(result);
    else console.log(`Team member removed: ${memberUserId}`);
    return;
  }

  if (subcommand === "billing") {
    if (rest[0] === "address") {
      const action = rest[1] ?? "show";
      const teamId = requireTeamId(rest.slice(2), flags);
      if (action === "show") printJson({ buyer_address: await client.getBuyerAddress(teamId) });
      else if (action === "set") {
        const address = buyerAddressFromFlags(flags);
        if (!address) throw new Error("Provide --billing-address-file <json-file>.");
        await client.saveBuyerAddress(address, teamId);
        console.log("Team billing address saved.");
      } else if (action === "clear") {
        await client.saveBuyerAddress(null, teamId);
        console.log("Team billing address cleared.");
      } else throw new Error("Use teams billing address show, set or clear.");
      return;
    }
    if (rest[0] === "bank-transfer") {
      const action = rest[1];
      if (action === "create") {
        const teamId = requireTeamId(rest.slice(2), flags);
        const credits = requiredNumberFlag(flags.credits, "--credits <amount>");
        const order = await client.createTeamBankTransferOrder(teamId, credits, buyerAddressFromFlags(flags));
        if (flags.json === true) printJson(order);
        else printBankTransferOrder(order, false);
        return;
      }
      if (action === "status") {
        const teamId = requireTeamId(rest.slice(2), flags);
        const orderId = requiredStringFlag(flags.order ?? rest[3], "<order-id>");
        const status = await client.getTeamBankTransferStatus(teamId, orderId);
        if (flags.json === true) printJson(status);
        else printBankTransferStatus(status, false);
        return;
      }
      if (action === "list") {
        const teamId = requireTeamId(rest.slice(2), flags);
        const orders = await client.listTeamBankTransferOrders(teamId);
        if (flags.json === true) printJson({ orders });
        else printJson(orders);
        return;
      }
      throw new Error("Unknown team billing bank-transfer command. Use create, status, or list.");
    }
    const teamId = requireTeamId(rest, flags);
    const billing = await client.getTeamBilling(teamId);
    if (flags.json === true) printJson({ billing });
    else printJson(billing);
    return;
  }

  if (subcommand === "storage") {
    if (rest[0] === "notice") {
      const teamId = requireTeamId(rest.slice(1), flags);
      const limit = flags.limit === undefined ? 50 : requiredNumberFlag(flags.limit, "--limit <1..100>");
      if (!Number.isInteger(limit) || limit < 1 || limit > 100) throw new Error("--limit must be an integer from 1 to 100");
      const afterUnitId = typeof flags["after-unit-id"] === "string" ? flags["after-unit-id"] : undefined;
      if (afterUnitId && !/^[a-f0-9]{64}$/.test(afterUnitId)) throw new Error("--after-unit-id must be a 64-character storage unit cursor");
      const notice = await client.getTeamStorageNotice(teamId, { limit, afterUnitId });
      if (flags.json === true) printJson(notice);
      else printTeamStorageNotice(notice);
      return;
    }
    const teamId = requireTeamId(rest, flags);
    const storage = await client.getTeamStorage(teamId);
    if (flags.json === true) printJson({ storage });
    else printTeamStorageSummary(storage);
    return;
  }

  if (subcommand === "add-credits") {
    throw new Error("Direct team credit grants are disabled. Use 'openmates teams billing bank-transfer create <team-id> --credits <amount>'.");
  }

  if (subcommand === "usage") {
    const teamId = requireTeamId(rest, flags);
    const usage = await client.listTeamUsage(teamId, typeof flags.user === "string" ? flags.user : undefined);
    if (flags.json === true) printJson({ usage });
    else printJson(usage);
    return;
  }

  if (subcommand === "move") {
    const teamId = requireTeamId(rest, flags);
    const workspaceType = parseWorkspaceMoveType(flags.type ?? rest[1]);
    const objectId = requiredStringFlag(flags.id ?? rest[2], "--id <resource-id>");
    if (flags.yes !== true && flags.confirm !== true) throw new Error("Moving a workspace resource requires --yes.");
    const result = await client.moveWorkspaceToTeam(workspaceType, objectId, teamId);
    if (flags.json === true) printJson(result);
    else console.log(`${workspaceType} moved to team ${teamId}: ${objectId}`);
    return;
  }

  if (subcommand === "export") {
    const teamId = requireTeamId(rest, flags);
    const output = requiredStringFlag(flags.output, "--output <path>");
    const result = await client.exportTeamData(teamId);
    const artifact = result.artifact && typeof result.artifact === "object" ? result.artifact : result;
    writeFileSync(output, `${JSON.stringify(artifact, null, 2)}\n`, { encoding: "utf-8", mode: 0o600 });
    if (flags.json === true) printJson({ ...result, output });
    else console.log(`Team export written: ${output}`);
    return;
  }

  if (subcommand === "import") {
    const file = requiredStringFlag(flags.file ?? rest[0], "--file <path>");
    const artifact = JSON.parse(readFileSync(file, "utf-8")) as Record<string, unknown>;
    let teamId = typeof flags.team === "string" ? flags.team : typeof flags["destination-team"] === "string" ? flags["destination-team"] : undefined;
    if (!teamId && typeof flags["new-team-name"] === "string") {
      const team = await client.createTeam({ name: flags["new-team-name"] });
      teamId = typeof team.team_id === "string" ? team.team_id : typeof team.id === "string" ? team.id : undefined;
    }
    if (!teamId) throw new Error("Team import requires --team <team-id> or --new-team-name <name>.");
    const result = await client.importTeamData(teamId, artifact);
    if (flags.json === true) printJson(result);
    else printJson(result);
    return;
  }

  throw new Error(`Unknown teams command '${subcommand}'. Run 'openmates teams --help'.`);
}

async function handleSwitchTo(
  client: OpenMatesClient,
  target: string | undefined,
  flags: Record<string, string | boolean>,
): Promise<void> {
  if (target === "help" || flags.help === true) {
    printSwitchToHelp();
    return;
  }
  if (!target) {
    const teams = await client.listTeams();
    printSwitchTargets(teams, client.getActiveTeamId(), flags);
    return;
  }

  if (target.toLowerCase() === "personal") {
    client.setActiveTeamId(null);
    if (flags.json === true) printJson({ active_team_id: null, context: "personal", target: "personal" });
    else console.log("Active context: personal");
    return;
  }

  const team = resolveTeamTarget(await client.listTeams(), target);
  const teamId = requiredTeamRecordId(team);
  client.setActiveTeamId(teamId);
  if (flags.json === true) {
    printJson({ active_team_id: teamId, context: "team", target, team });
  } else {
    const label = typeof team.slug === "string" && team.slug ? team.slug : teamId;
    console.log(`Active team: ${label}`);
  }
}

async function handleCredits(client: OpenMatesClient, flags: Record<string, string | boolean>): Promise<void> {
  const activeTeamId = client.getActiveTeamId();
  if (activeTeamId) {
    const billing = await client.getTeamBilling(activeTeamId);
    if (flags.json === true) printJson({ context: "team", active_team_id: activeTeamId, billing });
    else printCreditsSummary("team", activeTeamId, billing);
    return;
  }

  const billing = await client.settingsGet("billing") as Record<string, unknown>;
  if (flags.json === true) printJson({ context: "personal", active_team_id: null, billing });
  else printCreditsSummary("personal", null, billing);
}

function parseTeamInviteInput(value: string): { inviteId: string; inviteSecret: string | null } {
  try {
    const url = new URL(value);
    const inviteId = url.pathname.split("/").filter(Boolean).pop();
    const fragment = new URLSearchParams(url.hash.replace(/^#/, ""));
    if (inviteId) return { inviteId, inviteSecret: fragment.get("key") };
  } catch {
    // Plain invite IDs are still supported for the access-request fallback.
  }
  return { inviteId: value, inviteSecret: null };
}

function requireTeamId(rest: string[], flags: Record<string, string | boolean>): string {
  return requiredStringFlag(flags.team ?? flags["team-id"] ?? rest[0], "--team <team-id>");
}

function printTeamStorageSummary(storage: TeamStorageSummary): void {
  const measuredAt = new Date(storage.measurement_at * 1000).toISOString();
  console.log(`Team storage: ${(storage.total_bytes / 1024 ** 3).toFixed(2)} GiB measured ${measuredAt}`);
  console.log(`Free allowance: ${(storage.free_bytes / 1024 ** 3).toFixed(0)} GiB · ${storage.billable_gib} started excess GiB`);
  console.log(`Weekly quote: ${storage.weekly_cost_credits} team credits (${storage.credits_per_started_excess_gib_per_week} per started excess GiB; Sundays at 03:00 UTC)`);
  if (storage.billing_status === "disabled_pending_validation") console.log("Billing is not yet enabled. This is a price preview, not an invoice.");
  else if (storage.billing_status === "unpaid") console.log("Storage payment is due.");
  else if (storage.billing_status === "manual_review") console.log("Storage payment needs manual review.");
  else console.log("No storage payment is currently due.");
}

function printTeamStorageNotice(notice: TeamStorageNotice): void {
  if (!notice.episode_id) {
    console.log("No active team storage payment notice.");
    return;
  }
  console.log(`Delivered warning rounds: ${notice.warning_count} / 4`);
  if (notice.deadline_at) console.log(`Earliest removal deadline: ${new Date(notice.deadline_at * 1000).toISOString()}`);
  if (notice.manual_review) console.log("Some storage needs manual review and will not be removed automatically.");
  console.log("Affected units:");
  for (const unit of notice.units) console.log(`  ${unit.kind.replaceAll("_", " ")} · ${(unit.bytes / 1024 ** 2).toFixed(1)} MiB · oldest ${new Date(unit.oldest_at * 1000).toISOString()}`);
  if (notice.has_more) console.log(`More affected units available. Next cursor: ${notice.next_after_unit_id ?? "unavailable"}`);
}

function requiredTeamRecordId(team: TeamRecord): string {
  const teamId = typeof team.team_id === "string" ? team.team_id : typeof team.id === "string" ? team.id : "";
  if (!teamId) throw new Error("Team record is missing a team ID.");
  return teamId;
}

function resolveTeamTarget(teams: TeamRecord[], target: string): TeamRecord {
  const matches = [
    ...new Map(
      teams
        .filter((team) => team.team_id === target || team.id === target || team.slug === target)
        .map((team) => [requiredTeamRecordId(team), team]),
    ).values(),
  ];
  if (matches.length === 1) return matches[0];
  if (matches.length > 1) throw new Error(`Team '${target}' is ambiguous.`);
  throw new Error(`Team '${target}' was not found. Run 'openmates switch-to' to see available targets.`);
}

function printSwitchTargets(
  teams: TeamRecord[],
  activeTeamId: string | null,
  flags: Record<string, string | boolean>,
): void {
  if (flags.json === true) {
    printJson({
      active_team_id: activeTeamId,
      targets: [
        { context: "personal", target: "personal", active: activeTeamId === null },
        ...teams.map((team) => ({
          context: "team",
          target: typeof team.slug === "string" && team.slug ? team.slug : requiredTeamRecordId(team),
          team_id: requiredTeamRecordId(team),
          slug: team.slug ?? null,
          active: activeTeamId === requiredTeamRecordId(team),
        })),
      ],
    });
    return;
  }

  header("Available Contexts\n");
  console.log(`${activeTeamId === null ? "*" : " "} personal`);
  for (const team of teams) {
    const teamId = requiredTeamRecordId(team);
    const target = typeof team.slug === "string" && team.slug ? team.slug : teamId;
    const suffix = target === teamId ? "" : ` (${teamId})`;
    console.log(`${activeTeamId === teamId ? "*" : " "} ${target}${suffix}`);
  }
  console.log("\nSwitch with: openmates switch-to <context>");
}

function printCreditsSummary(context: "personal" | "team", teamId: string | null, billing: TeamBillingSummary | Record<string, unknown>): void {
  header("Credits\n");
  kv("Context", context === "personal" ? "personal" : `team ${teamId ?? "unknown"}`);
  const credits = billing.balance_credits ?? billing.credits ?? billing.current_credits;
  if (credits !== undefined) kv("Available", `${credits} credits`);
  else console.log("  Available credits were not included in the API response.");
  const tier = billing.payment_tier ?? billing.tier;
  if (tier !== undefined) kv("Payment tier", String(tier));
}

function requiredStringFlag(value: string | boolean | undefined, label: string): string {
  if (typeof value !== "string" || value.trim().length === 0) throw new Error(`Missing ${label}.`);
  return value.trim();
}

function requiredNumberFlag(value: string | boolean | undefined, label: string): number {
  const raw = requiredStringFlag(value, label);
  const parsed = Number(raw);
  if (!Number.isFinite(parsed) || parsed <= 0) throw new Error(`Invalid ${label}: ${raw}`);
  return parsed;
}

function parseTeamInviteRole(value: string | boolean | undefined): Exclude<TeamRole, "owner"> {
  if (value === undefined || value === false) return "member";
  return parseTeamAssignableRole(value);
}

function parseTeamAssignableRole(value: string | boolean | undefined): Exclude<TeamRole, "owner"> {
  const role = requiredStringFlag(value, "--role <admin|member|viewer>");
  if (role === "admin" || role === "member" || role === "viewer") return role;
  throw new Error("Team role must be admin, member, or viewer.");
}

function parseWorkspaceMoveType(value: string | boolean | undefined): WorkspaceMoveType {
  const type = requiredStringFlag(value, "--type <chat|project|task|plan|workflow>");
  if (type === "chat" || type === "project" || type === "task" || type === "plan" || type === "workflow") return type;
  throw new Error("Workspace type must be chat, project, task, plan, or workflow.");
}

function teamContextFromFlags(flags: Record<string, string | boolean>): { teamId?: string | null; personal?: boolean } {
  if (flags.personal === true) return { personal: true };
  if (typeof flags.team === "string") return { teamId: flags.team };
  if (typeof flags["team-id"] === "string") return { teamId: flags["team-id"] };
  return {};
}

function printTeamsOutput(teams: Array<Record<string, unknown>>, activeTeamId: string | null, flags: Record<string, string | boolean>): void {
  if (flags.json === true) {
    printJson({ teams, active_team_id: activeTeamId });
    return;
  }
  if (teams.length === 0) {
    console.log("No teams.");
    return;
  }
  for (const team of teams) printTeamRecord(team, activeTeamId);
}

function printTeamRecord(team: Record<string, unknown>, activeTeamId: string | null): void {
  const teamId = typeof team.team_id === "string" ? team.team_id : typeof team.id === "string" ? team.id : "unknown";
  const activeMarker = activeTeamId === teamId ? " *" : "";
  console.log(`${teamId}${activeMarker}`);
  if (typeof team.slug === "string") kv("slug", team.slug);
  if (typeof team.role === "string") kv("role", team.role);
  if (typeof team.status === "string") kv("status", team.status);
}

