function taskTitleFromFlagsOrRest(flags: Record<string, string | boolean>, rest: string[]): string {
  const title = typeof flags.title === "string" ? flags.title : rest.join(" ").trim();
  if (!title) throw new Error("Missing task title. Usage: openmates tasks create --title <title>");
  return title;
}

function planTitleFromFlagsOrRest(flags: Record<string, string | boolean>, rest: string[]): string {
  const explicitTitle = typeof flags.title === "string" ? flags.title : rest.join(" ").trim();
  const goal = typeof flags.goal === "string" ? flags.goal.trim() : "";
  const title = explicitTitle || goal.slice(0, 80);
  if (!title) throw new Error("Missing plan title or goal. Usage: openmates plans create --title <title> or --goal <goal>");
  return title;
}

function parseOptionalNumberFlag(value: string | boolean | undefined, flagName: string): number | null | undefined {
  if (value === undefined) return undefined;
  if (value === true || value === false) throw new Error(`${flagName} requires a numeric value.`);
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) throw new Error(`Invalid ${flagName}: ${value}`);
  return parsed;
}

function parsePlanVerificationStatus(
  value: string | boolean | undefined,
  defaultStatus?: UserPlanVerificationStatus,
  required = false,
): UserPlanVerificationStatus | undefined {
  if (value === undefined || value === false) {
    if (defaultStatus) return defaultStatus;
    if (required) throw new Error("Missing --status <proposed|pending|passed|failed|passed_unexpectedly|skipped|skipped_with_reason|not_applicable|waived>.");
    return undefined;
  }
  if (value === true) throw new Error("--status requires a value.");
  const allowed: UserPlanVerificationStatus[] = ["proposed", "pending", "passed", "failed", "passed_unexpectedly", "skipped", "skipped_with_reason", "not_applicable", "waived"];
  if (allowed.includes(value as UserPlanVerificationStatus)) return value as UserPlanVerificationStatus;
  throw new Error(`Unknown plan check status '${value}'. Expected one of: ${allowed.join(", ")}`);
}

function taskAssignFlag(flags: Record<string, string | boolean>): string | undefined {
  return typeof flags.assign === "string" ? flags.assign : typeof flags.assignee === "string" ? flags.assignee : undefined;
}

function labelFlags(flags: Record<string, string | boolean>, ...names: string[]): string[] {
  const keys = names.length > 0 ? names : ["label", "labels", "tag", "tags"];
  return normalizeLabels(keys.flatMap((key) => splitCsvFlag(flags[key])));
}

async function handleRemoteAccess(
  client: OpenMatesClient,
  subcommand: string | undefined,
  rest: string[],
  flags: Record<string, string | boolean>,
): Promise<void> {
  if (!subcommand || subcommand === "help" || flags.help === true) {
    if (subcommand && subcommand !== "help") {
      throw new Error("openmates remote-access does not accept public subcommands. Run 'openmates remote-access --help'.");
    }
    if (rest.length > 0) {
      throw new Error("openmates remote-access uses --path <folder>; positional paths are not supported.");
    }
    if (flags.help === true || subcommand === "help") {
      printRemoteAccessHelp();
      return;
    }

    assertRemoteAccessPublicFlags(flags);
    if (flags["enable-commands"] === true) {
      await ensureRemoteCommandSetupForCli(flags);
    }
    const hostingContext = await resolveRemoteAccessHostingContext(client, flags);
    const hostingFlags = {
      ...flags,
      personal: hostingContext.personal === true,
      ...(hostingContext.teamId ? { team: hostingContext.teamId } : {}),
    };
    const roots = resolveRemoteAccessRoots(typeof flags.path === "string" ? flags.path : undefined);
    const discovery = remoteAccessHostingCandidates(roots, typeof flags.path === "string");
    const candidateRoots = discovery.candidateRoots;
    const masterKey = client.getMasterKeyBytes();
    const projects = await loadProjects(client, masterKey, hostingFlags, hostingContext);
    const bindings = await resolveRemoteAccessBindings(client, masterKey, projects, candidateRoots, hostingFlags, hostingContext);
    if (bindings.length === 0) throw new Error("No Project folders were approved for remote access.");

    const sourceSessionId = randomUUID();
    const controller = new AbortController();
    const stop = () => controller.abort();
    process.once("SIGINT", stop);
    process.once("SIGTERM", stop);
    if (flags.json !== true) {
      console.log(`Remote access connecting ${bindings.length} Project source${bindings.length === 1 ? "" : "s"}.`);
      console.log("Keep this terminal open. For long-running work, start it inside zellij, tmux, or screen.");
      if (discovery.permissionDenied.length > 0) {
        console.warn(`Skipped ${discovery.permissionDenied.length} unreadable folder${discovery.permissionDenied.length === 1 ? "" : "s"}.`);
      }
    }
    try {
      let confirmedTakeover = false;
      while (!controller.signal.aborted) {
        try {
          await runRemoteAccessBridge({
            client,
            sourceSessionId,
            bindings,
            signal: controller.signal,
            confirmedTakeover,
            taskCacheRoot: typeof flags["task-cache"] === "string" ? flags["task-cache"] : undefined,
            onTaskSync: (event) => {
              if (flags.json === true) printJson({ type: "project_task_sync", ...event });
              else if (event.status !== "synced") console.warn(`Task sync: ${event.status}. Pending data will be reconciled automatically.`);
            },
            onLifecycle: (event) => {
              if (flags.json === true) printJson({ type: "remote_access_lifecycle", ...event });
              else if (event.state === "connected") console.log("Remote access connected.");
              else if (event.state === "reconnecting") console.log(`Remote access reconnecting in ${event.delayMs ?? 0}ms.`);
              else if (event.state === "disconnected") console.log("Remote access disconnected.");
            },
          });
          break;
        } catch (error) {
          if (!(error instanceof WebSocketProtocolError) || error.code !== "takeover_confirmation_required") throw error;
          if (flags.json === true || !process.stdin.isTTY) {
            throw new Error("Another remote-access process owns one of these sources; rerun interactively to confirm takeover.");
          }
          const answer = (await promptLine("Another process owns one of these sources. Take over? [y/N] ")).trim().toLowerCase();
          if (answer !== "y" && answer !== "yes") throw new Error("Remote access takeover cancelled.");
          confirmedTakeover = true;
        }
      }
    } finally {
      process.off("SIGINT", stop);
      process.off("SIGTERM", stop);
    }
    return;
  }

  throw new Error("openmates remote-access does not accept public subcommands. Run 'openmates remote-access --help'.");
}

function parsePositiveIntegerFlag(value: string | boolean | undefined, flagName: string): number | undefined {
  if (value === undefined) return undefined;
  if (typeof value !== "string") {
    throw new Error(`${flagName} requires a positive integer value`);
  }
  const parsed = Number.parseInt(value, 10);
  if (!Number.isInteger(parsed) || parsed <= 0 || String(parsed) !== value) {
    throw new Error(`${flagName} must be a positive integer`);
  }
  return parsed;
}

function parseResponseTimeoutMs(flags: Record<string, string | boolean>): number | undefined {
  const seconds = parsePositiveIntegerFlag(flags["response-timeout-seconds"], "--response-timeout-seconds");
  return seconds === undefined ? undefined : seconds * 1000;
}

function assertRemoteAccessPublicFlags(flags: Record<string, string | boolean>): void {
  const internalFlags = ["source-id", "type", "local-only", "encrypted-display-name", "encrypted-metadata"];
  const supplied = internalFlags.filter((name) => flags[name] !== undefined);
  if (supplied.length > 0) {
    throw new Error(`Unsupported remote-access option${supplied.length === 1 ? "" : "s"}: ${supplied.map((name) => `--${name}`).join(", ")}`);
  }
  if (flags["enable-commands"] !== undefined && flags["enable-commands"] !== true) {
    throw new CliContractError("invalid_enable_commands", "--enable-commands does not accept a value.");
  }
}

async function ensureRemoteCommandSetupForCli(flags: Record<string, string | boolean>): Promise<void> {
  const current = inspectRemoteCommandCapability();
  if (!current.supported && flags.json !== true && stdin.isTTY && stdout.isTTY) {
    console.log("Remote commands need a one-time protected Linux host setup. Your operating system may ask for administrator authorization.");
  }
  const result = await ensureRemoteCommandSetup({
    interactive: flags.json !== true && Boolean(stdin.isTTY && stdout.isTTY),
    json: flags.json === true,
  });
  if (result.installed && flags.json !== true) console.log("Remote command protection installed.");
}

async function resolveRemoteAccessHostingContext(
  client: OpenMatesClient,
  flags: Record<string, string | boolean>,
): Promise<{ teamId?: string; personal?: boolean }> {
  if (hasExplicitProjectContext(flags)) return resolveProjectContext(client, flags, true);
  if (flags.json === true || !process.stdin.isTTY) {
    throw new CliContractError("context_confirmation_required", "Remote access hosting requires --personal or --team <team> in non-interactive mode.");
  }
  const activeTeamId = client.getActiveTeamId();
  const currentLabel = activeTeamId ? `Team ${activeTeamId}` : "Personal";
  const answer = (await promptLine(`Host Project sources in ${currentLabel}? [Y/n/change] `)).trim().toLowerCase();
  if (!answer || answer === "y" || answer === "yes") return activeTeamId ? { teamId: activeTeamId } : { personal: true };
  if (answer === "n" || answer === "no" || answer === "cancel") {
    throw new CliContractError("context_confirmation_cancelled", "Remote access context confirmation cancelled.");
  }
  const selected = (await promptLine("Enter 'personal' or a Team ID/slug: ")).trim();
  return selected.toLowerCase() === "personal"
    ? { personal: true }
    : resolveProjectContext(client, { team: selected }, true);
}

async function resolveRemoteAccessBindings(
  client: OpenMatesClient,
  masterKey: Uint8Array,
  projects: DecryptedProject[],
  candidateRoots: string[],
  flags: Record<string, string | boolean>,
  context: { teamId?: string; personal?: boolean },
): Promise<LiveRemoteAccessBinding[]> {
  const sourceCapabilities: ProjectSourceCapability[] = ["read", "search", "import", "write_request"];
  if (inspectRemoteCommandCapability().supported) sourceCapabilities.push("run_command");
  const stored = listRemoteAccessSources();
  const resolved: Array<{ rootPath: string; project: DecryptedProject; sourceId: string }> = [];
  const unresolved: string[] = [];
  for (const rootPath of candidateRoots) {
    const existingSource = stored.find((source) => source.rootPath === rootPath && source.projectId);
    const project = existingSource
      ? projects.find((item) => item.projectId === existingSource.projectId)
      : undefined;
    if (existingSource && project) {
      resolved.push({ rootPath, project, sourceId: existingSource.sourceId });
    } else {
      unresolved.push(rootPath);
    }
  }

  if (unresolved.length > 0) {
    if (flags.json === true || !process.stdin.isTTY) {
      if (flags["write-policy"] === undefined) {
        throw new CliContractError("write_policy_required", "Adding a Project folder requires --write-policy apply_and_show|always_ask in non-interactive mode.");
      }
      if (typeof flags.project !== "string") {
        throw new CliContractError("project_selection_required", "Adding a Project folder requires --project <slug|id|new> in non-interactive mode.");
      }
    }
    const available = projects.filter((project) => !project.archived);
    for (const rootPath of unresolved) {
      let answer = typeof flags.project === "string" ? flags.project.trim() : "";
      if (!answer) {
        console.log(`Choose the OpenMates Project for ${rootPath}:`);
        available.forEach((project, index) => console.log(`  ${index + 1}. ${JSON.stringify(project.name)} (${project.projectId})`));
        console.log("  new. Create a new Project");
        answer = (await promptLine("Project number, 'new', or Enter to cancel: ")).trim();
      }
      const writeMode = await resolveProjectWriteMode(flags, `Choose how OpenMates may change files in ${JSON.stringify(rootPath)}:`);
      let project: DecryptedProject;
      if (answer.toLowerCase() === "new") {
        project = await createEncryptedRemoteAccessProject(client, basename(rootPath), rootPath, writeMode, context);
        available.push(project);
      } else {
        const index = Number(answer) - 1;
        const selected = /^[1-9][0-9]*$/.test(answer) && Number.isSafeInteger(index)
          ? available[index]
          : await tryResolveProject(client, masterKey, answer, flags, context);
        if (!selected) {
          throw new Error("Remote access Project selection cancelled or invalid; no Project was created.");
        }
        project = selected;
        await client.updateProjectSettings(project.projectId, {
          write_mode: writeMode,
          updated_at: nowSeconds(),
        }, context);
      }
      resolved.push({ rootPath, project, sourceId: randomUUID() });
    }
  }

  const bindings: LiveRemoteAccessBinding[] = [];
  for (const item of resolved) {
    await ensureProjectDefaultFocus(client, item.project, context, item.rootPath);
    const sourceType = remoteAccessSourceType(item.rootPath);
    const source = startRemoteAccessSource({
      sourceId: item.sourceId,
      projectId: item.project.projectId,
      rootPath: item.rootPath,
      sourceType,
      displayName: basename(item.rootPath),
    });
    const remoteSources = await client.listProjectSources(item.project.projectId, context);
    const remoteSource = remoteSources.find((entry) => entry.source_id === source.sourceId);
    if (!remoteSource) {
      const timestamp = Math.floor(Date.now() / 1000);
      await client.createProjectSource(item.project.projectId, {
        source_id: source.sourceId,
        source_type: sourceType,
        encrypted_display_name: await encryptWithAesGcmCombined(source.displayName, item.project.projectKey),
        encrypted_metadata: await encryptWithAesGcmCombined(
          JSON.stringify({ root: source.rootPath, binding_root: source.rootPath }),
          item.project.projectKey,
        ),
        capabilities: sourceCapabilities,
        status: "offline",
        created_at: timestamp,
        updated_at: timestamp,
      }, context);
    } else {
      const current = [...(remoteSource.capabilities ?? [])].sort();
      const desired = [...sourceCapabilities].sort();
      if (JSON.stringify(current) !== JSON.stringify(desired)) {
        await client.updateProjectSourceCapabilities(item.project.projectId, source.sourceId, sourceCapabilities, Math.floor(Date.now() / 1000), context);
      }
    }
    bindings.push({ source, projectKey: item.project.projectKey, keyEpoch: 1, ...(context.teamId ? { teamId: context.teamId } : {}) });
  }
  return bindings;
}

async function createEncryptedRemoteAccessProject(
  client: OpenMatesClient,
  name: string,
  rootPath: string,
  writeMode: ProjectWriteMode,
  context: { teamId?: string; personal?: boolean },
): Promise<DecryptedProject> {
  const projectKey = randomBytes(32);
  const projectId = randomUUID();
  const timestamp = Math.floor(Date.now() / 1000);
  const wrapping = await client.projectWrappingKey(context);
  const importedInstructions = readRootProjectInstructions(rootPath);
  const defaultFocus = buildProjectDefaultFocus(
    name,
    importedInstructions?.instructions,
    importedInstructions?.source,
  );
  const payload: ProjectRecord = {
    project_id: projectId,
    encrypted_project_key: wrapping.teamId ? null : await encryptBytesWithAesGcm(projectKey, wrapping.key),
    encrypted_name: await encryptWithAesGcmCombined(name, projectKey),
    encrypted_description: await encryptWithAesGcmCombined("", projectKey),
    encrypted_icon: await encryptWithAesGcmCombined("folder", projectKey),
    encrypted_color: await encryptWithAesGcmCombined("default", projectKey),
    pinned: false,
    archived: false,
    created_at: timestamp,
    updated_at: timestamp,
    last_opened_at: timestamp,
    write_mode: writeMode,
    default_focus_id: defaultFocus.focus_id,
    encrypted_settings: await encryptWithAesGcmCombined(JSON.stringify({ default_focus: defaultFocus }), projectKey),
    key_wrappers: wrapping.teamId ? [{
      key_type: "team",
      hashed_team_id: createHash("sha256").update(wrapping.teamId).digest("hex"),
      team_key_epoch: 1,
      encrypted_project_key: await encryptBytesWithAesGcm(projectKey, wrapping.key),
      wrapper_version: 1,
      created_at: timestamp,
    }] : [],
  };
  await client.createProject(payload, context);
  return {
    projectId,
    slug: "",
    name,
    description: "",
    icon: "folder",
    color: "default",
    pinned: false,
    archived: false,
    version: 1,
    projectKey,
    encrypted: payload,
  };
}

type ProjectWriteMode = "apply_and_show" | "always_ask";

interface ProjectDefaultFocusEnvelope {
  focus_id: string;
  name: string;
  instructions: string;
  source: string;
}

async function decryptProjectDefaultFocus(
  client: OpenMatesClient,
  project: DecryptedProject,
  context: { teamId?: string | null; personal?: boolean },
): Promise<ProjectDefaultFocusEnvelope> {
  return ensureProjectDefaultFocus(client, project, context);
}

async function ensureProjectDefaultFocus(
  client: OpenMatesClient,
  project: DecryptedProject,
  context: { teamId?: string | null; personal?: boolean },
  rootPath?: string,
): Promise<ProjectDefaultFocusEnvelope> {
  const settings = await client.getProjectSettings(project.projectId, context);
  if (!settings.encrypted_settings) {
    const importedInstructions = rootPath ? readRootProjectInstructions(rootPath) : null;
    const focus = buildProjectDefaultFocus(
      project.name,
      importedInstructions?.instructions,
      importedInstructions?.source,
    );
    await client.updateProjectSettings(project.projectId, {
      write_mode: settings.write_mode === "always_ask" ? "always_ask" : "apply_and_show",
      default_focus_id: focus.focus_id,
      encrypted_settings: await encryptWithAesGcmCombined(JSON.stringify({ default_focus: focus }), project.projectKey),
      updated_at: nowSeconds(),
    }, context);
    return focus;
  }
  const plaintext = await decryptWithAesGcmCombined(settings.encrypted_settings, project.projectKey);
  if (!plaintext) throw new CliContractError("project_focus_invalid", "The Project default focus could not be decrypted.");
  try {
    const parsed = JSON.parse(plaintext) as { default_focus?: Partial<ProjectDefaultFocusEnvelope> };
    const focus = parsed.default_focus;
    if (
      !focus
      || typeof focus.focus_id !== "string"
      || !/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(focus.focus_id)
      || typeof focus.name !== "string"
      || typeof focus.instructions !== "string"
      || typeof focus.source !== "string"
    ) {
      throw new Error("invalid default focus");
    }
    return focus as ProjectDefaultFocusEnvelope;
  } catch {
    throw new CliContractError("project_focus_invalid", "The Project encrypted settings do not contain a valid default focus.");
  }
}

export function buildProjectDefaultFocus(
  projectName: string,
  instructions?: string,
  source = "generated",
): ProjectDefaultFocusEnvelope {
  const name = projectName.trim() || "Untitled project";
  return {
    focus_id: randomUUID(),
    name: `Work on ${name}`,
    instructions: instructions?.trim() || `Help with work in ${name}. Follow the user's instructions and the Project's connected source guidance.`,
    source,
  };
}

export function readRootProjectInstructions(rootPath: string): { instructions: string; source: string } | null {
  const entries = readdirSync(rootPath, { withFileTypes: true })
    .filter((entry) => entry.isFile())
    .map((entry) => entry.name);
  for (const canonicalName of ["agents.md", "claude.md"]) {
    const matchingNames = entries
      .filter((entry) => entry.toLocaleLowerCase("en-US") === canonicalName)
      .sort((left, right) => {
        const exactName = canonicalName === "agents.md" ? "AGENTS.md" : "CLAUDE.md";
        if (left === exactName) return -1;
        if (right === exactName) return 1;
        return left.localeCompare(right);
      });
    const source = matchingNames[0];
    if (source) return { instructions: readFileSync(join(rootPath, source), "utf8"), source };
  }
  return null;
}

async function resolveProjectWriteMode(
  flags: Record<string, string | boolean>,
  prompt: string,
): Promise<ProjectWriteMode> {
  const supplied = flags["write-policy"];
  if (typeof supplied === "string") {
    if (supplied === "apply_and_show" || supplied === "always_ask") return supplied;
    throw new CliContractError("invalid_write_policy", "--write-policy must be apply_and_show or always_ask.");
  }
  if (supplied === true) {
    throw new CliContractError("invalid_write_policy", "--write-policy requires apply_and_show or always_ask.");
  }
  if (flags.json === true || !process.stdin.isTTY) {
    throw new CliContractError("write_policy_required", "This operation requires --write-policy apply_and_show|always_ask in non-interactive mode.");
  }
  console.log(prompt);
  console.log("  1. Apply and show changes (recommended)");
  console.log("  2. Always ask before writes");
  const answer = (await promptLine("Write policy (1 or 2): ")).trim().toLowerCase();
  if (answer === "1" || answer === "apply_and_show") return "apply_and_show";
  if (answer === "2" || answer === "always_ask") return "always_ask";
  throw new CliContractError("write_policy_selection_cancelled", "A write policy must be selected; no Project setting was changed.");
}

function parseJsonFlag<T>(value: string, flagName: string): T {
  try {
    return JSON.parse(value) as T;
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid JSON for ${flagName}: ${message}`);
  }
}

async function handleDrafts(
  client: OpenMatesClient,
  subcommand: string | undefined,
  rest: string[],
  flags: Record<string, string | boolean>,
): Promise<void> {
  if (!subcommand || subcommand === "help" || flags.help === true) {
    printDraftsHelp();
    return;
  }
  if (subcommand === "create" || subcommand === "update") {
    const chatId = subcommand === "update"
      ? rest[0]
      : typeof flags.chat === "string" ? flags.chat : undefined;
    const markdown = subcommand === "update" ? rest.slice(1).join(" ").trim() : rest.join(" ").trim();
    if (subcommand === "update" && !chatId) throw new Error("Missing chat ID for draft update.");
    if (!markdown) throw new Error(`Missing draft text for draft ${subcommand}.`);
    const draft = await client.saveDraft({
      chatId,
      markdown,
      preview: typeof flags.preview === "string" ? flags.preview : markdown.slice(0, 160),
    });
    printJson(draft);
    return;
  }
  if (subcommand === "list") {
    const drafts = await client.listDrafts(flags.refresh === true);
    printJson({ drafts });
    return;
  }
  if (subcommand === "get") {
    const chatId = rest[0];
    if (!chatId) throw new Error("Missing chat ID for draft get.");
    printJson({ draft: await client.getDraft(chatId, flags.refresh === true) });
    return;
  }
  if (subcommand === "clear") {
    const chatId = rest[0];
    if (!chatId) throw new Error("Missing chat ID for draft clear.");
    await client.clearDraft(chatId);
    printJson({ success: true, chat_id: chatId });
    return;
  }
  if (subcommand === "sync") {
    printJson({ versions: await client.reconcileDraftVersions() });
    return;
  }
  throw new Error(`Unknown drafts subcommand '${subcommand}'.`);
}

async function handleIdeaBucket(
  client: OpenMatesClient,
  subcommand: string | undefined,
  rest: string[],
  flags: Record<string, string | boolean>,
): Promise<void> {
  if (!subcommand || subcommand === "help" || flags.help === true) {
    printIdeaBucketHelp();
    return;
  }

  if (subcommand === "add") {
    const text = rest.join(" ").trim();
    if (!text) throw new Error("Missing IdeaBucket text for add.");
    const scheduledSendAt = typeof flags["scheduled-at"] === "string"
      ? parseUnixSecondsFlag(flags["scheduled-at"], "--scheduled-at")
      : undefined;
    printJson(await client.addIdeaBucketText({
      text,
      chatId: typeof flags.chat === "string" ? flags.chat : undefined,
      bucketId: typeof flags.bucket === "string" ? flags.bucket : undefined,
      scheduledSendAt,
      prompt: typeof flags.prompt === "string" ? flags.prompt : undefined,
    }));
    return;
  }

  if (subcommand === "audio") {
    const filePath = rest[0];
    if (!filePath) throw new Error("Missing audio file path for IdeaBucket audio.");
    const scheduledSendAt = typeof flags["scheduled-at"] === "string"
      ? parseUnixSecondsFlag(flags["scheduled-at"], "--scheduled-at")
      : undefined;
    printJson(await client.addIdeaBucketAudio({
      filePath,
      chatId: typeof flags.chat === "string" ? flags.chat : undefined,
      bucketId: typeof flags.bucket === "string" ? flags.bucket : undefined,
      scheduledSendAt,
      prompt: typeof flags.prompt === "string" ? flags.prompt : undefined,
    }));
    return;
  }

  if (subcommand === "status") {
    const bucketId = rest[0] ?? (typeof flags.bucket === "string" ? flags.bucket : undefined);
    printJson(await client.getIdeaBucketStatus(bucketId));
    return;
  }

  if (subcommand === "settings") {
    const action = rest[0] ?? "get";
    if (action === "get") {
      printJson(await client.getIdeaBucketSettings());
      return;
    }
    if (action === "set") {
      printJson(await client.saveIdeaBucketSettings({
        processingPrompt: typeof flags.prompt === "string" ? flags.prompt : undefined,
        processingTimes: typeof flags.times === "string" ? flags.times : undefined,
      }));
      return;
    }
    throw new Error(`Unknown ideabucket settings action '${action}'.`);
  }

  if (subcommand === "process") {
    const bucketId = rest[0] ?? (typeof flags.bucket === "string" ? flags.bucket : undefined);
    if (!bucketId) throw new Error("Missing IdeaBucket bucket ID for process.");
    printJson(await client.processIdeaBucketBucket(bucketId, { now: flags.now === true }));
    return;
  }

  throw new Error(`Unknown ideabucket subcommand '${subcommand}'.`);
}

function parseUnixSecondsFlag(value: string, flagName: string): number {
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed <= 0) throw new Error(`Invalid ${flagName}; expected Unix seconds.`);
  return parsed > 10_000_000_000 ? Math.floor(parsed / 1000) : Math.floor(parsed);
}

function parseCredentialEnvironmentMappings(value: string): Record<string, string> {
  const result: Record<string, string> = {};
  for (const entry of value.split(",")) {
    const [target, local, ...extra] = entry.split("=").map((item) => item.trim());
    if (!target || !local || extra.length > 0 || result[target]) throw new CliContractError("invalid_environment_mapping", "--environment must be a comma-separated TARGET=LOCAL_ENV mapping.");
    result[target] = local;
  }
  return result;
}

function escapeTerminalControls(value: string): string {
  // Security boundary: intentionally find raw terminal controls before rendering untrusted text.
  // eslint-disable-next-line no-control-regex
  return value.replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f\u202a-\u202e\u2066-\u2069]/g, (character) => {
    const codePoint = character.codePointAt(0) ?? 0;
    return `\\u${codePoint.toString(16).padStart(4, "0")}`;
  });
}

export function renderProjectWriteApprovalRequest(request: ProjectWriteApprovalRequest): string {
  const mutation = request.mutation;
  const bodyLabel = mutation.operation === "create_file" ? "Content" : "Patch";
  const body = mutation.operation === "create_file" ? mutation.content ?? "" : mutation.patch ?? "";
  return [
    "Project file write requested",
    `Operation: ${mutation.operation}`,
    `Path: ${escapeTerminalControls(mutation.path)}`,
    ...(mutation.expected_base ? [`Expected base: ${mutation.expected_base}`] : []),
    `${bodyLabel}:`,
    escapeTerminalControls(body),
  ].join("\n");
}

export function renderProjectReadApprovalRequest(request: ProjectReadApprovalRequest): string {
  return [
    "Project ignored-file read requested",
    `Path: ${escapeTerminalControls(request.path)}`,
    "This reads only this exact ignored file for the active chat.",
  ].join("\n");
}

export function renderRemoteCommandEvent(event: DecryptedRemoteCommandEvent): string {
  const identity = `${event.execution_id} #${event.sequence}`;
  if (event.event_kind === "output") {
    const raw = typeof event.payload.text === "string" ? event.payload.text : "";
    const limit = 24_000;
    const text = escapeTerminalControls(raw.slice(0, limit));
    const omitted = raw.length > limit ? `\n[${raw.length - limit} characters omitted from this display]` : "";
    return `Unreviewed command output (inert) ${identity}:\n${text}${omitted}`;
  }
  if (event.event_kind === "output_truncated") {
    return `Command output was truncated upstream (${identity}); displayed output does not cover the full process transcript.`;
  }
  if (event.event_kind === "terminal") {
    const safeError = typeof event.payload.error_message === "string" && event.payload.error_message
      ? `: ${escapeTerminalControls(event.payload.error_message.slice(0, 2_000))}`
      : "";
    return `Command ${event.status} (${identity})${safeError}`;
  }
  return `Command ${event.status} (${identity})`;
}

const EXPLICIT_PROJECT_MENTION = /@project:([A-Za-z0-9](?:[A-Za-z0-9_-]|\.(?=[A-Za-z0-9]))*)/gi;

export function extractExplicitProjectMentions(message: string): string[] {
  const matches = Array.from(message.matchAll(EXPLICIT_PROJECT_MENTION), (match) => match[1]);
  const unique = new Map<string, string>();
  for (const target of matches) unique.set(target.toLocaleLowerCase("en-US"), target);
  return [...unique.values()];
}

async function resolveExplicitChatProject(
  client: OpenMatesClient,
  masterKey: Uint8Array,
  message: string,
  flags: Record<string, string | boolean>,
  context: { teamId?: string | null; personal?: boolean },
): Promise<{ message: string; projectId?: string }> {
  const mentions = extractExplicitProjectMentions(message);
  if (mentions.length > 1) {
    throw new CliContractError("project_focus_conflict", "A chat turn can explicitly activate only one Project focus.");
  }
  if (flags.project === true) throw new CliContractError("project_selection_required", "--project requires a Project slug or ID.");
  const flagTarget = typeof flags.project === "string" ? flags.project.trim() : null;
  const mentionTarget = mentions[0] ?? null;
  if (!flagTarget && !mentionTarget) return { message };
  const flagProject = flagTarget
    ? await requiredResolvedProject(client, masterKey, flagTarget, flags, context)
    : null;
  const mentionProject = mentionTarget
    ? await requiredResolvedProject(client, masterKey, mentionTarget, flags, context)
    : null;
  if (flagProject && mentionProject && flagProject.projectId !== mentionProject.projectId) {
    throw new CliContractError("project_focus_conflict", "--project and @project:… must identify the same Project.");
  }
  const project = flagProject ?? mentionProject;
  if (!project) return { message };
  return {
    message: message.replace(EXPLICIT_PROJECT_MENTION, `Project ${JSON.stringify(project.name)}`),
    projectId: project.projectId,
  };
}

// ---------------------------------------------------------------------------
// Chats
// ---------------------------------------------------------------------------

async function handleChats(
  client: OpenMatesClient,
  subcommand: string | undefined,
  rest: string[],
  flags: Record<string, string | boolean>,
  redactor?: OutputRedactor,
): Promise<void> {
  if (!subcommand || subcommand === "help" || flags.help === true) {
    printChatsHelp();
    return;
  }

  const apiKey = resolveApiKey(flags) ?? undefined;
  const teamContext = teamContextFromFlags(flags);

  if (subcommand === "speak") {
    if (apiKey) throw new Error("Chat speech through --api-key is not supported; use an authenticated CLI session.");
    if (!client.hasSession()) throw new Error("Run `openmates login` before generating assistant speech.");
    const chatId = requiredStringFlag(rest[0], "<chat-id>");
    const messageId = typeof flags.message === "string" ? flags.message : undefined;
    const result = await client.generateExistingAssistantSpeech(chatId, { messageId, all: flags.all === true }, teamContext);
    if (flags.json === true) printJson(result);
    else {
      process.stdout.write(`Assistant speech saved for ${result.messages} message(s).\n`);
      process.stdout.write(`Generated ${result.generated_segments}, reused ${result.reused_segments}, failed ${result.failed_segments}.\n`);
    }
    if (result.failed_segments > 0) process.exitCode = 1;
    return;
  }

  if (rest[0] === "add-to-project") {
    if (apiKey) throw new Error("Chat add-to-project through --api-key is not supported by the CLI command; use an authenticated CLI session.");
    const projectId = requiredStringFlag(rest[1], "<project-id>");
    const project = await requiredResolvedProject(client, client.getMasterKeyBytes(), projectId, flags);
    const storageChoice = await resolveAddToProjectStorageChoice(client, project, flags, "chat");
    const result = await client.getChatMessages(subcommand, teamContext);
    const displayName = result.chat.title ?? result.chat.shortId ?? result.chat.id;
    const remoteCopyProposal = storageChoice.targetMode === "save_only_in_openmates"
      ? null
      : buildRemoteCopyProposal({
        objectType: "chat",
        objectId: result.chat.id,
        title: displayName,
        content: buildChatRemoteCopyMarkdown(result.chat, result.messages),
        source: storageChoice.source!,
        targetMode: storageChoice.targetMode,
      });
    const item = await createEncryptedProjectItem(client, project, {
      itemType: "chat",
      targetId: result.chat.id,
      displayName,
      folderId: typeof flags.folder === "string" ? flags.folder : null,
      metadata: { storage: storageChoice.targetMode, source: "cli_add_to_project", remote_copy_proposal: remoteCopyProposal ? { target_path: remoteCopyProposal.target_path, source_id: remoteCopyProposal.source_id } : null },
    });
    printAddToProjectResult({ objectType: "chat", objectId: result.chat.id, projectId: project.projectId, item, targetMode: storageChoice.targetMode, remoteCopyProposal }, flags);
    return;
  }

  if (rest[0] === "remove-from-project") {
    if (apiKey) throw new Error("Chat remove-from-project through --api-key is not supported by the CLI command; use an authenticated CLI session.");
    const projectId = requiredStringFlag(rest[1], "<project-id>");
    const project = await requiredResolvedProject(client, client.getMasterKeyBytes(), projectId, flags);
    const result = await client.getChatMessages(subcommand, teamContext);
    const removed = await client.deleteProjectItemByTarget(project.projectId, "chat", result.chat.id);
    printRemoveFromProjectResult({ objectType: "chat", objectId: result.chat.id, projectId: project.projectId, deleted: removed.deleted, deletedCount: removed.deleted_count }, flags);
    return;
  }

  if (rest[0] === "tasks") {
    await handleTasks(client, rest[1], rest.slice(2), { ...flags, chat: subcommand }, redactor);
    return;
  }

  if (rest[0] === "plans") {
    await handlePlans(client, rest[1], rest.slice(2), { ...flags, chat: subcommand }, redactor);
    return;
  }

  if (subcommand === "list") {
    const limit =
      typeof flags.limit === "string" ? parseInt(flags.limit, 10) : 10;
    const page = typeof flags.page === "string" ? parseInt(flags.page, 10) : 1;
    const result = apiKey
      ? await listApiKeyChats(client, apiKey, limit, page)
      : client.hasSession()
        ? await client.listChats(limit, page, teamContext)
        : listExampleChats(limit, page);
    if (flags.json === true) {
      printJson(result);
    } else {
      printChatsTable(result);
    }
    return;
  }

  if (subcommand === "search") {
    const query = rest.join(" ").trim();
    if (!query)
      throw new Error(
        "Missing search query. Usage: openmates chats search <query>",
      );
    const result = apiKey
      ? await searchApiKeyChats(client, apiKey, query)
      : client.hasSession()
        ? await client.searchChats(query, teamContext)
        : searchExampleChats(query);
    if (flags.json === true) {
      printJson(result);
    } else {
      printChatsTable({
        chats: result,
        total: result.length,
        page: 1,
        limit: result.length,
        hasMore: false,
      });
    }
    return;
  }

  if (subcommand === "files") {
    const chatId = rest[0];
    if (!chatId) {
      throw new Error("Missing chat ID. Usage: openmates chats files <chat-id> [--json]");
    }
    const resolvedId = chatId.toLowerCase() === "last" ? "__last__" : chatId;
    if (apiKey) {
      throw new Error("Chat file listing through --api-key is not supported; use an authenticated CLI session so encrypted chat embeds can be decrypted locally.");
    }

    if (!client.hasSession()) {
      const example = resolveExampleChatForOpen(resolvedId === "__last__" ? "1" : resolvedId);
      if (!example) {
        throw new Error(`Example chat '${chatId}' not found. Run 'openmates chats list' to see available examples.`);
      }
      printChatFiles(example.chat, example.files, flags, { example: true });
      return;
    }

    const { chat, messages } = await client.getChatMessages(resolvedId, teamContext);
    const result = await loadChatFileReferencesForCli(client, messages);
    printChatFiles(chat, result.files, flags, { errors: result.errors });
    return;
  }

  if (subcommand === "messages") {
    const chatId = rest[0];
    if (!chatId) {
      throw new Error("Missing chat ID. Usage: openmates chats messages <chat-id> [--json]");
    }
    const resolvedId = chatId.toLowerCase() === "last" ? "__last__" : chatId;
    const result = apiKey
      ? await createCliOpenMates(client, apiKey).chats.messages({
          chatId: resolvedId === "__last__"
            ? String((await createCliOpenMates(client, apiKey).chats.list({ limit: 1 }))[0]?.id ?? "")
            : resolvedId,
        })
      : await client.getChatMessageSummaries(resolvedId, teamContext);
    if (flags.json === true) {
      printJson(result);
    } else {
      printChatMessagesTable(result.chat as ChatListItem, result.messages as Array<DecryptedMessage & { preview?: string }>);
    }
    return;
  }

  if (subcommand === "fork") {
    const chatId = rest[0];
    const fromMessageId = typeof flags["from-message"] === "string" ? flags["from-message"] : undefined;
    if (!chatId || !fromMessageId) {
      throw new Error("Missing fork target. Usage: openmates chats fork <chat-id> --from-message <message-id> [--title <title>] [--json]");
    }
    const result = apiKey
      ? await createCliOpenMates(client, apiKey).chats.fork({
          chatId,
          fromMessageId,
          title: typeof flags.title === "string" ? flags.title : undefined,
        })
      : await client.forkChat({
          chatId,
          fromMessageId,
          title: typeof flags.title === "string" ? flags.title : undefined,
          ...teamContext,
        });
    if (flags.json === true) {
      printJson(result);
    } else {
      process.stdout.write(`Forked chat ${String(result.chat_id)} (${String(result.copied_message_count)} messages copied)\n`);
    }
    return;
  }

  if (subcommand === "rewind") {
    const chatId = rest[0];
    const toMessageId = typeof flags["to-message"] === "string" ? flags["to-message"] : undefined;
    if (!chatId || !toMessageId) {
      throw new Error("Missing rewind target. Usage: openmates chats rewind <chat-id> --to-message <message-id> [--send <prompt>] [--dry-run] [--yes] [--json]");
    }
    const dryRun = flags["dry-run"] === true || flags.yes !== true;
    const send = typeof flags.send === "string" ? flags.send : undefined;
    const result = apiKey
      ? await createCliOpenMates(client, apiKey).chats.rewind({
          chatId,
          toMessageId,
          send,
          dryRun,
          confirmDestructive: flags.yes === true,
        })
      : await client.rewindChat({
          chatId,
          toMessageId,
          send,
          dryRun,
          confirmDestructive: flags.yes === true,
          responseTimeoutMs: parseResponseTimeoutMs(flags),
          ...teamContext,
        });
    if (flags.json === true) {
      printJson(result);
    } else {
      printChatRewindResult(result);
    }
    return;
  }

  if (subcommand === "retry") {
    const chatId = rest[0];
    if (!chatId) {
      throw new Error("Missing chat ID. Usage: openmates chats retry <chat-id> [--dry-run] [--yes] [--json]");
    }
    const dryRun = flags["dry-run"] === true || flags.yes !== true;
    const result = apiKey
      ? await createCliOpenMates(client, apiKey).chats.retry({
          chatId,
          dryRun,
          confirmDestructive: flags.yes === true,
        })
      : await client.retryChat({
          chatId,
          dryRun,
          confirmDestructive: flags.yes === true,
          responseTimeoutMs: parseResponseTimeoutMs(flags),
          ...teamContext,
        });
    if (flags.json === true) {
      printJson(result);
    } else {
      printChatRewindResult(result);
    }
    return;
  }

  if (subcommand === "new") {
    let message = rest.join(" ").trim();
    if (!message)
      throw new Error(
        "Missing message text. Usage: openmates chats new <message>",
      );
    const hasProjectSelection = flags.project !== undefined || extractExplicitProjectMentions(message).length > 0;
    if (apiKey && hasProjectSelection) {
      throw new Error("Project focus through --api-key is not supported; use an authenticated CLI session.");
    }
    if (!client.hasSession() && hasProjectSelection) {
      throw new Error("Project focus requires an authenticated CLI session.");
    }
    const projectSelection = client.hasSession()
      ? await resolveExplicitChatProject(client, client.getMasterKeyBytes(), message, flags, teamContext)
      : { message, projectId: undefined };
    message = projectSelection.message;
    const projectId = projectSelection.projectId;
    const result = apiKey
      ? await sendApiKeyChatNew(client, apiKey, message, flags)
      : await sendMessageStreaming(
          client,
          {
            message,
            chatId: undefined,
            projectId,
            slug: typeof flags.slug === "string" ? flags.slug : undefined,
            incognito: false,
            json: flags.json === true,
            autoApproveSubChats: flags["auto-approve"] === true,
            autoApproveMemories: flags["auto-approve-memories"] === true,
            acceptTaskProposals: flags["accept-task-proposals"] === true,
            piiDetection: flags["no-pii-detection"] !== true,
            taskUpdateJobs: flags["no-task-update-jobs"] !== true,
            responseTimeoutMs: parseResponseTimeoutMs(flags),
            ...teamContext,
            anonymousLearningMode: client.hasSession() ? undefined : parseAnonymousLearningModeFlags(flags),
          },
          redactor,
        );
    if (flags.json === true) printJson(result);
    return;
  }

  if (subcommand === "send") {
    const chatId = typeof flags.chat === "string" ? flags.chat : undefined;
    let message = rest.join(" ").trim();

    // --followup <n>: pick the nth follow-up suggestion for this chat instead
    // of requiring the user to retype the full text.
    // Requires --chat <id> because suggestions are stored per-chat.
    if (
      typeof flags.followup === "string" ||
      typeof flags.followup === "boolean"
    ) {
      const rawN =
        typeof flags.followup === "string" ? flags.followup : rest[0];
      const n = parseInt(String(rawN), 10);
      if (!chatId) {
        console.error(
          "--followup requires --chat <id> so the chat's suggestions can be loaded.\n" +
            "Usage: openmates chats send --chat <id> --followup <n>",
        );
        process.exit(1);
      }
      if (isNaN(n) || n < 1) {
        console.error(
          `Invalid --followup value '${rawN}'. Must be a positive integer (1, 2, 3, ...).`,
        );
        process.exit(1);
      }

      // Resolve the full chat ID first so getChatFollowUpSuggestions can match it.
      const fullId = await client
        .resolveFullChatId(chatId, teamContext)
        .catch(() => undefined);
      if (!fullId) {
        console.error(
          `Chat '${chatId}' not found. Run 'openmates chats list' to see available chats.`,
        );
        process.exit(1);
      }

      const suggestions = await client.getChatFollowUpSuggestions(fullId, teamContext);
      if (suggestions.length === 0) {
        console.error(
          `No follow-up suggestions stored for chat '${chatId}'.\n` +
            "Suggestions are generated by the AI after your conversation and may take a moment to arrive.\n" +
            "Run 'openmates chats show " +
            chatId +
            "' to check if suggestions have been saved.",
        );
        process.exit(1);
      }
      if (n > suggestions.length) {
        console.error(
          `Follow-up #${n} not found — chat '${chatId}' has ${suggestions.length} suggestion${suggestions.length !== 1 ? "s" : ""}.\n`,
        );
        for (let i = 0; i < suggestions.length; i++) {
          process.stderr.write(`  ${i + 1}. ${suggestions[i]}\n`);
        }
        process.exit(1);
      }

      message = suggestions[n - 1];
      if (!flags.json) {
        process.stderr.write(
          `\x1b[2mUsing follow-up #${n}: "${message}"\x1b[0m\n`,
        );
      }
    }

    if (!message) {
      throw new Error(
        "Missing message text.\n" +
          "Usage: openmates chats send [--chat <id>] <message>\n" +
          "   or: openmates chats send --chat <id> --followup <n>",
      );
    }

    if (apiKey && (flags.project !== undefined || extractExplicitProjectMentions(message).length > 0)) {
      throw new Error("Project focus through --api-key is not supported; use an authenticated CLI session.");
    }
    const projectSelection = await resolveExplicitChatProject(client, client.getMasterKeyBytes(), message, flags, teamContext);
    message = projectSelection.message;
    const projectId = projectSelection.projectId;
    const result = await sendMessageStreaming(
      client,
      {
        message,
        chatId,
        projectId,
        slug: chatId ? undefined : typeof flags.slug === "string" ? flags.slug : undefined,
        incognito: flags.incognito === true,
        json: flags.json === true,
        autoApproveSubChats: flags["auto-approve"] === true,
        autoApproveMemories: flags["auto-approve-memories"] === true,
        acceptTaskProposals: flags["accept-task-proposals"] === true,
        piiDetection: flags["no-pii-detection"] !== true,
        taskUpdateJobs: flags["no-task-update-jobs"] !== true,
        responseTimeoutMs: parseResponseTimeoutMs(flags),
        ...teamContext,
      },
      redactor,
    );
    if (flags.json === true) printJson(result);
    return;
  }

  if (subcommand === "answer-interactive") {
    const chatId = typeof flags.chat === "string" ? flags.chat : undefined;
    const questionJson = typeof flags["question-json"] === "string" ? flags["question-json"] : undefined;
    const answerJson = typeof flags["answer-json"] === "string" ? flags["answer-json"] : undefined;

    if (!chatId || !questionJson || !answerJson) {
      throw new Error(
        "Missing interactive answer data. Usage: openmates chats answer-interactive --chat <id> --question-json '<json>' --answer-json '<json>'",
      );
    }

    const question = parseJsonFlag<InteractiveQuestionPayload>(questionJson, "--question-json");
    const answer = parseJsonFlag<InteractiveQuestionAnswer>(answerJson, "--answer-json");
    const formatted = formatInteractiveQuestionAnswer(question, answer);
    const result = await sendMessageStreaming(
      client,
      {
        message: formatted.messageContent,
        chatId,
        incognito: false,
        json: flags.json === true,
        autoApproveSubChats: flags["auto-approve"] === true,
        autoApproveMemories: flags["auto-approve-memories"] === true,
        acceptTaskProposals: flags["accept-task-proposals"] === true,
        piiDetection: flags["no-pii-detection"] !== true,
        responseTimeoutMs: parseResponseTimeoutMs(flags),
        ...teamContext,
      },
      redactor,
    );
    if (flags.json === true) printJson(result);
    return;
  }

  if (subcommand === "incognito") {
    const message = rest.join(" ").trim();
    if (!message)
      throw new Error(
        "Missing message text. Usage: openmates chats incognito <message>",
      );
    const result = await sendMessageStreaming(
      client,
      {
        message,
        incognito: true,
        json: flags.json === true,
        autoApproveSubChats: flags["auto-approve"] === true,
        autoApproveMemories: flags["auto-approve-memories"] === true,
        piiDetection: flags["no-pii-detection"] !== true,
        responseTimeoutMs: parseResponseTimeoutMs(flags),
      },
      redactor,
    );
    if (flags.json === true) printJson(result);
    return;
  }

  if (subcommand === "incognito-history") {
    printIncognitoNoHistoryNotice(flags.json === true);
    return;
  }

  if (subcommand === "incognito-clear") {
    printIncognitoNoHistoryNotice(flags.json === true);
    return;
  }

	if (subcommand === "show") {
		const chatId = rest[0];
		if (!chatId) {
			console.error("Missing chat ID.\n");
			printChatsHelp();
			process.exit(1);
		}
		// "last" opens the most recently modified chat
		const resolvedId = chatId.toLowerCase() === "last" ? "__last__" : chatId;
		const showAllMessages = flags.all === true;
		if (apiKey) {
			const sdk = createCliOpenMates(client, apiKey);
			const sdkChatId = resolvedId === "__last__"
				? (await sdk.chats.list({ limit: 1 }))[0]?.id
				: resolvedId;
			if (!sdkChatId) {
				throw new Error("No chats found for API key session.");
			}
			const loaded = showAllMessages
				? await sdk.chats.load(sdkChatId)
				: await sdk.chats.messages({ chatId: sdkChatId, limit: 30 });
			const apiKeyHasMoreBefore = (loaded as { hasMoreBefore?: boolean }).hasMoreBefore === true;
			const { chat, messages, followUpSuggestions } = normalizeApiKeyLoadedChat(loaded as Record<string, unknown>);
			if (flags.json === true) {
				printJson({
					chat,
					messages,
					follow_up_suggestions: followUpSuggestions,
					...(showAllMessages ? {} : { has_more_before: apiKeyHasMoreBefore }),
				});
			} else {
				await printChatConversationRaw(chat, messages);
				if (!showAllMessages && apiKeyHasMoreBefore) {
					process.stdout.write("\nShowing latest 30 messages. Use --all for full history.\n");
				}
			}
			return;
		}
		if (!client.hasSession()) {
			const example = resolveExampleChatForOpen(resolvedId === "__last__" ? "1" : resolvedId);
			if (!example) {
        console.error(
          `Example chat '${chatId}' not found. Run 'openmates chats list' to see available examples.`,
        );
        process.exit(1);
      }
      if (flags.json === true) {
        printJson({
          chat: example.chat,
          messages: example.messages,
          follow_up_suggestions: example.followUpSuggestions,
        });
      } else if (flags.raw === true) {
        await printChatConversationRaw(example.chat, example.messages, { example: true });
      } else {
        await printChatConversation(client, example.chat, example.messages, example.followUpSuggestions, { example: true });
      }
      return;
    }
    const messageResult = showAllMessages
      ? await client.getChatMessages(resolvedId, teamContext)
      : await client.getChatMessagesWindow(resolvedId, { ...teamContext, limit: 30 });
    const { chat, messages } = messageResult;
    if (flags.json === true) {
      // Fetch follow-up suggestions for JSON output too
      const followUpSuggestions = await client
        .getChatFollowUpSuggestions(chat.id, teamContext)
        .catch(() => [] as string[]);
      printJson({
        chat,
        messages,
        follow_up_suggestions: followUpSuggestions,
        ...(showAllMessages || !("hasMoreBefore" in messageResult) ? {} : { has_more_before: messageResult.hasMoreBefore }),
      });
    } else if (flags.raw === true) {
      await printChatConversationRaw(chat, messages);
      if (!showAllMessages && "hasMoreBefore" in messageResult && messageResult.hasMoreBefore) {
        process.stdout.write("\nShowing latest 30 messages. Use --all for full history.\n");
      }
    } else {
      // Fetch follow-up suggestions to display at the end of the conversation
      const followUpSuggestions = await client
        .getChatFollowUpSuggestions(chat.id, teamContext)
        .catch(() => [] as string[]);
      await printChatConversation(client, chat, messages, followUpSuggestions);
      if (!showAllMessages && "hasMoreBefore" in messageResult && messageResult.hasMoreBefore) {
        process.stdout.write("\nShowing latest 30 messages. Use --all for full history.\n");
      }
    }
    return;
  }

  if (subcommand === "delete") {
    // Collect IDs from positional args
    const chatIds = rest.filter((arg) => arg.length > 0);
    if (chatIds.length === 0) {
      throw new Error(
        "Missing chat IDs. Usage: openmates chats delete <id1> [id2] [id3] ...",
      );
    }

    // Resolve titles only for the interactive confirmation prompt. --yes is
    // commonly used in automation and should go straight to the delete path.
    const resolved: Array<{ input: string; title: string | null }> = [];
    if (flags.yes === true) {
      for (const id of chatIds) resolved.push({ input: id, title: null });
    } else {
      for (const id of chatIds) {
        try {
          const { chat } = await client.getChatMessages(id, teamContext);
          resolved.push({ input: id, title: chat.title ?? null });
        } catch {
          resolved.push({ input: id, title: null });
        }
      }
    }

    if (flags.yes !== true) {
      // Show what will be deleted and ask for confirmation
      process.stdout.write("\nChats to delete:\n");
      for (const r of resolved) {
        const label = r.title ? `"${r.title}"` : "(unable to resolve title)";
        process.stdout.write(`  \x1b[31m\u2717\x1b[0m ${r.input}  ${label}\n`);
      }
      process.stdout.write("\n");

      const rl = await import("node:readline");
      const iface = rl.createInterface({
        input: process.stdin,
        output: process.stdout,
      });
      const answer = await new Promise<string>((resolve) => {
        iface.question(
          `Delete ${resolved.length} chat(s)? This cannot be undone. [y/N] `,
          resolve,
        );
      });
      iface.close();

      if (answer.trim().toLowerCase() !== "y") {
        console.log("Aborted.");
        return;
      }
    }

    // Delete each chat
    let deleted = 0;
    for (const r of resolved) {
      try {
        if (apiKey) {
          await createCliOpenMates(client, apiKey).chats.delete(
            r.input,
            { confirmed: true },
          );
        } else {
          await client.deleteChat(r.input, teamContext);
        }
        const label = r.title ? `"${r.title}"` : r.input;
        process.stdout.write(`  \x1b[32m\u2713\x1b[0m Deleted ${label}\n`);
        deleted++;
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        process.stdout.write(
          `  \x1b[31m\u2717\x1b[0m Failed to delete ${r.input}: ${msg}\n`,
        );
      }
    }
    console.log(`\n${deleted}/${resolved.length} chat(s) deleted.`);
    return;
  }

  if (subcommand === "download") {
    const chatId = rest[0];
    if (!chatId) {
      console.error("Missing chat ID.\n");
      printChatsHelp();
      process.exit(1);
    }
    const resolvedId = chatId.toLowerCase() === "last" ? "__last__" : chatId;
    const { chat, messages } = await client.getChatMessages(resolvedId, teamContext);

    // Determine output directory
    const outputDir =
      typeof flags.output === "string" ? flags.output : process.cwd();
    const useZip = flags.zip === true;

    // Generate filename base (same pattern as web app: YYYY-MM-DD_HH-MM-SS_title)
    const timestampMs =
      chat.updatedAt && chat.updatedAt < 1e12
        ? chat.updatedAt * 1000
        : (chat.updatedAt ?? Date.now());
    const dateStr = new Date(timestampMs)
      .toISOString()
      .slice(0, 19)
      .replace(/[:-]/g, "-")
      .replace("T", "_");
    const safeTitle = (chat.title ?? "Untitled Chat")
      .replace(/[<>:"/\\|?*]/g, "")
      .substring(0, 50)
      .trim();
    const filenameBase = `${dateStr}_${safeTitle}`;

    // Build YAML content (mirrors chatExportService.convertChatToYaml)
    const yamlChat: Record<string, unknown> = {
      title: chat.title ?? null,
      exported_at: new Date().toISOString(),
      message_count: messages.length,
      summary: chat.summary ?? null,
    };
    const yamlMessages: Record<string, unknown>[] = [];
    for (const msg of messages) {
      const msgTimestampMs =
        msg.createdAt < 1e12 ? msg.createdAt * 1000 : msg.createdAt;
      yamlMessages.push({
        role: msg.role,
        sender:
          msg.senderName ??
          (msg.role === "user" ? "You" : (msg.category ?? "Assistant")),
        model: msg.modelName ?? null,
        timestamp: new Date(msgTimestampMs).toISOString(),
        content: msg.content,
      });
    }
    // Simple YAML serialization (no external dependency)
    const yamlContent = serializeToYaml({
      chat: yamlChat,
      messages: yamlMessages,
    });

    // Build Markdown content (mirrors zipExportService.convertChatToMarkdown)
    let mdContent = "";
    if (chat.title) mdContent += `# ${chat.title}\n\n`;
    mdContent += `*Created: ${new Date(timestampMs).toISOString()}*\n\n---\n\n`;
    for (const msg of messages) {
      const msgTimestampMs =
        msg.createdAt < 1e12 ? msg.createdAt * 1000 : msg.createdAt;
      const role =
        msg.role === "user" ? "You" : (msg.senderName ?? "Assistant");
      mdContent += `## ${role} - ${new Date(msgTimestampMs).toISOString()}\n\n`;
      // Strip embed JSON blocks from markdown output, keep surrounding text
      const cleaned = msg.content.replace(
        /```(?:json_embed|json)\n[\s\S]*?\n```/g,
        "",
      );
      if (cleaned.trim()) mdContent += `${cleaned.trim()}\n\n`;
    }

    // Extract code embeds and video transcript embeds from messages
    const codeEmbeds: Array<{
      embedId: string;
      language: string;
      filename?: string;
      content: string;
      filePath?: string;
    }> = [];
    const transcriptEmbeds: Array<{
      embedId: string;
      filename: string;
      content: string;
    }> = [];
    const diagramEmbeds: Array<{ embedId: string; content: string }> = [];
    const processedEmbedIds = new Set<string>();

    // Collect all embed IDs from messages
    const allEmbedIds: string[] = [];
    for (const msg of messages) {
      const segments = parseMessageSegments(msg.content);
      for (const seg of segments) {
        if (seg.type === "embed" && !processedEmbedIds.has(seg.value)) {
          processedEmbedIds.add(seg.value);
          allEmbedIds.push(seg.value);
        }
      }
    }

    // Process embeds (code + transcripts) with recursive child embed handling
    const embedQueue = [...allEmbedIds];
    while (embedQueue.length > 0) {
      const eid = embedQueue.shift()!;
      try {
        const embed = await client.getEmbed(eid);

        if ((embed.type === "diagram_html" || embed.type === "diagrams-html")
          && typeof embed.content?.html_source === "string" && embed.content.html_source) {
          diagramEmbeds.push({ embedId: embed.embedId, content: embed.content.html_source });
        }

        // Code embeds
        if (embed.type === "code" && embed.content) {
          const code =
            typeof embed.content.code === "string"
              ? embed.content.code
              : typeof embed.content.content === "string"
                ? (embed.content.content as string)
                : null;
          if (code) {
            codeEmbeds.push({
              embedId: embed.embedId,
              language:
                typeof embed.content.language === "string"
                  ? embed.content.language
                  : "text",
              filename:
                typeof embed.content.filename === "string"
                  ? embed.content.filename
                  : undefined,
              content: code,
              filePath:
                typeof embed.content.file_path === "string"
                  ? embed.content.file_path
                  : undefined,
            });
          }
        }

        // Video transcript embeds
        if (
          embed.type === "app_skill_use" &&
          embed.appId === "videos" &&
          (embed.skillId === "get_transcript" ||
            embed.skillId === "get-transcript") &&
          embed.content
        ) {
          const results = (embed.content.results ??
            embed.content.data ??
            []) as Array<Record<string, unknown>>;
          if (Array.isArray(results) && results.length > 0) {
            let text = "";
            for (const r of results) {
              const meta = r.metadata as
                | Record<string, unknown>
                | undefined;
              if (meta?.title) text += `# ${meta.title}\n\n`;
              if (r.url) text += `Source: ${r.url}\n\n`;
              text += String(
                r.transcript ??
                  r.formatted_transcript ??
                  r.text ??
                  r.content ??
                  "",
              );
              text += "\n\n---\n\n";
            }
            let fname = `${eid.slice(0, 8)}_transcript.md`;
            const firstMeta = (results[0]?.metadata as
              | Record<string, unknown>
              | undefined);
            if (firstMeta?.title) {
              fname = `${String(firstMeta.title).replace(/[^a-z0-9]/gi, "_").toLowerCase()}_transcript.md`;
            }
            transcriptEmbeds.push({
              embedId: eid,
              filename: fname,
              content: text,
            });
          }
        }

        // Queue child embeds for processing
        if (embed.content?.embed_ids) {
          const childIds = Array.isArray(embed.content.embed_ids)
            ? (embed.content.embed_ids as string[])
            : typeof embed.content.embed_ids === "string"
              ? embed.content.embed_ids.split("|").filter(Boolean)
              : [];
          for (const childId of childIds) {
            if (!processedEmbedIds.has(childId)) {
              processedEmbedIds.add(childId);
              embedQueue.push(childId);
            }
          }
        }
      } catch {
        // Embed not in cache — skip
      }
    }

    // Write files
    const { mkdir, writeFile } = await import("node:fs/promises");
    const { join } = await import("node:path");

    if (useZip) {
      // Zip mode — create temp directory, then shell out to system zip
      const tmpDir = join(outputDir, `.${filenameBase}_tmp`);
      await mkdir(tmpDir, { recursive: true });
      await writeFile(join(tmpDir, `${filenameBase}.yml`), yamlContent);
      await writeFile(join(tmpDir, `${filenameBase}.md`), mdContent);
      if (codeEmbeds.length > 0) {
        for (const ce of codeEmbeds) {
          const fpath =
            ce.filePath ??
            ce.filename ??
            `${ce.embedId.slice(0, 8)}.${getExtForLang(ce.language)}`;
          const fullPath = join(tmpDir, "code", fpath);
          await mkdir(fullPath.substring(0, fullPath.lastIndexOf("/")), {
            recursive: true,
          });
          await writeFile(fullPath, ce.content);
        }
      }
      if (transcriptEmbeds.length > 0) {
        const tDir = join(tmpDir, "transcripts");
        await mkdir(tDir, { recursive: true });
        for (const te of transcriptEmbeds) {
          await writeFile(join(tDir, te.filename), te.content);
        }
      }
      if (diagramEmbeds.length > 0) {
        const dDir = join(tmpDir, "diagrams");
        await mkdir(dDir, { recursive: true });
        for (const diagram of diagramEmbeds) {
          await writeFile(join(dDir, `${diagram.embedId}.html`), diagram.content);
        }
      }
      // Create zip using system zip command
      const zipPath = join(outputDir, `${filenameBase}.zip`);
      const { execSync } = await import("node:child_process");
      try {
        execSync(`cd "${tmpDir}" && zip -r "${zipPath}" .`, { stdio: "pipe" });
        // Clean up temp dir
        const { rm } = await import("node:fs/promises");
        await rm(tmpDir, { recursive: true, force: true });
        process.stdout.write(`\x1b[32m\u2713\x1b[0m ${zipPath}\n`);
      } catch {
        // zip not available — keep the directory as fallback
        process.stderr.write(
          `\x1b[33m!\x1b[0m 'zip' command not found — files saved to ${tmpDir}\n`,
        );
      }
    } else {
      // Direct file mode — write files into target directory
      const chatDir = join(outputDir, filenameBase);
      await mkdir(chatDir, { recursive: true });
      const written: string[] = [];

      await writeFile(join(chatDir, `${filenameBase}.yml`), yamlContent);
      written.push(`${filenameBase}.yml`);

      await writeFile(join(chatDir, `${filenameBase}.md`), mdContent);
      written.push(`${filenameBase}.md`);

      if (codeEmbeds.length > 0) {
        for (const ce of codeEmbeds) {
          const fpath =
            ce.filePath ??
            ce.filename ??
            `${ce.embedId.slice(0, 8)}.${getExtForLang(ce.language)}`;
          const fullPath = join(chatDir, "code", fpath);
          await mkdir(fullPath.substring(0, fullPath.lastIndexOf("/")), {
            recursive: true,
          });
          await writeFile(fullPath, ce.content);
          written.push(`code/${fpath}`);
        }
      }

      if (transcriptEmbeds.length > 0) {
        const tDir = join(chatDir, "transcripts");
        await mkdir(tDir, { recursive: true });
        for (const te of transcriptEmbeds) {
          await writeFile(join(tDir, te.filename), te.content);
          written.push(`transcripts/${te.filename}`);
        }
      }
      if (diagramEmbeds.length > 0) {
        const dDir = join(chatDir, "diagrams");
        await mkdir(dDir, { recursive: true });
        for (const diagram of diagramEmbeds) {
          const filename = `${diagram.embedId}.html`;
          await writeFile(join(dDir, filename), diagram.content);
          written.push(`diagrams/${filename}`);
        }
      }

      // Print summary
      const label = chat.title ? `"${chat.title}"` : chatHandle(chat);
      process.stdout.write(
        `\x1b[1mDownloaded chat ${label}\x1b[0m → ${chatDir}\n\n`,
      );
      for (const f of written) {
        process.stdout.write(`  \x1b[32m\u2713\x1b[0m ${f}\n`);
      }
      process.stdout.write(
        `\n\x1b[2m${written.length} file(s) written.\x1b[0m\n`,
      );
    }

    if (flags.json === true) {
      const files: string[] = [
        `${filenameBase}.yml`,
        `${filenameBase}.md`,
      ];
      for (const ce of codeEmbeds) {
        files.push(
          `code/${ce.filePath ?? ce.filename ?? ce.embedId.slice(0, 8)}`,
        );
      }
      for (const te of transcriptEmbeds) {
        files.push(`transcripts/${te.filename}`);
      }
      printJson({
        chat_id: chat.id,
        title: chat.title,
        output_dir: useZip
          ? join(outputDir, `${filenameBase}.zip`)
          : join(outputDir, filenameBase),
        files,
        code_embeds: codeEmbeds.length,
        transcript_embeds: transcriptEmbeds.length,
      });
    }
    return;
  }

  if (subcommand === "share") {
    const id = rest[0] || "last";
    const durationSeconds = (
      typeof flags.expires === "string" ? parseInt(flags.expires, 10) : 0
    ) as ShareDuration;
    const password =
      typeof flags.password === "string" ? flags.password : undefined;

    if (password && password.length > 10) {
      console.error("Password must be at most 10 characters.");
      process.exit(1);
    }

    try {
      const url = await client.createChatShareLink(
        id,
        durationSeconds,
        password,
        { includeSensitiveData: flags["include-sensitive-data"] === true },
      );
      if (flags.json === true) {
        printJson({
          url,
          chat_id: id,
          expires: durationSeconds,
          password_protected: !!password,
        });
      } else {
        process.stdout.write(`\n[1mChat share link[0m\n`);
        process.stdout.write(`${url}\n\n`);
        if (durationSeconds > 0) {
          process.stdout.write(
            `[2mExpires in ${humanizeDuration(durationSeconds)}[0m\n`,
          );
        }
        if (password) {
          process.stdout.write(`[2mPassword protected[0m\n`);
        }
      }
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      console.error(`Share link error: ${msg}`);
      process.exit(1);
    }
    return;
  }

  if (subcommand === "open") {
    if (!client.hasSession()) {
      const target = rest[0] ?? "1";
      const example = resolveExampleChatForOpen(target);
      if (!example) {
        console.error(
          `Example chat '${target}' not found. Run 'openmates chats list' to see available examples.`,
        );
        process.exit(1);
      }
      const appUrl = deriveAppUrl(client.apiUrl);
      const url = `${appUrl}/example/${example.chat.slug}`;
      if (!flags.json) {
        process.stderr.write(
          `\x1b[2mOpening example chat: "${example.chat.title ?? example.chat.slug}"\x1b[0m\n`,
        );
      }
      await openUrl(url);
      if (flags.json === true) {
        printJson({
          url,
          chat_id: example.chat.id,
          slug: example.chat.slug,
          title: example.chat.title,
          source: "example",
        });
      }
      return;
    }

    const n = rest[0] !== undefined ? parseInt(rest[0], 10) : 1;
    if (isNaN(n) || n < 1) {
      console.error(
        `Invalid position '${rest[0]}'. Must be a positive integer (1 = most recent, 2 = second most recent, ...).`,
      );
      process.exit(1);
    }

    // Fetch enough chats to reach position n (sorted most-recent-first)
    const result = await client.listChats(n, 1, teamContext);
    if (result.total === 0) {
      console.error(
        "No chats found. Run 'openmates chats list' to sync.",
      );
      process.exit(1);
    }
    if (n > result.total) {
      console.error(
        `Only ${result.total} chat(s) available — cannot open chat #${n}.`,
      );
      process.exit(1);
    }

    const chat = result.chats[n - 1];
    const appUrl = deriveAppUrl(client.apiUrl);
    const url = `${appUrl}/#chat-id=${chat.id}`;

    if (!flags.json) {
      const label = chat.title ? `"${chat.title}"` : chatHandle(chat);
      process.stderr.write(
        `\x1b[2mOpening chat #${n}: ${label}\x1b[0m\n`,
      );
    }

    await openUrl(url);

    if (flags.json === true) {
      printJson({ url, chat_id: chat.id, position: n, title: chat.title });
    }
    return;
  }

  console.error(`Unknown chats subcommand '${subcommand}'.\n`);
  printChatsHelp();
  process.exit(1);
}

async function listApiKeyChats(
  client: OpenMatesClient,
  apiKey: string,
  limit: number,
  page: number,
): Promise<ChatListPage> {
  const safeLimit = Number.isFinite(limit) && limit > 0 ? limit : 10;
  const safePage = Number.isFinite(page) && page > 0 ? page : 1;
  const sdk = createCliOpenMates(client, apiKey);
  const chats = await sdk.chats.list({ limit: safeLimit, offset: (safePage - 1) * safeLimit });
  return sdkChatsToChatListPage(chats, safeLimit, safePage);
}

async function searchApiKeyChats(
  client: OpenMatesClient,
  apiKey: string,
  query: string,
): Promise<ChatListItem[]> {
  const sdk = createCliOpenMates(client, apiKey);
  const chats = await sdk.chats.search(query, { limit: 0 });
  return sdkChatsToChatListPage(chats, chats.length || 1, 1).chats;
}

function sdkChatsToChatListPage(
  chats: EncryptedChatMetadata[],
  limit: number,
  page: number,
): ChatListPage {
  return {
    chats: chats.map((chat) => {
      const category = typeof chat.category === "string" ? chat.category : null;
      return {
        id: chat.id,
        shortId: chat.id.slice(0, 8),
        slug: typeof chat.slug === "string" && chat.slug ? chat.slug : null,
        title: typeof chat.title === "string" ? chat.title : null,
        summary: typeof chat.chat_summary === "string" ? chat.chat_summary : null,
        updatedAt: normalizeSdkTimestamp(chat.updated_at),
        category,
        mateName: category ? (MATE_NAMES[category] ?? null) : null,
      };
    }),
    total: chats.length,
    page,
    limit,
    hasMore: chats.length >= limit,
  };
}

function normalizeSdkTimestamp(value: unknown): number | null {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (typeof value === "string" && value.trim()) {
    const parsed = Date.parse(value);
    return Number.isFinite(parsed) ? Math.floor(parsed / 1000) : null;
  }
  return null;
}

async function sendApiKeyChatNew(
  client: OpenMatesClient,
  apiKey: string,
  message: string,
  flags: Record<string, string | boolean>,
): Promise<Record<string, unknown>> {
  const sdk = createCliOpenMates(client, apiKey);
  let response: ChatResponse;
  try {
    response = await sdk.chats.send(message, {
      saveToAccount: false,
      model: typeof flags.model === "string" ? flags.model : undefined,
      recoveryTimeoutMs: parseResponseTimeoutMs(flags),
    });
  } catch (err) {
    if (!isSdkChatUnavailableForApiKey(err)) throw err;
    const aiAskResult = await client.runSkill({
      app: "ai",
      skill: "ask",
      inputData: {
        messages: [{ role: "user", content: message }],
        stream: false,
        apps_enabled: true,
        is_incognito: true,
        model: typeof flags.model === "string" ? flags.model : undefined,
      },
      apiKey,
    });
    response = {
      content: extractAiAskContent(aiAskResult),
      modelName: typeof flags.model === "string" ? flags.model : undefined,
      raw: aiAskResult,
    };
  }
  const result = normalizeApiKeyChatResponse(response);
  if (flags.json !== true) {
    const category = typeof result.category === "string" ? result.category : null;
    const modelName = typeof result.modelName === "string" ? result.modelName : null;
    const mateBlock = ansiMateBlock(category, category ? (MATE_NAMES[category] ?? null) : null);
    const modelSuffix = modelName ? `  \x1b[2m${modelName}\x1b[0m` : "";
    process.stdout.write(`${SEP}\n`);
    process.stdout.write(`${mateBlock}${modelSuffix}\n`);
    process.stdout.write(`${SEP}\n`);
    process.stdout.write(`${String(result.assistant ?? "")}\n`);
    const chatId = typeof result.chatId === "string" ? result.chatId : null;
    if (chatId) {
      const shortId = chatId.slice(0, 8);
      process.stdout.write(`${SEP}\n`);
      process.stdout.write(
        `\x1b[2mContinue: openmates chats send --chat ${shortId} "your message"\x1b[0m\n` +
          `\x1b[2mHistory:  openmates chats show ${shortId}\x1b[0m\n`,
      );
    }
  }
  return result;
}

function isSdkChatUnavailableForApiKey(err: unknown): boolean {
	if (!(err instanceof OpenMatesApiError)) return false;
	if (err.status === 401) return true;
	if (err.status !== 403) return false;
	const data = err.data;
	const detail = data && typeof data === "object"
		? (data as Record<string, unknown>).detail
		: null;
	if (!detail || typeof detail !== "object") return false;
	const errorCode = (detail as Record<string, unknown>).error;
	return errorCode === "missing_scope";
}

function createCliOpenMates(client: OpenMatesClient, apiKey: string): OpenMates {
  return new OpenMates({
    apiKey,
    apiUrl: client.apiUrl,
    sdkName: "cli",
    deviceId: getCliApiKeyDeviceIdentity(),
  });
}

function getCliApiKeyDeviceIdentity(): string {
	return "cli:" + platform() + ":" + arch();
}

function extractAiAskContent(value: unknown): string {
  if (!value || typeof value !== "object") return "";
  const record = value as Record<string, unknown>;
  if (typeof record.content === "string") return record.content;
  if (typeof record.response === "string") return record.response;
  if (typeof record.answer === "string") return record.answer;
  const choices = record.choices;
  if (Array.isArray(choices)) {
    const first = choices[0] as Record<string, unknown> | undefined;
    const message = first?.message as Record<string, unknown> | undefined;
    if (typeof message?.content === "string") return message.content;
    if (typeof first?.text === "string") return first.text;
  }
  const data = record.data;
  if (data && typeof data === "object") return extractAiAskContent(data);
  return JSON.stringify(value);
}

function extractApiKeyChatModelName(value: unknown, depth = 0): string | null {
  if (!value || typeof value !== "object" || depth > 3) return null;
  const record = value as Record<string, unknown>;
  for (const key of ["model_name", "modelName", "model"]) {
    const field = record[key];
    if (typeof field === "string" && field) return field;
  }
  return extractApiKeyChatModelName(record.data, depth + 1)
    ?? extractApiKeyChatModelName(record.raw, depth + 1)
    ?? null;
}

function normalizeApiKeyChatResponse(response: ChatResponse): Record<string, unknown> {
	const chatId = typeof response.chat_id === "string" ? response.chat_id : null;
	const category = typeof response.category === "string" ? response.category : null;
  const modelName = typeof response.model_name === "string"
    ? response.model_name
    : typeof response.modelName === "string"
      ? response.modelName
      : extractApiKeyChatModelName(response.raw);
  return {
    status: "completed",
    chatId,
    chat_id: chatId,
    messageId: null,
    message_id: null,
    assistant: typeof response.content === "string" ? response.content : "",
    category,
    modelName,
    model_name: modelName,
    mateName: category ? (MATE_NAMES[category] ?? null) : null,
    followUpSuggestions: [],
    follow_up_suggestions: [],
    taskEvents: [],
    task_events: [],
    pendingTaskUpdateJobs: [],
    pending_task_update_jobs: [],
    subChatEvents: [],
    sub_chat_events: [],
    appSettingsMemoryRequests: [],
    app_settings_memory_requests: [],
    acceptedTaskProposals: [],
    accepted_task_proposals: [],
    raw: response,
	};
}

function normalizeApiKeyLoadedChat(payload: Record<string, unknown>): {
	chat: ChatListItem;
	messages: DecryptedMessage[];
	followUpSuggestions: string[];
} {
	const rawChat = payload.chat && typeof payload.chat === "object"
		? payload.chat as Record<string, unknown>
		: {};
	const chatId = String(rawChat.id ?? rawChat.chat_id ?? "");
	if (!chatId) throw new Error("API key chat load did not include a chat id.");

	const category = typeof rawChat.category === "string" ? rawChat.category : null;
	const chat: ChatListItem = {
		id: chatId,
		shortId: chatId.slice(0, 8),
		slug: typeof rawChat.slug === "string" && rawChat.slug ? rawChat.slug : null,
		title: typeof rawChat.title === "string" ? rawChat.title : null,
		summary: typeof rawChat.chat_summary === "string"
			? rawChat.chat_summary
			: typeof rawChat.summary === "string"
				? rawChat.summary
				: null,
		updatedAt: normalizeSdkTimestamp(rawChat.updated_at),
		category,
		mateName: category ? MATE_NAMES[category] ?? null : null,
	};

	const rawEmbeds = Array.isArray(payload.embeds)
		? payload.embeds.filter((item): item is Record<string, unknown> => Boolean(item) && typeof item === "object")
		: [];
	const rawMessages = Array.isArray(payload.messages)
		? payload.messages.filter((item): item is Record<string, unknown> => Boolean(item) && typeof item === "object")
		: [];
	const messages = rawMessages.map((message) => {
		const messageId = String(message.client_message_id ?? message.message_id ?? message.id ?? "");
		const directEmbedIds = Array.isArray(message.embedIds)
			? message.embedIds
			: Array.isArray(message.embed_ids)
				? message.embed_ids
				: [];
		const hashedMessageId = messageId ? createHash("sha256").update(messageId).digest("hex") : null;
		const matchedEmbedIds = hashedMessageId
			? rawEmbeds
				.filter((embed) => embed.hashed_message_id === hashedMessageId && !embed.parent_embed_id)
				.map((embed) => String(embed.embed_id ?? embed.id ?? ""))
				.filter(Boolean)
			: [];
		return {
			id: messageId,
			chatId: String(message.chat_id ?? chatId),
			role: String(message.role ?? "unknown"),
			content: typeof message.content === "string" ? message.content : "",
			senderName: typeof message.senderName === "string"
				? message.senderName
				: typeof message.sender_name === "string"
					? message.sender_name
					: null,
			category: typeof message.category === "string" ? message.category : null,
			modelName: typeof message.modelName === "string"
				? message.modelName
				: typeof message.model_name === "string"
					? message.model_name
					: null,
			createdAt: normalizeSdkTimestamp(message.created_at) ?? 0,
			embedIds: [...new Set([...directEmbedIds.map(String), ...matchedEmbedIds])],
		};
	});
	messages.sort((a, b) => a.createdAt - b.createdAt);

	const followUpSuggestions = Array.isArray(payload.follow_up_suggestions)
		? payload.follow_up_suggestions.map(String)
		: [];
	return { chat, messages, followUpSuggestions };
}

function resolveExampleChatForOpen(target: string): ExampleChatConversation | null {
  const numericTarget = parseInt(target, 10);
  if (!Number.isNaN(numericTarget) && String(numericTarget) === target.trim()) {
    if (numericTarget < 1) return null;
    const page = listExampleChats(numericTarget, 1);
    const chat = page.chats[numericTarget - 1];
    return chat ? getExampleChatConversation(chat.id) : null;
  }
  return getExampleChatConversation(target);
}

function collectMessageEmbedIdsForFiles(messages: DecryptedMessage[]): string[] {
  const ids = new Set<string>();
  const inlineEmbedRefRe = /embed:([a-zA-Z0-9_.:-]+)/g;
  for (const message of messages) {
    for (const embedId of message.embedIds ?? []) {
      if (embedId) ids.add(embedId);
    }
    for (const match of Array.from((message.content ?? "").matchAll(inlineEmbedRefRe))) {
      if (match[1]) ids.add(match[1]);
    }
    for (const segment of parseMessageSegments(message.content ?? "")) {
      if (segment.type === "embed" && segment.value) ids.add(segment.value);
    }
  }
  return Array.from(ids);
}

function fileReferenceKey(file: ChatFileReference): string {
  return `${file.embedId}:${file.title}`.toLowerCase();
}

function chatFileReferenceFromEmbed(embed: DecryptedEmbed): ChatFileReference[] {
  return getEmbedFileReferences({
    embedId: embed.embedId,
    type: embed.type,
    content: embed.content,
    appId: embed.appId,
    skillId: embed.skillId,
    createdAt: embed.createdAt,
  });
}

async function loadChatFileReferencesForCli(
  client: OpenMatesClient,
  messages: DecryptedMessage[],
): Promise<{ files: ChatFileReference[]; errors: Array<{ embed_id: string; message: string }> }> {
  const queue = collectMessageEmbedIdsForFiles(messages);
  const visitedEmbeds = new Set<string>();
  const seenFiles = new Set<string>();
  const files: ChatFileReference[] = [];
  const errors: Array<{ embed_id: string; message: string }> = [];

  while (queue.length > 0) {
    const embedId = queue.shift();
    if (!embedId || visitedEmbeds.has(embedId)) continue;
    visitedEmbeds.add(embedId);

    try {
      const embed = await client.getEmbed(embedId);
      for (const file of chatFileReferenceFromEmbed(embed)) {
        const key = fileReferenceKey(file);
        if (seenFiles.has(key)) continue;
        files.push(file);
        seenFiles.add(key);
      }

      for (const childId of extractEmbedIdsFromContent(embed.content)) {
        if (childId && !visitedEmbeds.has(childId)) queue.push(childId);
      }
    } catch (error) {
      errors.push({
        embed_id: embedId,
        message: error instanceof Error ? error.message : String(error),
      });
    }
  }

  return { files, errors };
}

function chatFileToJson(file: ChatFileReference): Record<string, unknown> {
  return {
    embed_id: file.embedId,
    content_ref: file.contentRef,
    title: file.title,
    type: file.type,
    node_type: file.nodeType,
    metadata: file.metadata,
    app_id: file.appId,
    skill_id: file.skillId,
    url: file.url,
    mime_type: file.mimeType,
  };
}

function printChatFiles(
  chat: Pick<ChatListItem, "id" | "shortId" | "title">,
  files: ChatFileReference[],
  flags: Record<string, string | boolean>,
  options: { example?: boolean; errors?: Array<{ embed_id: string; message: string }> } = {},
): void {
  if (flags.json === true) {
    printJson({
      chat_id: chat.id,
      title: chat.title,
      source: options.example ? "example" : "chat",
      count: files.length,
      files: files.map(chatFileToJson),
      errors: options.errors ?? [],
    });
    return;
  }

  const title = chat.title ?? chat.shortId ?? chat.id;
  header(`Files for ${title}`);
  if (options.example) {
    process.stdout.write("\x1b[2mPublic example chat files are resolved from bundled static embed metadata.\x1b[0m\n");
  }
  if (files.length === 0) {
    process.stdout.write("\x1b[2mNo files found for this chat.\x1b[0m\n");
  } else {
    for (const file of files) {
      const appSkill = [file.appId, file.skillId].filter(Boolean).join("/");
      const suffix = appSkill ? `  \x1b[2m${appSkill}\x1b[0m` : "";
      process.stdout.write(`  \x1b[1m${file.title}\x1b[0m  \x1b[2m${file.metadata}\x1b[0m${suffix}\n`);
      process.stdout.write(`    \x1b[2m${file.contentRef}${file.url ? `  ${file.url}` : ""}\x1b[0m\n`);
    }
  }
  for (const error of options.errors ?? []) {
    process.stderr.write(`Warning: could not inspect embed ${error.embed_id}: ${error.message}\n`);
  }
}

async function openUrl(url: string): Promise<void> {
  // Open in default browser using platform-appropriate command.
  const { exec } = await import("node:child_process");
  const platform = process.platform;
  const openCmd =
    platform === "darwin"
      ? `open "${url}"`
      : platform === "win32"
        ? `start "" "${url}"`
        : `xdg-open "${url}"`;
  exec(openCmd, (err) => {
    if (err) {
      // Fallback: print the URL so the user can open it manually.
      console.log(url);
    }
  });
}

