/** Wait for this accepted run and its selected chat deliveries, never dispatch again. */
export async function waitForWorkflowRun(
  client: Pick<OpenMatesClient, "getWorkflowRun" | "ensureSynced">,
  workflowId: string,
  initialRun: WorkflowRunDetail,
  options: { timeoutMs?: number; pollIntervalMs?: number; syncIntervalMs?: number } = {},
): Promise<WorkflowRunDetail> {
  const deadline = Date.now() + (options.timeoutMs ?? 180_000);
  const runId = initialRun.id;
  let run = initialRun;
  let lastSyncError = "";
  const timeoutError = () => new Error(
    `Workflow run ${runId} is still ${run.status === "completed" ? "waiting for chat delivery acknowledgement" : run.status}. ` +
    `Inspect it with workflows run-show; retry with the same --idempotency-key to avoid rerunning skills.` +
    (lastSyncError ? ` Last delivery sync error: ${lastSyncError}` : ""),
  );
  async function withinBudget<T>(operation: () => Promise<T>): Promise<T> {
    const remaining = deadline - Date.now();
    if (remaining <= 0) throw timeoutError();
    let timer: ReturnType<typeof setTimeout>;
    try {
      return await Promise.race([
        operation(),
        new Promise<never>((_, reject) => { timer = setTimeout(() => reject(timeoutError()), remaining); }),
      ]);
    } finally {
      clearTimeout(timer!);
    }
  }
  const pause = () => withinBudget(() => new Promise<void>(resolve => setTimeout(resolve, Math.min(options.pollIntervalMs ?? 2000, deadline - Date.now()))));
  const refresh = async () => { run = await withinBudget(() => client.getWorkflowRun(workflowId, runId)); };
  while (["queued", "planned", "running", "waiting", "cancellation_requested"].includes(run.status)) {
    await pause();
    await refresh();
  }
  // Acceptance can return an already-completed idempotent run without its live
  // routing projection. Read it once before deciding whether delivery is needed.
  await refresh();
  let nextSyncAt = 0;
  while (true) {
    if (run.status !== "completed") {
      throw new Error(`Workflow run ${runId} ${run.status}: ${run.error_summary ?? "inspect workflows run-show for details"}`);
    }
    const projection = run.output_summary?.deliveries;
    const deliveries = isRecord(projection) ? Object.values(projection).filter(isRecord) : [];
    const failed = deliveries.find(delivery => ["cancelled", "expired"].includes(String(delivery.status)));
    if (failed) throw new Error(`Workflow run ${runId} completed, but chat delivery ${String(failed.delivery_id)} is ${String(failed.status)}.`);
    if (deliveries.every(delivery => delivery.status === "acknowledged")) return run;
    if (Date.now() >= deadline) throw timeoutError();
    if (Date.now() >= nextSyncAt) {
      // Personal workflow delivery uses this profile's owner session. The sync
      // handler respects another device's claim lease before attempting a claim.
      try {
        await withinBudget(() => client.ensureSynced(true, [], { personal: true }));
        lastSyncError = "";
      } catch (error) {
        lastSyncError = error instanceof Error ? error.message : String(error);
        if (Date.now() >= deadline) throw timeoutError();
      }
      nextSyncAt = Date.now() + (options.syncIntervalMs ?? 10_000);
      await refresh();
      continue;
    }
    await pause();
    await refresh();
  }
}

async function persistCliWorkflowFile(
  client: OpenMatesClient, project: DecryptedProject, workflow: WorkflowDetail,
  binding: WorkflowRemoteFileBinding, source: ProjectSourceRecord | null | undefined,
  flags: Record<string, string | boolean>,
): Promise<Awaited<ReturnType<typeof persistWorkflowRemoteFile>>> {
  const context = teamContextFromFlags(flags);
  const chatId = typeof flags['source-chat'] === 'string' ? flags['source-chat'] : workflow.source_chat_id;
  const focus = chatId ? await client.getActiveProjectFocus(chatId) : null;
  if (!source || source.source_id !== binding.source_id || !chatId || focus?.project_id !== project.projectId) {
    return { status: 'pending', binding, error: !source ? 'source_selection_required' : 'project_focus_required' };
  }
  return persistWorkflowRemoteFile({ workflow: { ...workflow, graph: { ...workflow.graph, edges: workflow.graph.edges ?? [] } },
    binding, expectedVersionId: workflow.current_version_id, operationId: randomUUID(), serialize: stringifyYaml,
    currentVersion: async () => (await client.getWorkflow(workflow.id, context)).current_version_id,
    execute: async mutation => {
      const settings = await client.getProjectSettings(project.projectId, context);
      if (!settings.write_mode) return { status: 'failed', error: 'write_policy_required' };
      if (settings.write_mode === 'always_ask') {
        const accepted = flags.yes === true || (process.stdin.isTTY && flags.json !== true
          && await promptConfirmation(`Write Workflow YAML to ${mutation.path}?`));
        if (!accepted) return { status: 'pending', error: 'write_approval_required' };
        await client.approveProjectWrite(project.projectId, { chat_id: chatId, operation_id: mutation.operation_id,
          proposal_digest: await projectFileMutationDigest(project.projectKey, project.projectId, chatId, mutation) }, context);
      }
      return await requestProjectRemoteOperation({ client, projectId: project.projectId, projectKey: project.projectKey,
        source, operation: mutation.operation, arguments: { chat_id: chatId, mutation }, context }) as Record<string, unknown>;
    },
  });
}

async function syncCliBoundWorkflowFiles(client: OpenMatesClient, workflow: WorkflowDetail, flags: Record<string, string | boolean>) {
  const results: Array<{ project_id: string; status: string; error?: string }> = [];
  const context = teamContextFromFlags(flags);
  for (const project of await loadProjects(client, client.getMasterKeyBytes(), flags, context)) {
    const contents = await client.listProjectItems(project.projectId, context);
    for (const item of contents.items.filter(item => item.item_type === 'workflow')) {
      if (await decryptOptionalProjectField(item.target_id_encrypted, project.projectKey) !== workflow.id) continue;
      const text = await decryptOptionalProjectField(item.encrypted_metadata, project.projectKey);
      const metadata = text ? JSON.parse(text) as Record<string, unknown> : {};
      const binding = metadata.remote_workflow_file as WorkflowRemoteFileBinding | undefined;
      if (!binding) continue;
      const source = (await client.listProjectSources(project.projectId, context)).find(item => item.source_id === binding.source_id);
      const saved = await persistCliWorkflowFile(client, project, workflow, binding, source, flags);
      await client.updateProjectItemMetadata(project.projectId, item.project_item_id,
        await encryptWithAesGcmCombined(JSON.stringify({ ...metadata, remote_workflow_file: saved.binding,
          remote_file_status: saved.status, remote_file_error: saved.error }), project.projectKey), context);
      results.push({ project_id: project.projectId, status: saved.status, error: saved.error });
    }
  }
  return results;
}

async function handleWorkflows(
  client: OpenMatesClient,
  subcommand: string | undefined,
  rest: string[],
  flags: Record<string, string | boolean>,
  redactor?: OutputRedactor,
): Promise<void> {
  if (!subcommand || subcommand === "help" || flags.help === true) {
    printWorkflowsHelp();
    return;
  }

  if (rest[0] === "add-to-project") {
    const projectId = requiredStringFlag(rest[1], "<project-id>");
    const workflowId = await requiredResolvedWorkflowId(client, subcommand, flags, "add-to-project");
    const masterKey = client.getMasterKeyBytes();
    const project = await requiredResolvedProject(client, masterKey, projectId, flags);
    const storageChoice = await resolveAddToProjectStorageChoice(client, project, flags, "workflow");
    const workflow = await client.getWorkflow(workflowId, teamContextFromFlags(flags));
    const context = teamContextFromFlags(flags);
    const contents = await client.listProjectItems(project.projectId, context);
    let existing: typeof contents.items[number] | undefined;
    for (const item of contents.items.filter(item => item.item_type === 'workflow')) {
      if (await decryptOptionalProjectField(item.target_id_encrypted, project.projectKey) === workflow.id) { existing = item; break; }
    }
    const metadataText = existing?.encrypted_metadata ? await decryptOptionalProjectField(existing.encrypted_metadata, project.projectKey) : '';
    const metadata = metadataText ? JSON.parse(metadataText) as Record<string, unknown> : {};
    let fileResult: Awaited<ReturnType<typeof persistWorkflowRemoteFile>> | null = null;
    if (storageChoice.targetMode !== 'save_only_in_openmates' || (storageChoice.source && flags['openmates-only'] !== true)) {
      const source = typeof flags.source === 'string'
        ? (await client.listProjectSources(project.projectId, context)).find(item => item.source_id === flags.source)
        : storageChoice.source;
      const binding = metadata.remote_workflow_file as WorkflowRemoteFileBinding | undefined
        ?? { project_id: project.projectId, source_id: source?.source_id ?? '', folder_path: typeof flags['remote-folder'] === 'string' ? flags['remote-folder'] : '' };
      fileResult = await persistCliWorkflowFile(client, project, workflow, binding, source, flags);
      metadata.remote_workflow_file = fileResult.binding;
      metadata.remote_file_status = fileResult.status;
      metadata.remote_file_error = fileResult.error;
    }
    const item = existing ?? await createEncryptedProjectItem(client, project, {
      itemType: "workflow",
      targetId: workflow.id,
      displayName: workflow.title,
      folderId: typeof flags.folder === "string" ? flags.folder : null,
      metadata: { ...metadata, storage: storageChoice.targetMode, source: "cli_add_to_project" },
    });
    if (existing) await client.updateProjectItemMetadata(project.projectId, existing.project_item_id,
      await encryptWithAesGcmCombined(JSON.stringify(metadata), project.projectKey), context);
    if (flags.json === true) printJson({ objectType: 'workflow', objectId: workflow.id, projectId: project.projectId, item,
      remote_file: fileResult ? { status: fileResult.status, path: fileResult.binding.file_path ?? null, error: fileResult.error ?? null } : null });
    else {
      console.log(`Workflow linked to Project: ${project.projectId}`);
      console.log(fileResult ? fileResult.status === 'saved' ? `Remote YAML saved: ${fileResult.binding.file_path}`
        : `Remote YAML ${fileResult.status}: ${fileResult.error ?? 'Retry the file save.'}` : 'Storage: encrypted OpenMates Project link only');
    }
    return;
  }

  if (rest[0] === "remove-from-project") {
    const projectId = requiredStringFlag(rest[1], "<project-id>");
    const workflowId = await requiredResolvedWorkflowId(client, subcommand, flags, "remove-from-project");
    const masterKey = client.getMasterKeyBytes();
    const project = await requiredResolvedProject(client, masterKey, projectId, flags);
    const workflow = await client.getWorkflow(workflowId, teamContextFromFlags(flags));
    const removed = await client.deleteProjectItemByTarget(project.projectId, "workflow", workflow.id);
    printRemoveFromProjectResult({ objectType: "workflow", objectId: workflow.id, projectId: project.projectId, deleted: removed.deleted, deletedCount: removed.deleted_count }, flags);
    return;
  }

  if (subcommand === "capabilities") {
    const capabilities = await client.listWorkflowCapabilities();
    if (flags.json === true) {
      printJson(capabilities);
    } else {
      printWorkflowCapabilities(capabilities);
    }
    return;
  }

  if (subcommand === "list") {
    const workflows = await client.listWorkflows(teamContextFromFlags(flags));
    if (flags.json === true) {
      printJson(workflows);
    } else {
      printWorkflowList(workflows);
    }
    return;
  }

  if (subcommand === "export") {
    const target = rest[0];
    if (!target) throw new Error("Missing workflow ID. Example: openmates workflows export <id> --output morning.workflow.yml");
    const workflowId = await requiredResolvedWorkflowId(client, target, flags, "export");
    const workflow = await client.getWorkflow(workflowId, teamContextFromFlags(flags));
    if (workflow.lifecycle === "temporary") throw new Error("Save the workflow before exporting it.");
    const output = typeof flags.output === "string" ? flags.output : workflowFileName(workflow.title);
    assertWorkflowFilePath(output);
    const document = buildWorkflowFile({
      title: workflow.title,
      description: workflow.description,
      run_content_retention: workflow.run_content_retention,
      graph: { ...workflow.graph, edges: workflow.graph.edges ?? [] },
      binding_requirements: workflow.binding_requirements,
    });
    const source = stringifyYaml(document, { lineWidth: 0 });
    if (Buffer.byteLength(source, "utf8") > WORKFLOW_FILE_MAX_BYTES) throw new Error("Workflow export exceeds the file size limit.");
    writeFileSync(output, source, { encoding: "utf8", flag: "wx" });
    if (flags.json === true) printJson({ workflow_id: workflow.id, file: output, binding_requirements: document.binding_requirements });
    else console.log(`Workflow exported: ${output}`);
    return;
  }

  if (subcommand === "import") {
    if (flags.team !== undefined || flags["team-id"] !== undefined || (client.getActiveTeamId() && flags.personal !== true)) {
      throw new CliContractError("unsupported_ownership_context", "Workflow file import creates a Personal Workflow. Use --personal or switch to Personal context before importing.");
    }
    const file = requiredStringFlag(flags.file, "--file <path.workflow.yml>");
    assertWorkflowFilePath(file);
    if (statSync(file).size > WORKFLOW_FILE_MAX_BYTES) throw new Error("Workflow file exceeds the size limit.");
    const source = readFileSync(file, "utf8");
    if (Buffer.byteLength(source, "utf8") > WORKFLOW_FILE_MAX_BYTES) throw new Error("Workflow file exceeds the size limit.");
    const yaml = parseYamlDocument(source, { uniqueKeys: true, strict: true });
    if (yaml.errors.length > 0) throw new Error(`Invalid workflow YAML: ${yaml.errors[0].message}`);
    const document = validateWorkflowFile(yaml.toJS({ maxAliasCount: 20 }));
    if (flags.folder && !flags.project) throw new Error("--folder requires --project.");
    const project = typeof flags.project === "string"
      ? await requiredResolvedProject(client, client.getMasterKeyBytes(), flags.project, flags)
      : null;
    const folderId = typeof flags.folder === "string" ? flags.folder : null;
    if (project && folderId) {
      const { folders } = await client.listProjectItems(project.projectId);
      if (!folders.some((folder) => folder.id === folderId || folder.folder_id === folderId)) {
        throw new Error(`Project folder '${folderId}' not found.`);
      }
    }
    const workflow = await client.importWorkflowFile(document);
    if (project) {
      try {
        await createEncryptedProjectItem(client, project, {
          itemType: "workflow",
          targetId: workflow.id,
          displayName: workflow.title,
          folderId,
          metadata: { storage: "save_only_in_openmates", source: "cli_file_import" },
        });
      } catch (error) {
        throw new Error(`Workflow imported as ${workflow.id}, but linking it to Project ${project.projectId} failed: ${error instanceof Error ? error.message : String(error)}`);
      }
    }
    if (flags.json === true) printJson({ workflow, project_id: project?.projectId ?? null });
    else {
      console.log(`Workflow imported: ${workflow.title} (${workflow.id})`);
      console.log("Disabled until you review bindings and enable it.");
      for (const requirement of workflow.binding_requirements ?? []) {
        console.log(`Review ${requirement.type} for ${requirement.node_id}.`);
      }
      if (project) console.log(`Added to Project: ${project.projectId}`);
    }
    return;
  }

  if (subcommand === "validate") {
    const file = typeof flags.file === "string" ? flags.file : "";
    if (!file) throw new Error("Missing --file. Example: openmates workflows validate --file workflow.yml");
    const validation = await client.validateWorkflowYaml(readFileSync(file, "utf8"));
    if (flags.json === true) {
      printJson(validation);
    } else {
      kv("Draft valid", validation.draft_valid ? "yes" : "no");
      kv("Ready to enable", validation.enable_ready ? "yes" : "no");
      for (const diagnostic of validation.diagnostics) {
        console.log(`  - ${String(diagnostic.path ?? "$")}: ${String(diagnostic.message ?? diagnostic.code ?? "invalid")}`);
      }
    }
    if (!validation.draft_valid) process.exitCode = 1;
    return;
  }

  if (subcommand === "create") {
    const yamlFile = typeof flags.file === "string" ? flags.file : "";
    if (yamlFile) {
      const result = await client.createWorkflowYaml(readFileSync(yamlFile, "utf8"));
      if (flags.json === true) {
        printJson(result);
      } else {
        printWorkflowDetail(result.workflow);
        kv("Ready to enable", result.validation.enable_ready ? "yes" : "no");
        printWorkflowAuthoringWarnings(result.warnings);
        for (const diagnostic of result.validation.diagnostics) {
          console.log(`  - ${String(diagnostic.path ?? "$")}: ${String(diagnostic.message ?? diagnostic.code ?? "input required")}`);
        }
      }
      return;
    }
    const title = typeof flags.title === "string" ? flags.title.trim() : "";
    const graphJson = typeof flags.graph === "string" ? flags.graph : "";
    if (!title) throw new Error("Missing --title for workflow create.");
    if (!graphJson) throw new Error("Missing --graph JSON for workflow create.");
    const workflow = await client.createWorkflow({
      title,
      slug: typeof flags.slug === "string" ? flags.slug : undefined,
      graph: parseJsonFlag<WorkflowGraph>(graphJson, "--graph"),
      enabled: flags.enabled === true,
      runContentRetention: parseWorkflowRunContentRetention(flags["run-content-retention"]),
    });
    if (flags.json === true) {
      printJson(workflow);
    } else {
      printWorkflowDetail(workflow);
    }
    return;
  }

  if (subcommand === "update") {
    const workflowId = rest[0] ? await requiredResolvedWorkflowId(client, rest[0], flags, "update") : undefined;
    const yamlFile = typeof flags.file === "string" ? flags.file : "";
    if (!workflowId || !yamlFile) throw new Error("Missing workflow ID or --file. Example: openmates workflows update <id> --file workflow.yml");
    const result = await client.updateWorkflowYaml(workflowId, readFileSync(yamlFile, "utf8"));
    if (typeof flags.slug === "string") {
      result.workflow = await client.updateWorkflow(result.workflow.id, { slug: flags.slug });
    }
    const remoteFileSaves = await syncCliBoundWorkflowFiles(client, result.workflow, flags);
    if (flags.json === true) {
      printJson({ ...result, remote_file_saves: remoteFileSaves });
    } else {
      printWorkflowDetail(result.workflow);
      kv("Ready to enable", result.validation.enable_ready ? "yes" : "no");
      printWorkflowAuthoringWarnings(result.warnings);
      for (const save of remoteFileSaves) console.log(`Remote YAML ${save.status}: ${save.project_id}${save.error ? ` (${save.error})` : ''}`);
      for (const diagnostic of result.validation.diagnostics) {
        console.log(`  - ${String(diagnostic.path ?? "$")}: ${String(diagnostic.message ?? diagnostic.code ?? "input required")}`);
      }
    }
    return;
  }

  if (subcommand === "history") {
    const workflowId = rest[0] ? await requiredResolvedWorkflowId(client, rest[0], flags, "history") : undefined;
    if (!workflowId) throw new Error("Missing workflow ID. Usage: openmates workflows history <workflow-id>");
    printObjectHistory(await client.listObjectHistory("workflow", workflowId, typeof flags.limit === "string" ? Number(flags.limit) : 50), flags);
    return;
  }

  if (subcommand === "restore") {
    const workflowId = rest[0] ? await requiredResolvedWorkflowId(client, rest[0], flags, "restore") : undefined;
    if (!workflowId) throw new Error("Missing workflow ID. Usage: openmates workflows restore <workflow-id> --entry <history-entry-id>");
    const entryId = historyEntryIdFromFlagsOrRest(flags, rest, "openmates workflows restore <workflow-id> --entry <history-entry-id>");
    const result = await client.restoreObjectHistory("workflow", workflowId, entryId, parseHistoryRestoreState(flags.state));
    if (flags.json === true) printJson(result);
    else {
      console.log(`Workflow restored: ${workflowId}`);
      printHistoryCommands(result.history as WorkspaceHistoryResult | null | undefined);
    }
    return;
  }

  if (subcommand === "ask") {
    const instruction = requiredAskInstruction(flags, rest, "openmates workflows ask \"alert me if it rains\"");
    const exactAsk = await buildExactWorkflowAsk(client, instruction, flags);
    if (exactAsk) {
      const result = await client.askWorkflow({ instruction, ...exactAsk });
      if (await handleWorkspaceAskFallbackChat(client, "workflow", instruction, result, flags, redactor)) return;
      printAskApplyResult("workflow", result, flags);
      return;
    }
    const retention = parseWorkflowRunContentRetention(flags["run-content-retention"]);
    const explicitCreate = typeof flags.graph === "string" || typeof flags.description === "string" || flags.enabled === true || Boolean(retention)
      ? {
          title: instruction.slice(0, 200),
          description: typeof flags.description === "string" ? flags.description : null,
          graph: workflowAskGraphFromFlags(flags),
          enabled: flags.enabled === true,
          ...(retention ? { run_content_retention: retention } : {}),
          source: "cli_ask",
          created_by_assistant: true,
        }
      : undefined;
    const result = await client.askWorkflow({ instruction, ...(explicitCreate ? { create: explicitCreate } : {}) });
    if (await handleWorkspaceAskFallbackChat(client, "workflow", instruction, result, flags, redactor)) return;
    printAskApplyResult("workflow", result, flags);
    return;
  }

  if (subcommand === "input") {
    const text = typeof flags.text === "string" ? flags.text : rest.join(" ").trim();
    if (!text) throw new Error("Missing workflow input text. Example: openmates workflows ask \"alert me if it rains\"");
    const session = await client.startWorkflowInput({
      text,
      selectedWorkflowId: typeof flags["workflow-id"] === "string" ? flags["workflow-id"] : undefined,
      selectedProjectId: typeof flags["project-id"] === "string" ? flags["project-id"] : undefined,
      timezone: typeof flags.timezone === "string" ? flags.timezone : Intl.DateTimeFormat().resolvedOptions().timeZone,
      optimisticSave: flags.optimistic === true,
      idempotencyKey: typeof flags["idempotency-key"] === "string" ? flags["idempotency-key"] : undefined,
    });
    if (flags.json === true) {
      printJson(session);
    } else {
      printWorkflowInputSession(session);
    }
    return;
  }

  if (subcommand === "input-show") {
    const sessionId = rest[0];
    if (!sessionId) throw new Error("Missing session ID. Example: openmates workflows input-show <session-id>");
    const session = await client.getWorkflowInputSession(sessionId);
    if (flags.json === true) {
      printJson(session);
    } else {
      printWorkflowInputSession(session);
      if (session.events.length > 0) {
        console.log("\nEvents:");
        for (const event of session.events) {
          kv(String(event.event_id), `${event.type} · ${event.status}`, 6);
        }
      }
    }
    return;
  }

  if (subcommand === "input-events") {
    const sessionId = rest[0];
    if (!sessionId) throw new Error("Missing session ID. Example: openmates workflows input-events <session-id>");
    const afterEventId = typeof flags.after === "string" ? Number.parseInt(flags.after, 10) : 0;
    const events = await client.listWorkflowInputEvents(sessionId, Number.isFinite(afterEventId) ? afterEventId : 0);
    if (flags.json === true) {
      printJson(events);
    } else {
      for (const event of events) {
        kv(String(event.event_id), `${event.type} · ${event.status}`, 6);
      }
    }
    return;
  }

  if (subcommand === "input-follow-up") {
    const sessionId = rest[0];
    const text = typeof flags.text === "string" ? flags.text : rest.slice(1).join(" ").trim();
    if (!sessionId || !text) throw new Error("Missing session ID or text. Example: openmates workflows input-follow-up <session-id> \"make it weekdays only\"");
    const session = await client.followUpWorkflowInput(sessionId, text);
    if (flags.json === true) {
      printJson(session);
    } else {
      printWorkflowInputSession(session);
    }
    return;
  }

  if (subcommand === "input-stop" || subcommand === "input-undo") {
    const sessionId = rest[0];
    if (!sessionId) throw new Error(`Missing session ID. Example: openmates workflows ${subcommand} <session-id>`);
    const session = subcommand === "input-stop"
      ? await client.stopWorkflowInput(sessionId)
      : await client.undoWorkflowInput(sessionId);
    if (flags.json === true) {
      printJson(session);
    } else {
      printWorkflowInputSession(session);
    }
    return;
  }

  if (subcommand === "show") {
    const workflowId = rest[0] ? await requiredResolvedWorkflowId(client, rest[0], flags, "show") : undefined;
    if (!workflowId) throw new Error("Missing workflow ID. Example: openmates workflows show <id>");
    const workflow = await client.getWorkflow(workflowId, teamContextFromFlags(flags));
    if (flags.json === true) {
      printJson(workflow);
    } else {
      printWorkflowDetail(workflow);
    }
    return;
  }

  if (subcommand === "enable" || subcommand === "disable") {
    const workflowId = rest[0] ? await requiredResolvedWorkflowId(client, rest[0], flags, subcommand) : undefined;
    if (!workflowId) throw new Error(`Missing workflow ID. Example: openmates workflows ${subcommand} <id>`);
    const workflow = subcommand === "enable"
      ? await client.enableWorkflow(workflowId)
      : await client.disableWorkflow(workflowId);
    if (flags.json === true) {
      printJson(workflow);
    } else {
      printWorkflowDetail(workflow);
    }
    return;
  }

  if (subcommand === "delete") {
    const workflowId = rest[0] ? await requiredResolvedWorkflowId(client, rest[0], flags, "delete") : undefined;
    if (!workflowId) throw new Error("Missing workflow ID. Example: openmates workflows delete <id> --yes");
    if (flags.yes !== true) throw new Error("Refusing to delete workflow without --yes.");
    const result = await client.deleteWorkflow(workflowId);
    if (flags.json === true) {
      printJson(result);
    } else {
      console.log("Workflow deleted.");
    }
    return;
  }

  if (subcommand === "save-as-reusable") {
    const workflowId = rest[0] ? await requiredResolvedWorkflowId(client, rest[0], flags, "save-as-reusable") : undefined;
    if (!workflowId) throw new Error("Missing workflow ID. Example: openmates workflows save-as-reusable <id>");
    const idempotencyKey = typeof flags["idempotency-key"] === "string" ? flags["idempotency-key"] : "";
    if (!idempotencyKey) throw new Error("Missing --idempotency-key for workflow save-as-reusable.");
    const workflow = await client.saveWorkflowAsReusable(workflowId, { idempotencyKey });
    if (flags.json === true) printJson(workflow);
    else printWorkflowDetail(workflow);
    return;
  }

  const runRouting = () => ({
    ...(typeof flags["source-chat"] === "string" ? { sourceChatId: flags["source-chat"] } : {}),
    ...(typeof flags["message-destination-overrides"] === "string" ? { messageDestinationOverrides: parseJsonFlag<Record<string, string>>(flags["message-destination-overrides"], "--message-destination-overrides") } : {}),
    ...(typeof flags["return-outputs"] === "string" ? { returnOutputs: parseJsonFlag<Record<string, WorkflowReturnedOutputReference>>(flags["return-outputs"], "--return-outputs") } : {}),
  });

  if (subcommand === "run-once") {
    const titleFlag = typeof flags.title === "string" ? flags.title.trim() : "";
    const graphFlag = typeof flags.graph === "string" ? flags.graph : "";
    const fileFlag = typeof flags.file === "string" ? flags.file : "";
    if (Boolean(graphFlag) === Boolean(fileFlag)) throw new Error("Specify exactly one of --graph JSON or --file definition.workflow.yml for run-once.");
    let graph: WorkflowGraph;
    let title = titleFlag;
    if (fileFlag) {
      assertWorkflowFilePath(fileFlag);
      if (statSync(fileFlag).size > WORKFLOW_FILE_MAX_BYTES) throw new Error("Workflow file exceeds the size limit.");
      const yaml = parseYamlDocument(readFileSync(fileFlag, "utf8"), { uniqueKeys: true, strict: true });
      if (yaml.errors.length > 0) throw new Error(`Invalid workflow YAML: ${yaml.errors[0].message}`);
      const document = validateWorkflowFile(yaml.toJS({ maxAliasCount: 20 }));
      graph = document.workflow.graph as WorkflowGraph;
      title ||= document.workflow.title;
    } else graph = parseJsonFlag<WorkflowGraph>(graphFlag, "--graph");
    if (!title) throw new Error("Missing --title for workflow run-once.");
    const idempotencyKey = typeof flags["idempotency-key"] === "string" ? flags["idempotency-key"] : "";
    if (!idempotencyKey) throw new Error("Missing --idempotency-key for workflow run-once.");
    const sourceChatId = flags["source-chat"];
    if (typeof sourceChatId !== "string" || !sourceChatId) throw new Error("Missing --source-chat for workflow run-once.");
    const input = typeof flags.input === "string" ? parseJsonFlag<Record<string, unknown>>(flags.input, "--input") : {};
    const result = await client.runWorkflowOnce({ title, graph, idempotencyKey, input, ...runRouting(), sourceChatId });
    if (flags.wait === true) result.run = await waitForWorkflowRun(client, result.workflow.id, result.run);
    if (flags.json === true) printJson(result);
    else { printWorkflowDetail(result.workflow); printWorkflowRun(result.run); }
    return;
  }

  if (subcommand === "run") {
    const workflowId = rest[0] ? await requiredResolvedWorkflowId(client, rest[0], flags, "run") : undefined;
    if (!workflowId) throw new Error("Missing workflow ID. Example: openmates workflows run <id>");
    const idempotencyKey = typeof flags["idempotency-key"] === "string" ? flags["idempotency-key"] : "";
    if (!idempotencyKey) throw new Error("Missing --idempotency-key. Reuse this stable key when retrying the same workflow run.");
    const mode = flags.mode === "test" ? "test" : "manual";
    const input = typeof flags.input === "string" ? parseJsonFlag<Record<string, unknown>>(flags.input, "--input") : {};
    let run = await client.runWorkflow(workflowId, { idempotencyKey, mode, input, ...runRouting() });
    if (flags.wait === true) {
      run = await waitForWorkflowRun(client, workflowId, run);
    }
    if (flags.json === true) {
      printJson(run);
    } else {
      printWorkflowRun(run);
    }
    return;
  }

  if (subcommand === "runs") {
    const workflowId = rest[0] ? await requiredResolvedWorkflowId(client, rest[0], flags, "runs") : undefined;
    if (!workflowId) throw new Error("Missing workflow ID. Example: openmates workflows runs <id>");
    const runs = await client.listWorkflowRuns(workflowId);
    if (flags.json === true) {
      printJson(runs);
    } else {
      printWorkflowRuns(runs);
    }
    return;
  }

  if (subcommand === "run-show") {
    const workflowId = rest[0] ? await requiredResolvedWorkflowId(client, rest[0], flags, "run-show") : undefined;
    const runId = rest[1];
    if (!workflowId || !runId) throw new Error("Missing workflow/run ID. Example: openmates workflows run-show <workflow-id> <run-id>");
    const run = await client.getWorkflowRun(workflowId, runId);
    if (flags.json === true) {
      printJson(run);
    } else {
      printWorkflowRun(run);
    }
    return;
  }

  if (subcommand === "run-delete") {
    const workflowId = rest[0] ? await requiredResolvedWorkflowId(client, rest[0], flags, "run-delete") : undefined;
    const runId = rest[1];
    if (!workflowId || !runId) throw new Error("Usage: openmates workflows run-delete <workflow-id> <run-id> --yes");
    if (flags.yes !== true) throw new Error("Run deletion forgets its delivered-result history. Existing chat messages remain. Pass --yes to confirm.");
    const result = await client.deleteWorkflowRun(workflowId, runId);
    if (flags.json === true) printJson(result);
    else kv("Status", result.status);
    return;
  }

  if (subcommand === "run-cancel") {
    const workflowId = rest[0] ? await requiredResolvedWorkflowId(client, rest[0], flags, "run-cancel") : undefined;
    const runId = rest[1];
    if (!workflowId || !runId) throw new Error("Missing workflow/run ID. Example: openmates workflows run-cancel <workflow-id> <run-id>");
    const result = await client.cancelWorkflowRun(workflowId, runId);
    if (flags.json === true) {
      printJson(result);
    } else {
      kv("Status", result.status);
    }
    return;
  }

  if (subcommand === "step-test" || subcommand === "step-preview") {
    const workflowId = rest[0] ? await requiredResolvedWorkflowId(client, rest[0], flags, "step-test") : undefined;
    const stepId = rest[1];
    if (!workflowId || !stepId) throw new Error("Missing workflow/step ID. Example: openmates workflows step-test <workflow-id> <step-id> --yes");
    const input = typeof flags.input === "string" ? parseJsonFlag<Record<string, unknown>>(flags.input, "--input") : {};
    const node = typeof flags.node === "string" ? parseJsonFlag<WorkflowNode>(flags.node, "--node") : undefined;
    const upstreamOutputs = typeof flags.upstream === "string" ? parseJsonFlag<Record<string, Record<string, unknown>>>(flags.upstream, "--upstream") : undefined;
    if (subcommand === "step-preview") {
      const preview = await client.previewWorkflowStep(workflowId, stepId, { input, node, upstreamOutputs });
      if (flags.json === true) printJson(preview);
      else console.log(String(preview.text ?? preview.message ?? preview.body ?? ""));
      return;
    }
    const run = await client.testWorkflowStep(workflowId, stepId, { input, node, upstreamOutputs, confirmed: flags.yes === true });
    if (flags.json === true) {
      printJson(run);
    } else {
      printWorkflowRun(run);
    }
    return;
  }

  if (subcommand === "respond") {
    const workflowId = rest[0] ? await requiredResolvedWorkflowId(client, rest[0], flags, "respond") : undefined;
    const runId = rest[1];
    const stepId = rest[2];
    if (!workflowId || !runId || !stepId) throw new Error("Missing workflow/run/step ID. Example: openmates workflows respond <workflow-id> <run-id> <step-id> --input '{\"answer\":\"Berlin\"}'");
    const input = typeof flags.input === "string" ? parseJsonFlag<Record<string, unknown>>(flags.input, "--input") : {};
    const run = await client.respondToWorkflowRun(workflowId, runId, stepId, input);
    if (flags.json === true) {
      printJson(run);
    } else {
      printWorkflowRun(run);
    }
    return;
  }

  if (subcommand === "help-app") {
    const capabilityId = rest[0];
    if (!capabilityId) throw new Error("Missing app skill. Example: openmates workflows help-app weather.forecast");
    const capabilities = await client.listWorkflowCapabilities();
    const capability = capabilities.find((item) => item.id === capabilityId || item.id === capabilityId.replace(":", "."));
    if (!capability) throw new Error(`Workflow capability not found: ${capabilityId}`);
    if (flags.json === true) {
      printJson(capability);
    } else {
      printWorkflowCapabilityHelp(capability);
    }
    return;
  }

  throw new Error(`Unknown workflows command '${subcommand}'. Run 'openmates workflows --help'.`);
}

function printWorkflowList(workflows: WorkflowSummary[]): void {
  if (workflows.length === 0) {
    console.log("No workflows yet.");
    console.log("Create one: openmates workflows create --title \"Morning brief\" --graph '<json>'");
    return;
  }
  header(`Workflows  \x1b[2m(${workflows.length})\x1b[0m\n`);
  for (const workflow of workflows) {
    const identity = [workflow.category, workflow.icon ? `icon: ${workflow.icon}` : null].filter(Boolean).join(" · ");
    kv(workflow.slug || workflow.id.slice(0, 8), `${workflow.title}${identity ? ` · ${identity}` : ""} · ${workflow.status}${workflow.trigger_summary ? ` · ${workflow.trigger_summary}` : ""}`, 18);
  }
}

function printWorkflowDetail(workflow: WorkflowDetail): void {
  header(`${workflow.title}\n`);
  if (workflow.slug) kv("Slug", workflow.slug);
  kv("ID", workflow.id);
  if (workflow.category) kv("Category", workflow.category);
  if (workflow.icon) kv("Icon", workflow.icon);
  kv("Status", workflow.status);
  kv("Enabled", String(workflow.enabled));
  kv("Run content", workflow.run_content_retention ?? "last_5");
  if (workflow.trigger_summary) kv("Trigger", workflow.trigger_summary);
  kv("Nodes", String(workflow.graph.nodes.length));
  for (const warning of workflow.authoring_warnings ?? []) kv("Warning", warning.message);
  console.log(`\n\x1b[2mRun: openmates workflows run ${workflow.slug || workflow.id}\x1b[0m`);
}

function printWorkflowAuthoringWarnings(warnings: Array<{ message?: string; code?: string }>): void {
  for (const warning of warnings) kv("Warning", warning.message ?? warning.code ?? "Workflow AI validation was unavailable.");
}

function printWorkflowInputSession(session: WorkflowInputSessionResult): void {
  header(`Workflow Input ${session.session_id}\n`);
  kv("Status", session.status);
  kv("Events", String(session.event_cursor));
  kv("Undo", session.undo_available ? "available" : "unavailable");
  if (session.message) kv("Message", session.message);
  if (session.error) kv("Error", session.error);
  if (session.workflow) kv("Workflow", `${session.workflow.title} (${session.workflow.id})`);
  if (session.preview_workflow) kv("Preview (saving)", `${session.preview_workflow.title} (${session.preview_workflow.id})`);
  const metrics = session.authoring_metrics;
  if (metrics && typeof metrics.total_seconds === "number") kv("AI planning", `${metrics.total_seconds.toFixed(2)}s`);
  if (metrics && typeof metrics.estimated_cost_usd === "number") kv("Est. AI cost", `$${metrics.estimated_cost_usd.toFixed(5)}`);
  if (session.workflow && !session.workflow.enabled) kv("Activation", "Disabled; enable it when you are ready.");
}

function printWorkflowRun(run: WorkflowRunDetail): void {
  header(`Workflow Run ${run.id}\n`);
  kv("Status", run.status);
  kv("Trigger", run.trigger_type);
  kv("Content", run.content_available === false ? "unavailable" : `${run.content_storage ?? "unknown"} (${run.content_retention_mode ?? "last_5"})`);
  if (run.content_expires_at) kv("Content expires", new Date(run.content_expires_at * 1000).toISOString());
  kv("Nodes", String(run.node_runs?.length ?? 0));
  if (run.error_summary) kv("Error", run.error_summary);
}

function parseWorkflowRunContentRetention(value: string | boolean | undefined): WorkflowRunContentRetention | undefined {
  if (value === undefined || value === false) return undefined;
  if (value === "last_5" || value === "none") return value;
  throw new Error("Invalid --run-content-retention. Expected last_5 or none.");
}

function assertWorkflowFilePath(path: string): void {
  if (!path.endsWith(".workflow.yml")) throw new Error("Workflow files must use the .workflow.yml extension.");
}

function printWorkflowRuns(runs: WorkflowRunDetail[]): void {
  if (runs.length === 0) {
    console.log("No workflow runs yet.");
    return;
  }
  header(`Workflow Runs  \x1b[2m(${runs.length})\x1b[0m\n`);
  for (const run of runs) {
    kv(run.id.slice(0, 8), `${run.status} · ${run.trigger_type}`, 10);
  }
}

function printWorkflowCapabilities(capabilities: WorkflowCapability[]): void {
  header("Workflow Capabilities\n");
  for (const capability of capabilities) {
    const state = capability.enabled ? "enabled" : `disabled${capability.reason ? `: ${capability.reason}` : ""}`;
    kv(capability.id, `${capability.title} · ${state}`, 24);
  }
}

function printWorkflowCapabilityHelp(capability: WorkflowCapability): void {
  header(`${capability.title}\n`);
  kv("ID", capability.id);
  kv("Type", capability.type);
  kv("Enabled", capability.enabled ? "yes" : "no");
  if (capability.reason) kv("Reason", capability.reason);
  const metadata = capability.metadata ?? {};
  const workflow = metadata.workflow as Record<string, unknown> | undefined;
  if (workflow) {
    kv("Effect", String(workflow.effect ?? "unknown"));
    kv("Execution", String(workflow.execution_mode ?? "unknown"));
    kv("Approval", String(workflow.approval ?? "unknown"));
    kv("Unattended", workflow.unattended === true ? "yes" : "no");
  }
  if (metadata.input_schema) {
    console.log("\nInput schema:");
    console.log(JSON.stringify(metadata.input_schema, null, 2));
  }
  if (workflow?.test_example_input) {
    console.log("\nTest example:");
    console.log(JSON.stringify(workflow.test_example_input, null, 2));
  }
}

