  type?: string;
  description?: string;
  properties?: Record<string, JsonSchema>;
  items?: JsonSchema;
  required?: string[];
  enum?: unknown[];
  default?: unknown;
};

type GeneratedAppSkillCommand = {
  app_id: string;
  skill_id: string;
  description?: string;
  schema?: JsonSchema;
};

type AppSkillInputShape = {
  kind: "request-array" | "flat";
  schema: JsonSchema;
  properties: Record<string, JsonSchema>;
  required: string[];
};

