function appSkillCliType(schema: JsonSchema): string {
  if (schema.enum && schema.enum.length > 0) return schema.enum.map(String).join("|");
  if (schema.type === "array") return "csv";
  return schema.type ?? "value";
}

function buildGeneratedAppSkillExample(
  command: GeneratedAppSkillCommand,
  shape: AppSkillInputShape,
): string {
  const primary = primaryPositionalProperty(shape.properties, shape.required);
  const value = primary ? String(buildExampleValue(primary, shape.properties[primary]?.type ?? "string", shape.properties[primary]?.description ?? "")) : "<value>";
  return `openmates apps ${command.app_id} ${command.skill_id} ${JSON.stringify(value)} --json`;
}

function kebabCase(value: string): string {
  return value.replace(/_/g, "-");
}

async function handleApps(
  client: OpenMatesClient,
  subcommand: string | undefined,
  rest: string[],
  flags: Record<string, string | boolean>,
): Promise<void> {
  // API key is optional — session cookies are used when absent
  const apiKey = resolveApiKey(flags) ?? undefined;

  if (!subcommand || subcommand === "help") {
    printAppsHelp();
    return;
  }

  if (flags.help === true && subcommand === "images" && (rest[0] === "detect-ai" || rest[0] === "detect_ai")) {
    printImagesDetectAiHelp();
    return;
  }

  // `apps <app> --help` → show app info. Skill help uses the explicit
  // metadata command `apps skill-info <app> <skill>`, not a generic runner.
  if (
    flags.help === true &&
    subcommand !== "list" &&
    subcommand !== "info" &&
    subcommand !== "skill-info" &&
    subcommand !== "examples"
  ) {
    const potentialApp = subcommand;
    const potentialSkill = rest[0];
    if (potentialSkill) {
      const command = findGeneratedAppSkillCommand(potentialApp, potentialSkill);
      if (command) {
        printGeneratedAppSkillCommandHelp(command);
        return;
      }
      console.error(
        "Generic app-skill CLI execution is not supported.\n\n" +
          "Use an explicit typed command for this app skill, or inspect metadata with:\n" +
          `  openmates apps skill-info ${potentialApp} ${potentialSkill}\n`,
      );
      process.exit(1);
    }
    try {
      const data = await client.getApp(potentialApp);
      await printAppInfo(client, data as AppMetadata);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      console.error(`\x1b[31m✗ ${msg}\x1b[0m\n`);
      const suggestion = await suggestAppOrSkill(
        client,
        potentialApp,
        potentialSkill ?? "",
        apiKey,
      );
      if (suggestion) console.error(`${suggestion}\n`);
      console.error(`List all apps: openmates apps list`);
      process.exit(1);
    }
    return;
  }

  if (subcommand === "list") {
    const data = await client.listApps(apiKey);
    if (flags.json === true) {
      printJson(data);
    } else {
      printAppsList(data as AppsListResponse);
    }
    return;
  }

  if (subcommand === "info") {
    const appId = rest[0];
    if (!appId) {
      console.error("Missing app ID.\n");
      printAppsHelp();
      process.exit(1);
    }
    try {
      const data = await client.getApp(appId);
      if (flags.json === true) {
        printJson(data);
      } else {
        await printAppInfo(client, data as AppMetadata);
      }
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      console.error(`\x1b[31m✗ ${msg}\x1b[0m\n`);
      const suggestion = await suggestAppOrSkill(client, appId, "", apiKey);
      if (suggestion) console.error(`${suggestion}\n`);
      console.error(`List all apps: openmates apps list`);
      process.exit(1);
    }
    return;
  }

  if (subcommand === "skill-info") {
    const [appId, skillId] = rest;
    if (!appId || !skillId) {
      console.error(`Missing ${!appId ? "app ID" : "skill ID"}.\n`);
      printAppsHelp();
      process.exit(1);
    }
    const data = await client.getSkillInfo(appId, skillId, apiKey);
    if (flags.json === true) {
      printJson(data);
    } else {
      await printSkillInfo(client, appId, data as SkillMetadata);
    }
    return;
  }

  if (subcommand === "examples") {
    const [appId, skillId] = rest;
    if (flags.help === true) {
      printAppsHelp();
      return;
    }
    if (!appId) {
      console.error("Missing app ID.\n");
      printAppsHelp();
      process.exit(1);
    }

    const examples = skillId
      ? listExampleChatsForSkill(appId, skillId)
      : listExampleChatsForApp(appId);
    if (flags.json === true) {
      printJson({
        app_id: appId,
        skill_id: skillId ?? null,
        examples: examples.map(exampleChatForSkillToJson),
      });
    } else {
      printExampleChatsForSkill(appId, skillId, examples);
    }
    return;
  }

  if (subcommand === "run") {
    console.error(
      "Generic app-skill CLI execution is not supported.\n\n" +
        "Use an explicit typed command such as `openmates tasks ...`, `openmates workflows ...`, or another app-specific command.\n" +
        "Inspect app metadata with `openmates apps list`, `openmates apps info <app-id>`, or `openmates apps skill-info <app-id> <skill-id>`.\n",
    );
    process.exit(1);
  }

  // ── travel booking-link: resolve a booking URL from a booking_token ────
  // openmates apps travel booking-link --token "..." [--context '{...}']
  if (subcommand === "travel" && rest[0] === "booking-link") {
    const token = typeof flags.token === "string" ? flags.token : undefined;
    if (!token) {
      console.error(
        "Missing --token flag.\n\n" +
          "Usage:\n" +
          "  openmates apps travel booking-link --token \"<booking_token>\" [--context '<json>']\n\n" +
          "The booking_token is shown in the output of:\n" +
          "  openmates apps travel search_connections --input '...'\n",
      );
      process.exit(1);
    }
    let bookingContext: Record<string, string> | undefined;
    if (typeof flags.context === "string") {
      try {
        bookingContext = JSON.parse(flags.context) as Record<string, string>;
      } catch {
        console.error("Invalid --context JSON.");
        process.exit(1);
      }
    }
    try {
      const result = await client.getBookingLink({
        bookingToken: token,
        bookingContext,
        apiKey,
      });
      if (flags.json === true) {
        printJson(result);
      } else if (result.success && result.booking_url) {
        header(
          `Travel › Booking Link${result.credits_charged ? `  \x1b[2m(${result.credits_charged} credits)\x1b[0m` : ""}\n`,
        );
        kv("URL", result.booking_url);
        if (result.booking_provider) kv("Provider", result.booking_provider);
        console.log(
          `\n\x1b[2mOpen this URL in your browser to complete the booking.\x1b[0m`,
        );
      } else {
        console.error(
          `\x1b[31m✗ Booking link not found:\x1b[0m ${result.error ?? "no booking URL available for this flight"}`,
        );
        process.exit(1);
      }
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      console.error(`\x1b[31m✗ Booking link request failed:\x1b[0m ${msg}`);
      process.exit(1);
    }
    return;
  }

  if (subcommand === "images" && (rest[0] === "detect-ai" || rest[0] === "detect_ai")) {
    await handleImagesDetectAi(client, rest.slice(1), flags);
    return;
  }

  if (subcommand === "code" && rest[0] === "run") {
    await handleCodeRun(client, flags, apiKey);
    return;
  }

  if (subcommand === "design" && rest[0] === "export-icon") {
    await handleDesignIconExport(client, rest.slice(1), flags, apiKey);
    return;
  }

  const generatedCommand = findGeneratedAppSkillCommand(subcommand, rest[0]);
  if (generatedCommand) {
    await handleGeneratedAppSkillCommand(client, generatedCommand, rest.slice(1), flags, apiKey);
    return;
  }

  const app = subcommand;
  const skill = rest[0];
  if (app && skill) {
    console.error(
      "Generic app-skill CLI execution is not supported.\n\n" +
        `There is no generic runner for \`openmates apps ${app} ${skill}\`.\n` +
        "Use the app's explicit typed command or inspect metadata with:\n" +
        `  openmates apps skill-info ${app} ${skill}\n`,
    );
    process.exit(1);
  }

  // `apps <app>` with no skill — treat as `apps info <app>`
  if (app && !skill) {
    try {
      const data = await client.getApp(app);
      if (flags.json === true) {
        printJson(data);
      } else {
        await printAppInfo(client, data as AppMetadata);
      }
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      console.error(`\x1b[31m✗ ${msg}\x1b[0m\n`);
      const suggestion = await suggestAppOrSkill(client, app, "", apiKey);
      if (suggestion) console.error(`${suggestion}\n`);
      console.error(`List all apps: openmates apps list`);
      process.exit(1);
    }
    return;
  }

  console.error(`Unknown apps subcommand '${subcommand}'.\n`);
  printAppsHelp();
  process.exit(1);
}

async function handleImagesDetectAi(
  client: OpenMatesClient,
  positionals: string[],
  flags: Record<string, string | boolean>,
): Promise<void> {
  if (flags.help === true) {
    printImagesDetectAiHelp();
    return;
  }

  const fileFlag = stringFlag(flags, "file");
  const file = fileFlag ?? positionals[0];
  if (!file) {
    console.error(
      "Missing image file.\n\n" +
        "Usage:\n" +
        "  openmates apps images detect-ai --file ./image.png [--json]\n",
    );
    process.exit(1);
  }

  if ((fileFlag && positionals.length > 0) || (!fileFlag && positionals.length > 1)) {
    const unexpected = fileFlag ? positionals : positionals.slice(1);
    console.error(
      `Unexpected argument(s): ${unexpected.join(" ")}\n\n` +
        "Run: openmates apps images detect-ai --help",
    );
    process.exit(1);
  }

  let resolvedFile: string;
  try {
    resolvedFile = realpathSync(file);
  } catch {
    console.error(`\x1b[31m✗ Image file not found:\x1b[0m ${file}`);
    process.exit(1);
  }

  try {
    const uploadResult = await uploadFile(resolvedFile, client.getSession());
    const summary = buildImagesAiDetectionSummary(uploadResult, resolvedFile);
    if (flags.json === true) {
      printJson({
        success: summary.status === "success",
        ...summary,
        ai_detection: uploadResult.ai_detection,
      });
      return;
    }

    header("Images › Detect AI");
    kv("File", summary.file);
    kv("Provider", summary.provider ?? "n/a");
    kv("Detection status", summary.status);
    kv(
      "AI-generated probability",
      summary.ai_generated === null ? "unavailable" : `${(summary.ai_generated * 100).toFixed(1)}%`,
    );
    kv("Classification", summary.label);
    kv("Stored upload embed", summary.embed_id);
    if (summary.error) kv("Detection error", summary.error);
    console.log("\n\x1b[2mThis command uses the authenticated upload pipeline, which stores the image and returns Sightengine metadata.\x1b[0m");
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    console.error(`\x1b[31m✗ Images AI detection failed:\x1b[0m ${msg}`);
    process.exit(1);
  }
}

function printImagesDetectAiHelp(): void {
  console.log(`Images AI detection command:
  openmates apps images detect-ai --file <image> [--json]
  openmates apps images detect-ai <image> [--json]

Options:
  --file <path>       Local PNG, JPEG, WEBP, or other upload-supported image file.
  --json              Print raw detection metadata and classification as JSON.

Authentication:
  Requires a logged-in CLI session because it reuses the authenticated upload pipeline.

Examples:
  openmates apps images detect-ai --file ./image.png
  openmates apps images detect-ai ./image.webp --json`);
}

async function handleDesignIconExport(
  client: OpenMatesClient,
  positionals: string[],
  flags: Record<string, string | boolean>,
  apiKey?: string,
): Promise<void> {
  if (flags.help === true) {
    printDesignIconExportHelp();
    return;
  }
  const outputPath = stringFlag(flags, "output");
  if (!outputPath) {
    console.error(
      "Missing --output flag.\n\n" +
        "Usage:\n" +
        "  openmates apps design export-icon lucide:home --output home.svg [--color '#111827']\n" +
        "  openmates apps design export-icon --prefix lucide --name home --format png --size 64 --output home.png\n",
    );
    process.exit(1);
  }

  const format = parseDesignIconExportFormat(flags.format);
  const size = parsePositiveIntegerFlag(flags.size, "--size");
  const width = parsePositiveIntegerFlag(flags.width, "--width");
  const height = parsePositiveIntegerFlag(flags.height, "--height");
  const iconRef = parseDesignIconReference(positionals, flags);
  try {
    const result = await exportDesignIcon({
      ...iconRef,
      outputPath,
      format,
      color: stringFlag(flags, "color"),
      palette: flags.palette === true,
      allowPaletteRecolor: flags["allow-palette-recolor"] === true,
      size,
      width,
      height,
      fetchSvg: async (path) => (await client.getRaw(path, apiKey)).data,
    });
    if (flags.json === true) {
      printJson({
        success: true,
        format: result.format,
        content_type: result.contentType,
        output_path: result.outputPath,
        svg_path: result.svgPath,
        bytes: result.data.byteLength,
      });
    } else {
      console.log(`Exported ${result.format.toUpperCase()} icon to ${result.outputPath}`);
    }
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    console.error(`\x1b[31m✗ Design icon export failed:\x1b[0m ${msg}`);
    process.exit(1);
  }
}

function parseDesignIconReference(
  positionals: string[],
  flags: Record<string, string | boolean>,
): { svgPath?: string; prefix?: string; name?: string } {
  const svgPath = stringFlag(flags, "svg-path");
  if (svgPath) return { svgPath };
  const icon = stringFlag(flags, "icon") ?? positionals[0];
  if (icon) {
    const [prefix, name, extra] = icon.split(":");
    if (!prefix || !name || extra !== undefined) {
      throw new Error("Icon reference must use prefix:name, such as lucide:home");
    }
    return { prefix, name };
  }
  return {
    prefix: stringFlag(flags, "prefix"),
    name: stringFlag(flags, "name"),
  };
}

function parseDesignIconExportFormat(value: string | boolean | undefined): DesignIconExportFormat | undefined {
  if (value === undefined) return undefined;
  if (value === "svg" || value === "png") return value;
  throw new Error("--format must be svg or png");
}

interface CodeRunSkillResponse {
  success?: boolean;
  data?: {
    results?: Array<{
      execution_id?: string;
      status?: string;
      target_filename?: string;
      files?: string[];
      stream_path?: string;
      status_path?: string;
      credits_per_minute?: number;
    }>;
  };
}

async function handleCodeRun(
  client: OpenMatesClient,
  flags: Record<string, string | boolean>,
  apiKey?: string,
): Promise<void> {
  const requests = await buildCodeRunRequestsFromFlags({
    code: typeof flags.code === "string" ? flags.code : undefined,
    language: typeof flags.language === "string" ? flags.language : undefined,
    filename: typeof flags["source-filename"] === "string" ? flags["source-filename"] : undefined,
    entry: typeof flags.entry === "string" ? flags.entry : undefined,
    file: typeof flags.file === "string" ? flags.file : undefined,
    dir: typeof flags.dir === "string" ? flags.dir : undefined,
    url: typeof flags.url === "string" ? flags.url : undefined,
    repo: typeof flags.repo === "string" ? flags.repo : undefined,
    include: typeof flags.include === "string" ? flags.include : undefined,
    exclude: typeof flags.exclude === "string" ? flags.exclude : undefined,
    noInternet: flags["no-internet"] === true,
    chat: typeof flags.chat === "string" ? flags.chat : undefined,
    targetEmbed: typeof flags["target-embed"] === "string" ? flags["target-embed"] : undefined,
  });

  if (flags.json !== true) {
    const first = requests[0];
    if (first.mode === "direct") {
      process.stderr.write(`Starting Code Run for ${first.entry_path} (${first.files.length} file${first.files.length === 1 ? "" : "s"})...\n`);
    }
  }

  const downloadOptions = generatedFileOptions(flags, {requests});
  const response = await client.runSkill({
    app: "code",
    skill: "run",
    inputData: { requests: requests as unknown as Array<Record<string, unknown>> },
    apiKey,
    promptInjectionProtection: flags["disable-prompt-injection-protection"] === true ? false : undefined,
  }) as CodeRunSkillResponse;
  const result = response.data?.results?.[0];
  if (!result?.execution_id || !result.status_path) {
    throw new Error("Code Run did not return an execution id.");
  }

  const streamAuth = apiKey ? null : await client.getCodeRunStreamAuth();
  let finalStatus: Record<string, unknown>;
  let usedStream = false;
  if (streamAuth && result.stream_path) {
    usedStream = true;
    const url = buildCodeRunStreamUrl({
      apiUrl: client.apiUrl,
      executionId: result.execution_id,
      sessionId: streamAuth.sessionId,
      token: streamAuth.token,
    });
    try {
      finalStatus = await streamCodeRunToTerminal(url, flags.json === true);
    } catch {
      // Recover the existing job through the independently authenticated status route.
      usedStream = false;
      process.stderr.write(`Code Run live stream unavailable; polling execution ${result.execution_id}. No new run started.\n`);
      finalStatus = await pollCodeRunStatus(client, result.status_path, apiKey, flags.json === true);
    }
  } else {
    finalStatus = await pollCodeRunStatus(client, result.status_path, apiKey, flags.json === true);
  }

  // Stream updates may omit signed artifact URLs; retrieve the complete owner-authorized result.
  if (usedStream) finalStatus = await client.getCodeRunStatus(result.status_path, apiKey);
  const localFiles = finalStatus.status === "finished" && finalStatus.exit_code === 0
    ? await downloadGeneratedFiles(finalStatus, downloadOptions) : [];
  if (flags.json === true) {
    printJson({ ...result, final: finalStatus, ...(localFiles.length ? {local_files: localFiles} : {}) });
  } else {
    const finalOutput = formatCodeRunFinalStatusOutput(finalStatus, { includeOutput: !usedStream });
    if (finalOutput) process.stdout.write(finalOutput);
    for (const file of localFiles) console.log(`Saved ${file.path}`);
  }
  const finalExitCode = typeof finalStatus.exit_code === "number" ? finalStatus.exit_code : null;
  const finalState = typeof finalStatus.status === "string" ? finalStatus.status : "unknown";
  if (finalState !== "finished" || finalExitCode !== 0) {
    throw new Error(`Code Run ${finalState} with exit code ${finalExitCode ?? "unknown"}.`);
  }
}

async function streamCodeRunToTerminal(url: string, jsonMode: boolean): Promise<Record<string, unknown>> {
  return await new Promise((resolve, reject) => {
    const ws = new WebSocket(url);
    let lastStatus: Record<string, unknown> = {};
    ws.on("message", (data) => {
      try {
        const message = JSON.parse(String(data)) as { type?: string; payload?: Record<string, unknown> };
        const payload = message.payload ?? {};
        if (message.type === "code_run_event") {
          const kind = String(payload.kind ?? "status");
          const text = String(payload.text ?? "");
          if (!jsonMode) {
            if (kind === "stdout") process.stdout.write(text);
            else process.stderr.write(text);
          }
        } else if (message.type === "code_run_update") {
          lastStatus = { ...lastStatus, ...payload };
          const status = String(payload.status ?? "");
          if (["finished", "failed", "timeout", "cancelled"].includes(status)) {
            ws.close();
            resolve(lastStatus);
          }
        }
      } catch (err) {
        ws.close();
        reject(err);
      }
    });
    ws.on("error", () => reject(new Error("Code Run stream failed.")));
    ws.on("close", () => {
      if (Object.keys(lastStatus).length > 0) resolve(lastStatus);
    });
  });
}

async function pollCodeRunStatus(
  client: OpenMatesClient,
  statusPath: string,
  apiKey: string | undefined,
  jsonMode: boolean,
): Promise<Record<string, unknown>> {
  for (;;) {
    const status = await client.getCodeRunStatus(statusPath, apiKey);
    const value = String(status.status ?? "");
    if (!jsonMode && value) process.stderr.write(`Code Run status: ${value}\n`);
    if (["finished", "failed", "timeout", "cancelled"].includes(value)) return status;
    await new Promise((resolve) => setTimeout(resolve, 1000));
  }
}

/**
 * Suggest the closest app or skill name when a 404 occurs.
 * Uses Levenshtein distance for fuzzy matching against available apps/skills.
 */
async function suggestAppOrSkill(
  client: OpenMatesClient,
  app: string,
  skill: string,
  apiKey?: string,
): Promise<string | null> {
  try {
    const data = (await client.listApps(apiKey)) as {
      apps?: Array<{ id: string; skills?: Array<{ id: string }> }>;
    };
    const apps = data.apps ?? [];
    const appIds = apps.map((a) => a.id);

    // Check if app exists
    const matchedApp = apps.find((a) => a.id === app);
    if (!matchedApp) {
      // Suggest closest app name
      const closest = findClosestMatch(app, appIds);
      if (closest) {
        const suffix = skill ? ` ${skill}` : "";
        return `Did you mean: openmates apps ${closest}${suffix}`;
      }
      return `Available apps: ${appIds.join(", ")}`;
    }

    // App exists but skill not found — suggest closest skill
    const skillIds = (matchedApp.skills ?? []).map((s) => s.id);
    const closest = findClosestMatch(skill, skillIds);
    if (closest) {
      return `Did you mean: openmates apps ${app} ${closest}`;
    }
    if (skillIds.length > 0) {
      return `Available skills for '${app}': ${skillIds.join(", ")}`;
    }
    return null;
  } catch {
    return null;
  }
}

/** Simple Levenshtein distance for short CLI names. */
function levenshtein(a: string, b: string): number {
  const m = a.length;
  const n = b.length;
  const dp: number[][] = Array.from({ length: m + 1 }, () =>
    Array(n + 1).fill(0) as number[],
  );
  for (let i = 0; i <= m; i++) dp[i][0] = i;
  for (let j = 0; j <= n; j++) dp[0][j] = j;
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      dp[i][j] =
        a[i - 1] === b[j - 1]
          ? dp[i - 1][j - 1]
          : 1 + Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]);
    }
  }
  return dp[m][n];
}

/** Find the closest match within a reasonable edit distance (max 3). */
function findClosestMatch(
  input: string,
  candidates: string[],
): string | null {
  let best: string | null = null;
  let bestDist = 4; // max acceptable distance
  for (const candidate of candidates) {
    const dist = levenshtein(input.toLowerCase(), candidate.toLowerCase());
    if (dist < bestDist) {
      bestDist = dist;
      best = candidate;
    }
  }
  return best;
}

