/** Format a share duration for display */
/**
 * Simple YAML serializer for chat export (no external dependency).
 * Handles nested objects, arrays, and multiline strings.
 * Mirrors chatExportService.convertToYamlString for compatibility.
 */
export function serializeToYaml(
  data: Record<string, unknown>,
  indent: number = 0,
): string {
  const pad = "  ".repeat(indent);
  let out = "";
  for (const [key, val] of Object.entries(data)) {
    if (val === null || val === undefined) {
      out += `${pad}${key}: null\n`;
    } else if (typeof val === "boolean" || typeof val === "number") {
      out += `${pad}${key}: ${val}\n`;
    } else if (typeof val === "string") {
      if (val.includes("\n")) {
        out += `${pad}${key}: |\n`;
        for (const line of val.split("\n")) {
          out += `${pad}  ${line}\n`;
        }
      } else {
        // Escape strings that could be misinterpreted as YAML
        const needsQuote =
          val.includes(":") ||
          val.includes("#") ||
          val.startsWith("{") ||
          val.startsWith("[") ||
          val.startsWith("'") ||
          val.startsWith('"') ||
          val === "" ||
          val === "true" ||
          val === "false" ||
          val === "null";
        out += `${pad}${key}: ${needsQuote ? `"${val.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"` : val}\n`;
      }
    } else if (Array.isArray(val)) {
      out += `${pad}${key}:\n`;
      for (const item of val) {
        if (typeof item === "object" && item !== null) {
          out += `${pad}  -\n`;
          out += serializeToYaml(
            item as Record<string, unknown>,
            indent + 2,
          );
        } else {
          out += `${pad}  - ${formatYamlScalar(item)}\n`;
        }
      }
    } else if (typeof val === "object") {
      out += `${pad}${key}:\n`;
      out += serializeToYaml(val as Record<string, unknown>, indent + 1);
    }
  }
  return out;
}

function formatYamlScalar(value: unknown): string {
  if (value === null || value === undefined) return "null";
  if (typeof value === "boolean" || typeof value === "number") return String(value);
  if (typeof value === "string") {
    const needsQuote =
      value.includes(":") ||
      value.includes("#") ||
      value.startsWith("{") ||
      value.startsWith("[") ||
      value.startsWith("'") ||
      value.startsWith('"') ||
      value === "" ||
      value === "true" ||
      value === "false" ||
      value === "null";
    return needsQuote ? `"${value.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"` : value;
  }
  return JSON.stringify(value);
}

