function printWikiHelp(): void {
  console.log("Wikipedia commands:\n  openmates wiki search <query> [--language en] [--json]\n  openmates wiki show <canonical-title> [--language en] [--json]");
}

export async function handleWiki(
  client: OpenMatesClient, action: string | undefined, rest: string[],
  flags: Record<string, string | boolean>,
): Promise<void> {
  if (!action || action === "help") { printWikiHelp(); return; }
  if (!["search", "show"].includes(action) || !rest.length) throw new Error("Use openmates wiki search <query> or openmates wiki show <canonical-title>.");
  const language = typeof flags.language === "string" ? flags.language : "en";
  const topic = rest.join(" ");
  const apiKey = resolveApiKey(flags);
  const sdk = apiKey ? createCliOpenMates(client, apiKey).wikipedia : null;
  if (action === "search") {
    const payload = sdk ? await sdk.search(topic, { language }) : { results: await client.searchWikipediaTitles(topic, language) };
    if (flags.json === true) printJson(payload);
    else for (const result of (payload.results as Array<{ title: string; description?: string; disambiguation?: boolean }>) ?? []) {
      console.log(`${result.title}${result.disambiguation ? " (choose a specific article)" : ""}${result.description ? ` — ${result.description}` : ""}`);
    }
    return;
  }
  const summary = sdk ? await sdk.summary(topic, { language }) : await client.wikipediaSummary(topic, language);
  let suggestions = null;
  let suggestionsUnavailable = false;
  try {
    const canonicalTitle = String(summary.title || topic);
    suggestions = sdk ? await sdk.learning(canonicalTitle, { language }) : await client.wikipediaLearning(canonicalTitle, language);
  } catch {
    suggestionsUnavailable = true;
  }
  const payload = { ...summary, questions: suggestions?.questions ?? [],
    related_articles: suggestions?.related_articles ?? [], suggestions_unavailable: suggestionsUnavailable };
  if (flags.json === true) printJson(payload);
  else {
    console.log(`${summary.title}\n${summary.description || ""}\n\n${summary.extract || ""}\n\n${summary.source_url || ""}`);
    if (suggestions) {
      console.log("\nRelated articles:");
      suggestions.related_articles.forEach((article) => console.log(`- ${article.title}`));
      console.log("\nFollow-up questions:");
      suggestions.questions.forEach((question, index) => console.log(`${index + 1}. ${question}`));
    } else console.log("\nArticle suggestions are temporarily unavailable. Try again shortly.");
  }
}

async function handleDocs(
  client: OpenMatesClient,
  subcommand: string | undefined,
  rest: string[],
  flags: Record<string, string | boolean>,
): Promise<void> {
  if (!subcommand || subcommand === "help" || flags.help === true) {
    printDocsHelp();
    return;
  }

  if (subcommand === "list") {
    const tree = await client.listDocs();
    if (flags.json === true) {
      printJson(tree);
    } else {
      printDocsTree(tree);
    }
    return;
  }

  if (subcommand === "search") {
    const query = rest.join(" ").trim();
    if (!query) {
      console.error("Error: provide a search query.");
      console.error("Usage: openmates docs search <query>");
      process.exit(1);
    }
    const results = await client.searchDocs(query);
    if (flags.json === true) {
      printJson(results);
    } else if (results.length === 0) {
      console.log(`No results for "${query}".`);
    } else {
      console.log(`Found ${results.length} result(s) for "${query}":\n`);
      for (const r of results) {
        console.log(`  \x1b[1m${r.title}\x1b[0m`);
        console.log(`  \x1b[2m${r.slug}\x1b[0m`);
        console.log(`  ${r.snippet}\n`);
      }
    }
    return;
  }

  if (subcommand === "show") {
    const slug = rest[0];
    if (!slug) {
      console.error("Error: provide a doc slug.");
      console.error("Usage: openmates docs show <slug>");
      process.exit(1);
    }
    const content = await client.getDoc(slug);
    console.log(content);
    return;
  }

  if (subcommand === "download") {
    const { writeFile, mkdir } = await import("node:fs/promises");
    const { join, dirname } = await import("node:path");

    if (flags.all === true) {
      // Download all docs
      const outputDir =
        typeof flags.output === "string" ? flags.output : "./openmates-docs";
      const tree = await client.listDocs();
      const slugs = collectSlugs(tree);
      await mkdir(outputDir, { recursive: true });
      let count = 0;
      for (const slug of slugs) {
        const content = await client.getDoc(slug);
        const filePath = join(outputDir, `${slug}.md`);
        await mkdir(dirname(filePath), { recursive: true });
        await writeFile(filePath, content, "utf-8");
        count++;
        process.stderr.write(`\r  Downloaded ${count}/${slugs.length}`);
      }
      process.stderr.write("\n");
      console.log(`Downloaded ${count} docs to ${outputDir}/`);
      return;
    }

    const slug = rest[0];
    if (!slug) {
      console.error(
        "Error: provide a doc slug or --all to download everything.",
      );
      console.error("Usage: openmates docs download <slug> [--output <path>]");
      console.error("       openmates docs download --all [--output <dir>]");
      process.exit(1);
    }
    const content = await client.getDoc(slug);
    const filename = typeof flags.output === "string" ? flags.output : `${slug.split("/").pop()}.md`;
    await writeFile(filename, content, "utf-8");
    console.log(`Saved to ${filename}`);
    return;
  }

  console.error(`Unknown docs subcommand '${subcommand}'.`);
  printDocsHelp();
  process.exit(1);
}

/** Collect all file slugs from a docs tree recursively. */
function collectSlugs(tree: DocsTree): string[] {
  const slugs: string[] = [];
  for (const file of tree.files) {
    slugs.push(file.slug);
  }
  for (const folder of tree.folders) {
    slugs.push(...collectSlugs(folder));
  }
  return slugs;
}

/** Print the docs tree to terminal with indentation. */
function printDocsTree(tree: DocsTree, indent = 0): void {
  const prefix = "  ".repeat(indent);
  for (const folder of tree.folders) {
    console.log(`${prefix}\x1b[1m${folder.title}\x1b[0m/`);
    printDocsTree(folder, indent + 1);
  }
  for (const file of tree.files) {
    console.log(
      `${prefix}  ${file.title} \x1b[2m(${file.slug})\x1b[0m`,
    );
  }
}

