    if (name) write(`  ${name}${speciality ? ` · ${speciality}` : ""}\n`);
    if (address) write(`  \x1b[2m${address}\x1b[0m\n`);
    writeEmbedLine(write);
  }
}

function renderAudioTranscribePreview(
  c: Record<string, unknown>,
