/** Run a command synchronously, returning stdout. Throws on non-zero exit. */
function exec(cmd: string, cwd: string): string {
  return execSync(cmd, { cwd, encoding: "utf-8", stdio: ["pipe", "pipe", "pipe"] }).trim();
}

/** Run a command with inherited stdio so the user sees output live. Returns the exit code. */
function runInteractive(cmd: string, args: string[], cwd: string): Promise<number> {
  return new Promise((resolve, reject) => {
    const child = nodeSpawn(cmd, args, { cwd, stdio: "inherit", shell: false });
    child.on("close", (code) => resolve(code ?? 1));
    child.on("error", reject);
  });
}

function beginEngineeringRuntimeOperation(
  installPath: string,
  operationType: string,
  services: string[],
): string | null {
  const manager = join(installPath, "scripts", "engineering_control_plane.py");
  const sharedConfig = join(homedir(), ".config", "openmates", "engineering-control-plane.env");
  if (!existsSync(manager) || !existsSync(sharedConfig)) return null;
  const requestedBy = process.env.CODEX_THREAD_ID || `openmates-cli:${process.pid}`;
  const args = [
    manager,
    "operation",
    "begin",
    "--operation-type",
    operationType,
    "--requested-by",
    requestedBy,
    "--resource",
    "dev-stack",
  ];
  for (const service of services) args.push("--service", service);
  const output = execFileSync("python3", args, {
    cwd: installPath,
    encoding: "utf-8",
    stdio: ["ignore", "pipe", "pipe"],
  });
  const parsed = JSON.parse(output.trim()) as { operation_key?: string };
  if (!parsed.operation_key) throw new Error("Engineering control plane did not return an operation key.");
  return parsed.operation_key;
}

function finishEngineeringRuntimeOperation(
  installPath: string,
  operationKey: string,
  status: "completed" | "failed",
): void {
  const manager = join(installPath, "scripts", "engineering_control_plane.py");
  execFileSync(
    "python3",
    [manager, "operation", "update", "--operation-key", operationKey, "--status", status],
    { cwd: installPath, stdio: ["ignore", "ignore", "pipe"] },
  );
}

async function withEngineeringRuntimeOperation(
  installPath: string,
  operationType: string,
  services: string[],
  mutation: () => Promise<void>,
): Promise<void> {
  const operationKey = beginEngineeringRuntimeOperation(installPath, operationType, services);
  try {
    await mutation();
  } catch (error) {
    if (operationKey) {
      try {
        finishEngineeringRuntimeOperation(installPath, operationKey, "failed");
      } catch (coordinationError) {
        console.error(`Failed to record runtime-operation failure: ${String(coordinationError)}`);
      }
    }
    throw error;
  }
  if (operationKey) finishEngineeringRuntimeOperation(installPath, operationKey, "completed");
}

function loadConfigForInstallPath(installPath: string): ServerConfig | null {
  const config = loadServerConfig();
  return config?.installPath === installPath ? config : null;
}

function getInstallMode(
  installPath: string,
  config: ServerConfig | null = loadConfigForInstallPath(installPath),
): NonNullable<ServerConfig["installMode"]> {
  if (config?.installMode) return config.installMode;
  if (existsSync(join(installPath, SOURCE_COMPOSE_FILE))) return "source";
  if (Object.values(ROLE_IMAGE_COMPOSE_FILES).some((composeFile) => existsSync(join(installPath, composeFile)))) return "image";
  return "source";
}

function getServerRole(flags: Record<string, string | boolean>, config: ServerConfig | null): ServerRole {
  return parseServerRole(typeof flags.role === "string" ? flags.role : config?.serverRole);
}

function getCoreProfile(flags: Record<string, string | boolean>, config: ServerConfig | null): CoreProfile {
  const value = typeof flags.profile === "string" ? flags.profile : config?.serverProfile;
  if (value === "minimal" || value === "standard" || value === "production") return value;
  return "production";
}

function normalizeServerDeploymentMode(value: string | undefined): ServerDeploymentMode {
  if (!value) return "self_host";
  if (value === "self_host" || value === "self-host") return "self_host";
  if (value === "official_cloud" || value === "official-cloud") return "official_cloud";
  throw new Error("Unsupported deployment mode. Use self-host or official-cloud.");
}

function getServerDeploymentMode(flags: Record<string, string | boolean>, config: ServerConfig | null): ServerDeploymentMode {
  if (flags["official-cloud"] === true) return "official_cloud";
  if (flags["deployment-mode"] === true) throw new Error("Provide a deployment mode value: --deployment-mode self-host|official-cloud.");
  if (typeof flags["deployment-mode"] === "string") return normalizeServerDeploymentMode(flags["deployment-mode"]);
  return normalizeServerDeploymentMode(config?.deploymentMode);
}

function getInstallDeploymentMode(installPath: string, config: ServerConfig | null): ServerDeploymentMode {
  const env = readEnvMap(installPath);
  if (env.OPENMATES_CLOUD_OVERLAY_ENABLED === "true") return "official_cloud";
  if (env.OPENMATES_CLOUD_OVERLAY_ENABLED === "false") return "self_host";
  return normalizeServerDeploymentMode(config?.deploymentMode);
}

function getOpenMatesCloudOverlayPath(flags: Record<string, string | boolean>, config: ServerConfig | null): string | undefined {
  const explicit = flags["openmatescloud-path"] ?? flags["openmates-cloud-path"];
  if (explicit === true) throw new Error("Provide an OpenMatesCloud path: --openmatescloud-path <dir>.");
  if (typeof explicit === "string") return resolve(explicit);
  return config?.openMatesCloudOverlayPath;
}

function hasServiceFilter(flags: Record<string, string | boolean>): boolean {
  return typeof flags.services === "string" || typeof flags.exclude === "string";
}

function selectedComposeServices(role: ServerRole, flags: Record<string, string | boolean>): string[] {
  return resolveServiceSelection(role, {
    services: typeof flags.services === "string" ? flags.services : undefined,
    exclude: typeof flags.exclude === "string" ? flags.exclude : undefined,
  });
}

function lifecycleServiceSelection(
  role: ServerRole,
  flags: Record<string, string | boolean>,
  config: ServerConfig | null,
): { services: string[]; requested: boolean } {
  if (hasServiceFilter(flags)) {
    return { services: selectedComposeServices(role, flags), requested: true };
  }
  if (config?.defaultServices?.length) {
    return {
      services: resolveServiceSelection(role, { services: config.defaultServices }),
      requested: true,
    };
  }
  return { services: [], requested: false };
}

type ReusedSetupContainer = { image: string; status: string; exitCode: number; health?: string };

type ReuseCompletedSetupInput = {
  role: ServerRole;
  installMode: string;
  servicesFlag: string | boolean | undefined;
  excludeFlag: string | boolean | undefined;
  selectedServices: string[];
  targetTag: string;
  registry: string;
};

function validateReuseCompletedSetupScope(input: ReuseCompletedSetupInput): void {
  if (input.role !== "core" || input.installMode !== "image" || typeof input.servicesFlag !== "string" || input.excludeFlag !== undefined) {
    throw new Error("--reuse-completed-setup requires a core image-mode update with explicit --services and no --exclude.");
  }
  if (!input.selectedServices.length || input.selectedServices.some((service) => service !== "api" && service !== "prometheus" && !service.endsWith("-worker"))) {
    throw new Error("--reuse-completed-setup allows only api, worker, and prometheus services; exclude setup and infrastructure services.");
  }
  if (!/^sha-[a-f0-9]{40}$/i.test(input.targetTag)) {
    throw new Error("--reuse-completed-setup requires an immutable --image-tag sha-<40 hex characters>.");
  }
}

export function validateReuseCompletedSetup(input: ReuseCompletedSetupInput & {
  setup: ReusedSetupContainer;
  dependencies: Record<string, ReusedSetupContainer>;
}): void {
  validateReuseCompletedSetupScope(input);
  const expectedImage = `${input.registry.replace(/\/$/, "")}/openmates-cms-setup:${input.targetTag}`;
  if (input.setup.image !== expectedImage || input.setup.status !== "exited" || input.setup.exitCode !== 0) {
    throw new Error(`--reuse-completed-setup requires cms-setup exited successfully with target image ${expectedImage}.`);
  }
  for (const service of ["cms", "cms-database", "cache", "vault"]) {
    const state = input.dependencies[service];
    if (!state || state.status !== "running" || (state.health !== undefined && state.health !== "healthy")) {
      throw new Error(`--reuse-completed-setup requires running, healthy ${service}.`);
    }
  }
}

export function imageUpdateUpArgs(baseArgs: string[], selectedServices: string[], filterRequested: boolean, reuseCompletedSetup: boolean): string[] {
  if (reuseCompletedSetup && (!filterRequested || selectedServices.length === 0)) {
    throw new Error("--reuse-completed-setup requires explicitly selected services.");
  }
  return appendSelectedServices([...baseArgs, "up", "-d", ...(reuseCompletedSetup ? ["--no-deps"] : [])], selectedServices, filterRequested);
}

function inspectReuseCompletedSetupContainer(installPath: string, withOverrides: boolean, service: string, includeStopped: boolean, installMode: "image" | "source" = "image"): ReusedSetupContainer {
  const compose = composeArgs(installPath, withOverrides, installMode, "core", false);
  const ps = spawnSync("docker", [...compose, "ps", ...(includeStopped ? ["-a"] : []), "-q", service], { cwd: installPath, encoding: "utf8", timeout: 5_000 });
  const ids = ps.status === 0 ? ps.stdout.trim().split(/\s+/).filter(Boolean) : [];
  if (ids.length !== 1) throw new Error(`--reuse-completed-setup could not identify one ${service} container.`);
  const inspect = (format: string): string => {
    const result = spawnSync("docker", ["inspect", "--format", format, ids[0]], { cwd: installPath, encoding: "utf8", timeout: 5_000 });
    if (result.status !== 0) throw new Error(`--reuse-completed-setup could not inspect ${service}.`);
    return result.stdout.trim();
  };
  const image = JSON.parse(inspect("{{json .Config.Image}}")) as string;
  const state = JSON.parse(inspect("{{json .State}}")) as { Status: string; ExitCode: number; Health?: { Status: string } };
  return { image, status: state.Status, exitCode: state.ExitCode, health: state.Health?.Status };
}

function verifyReuseCompletedSetup(installPath: string, withOverrides: boolean, input: ReuseCompletedSetupInput): void {
  validateReuseCompletedSetupScope(input);
  const setup = inspectReuseCompletedSetupContainer(installPath, withOverrides, "cms-setup", true);
  const dependencies = Object.fromEntries(["cms", "cms-database", "cache", "vault"].map((service) => [service, inspectReuseCompletedSetupContainer(installPath, withOverrides, service, false)]));
  validateReuseCompletedSetup({ ...input, setup, dependencies });
}

function verifyCoreSetupResult(installPath: string, withOverrides: boolean, installMode: "image" | "source", targetTag?: string): void {
  const setup = inspectReuseCompletedSetupContainer(installPath, withOverrides, "cms-setup", true, installMode);
  if (setup.status !== "exited" || setup.exitCode !== 0) {
    throw new Error("Target cms-setup did not exit successfully; API and email consumers remain stopped.");
  }
  if (installMode === "image") {
    const registry = (readEnvMap(installPath).OPENMATES_IMAGE_REGISTRY || DEFAULT_IMAGE_REGISTRY).replace(/\/$/, "");
    if (setup.image !== `${registry}/openmates-cms-setup:${targetTag}`) {
      throw new Error("Target cms-setup image did not match the requested tag; API and email consumers remain stopped.");
    }
  }
}

function shouldPullImages(): boolean {
  return process.env.OPENMATES_SKIP_IMAGE_PULL !== "1";
}

const CORE_NOTIFICATION_SERVICES = ["api", "task-worker", "task-scheduler"] as const;

/** A core code update must not leave old email consumers running after setup changes defaults. */
export function planCoreSetupUpdate(role: ServerRole, selectedServices: string[], filterRequested: boolean, reuseCompletedSetup = false): {
  required: boolean;
  pullOrBuildServices: string[];
  startServices: string[];
  stopServices: string[];
} {
  const required = role === "core" && (reuseCompletedSetup || !filterRequested || selectedServices.some((service) =>
    service === "cms" || service === "cms-setup" || service === "api" || service.endsWith("-worker") || service === "task-scheduler"));
  if (!required) return { required: false, pullOrBuildServices: selectedServices, startServices: selectedServices, stopServices: [] };
  const add = (services: string[], extra: readonly string[]) => [...new Set([...services, ...extra])];
  const cohort = add(selectedServices, CORE_NOTIFICATION_SERVICES);
  return {
    required: true,
    pullOrBuildServices: filterRequested ? add(cohort, reuseCompletedSetup ? [] : ["cms", "cms-setup"]) : selectedServices,
    startServices: filterRequested ? cohort.filter((service) => service !== "cms-setup") : selectedServices,
    stopServices: [...CORE_NOTIFICATION_SERVICES],
  };
}

/** The one-shot setup exit is checked before any target API or email consumer starts. */
export async function runCoreSetupUpdate(input: {
  compose: string[];
  stopServices: string[];
  upArgs: string[];
  reuseCompletedSetup: boolean;
  run: (args: string[]) => Promise<number>;
  verifySetup: () => void;
  step?: (name: string) => void;
}): Promise<void> {
  input.step?.("stop-email-consumers");
  if (await input.run([...input.compose, "stop", ...input.stopServices]) !== 0) {
    throw new Error("Could not stop old API and email consumers; setup was not started.");
  }
  if (!input.reuseCompletedSetup) {
    input.step?.("stage-cms");
    if (await input.run([...input.compose, "up", "-d", "--no-deps", "cms"]) !== 0) {
      throw new Error("Target CMS could not start; API and email consumers remain stopped.");
    }
    input.step?.("cms-setup");
    if (await input.run([...input.compose, "up", "--no-deps", "--force-recreate", "--exit-code-from", "cms-setup", "cms-setup"]) !== 0) {
      throw new Error("Target cms-setup failed; API and email consumers remain stopped. Fix setup and retry the update.");
    }
  }
  input.verifySetup();
  input.step?.("up");
  if (await input.run(input.upArgs) !== 0) {
    throw new Error("Target containers could not start; check Docker Compose and retry the update.");
  }
}

type FeatureOverrides = {
  enabled: string[];
  disabled: string[];
};

function normalizeFeatureList(items: string[]): string[] {
  const seen = new Set<string>();
  const normalized: string[] = [];
  for (const item of items) {
    const value = item.trim();
    if (!value || seen.has(value)) continue;
    seen.add(value);
    normalized.push(value);
  }
  return normalized;
}

function parseListBlock(content: string, key: string): string[] {
  const match = content.match(new RegExp(`^${key}:\\n((?:[ \\t]+.*\\n?)*)`, "m"));
  if (!match) return [];
  const block = match[1] ?? "";
  return normalizeFeatureList(
    [...block.matchAll(/^\s*-\s*["']?([^"'\n#]+)["']?/gm)].map((item) => item[1] ?? ""),
  );
}

function parseFeatureOverrides(content: string): FeatureOverrides {
  const overridesMatch = content.match(/^feature_overrides:\n((?:[ \t]+.*\n?)*)/m);
  const overridesBlock = overridesMatch?.[1] ?? "";
  const enabled = parseListBlock(overridesBlock.replace(/^ {2}/gm, ""), "enabled");
  const disabled = parseListBlock(overridesBlock.replace(/^ {2}/gm, ""), "disabled");
  const legacyDisabledApps = parseListBlock(content, "disabled_apps").map((appId) =>
    appId.startsWith("app:") ? appId : `app:${appId}`,
  );
  return {
    enabled: normalizeFeatureList(enabled),
    disabled: normalizeFeatureList([...disabled, ...legacyDisabledApps]),
  };
}

function renderFeatureOverrides(overrides: FeatureOverrides): string {
  const renderList = (key: string, items: string[]) => {
    if (!items.length) return `  ${key}: []`;
    return [`  ${key}:`, ...items.map((item) => `    - "${item}"`)].join("\n");
  };
  return [
    "# Admin feature overrides. Changes require a server restart.",
    "feature_overrides:",
    renderList("enabled", overrides.enabled),
    renderList("disabled", overrides.disabled),
    "",
  ].join("\n");
}

function removeConfigBlock(content: string, key: string): string {
  return content.replace(new RegExp(`(?:^|\\n)#.*\\n${key}:\\n(?:[ \\t]+.*\\n?)*`, "m"), "\n")
    .replace(new RegExp(`^${key}:\\n(?:[ \\t]+.*\\n?)*`, "m"), "");
}

function updateFeatureOverridesContent(content: string, overrides: FeatureOverrides): string {
  let next = removeConfigBlock(content, "feature_overrides");
  next = removeConfigBlock(next, "disabled_apps");
  next = next.trimEnd();
  return `${next}\n\n${renderFeatureOverrides(overrides)}`;
}

function featureKind(featureId: string): string {
  return featureId.split(":", 1)[0] || "unknown";
}

/** Build the docker compose argument array. */
export function composeArgs(
  installPath: string,
  withOverrides: boolean,
  installMode: NonNullable<ServerConfig["installMode"]> = getInstallMode(installPath),
  role: ServerRole = "core",
  materializeCloudNoWebapp = true,
): string[] {
  const config = loadConfigForInstallPath(installPath);
  const deploymentMode = getInstallDeploymentMode(installPath, config);
  if (materializeCloudNoWebapp) ensureOfficialCloudNoWebappComposeFile(installPath, deploymentMode, role);
  const env = readEnvMap(installPath);
  const overlayPath = env.OPENMATES_CLOUD_OVERLAY_PATH || config?.openMatesCloudOverlayPath || undefined;
  const resolvedOverlayPath = overlayPath ?? defaultOpenMatesCloudOverlayPath(installPath);
  const overlayComposeFile = defaultOpenMatesCloudComposeFile(resolvedOverlayPath);
  return planDockerComposeArgs({
    openMatesPath: installPath,
    withOverrides,
    installMode,
    role,
    overrideExists: existsSync(join(installPath, COMPOSE_OVERRIDE)),
    deploymentMode,
    overlayPath,
    overlayComposeFile,
    overlayExists: deploymentMode === "official_cloud" && existsSync(resolvedOverlayPath) && existsSync(overlayComposeFile),
  });
}

/** Ensure compose interpolation has an absolute project mount path. */
function ensureGitWorkDirEnv(installPath: string): void {
  const envPath = join(installPath, ".env");
  if (!existsSync(envPath)) return;

  const content = readFileSync(envPath, "utf-8");
  const lineRegex = /^GIT_WORK_DIR=.*$/m;
  const value = `GIT_WORK_DIR=${installPath}`;

  if (lineRegex.test(content)) {
    const next = content.replace(lineRegex, value);
    if (next !== content) writeServerEnvFile(envPath, next);
    return;
  }

  const separator = content.endsWith("\n") ? "" : "\n";
  writeServerEnvFile(envPath, `${content}${separator}${value}\n`);
}

