export function getDefaultImageTagForVersion(version: string): string {
  if (!version) return DEV_BRANCH;
  return /-(alpha|beta|rc)(\.|\d|$)/.test(version) ? `v${version}` : "stable";
}

function getDefaultImageTag(): string {
  const version = getPackageVersion();
  return getDefaultImageTagForVersion(version);
}

function defaultTemplateRefForVersion(version: string): string {
  return /-(alpha|beta|rc)(\.|\d|$)/.test(version) ? DEV_BRANCH : `v${version}`;
}

export function templateRefForImageTag(imageTag: string, packageVersion = ""): string {
  if (/^sha-[a-f0-9]{40}$/i.test(imageTag)) return imageTag.slice(4);
  if (imageTag === "stable") return MAIN_BRANCH;
  const channelTag = IMAGE_CHANNEL_TAGS[imageTag as keyof typeof IMAGE_CHANNEL_TAGS];
  if (channelTag) return channelTag;
  if (imageTag.startsWith("v")) return defaultTemplateRefForVersion(imageTag.slice(1));
  if (!imageTag && packageVersion) return defaultTemplateRefForVersion(packageVersion);
  return DEV_BRANCH;
}

export function resolveTargetImageTag(
  flags: Record<string, string | boolean>,
  currentTag: string,
  _packageVersion: string,
): { tag: string; channel?: "stable" | "dev" | "main" } {
  const imageTag = flags["image-tag"];
  const channel = flags.channel;
  if (imageTag === true) {
    throw new Error("Provide an image tag value: --image-tag <tag>.");
  }
  if (channel === true) {
    throw new Error("Provide an update channel value: --channel stable, --channel main, or --channel dev.");
  }
  if (typeof imageTag === "string" && typeof channel === "string") {
    throw new Error("Use either --image-tag or --channel, not both.");
  }

  if (typeof imageTag === "string") {
    const trimmed = imageTag.trim();
    if (!trimmed) throw new Error("--image-tag cannot be empty.");
    return { tag: trimmed };
  }

  if (typeof channel === "string") {
    const normalized = channel.trim().toLowerCase();
    const tag = IMAGE_CHANNEL_TAGS[normalized as keyof typeof IMAGE_CHANNEL_TAGS];
    if (!tag) {
      throw new Error("Unsupported update channel. Use --channel stable, --channel main, or --channel dev.");
    }
    return { tag, channel: tag };
  }

  const installedChannel = IMAGE_CHANNEL_TAGS[currentTag as keyof typeof IMAGE_CHANNEL_TAGS];
  if (installedChannel) return { tag: installedChannel, channel: installedChannel };
  return { tag: "stable", channel: "stable" };
}

function randomHex(bytes: number): string {
  return randomBytes(bytes).toString("hex");
}

function generateInviteCode(): string {
  const digits = Array.from(randomBytes(12), (byte) => String(byte % 10)).join("");
  return `${digits.slice(0, 4)}-${digits.slice(4, 8)}-${digits.slice(8, 12)}`;
}

function getEnvVar(content: string, name: string): string {
  const match = content.match(new RegExp(`^${name}=(.*)$`, "m"));
  return match?.[1]?.replace(/^"|"$/g, "") ?? "";
}

function setEnvVar(content: string, name: string, value: string): string {
  const line = `${name}=${value}`;
  const pattern = new RegExp(`^${name}=.*$`, "m");
  if (pattern.test(content)) {
    return content.replace(pattern, line);
  }
  const separator = content.endsWith("\n") ? "" : "\n";
  return `${content}${separator}${line}\n`;
}

function setEnvIfEmpty(content: string, name: string, value: string): string {
  return getEnvVar(content, name) ? content : setEnvVar(content, name, value);
}

function firstCsvValue(value: string): string {
  return value.split(",").map((item) => item.trim()).find(Boolean) ?? "";
}

function deriveSelfHostCliUrls(envContent: string): { apiUrl: string; appUrl: string } {
  return {
    apiUrl: firstCsvValue(getEnvVar(envContent, "VITE_API_URL")) || "http://127.0.0.1:8000",
    appUrl: firstCsvValue(getEnvVar(envContent, "PRODUCTION_URL")) || "http://localhost:5173",
  };
}

async function fetchText(url: string): Promise<string> {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`Failed to download ${url}: HTTP ${response.status}`);
  }
  return response.text();
}

function packagedTemplatePath(role: ServerRole): string {
  return join(dirname(new URL(import.meta.url).pathname), "..", "templates", ROLE_TEMPLATE_FILES[role]);
}

function packagedNoWebappTemplatePath(): string {
  return join(dirname(new URL(import.meta.url).pathname), "..", "templates", CORE_NO_WEBAPP_TEMPLATE_FILE);
}

function packagedCaddyTemplatePath(role: ServerRole): string {
  return join(dirname(new URL(import.meta.url).pathname), "..", "templates", "caddy", role, "Caddyfile");
}

function packagedCoreAlertmanagerTemplatePath(): string {
  return join(dirname(new URL(import.meta.url).pathname), "..", "templates", "core", "monitoring", "alertmanager", "alertmanager.yml");
}

export function ensureCoreAlertmanagerRuntimeFile(installPath: string): void {
  const templatePath = packagedCoreAlertmanagerTemplatePath();
  if (!existsSync(templatePath)) throw new Error(`Packaged Alertmanager config not found: ${templatePath}`);
  const runtimePath = join(installPath, CORE_ALERTMANAGER_CONFIG_FILE);
  if (fileHash(templatePath) === fileHash(runtimePath)) return;
  mkdirSync(dirname(runtimePath), { recursive: true });
  copyFileSync(templatePath, runtimePath);
}

export function ensureCorePrometheusRuntimeFiles(installPath: string): void {
  const packagedDir = join(dirname(new URL(import.meta.url).pathname), "..", "templates", "core", "monitoring", "prometheus");
  const runtimeDir = join(installPath, CORE_PROMETHEUS_CONFIG_DIR);
  for (const fileName of ["prometheus.yml", "alert_rules.yml"]) {
    const packagedPath = join(packagedDir, fileName);
    if (!existsSync(packagedPath)) throw new Error(`Packaged Prometheus file not found: ${packagedPath}`);
  }
  mkdirSync(runtimeDir, { recursive: true });
  for (const fileName of ["prometheus.yml", "alert_rules.yml"]) {
    const runtimePath = join(runtimeDir, fileName);
    if (!existsSync(runtimePath)) copyFileSync(join(packagedDir, fileName), runtimePath);
  }
}

function readOfficialCloudNoWebappComposeTemplate(): string {
  const packaged = packagedNoWebappTemplatePath();
  if (existsSync(packaged)) return readFileSync(packaged, "utf-8");
  return [
    "# backend/core/docker-compose.no-webapp.yml",
    "#",
    "# Keeps official OpenMatesCloud core runtimes backend-only while regular",
    "# self-host installs continue to start the webapp from the base compose file.",
    "",
    "services:",
    "  webapp:",
    "    profiles: [\"webapp\"]",
    "",
  ].join("\n");
}

function ensureOfficialCloudNoWebappComposeFile(
  installPath: string,
  deploymentMode: ServerDeploymentMode,
  role: ServerRole,
): void {
  if (deploymentMode !== "official_cloud" || role !== "core") return;
  const filePath = join(installPath, OFFICIAL_CLOUD_NO_WEBAPP_COMPOSE_FILE);
  if (existsSync(filePath)) return;
  mkdirSync(dirname(filePath), { recursive: true });
  writeFileSync(filePath, readOfficialCloudNoWebappComposeTemplate());
