function printQuickTestLoginGuidance(eligibility: Extract<ReturnType<typeof assessQuickServerTestEligibility>, { status: "login_required" }>): void {
  console.error("Quick server testing requires a CLI account logged into this self-hosted instance.");
  console.error("Run:");
  console.error(`  ${eligibility.loginCommand}`);
  console.error("Then run:");
  console.error(`  ${eligibility.rerunCommand}`);
}

async function promptForQuickServerTest(): Promise<boolean> {
  console.error("\nQuick server test:");
  console.error("  - Create, reload, and remove one temporary AI chat");
  console.error("  - Run math.calculate");
  console.error("  - Run one-result web.search");
  console.error("\nThese checks use your logged-in account and may consume credits.");
  const rl = createPromptInterface({ input: process.stdin, output: process.stderr });
  try {
    const answer = await rl.question("Continue with quick server test? [y/N] ");
    return ["y", "yes"].includes(answer.trim().toLowerCase());
  } finally {
    rl.close();
  }
}

async function maybeRunQuickServerTest(
  client: OpenMatesClient,
  installPath: string,
  role: ServerRole,
  config: ServerConfig | null,
  flags: Record<string, string | boolean>,
  standalone = false,
): Promise<QuickServerTestOutcome> {
  const action = decideQuickServerTestAction({
    interactive: process.stdin.isTTY === true && process.stderr.isTTY === true,
    json: flags.json === true,
    continuous: flags["continuous-update"] === true,
    skipQuickTest: flags["skip-quick-test"] === true,
    quickTest: flags["quick-test"] === true || standalone,
    confirmSpendCredits: flags["confirm-spend-credits"] === true,
    yes: flags.yes === true,
  });
  if (role !== "core") return { status: "not_run", reason: "non_core_role", checks: [] };
  if (action === "skip") {
    if (standalone) {
      throw new Error("Non-interactive quick tests require --confirm-spend-credits.");
    }
    return { status: "not_run", reason: "not_confirmed", checks: [] };
  }

  const eligibility = assessQuickServerTestEligibility({
    role,
    expectedApiUrl: expectedServerApiUrl(installPath, config, flags, standalone),
    client,
  });
  if (eligibility.status === "login_required") {
    printQuickTestLoginGuidance(eligibility);
    if (standalone || action === "run") {
      throw new Error("Log into the self-hosted instance before running quick server tests.");
    }
    return { status: "not_run", reason: eligibility.reason, checks: [] };
  }
  if (eligibility.status !== "ready") {
    return { status: "not_run", reason: eligibility.reason, checks: [] };
  }
  if (action === "prompt" && !await promptForQuickServerTest()) {
    return { status: "not_run", reason: "declined", checks: [] };
  }

  console.error("Running authenticated quick server test...");
  const result = await runQuickServerTest(client);
  if (flags.json !== true) {
    for (const check of result.checks) {
      const marker = check.status === "passed" ? "x" : "!";
      const reason = check.sanitized_reason ? ` (${check.sanitized_reason})` : "";
      console.error(`  [${marker}] ${check.id}${reason}`);
    }
  }
  return result;
}

type UpdateSourceLinks = {
  releaseUrl: string | null;
  sourceUrl: string | null;
  commitUrl: string | null;
  pullRequestUrl: string | null;
};

function targetSourceLinks(imageTag: string, templateRef: string): UpdateSourceLinks {
  const repositoryUrl = REPO_URL.replace(/\.git$/, "");
  if (imageTag.startsWith("v")) {
    return {
      releaseUrl: `${repositoryUrl}/releases/tag/${imageTag}`,
      sourceUrl: `${repositoryUrl}/tree/${imageTag}`,
      commitUrl: null,
      pullRequestUrl: null,
    };
  }
  const pullRequest = /^pr-(\d+)(?:-|$)/.exec(imageTag)?.[1];
  const revision = /^sha-([a-f0-9]{7,40})$/i.exec(imageTag)?.[1];
  return {
    releaseUrl: null,
    sourceUrl: `${repositoryUrl}/tree/${templateRef}`,
    commitUrl: revision ? `${repositoryUrl}/commit/${revision}` : null,
    pullRequestUrl: pullRequest ? `${repositoryUrl}/pull/${pullRequest}` : null,
  };
}

function installedImageLabels(input: { installPath: string; role: ServerRole; withOverrides: boolean }): Record<string, string> {
  const containerId = execFileSync(
    "docker",
    [...composeArgs(input.installPath, input.withOverrides, "image", input.role), "ps", "-q", ROLE_PROVENANCE_SERVICE[input.role]],
    { cwd: input.installPath, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] },
  ).trim();
  if (!containerId) throw new Error("updated_container_unavailable");
  const labels = JSON.parse(execFileSync(
    "docker",
    ["inspect", "--format", "{{json .Config.Labels}}", containerId],
    { cwd: input.installPath, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] },
  )) as Record<string, string> | null;
  if (labels?.["org.opencontainers.image.source"]?.trim().replace(/\.git$/, "") !== REPO_URL.replace(/\.git$/, "")) {
    throw new Error("installed_image_source_unverified");
  }
  return labels;
}

function installedImageMetadata(input: {
  installPath: string;
  role: ServerRole;
  withOverrides: boolean;
  templateRef: string;
  requestedTag: string;
}): { installedVersion: string; sourceLinks: UpdateSourceLinks } {
  const labels = installedImageLabels(input);
  const installedVersion = labels?.["org.opencontainers.image.version"]?.trim();
  if (!installedVersion) throw new Error("installed_image_version_unavailable");
  const imageSource = labels?.["org.opencontainers.image.source"]?.trim().replace(/\.git$/, "");
  if (imageSource !== REPO_URL.replace(/\.git$/, "")) throw new Error("installed_image_source_unverified");
  const sourceLinks = targetSourceLinks(installedVersion, input.templateRef);
  const revision = labels?.["org.opencontainers.image.revision"]?.trim();
  if (revision && /^[a-f0-9]{40}$/i.test(revision)) {
    sourceLinks.commitUrl = `${REPO_URL.replace(/\.git$/, "")}/commit/${revision}`;
  }
  sourceLinks.sourceUrl = imageSource;
  const requestedLinks = targetSourceLinks(input.requestedTag, input.templateRef);
  sourceLinks.pullRequestUrl = requestedLinks.pullRequestUrl;
  return { installedVersion, sourceLinks };
}

function sourceUpdateMetadata(installPath: string): { installedVersion: string; sourceLinks: UpdateSourceLinks } {
  const revision = exec("git rev-parse HEAD", installPath).trim();
  if (!/^[a-f0-9]{40}$/i.test(revision)) throw new Error("Unable to resolve the installed source revision for the completion email.");
  const remote = exec("git remote get-url origin", installPath).trim();
  if (!/^(?:https:\/\/github\.com\/glowingkitty\/OpenMates(?:\.git)?|git@github\.com:glowingkitty\/OpenMates(?:\.git)?)$/i.test(remote)) {
    throw new Error("Unable to verify canonical public source provenance for the completion email.");
  }
  const remoteRefs = exec(`git branch -r --contains ${revision}`, installPath)
    .split("\n")
    .map((value) => value.trim());
  if (!remoteRefs.some((value) => value.startsWith("origin/"))) {
    throw new Error("The installed source revision is not present on a canonical public remote branch.");
  }
  const repositoryUrl = REPO_URL.replace(/\.git$/, "");
  return {
    installedVersion: revision,
    sourceLinks: {
      releaseUrl: null,
      pullRequestUrl: null,
      commitUrl: `${repositoryUrl}/commit/${revision}`,
      sourceUrl: repositoryUrl,
    },
  };
}

function runAutomaticStorageMigration(
  installPath: string, role: ServerRole, installMode: "image" | "source",
  withOverrides: boolean,
): StorageMigrationOutcome {
  if (role !== "core") return { status: "not_applicable" };
  if (!shouldAutoInstallRuntimeMonitoringServices(process.env)) {
    return { status: "paused", reason: "inventory_refresh_service_disabled", retry_seconds: 60 };
  }
  if (!refreshStorageRuntimeInventory(installPath, role, installMode, withOverrides)) {
    return { status: "paused", reason: "runtime_inventory_refresh_unavailable", retry_seconds: 60 };
  }
  let sourceRevision: string | undefined;
  if (installMode === "source") {
    // A source build containing uncommitted code cannot be authorized by a
    // certificate for HEAD, even if the commit itself is release eligible.
    if (exec("git status --porcelain", installPath).trim()) {
      return { status: "pending", reason: "source_worktree_unverified" };
    }
    const revision = exec("git rev-parse HEAD", installPath).trim();
    if (!/^[a-f0-9]{40}$/i.test(revision)) {
      return { status: "pending", reason: "source_revision_unavailable" };
    }
    sourceRevision = revision;
  }
  const args = storageMigrationCommand(composeArgs(installPath, withOverrides, installMode, role), "auto", sourceRevision);
  const result = spawnSync("docker", args, {
    cwd: installPath, encoding: "utf8", timeout: 45_000,
    stdio: ["ignore", "pipe", "pipe"], maxBuffer: 64 * 1024,
  });
  if (result.error || result.status !== 0) {
    return { status: "paused", reason: "migration_coordinator_unavailable" };
  }
  try {
    return parseStorageMigrationOutcome(JSON.parse(result.stdout.trim()));
  } catch {
    // Only the bounded, sanitized coordinator status is exposed to callers.
  }
  return { status: "paused", reason: "migration_coordinator_response_invalid" };
}

function refreshStorageRuntimeInventory(
  installPath: string, role: ServerRole, installMode: "image" | "source", withOverrides: boolean,
): boolean {
  if (role !== "core") return true;
  if (installMode === "source" && exec("git status --porcelain", installPath).trim()) return false;
  try {
    const containers = execFileSync("docker", [...composeArgs(installPath, withOverrides, installMode, role), "ps", "--all", "-q", "api"],
      { cwd: installPath, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"], timeout: 15_000 }).trim().split(/\s+/).filter(Boolean);
    if (containers.length < 1 || containers.length > 128 || new Set(containers).size !== containers.length
        || containers.some((id) => !/^[a-f0-9]{12,64}$/.test(id))) return false;
    const cohort: unknown[] = [];
    for (const container of containers) {
      const output = execFileSync("docker", ["exec", container, "python", "/app/scripts/storage_runtime_inventory.py", "inspect"],
        { cwd: installPath, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"], timeout: 15_000, maxBuffer: 64 * 1024 });
      cohort.push(JSON.parse(output.trim()));
    }
    const result = spawnSync("docker", ["exec", "-i", containers[0], "python", "/app/scripts/storage_runtime_inventory.py", "publish"],
      { cwd: installPath, encoding: "utf8", input: JSON.stringify(cohort), timeout: 45_000,
        stdio: ["pipe", "pipe", "pipe"], maxBuffer: 64 * 1024 });
    if (result.error || result.status !== 0) return false;
    const published = JSON.parse(result.stdout.trim()) as { status?: string };
    return published.status === "published";
  } catch { return false; }
}

function readStorageMigrationProgress(
  installPath: string, role: ServerRole, installMode: "image" | "source", withOverrides: boolean,
): StorageMigrationProgress {
  if (role !== "core") return { automatic: { status: "not_applicable" } };
  const result = spawnSync("docker", storageMigrationCommand(
    composeArgs(installPath, withOverrides, installMode, role), "status",
  ), { cwd: installPath, encoding: "utf8", timeout: 45_000,
       stdio: ["ignore", "pipe", "pipe"], maxBuffer: 64 * 1024 });
  if (!result.error && result.status === 0) {
    try { return parseStorageMigrationProgress(JSON.parse(result.stdout.trim())); } catch { /* bounded status below */ }
  }
  return { automatic: { status: "paused", reason: "migration_coordinator_unavailable", retry_seconds: 60 } };
}

function copyIfExists(source: string, destination: string): void {
  if (!existsSync(source)) return;
  mkdirSync(dirname(destination), { recursive: true });
  cpSync(source, destination, { recursive: true, force: true });
}

function readEnvMap(installPath: string): Record<string, string> {
  const envPath = join(installPath, ".env");
  if (!existsSync(envPath)) return {};
  const values: Record<string, string> = {};
  for (const line of readFileSync(envPath, "utf-8").split("\n")) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const eqIdx = trimmed.indexOf("=");
    if (eqIdx === -1) continue;
    values[trimmed.slice(0, eqIdx)] = trimmed.slice(eqIdx + 1).replace(/^"|"$/g, "");
  }
  return values;
}

function envPathForInstall(installPath: string): string {
  return join(installPath, ".env");
}

function readEnvContent(installPath: string): string {
  const envPath = envPathForInstall(installPath);
  return existsSync(envPath) ? readFileSync(envPath, "utf-8") : "";
}

function writeEnvContent(installPath: string, content: string): void {
  const envPath = envPathForInstall(installPath);
  writeServerEnvFile(envPath, content);
}

function writeDeploymentModeEnv(
  installPath: string,
  deploymentMode: ServerDeploymentMode,
  overlayPath?: string,
): { overlayPath: string | null } {
  let content = readEnvContent(installPath);
  content = setEnvVar(content, "OPENMATES_DEPLOYMENT_MODE", deploymentMode);
  if (deploymentMode === "self_host") {
    content = setEnvVar(content, "OPENMATES_CLOUD_OVERLAY_ENABLED", "false");
    content = setEnvVar(content, "OPENMATES_CLOUD_OVERLAY_PACKAGE", "");
    content = unsetEnvValue(content, "OPENMATES_CLOUD_OVERLAY_PATH");
    writeEnvContent(installPath, content);
    return { overlayPath: null };
  }

  const resolvedOverlayPath = resolve(overlayPath ?? defaultOpenMatesCloudOverlayPath(installPath));
  const overlayComposeFile = defaultOpenMatesCloudComposeFile(resolvedOverlayPath);
  if (!existsSync(resolvedOverlayPath) || !existsSync(overlayComposeFile)) {
    throw new Error(
      "OpenMatesCloud official-cloud mode requires an overlay checkout with " +
      `${overlayComposeFile}. Pass --openmatescloud-path <dir> or create the sibling OpenMatesCloud repository.`,
    );
  }

  content = setEnvVar(content, "OPENMATES_CLOUD_OVERLAY_ENABLED", "true");
  content = setEnvVar(content, "OPENMATES_CLOUD_OVERLAY_PACKAGE", "OpenMatesCloud");
  content = setEnvVar(content, "OPENMATES_CLOUD_OVERLAY_PATH", resolvedOverlayPath);
  writeEnvContent(installPath, content);
  return { overlayPath: resolvedOverlayPath };
}

function assertEnvKey(key: string | undefined): string {
  if (!key || !/^[A-Z][A-Z0-9_]*$/.test(key)) {
    throw new Error("Provide an env key such as SECRET__BRAVE__API_KEY.");
  }
  return key;
}

async function promptHiddenValue(prompt: string): Promise<string> {
  if (!process.stdin.isTTY || typeof process.stdin.setRawMode !== "function") {
    const rl = createPromptInterface({ input: process.stdin, output: process.stderr });
    try {
      return await rl.question(prompt);
    } finally {
      rl.close();
    }
  }

  process.stderr.write(prompt);
  return await new Promise<string>((resolveValue, reject) => {
    let value = "";
    const onData = (buffer: Buffer) => {
      const char = buffer.toString("utf-8");
      if (char === "\u0003") {
        cleanup();
        reject(new Error("Input cancelled."));
        return;
      }
      if (char === "\r" || char === "\n") {
        cleanup();
        process.stderr.write("\n");
        resolveValue(value);
        return;
      }
      if (char === "\u007f" || char === "\b") {
        value = value.slice(0, -1);
        return;
      }
      value += char;
    };
    const cleanup = () => {
      process.stdin.off("data", onData);
      process.stdin.setRawMode(false);
      process.stdin.pause();
    };
    process.stdin.setRawMode(true);
    process.stdin.resume();
    process.stdin.on("data", onData);
  });
}

