type RuntimeSecretPreflight = SecretPreflightSummary & {
  vaultChecked: boolean;
  vaultUnavailableReason: string | null;
};

const LONG_RUNNING_SERVER_COMMANDS = new Set([
  "install",
  "start",
  "stop",
  "restart",
  "update",
  "preflight",
  "caddy",
  "backup",
  "restore",
  "reset",
  "make-admin",
  "ai",
  "uninstall",
]);

function shouldPrintServerCommandStart(
  subcommand: string,
  rest: string[],
  flags: Record<string, string | boolean>,
): boolean {
  if (flags.json === true || !LONG_RUNNING_SERVER_COMMANDS.has(subcommand)) return false;
  if (subcommand === "backup" && rest[0] === "list") return false;
  if (subcommand === "update" && rest[0] === "status") return false;
  if (subcommand === "ai" && rest[0] === "models" && (rest[1] === "list" || rest[1] === "remove")) return false;
  if (subcommand === "caddy" && (rest[0] === "status" || rest[0] === "diff")) return false;
  return true;
}

function printServerCommandStart(
  subcommand: string,
  rest: string[],
  flags: Record<string, string | boolean>,
): void {
  const command = ["server", subcommand, ...rest].join(" ");
  console.log(renderOpenMatesAsciiLogo());
  console.log("");
  console.log(`Running OpenMates ${command}...`);
  if (typeof flags.path === "string") console.log(`Path: ${resolve(flags.path)}`);
  if (typeof flags.role === "string") console.log(`Role: ${flags.role}`);
  console.log("");
}

function vaultCheckContainerForRole(role: ServerRole): string | null {
  if (role === "core") return "api";
  if (role === "upload") return "app-uploads";
  return null;
}

function readImportedVaultSecretPresence(role: ServerRole, importedSecrets: ReturnType<typeof parseSecretEnvKey>[]): {
  presence: Record<string, VaultSecretPresence>;
  checked: boolean;
  unavailableReason: string | null;
} {
  const checks = importedSecrets.filter((item): item is NonNullable<typeof item> => item !== null);
  if (checks.length === 0) return { presence: {}, checked: true, unavailableReason: null };
  const container = vaultCheckContainerForRole(role);
  if (!container) {
    return { presence: {}, checked: false, unavailableReason: `${role} role does not expose a Vault-backed app container for secret verification.` };
  }

  const script = `
import json
import os
import urllib.error
import urllib.request

checks = json.loads(os.environ["OPENMATES_SECRET_CHECKS"])
token_path = "/vault-data/api.token"
try:
    with open(token_path, "r", encoding="utf-8") as token_file:
        token = token_file.read().strip()
except Exception as exc:
    print(json.dumps({"ok": False, "reason": f"could not read {token_path}: {exc}", "presence": {}}))
    raise SystemExit(0)

presence = {}
for item in checks:
    request = urllib.request.Request(
        f"http://vault:8200/v1/{item['vaultPath']}",
        headers={"X-Vault-Token": token},
    )
    try:
        with urllib.request.urlopen(request, timeout=3) as response:
            payload = json.loads(response.read().decode("utf-8"))
        value = payload.get("data", {}).get("data", {}).get(item["vaultKey"])
        presence[item["envKey"]] = "present" if value else "missing"
    except urllib.error.HTTPError as exc:
        presence[item["envKey"]] = "missing" if exc.code == 404 else "unavailable"
    except Exception:
        presence[item["envKey"]] = "unavailable"

print(json.dumps({"ok": True, "presence": presence}))
`;

  try {
    const output = execFileSync(
      "docker",
      ["exec", "-e", `OPENMATES_SECRET_CHECKS=${JSON.stringify(checks)}`, container, "python", "-c", script],
      { encoding: "utf-8", timeout: 10_000, stdio: ["pipe", "pipe", "pipe"] },
    ).trim();
    const parsed = JSON.parse(output) as { ok?: boolean; reason?: string; presence?: Record<string, VaultSecretPresence> };
    if (parsed.ok === false) return { presence: {}, checked: false, unavailableReason: parsed.reason ?? "Vault check failed." };
    return { presence: parsed.presence ?? {}, checked: true, unavailableReason: null };
  } catch (error) {
    return {
      presence: {},
      checked: false,
      unavailableReason: `Vault check unavailable. Is the ${container} container running? ${error instanceof Error ? error.message : String(error)}`,
    };
  }
}

function runtimeSecretPreflight(installPath: string, role: ServerRole): RuntimeSecretPreflight {
  const env = readEnvMap(installPath);
  const importedSecrets = Object.entries(env)
    .filter(([, value]) => value.trim() === "IMPORTED_TO_VAULT")
    .map(([envKey]) => parseSecretEnvKey(envKey))
    .filter((item): item is NonNullable<typeof item> => item !== null);
  const vault = readImportedVaultSecretPresence(role, importedSecrets);
  return {
    ...summarizeSecretPreflight({ env, vaultPresence: vault.presence }),
    vaultChecked: vault.checked,
    vaultUnavailableReason: vault.unavailableReason,
  };
}

function formatSecretPreflight(preflight: RuntimeSecretPreflight): string {
  const parts = [
    `${preflight.importedVaultPresent.length}/${preflight.importedSecretEnvKeys.length} imported verified`,
  ];
  if (preflight.importedVaultMissing.length) parts.push(`missing in Vault: ${preflight.importedVaultMissing.join(", ")}`);
  if (preflight.importedVaultUnavailable.length) parts.push(`unverified: ${preflight.importedVaultUnavailable.join(", ")}`);
  if (preflight.inlineSecretEnvKeys.length) parts.push(`inline SECRET entries: ${preflight.inlineSecretEnvKeys.length}`);
  if (preflight.emptySecretEnvKeys.length) parts.push(`empty SECRET entries: ${preflight.emptySecretEnvKeys.length}`);
  if (preflight.vaultUnavailableReason) parts.push(preflight.vaultUnavailableReason);
  return parts.join("; ");
}

function hashFile(path: string): string {
  const hash = createHash("sha256");
  const fd = openSync(path, "r");
  const buffer = Buffer.allocUnsafe(CHECKSUM_BUFFER_BYTES);
  try {
    while (true) {
      const bytesRead = readSync(fd, buffer, 0, buffer.length, null);
      if (bytesRead === 0) break;
      hash.update(buffer.subarray(0, bytesRead));
    }
  } finally {
    closeSync(fd);
  }
  return hash.digest("hex");
}

function writeChecksums(rootDir: string): void {
  const lines: string[] = [];
  const walk = (dir: string) => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const path = join(dir, entry.name);
      if (entry.isDirectory()) {
        walk(path);
        continue;
      }
      if (entry.name === "checksums.sha256") continue;
      const relative = path.slice(rootDir.length + 1);
      lines.push(`${hashFile(path)}  ${relative}`);
    }
  };
  walk(rootDir);
  writeFileSync(join(rootDir, "checksums.sha256"), `${lines.sort().join("\n")}\n`);
}

function verifyChecksums(rootDir: string): void {
  const checksumsPath = join(rootDir, "checksums.sha256");
  if (!existsSync(checksumsPath)) throw new Error("Backup archive is missing checksums.sha256.");

  for (const line of readFileSync(checksumsPath, "utf-8").split("\n")) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    const match = trimmed.match(/^([a-f0-9]{64}) {2}(.+)$/);
    if (!match) throw new Error(`Invalid checksum entry: ${trimmed}`);
    const relative = match[2];
    if (relative.startsWith("/") || relative.split(/[\\/]/).includes("..")) {
      throw new Error(`Unsafe checksum path in backup archive: ${relative}`);
    }
    const filePath = join(rootDir, relative);
    if (!existsSync(filePath)) throw new Error(`Backup archive is missing checksummed file: ${relative}`);
    const actual = hashFile(filePath);
    if (actual !== match[1]) throw new Error(`Backup checksum mismatch for ${relative}.`);
  }
}

function createServerBackup(installPath: string, role: ServerRole, options: { output?: string; includeObservability?: boolean; preUpdate?: boolean } = {}): string {
  const plan = planBackup({ role, includeObservability: options.includeObservability });
  const backupDir = roleBackupDir(installPath, role);
  mkdirSync(backupDir, { recursive: true, mode: 0o700 });
  const archivePath = options.output
    ? resolve(options.output)
    : join(backupDir, options.preUpdate ? `latest-pre-update-${role}.tar.gz` : `openmates-${role}-${nowStamp()}.tar.gz`);
  mkdirSync(dirname(archivePath), { recursive: true, mode: 0o700 });
  const tempDir = mkdtempSync(join(backupDir, ".tmp-"));
  const env = readEnvMap(installPath);
  const manifest: {
    role: ServerRole;
    backup_format_version: number;
    created_at: string;
    cli_version: string;
    image_tag: string;
    recovery_scope: string;
    include_observability: boolean;
    contents: string[];
  } = {
    role,
    backup_format_version: BACKUP_FORMAT_VERSION,
    created_at: new Date().toISOString(),
    cli_version: getPackageVersion(),
    image_tag: getEnvVar(existsSync(join(installPath, ".env")) ? readFileSync(join(installPath, ".env"), "utf-8") : "", "OPENMATES_IMAGE_TAG"),
    recovery_scope: role === "core" ? "database-and-runtime-only" : "runtime-only",
    include_observability: false,
    contents: plan.contents.filter((content) => (
      content !== "runtime-env" || existsSync(join(installPath, ".env"))
    )).filter((content) => (
      content !== "runtime-config" || existsSync(join(installPath, "config"))
    )),
  };

  try {
    copyIfExists(join(installPath, ".env"), join(tempDir, "runtime", ".env"));
    copyIfExists(join(installPath, "config"), join(tempDir, "runtime", "config"));

    if (role === "core") {
      const databaseUser = env.DATABASE_USERNAME || "directus";
      const databaseName = env.DATABASE_NAME || "directus";
      const dumpFile = openSync(join(tempDir, "postgres.sql"), "w");
      try {
        const result = spawnSync(
          "docker",
          ["exec", "cms-database", "pg_dump", "--clean", "--if-exists", "--no-owner", "--no-privileges", "-U", databaseUser, databaseName],
          { encoding: "utf-8", stdio: ["ignore", dumpFile, "pipe"] },
        );
        if (result.error) throw result.error;
        if (result.status !== 0) throw new Error(result.stderr || `pg_dump exited with status ${result.status}`);
      } catch (error) {
        throw new Error(`Postgres backup failed. Is cms-database running? ${error instanceof Error ? error.message : String(error)}`);
      } finally {
        closeSync(dumpFile);
      }
    }

    writeFileSync(join(tempDir, "manifest.json"), `${JSON.stringify(manifest, null, 2)}\n`, { mode: 0o600 });
    writeChecksums(tempDir);
    publishServerBackupArchive(tempDir, archivePath);
    return archivePath;
  } finally {
    rmSync(tempDir, { recursive: true, force: true });
  }
}

function validateExtractedServerBackup(tempDir: string, role: ServerRole): void {
  verifyChecksums(tempDir);
  const manifestPath = join(tempDir, "manifest.json");
  if (!existsSync(manifestPath)) throw new Error("Backup archive is missing manifest.json.");
  const manifest = JSON.parse(readFileSync(manifestPath, "utf-8")) as { role?: string; backup_format_version?: number; recovery_scope?: string };
  if (manifest.role !== role) throw new Error(`Backup role '${manifest.role}' does not match requested role '${role}'.`);
  if (role === "core" && manifest.backup_format_version === BACKUP_FORMAT_VERSION && manifest.recovery_scope !== "full-core") {
    throw new Error("This backup records database and runtime state only; refusing unsafe full core restore.");
  }
}

function withValidatedServerBackup(installPath: string, role: ServerRole, file: string, useBackup: (tempDir: string) => void, tempRoot = roleBackupDir(installPath, role)): void {
  const archivePath = resolve(file);
  if (!existsSync(archivePath)) throw new Error(`Backup file not found: ${archivePath}`);
  mkdirSync(tempRoot, { recursive: true, mode: 0o700 });
  const tempDir = mkdtempSync(join(tempRoot, ".restore-"));
  try {
    execSync(`tar -xzf ${shellQuote(archivePath)} -C ${shellQuote(tempDir)}`, { stdio: "pipe" });
    validateExtractedServerBackup(tempDir, role);
    useBackup(tempDir);
  } finally {
    rmSync(tempDir, { recursive: true, force: true });
  }
}

function restoreServerBackup(installPath: string, role: ServerRole, file: string): void {
  withValidatedServerBackup(installPath, role, file, (tempDir) => {
    const env = readEnvMap(installPath);
    copyIfExists(join(tempDir, "runtime", ".env"), join(installPath, ".env"));
    copyIfExists(join(tempDir, "runtime", "config"), join(installPath, "config"));

    const postgresDump = join(tempDir, "postgres.sql");
    if (role === "core" && existsSync(postgresDump)) {
      const databaseUser = env.DATABASE_USERNAME || "directus";
      const databaseName = env.DATABASE_NAME || "directus";
      const dumpFile = openSync(postgresDump, "r");
      try {
        const result = spawnSync(
          "docker",
          ["exec", "-i", "cms-database", "psql", "-v", "ON_ERROR_STOP=1", "-U", databaseUser, databaseName],
          { encoding: "utf-8", stdio: [dumpFile, "pipe", "pipe"] },
        );
        if (result.error) throw result.error;
        if (result.status !== 0) throw new Error(result.stderr || `psql exited with status ${result.status}`);
      } finally {
        closeSync(dumpFile);
      }
    }
  });
}

function restoreStopServices(
  installPath: string,
  withOverrides: boolean,
  installMode: ServerConfig["installMode"],
  role: ServerRole,
): string[] {
  if (role !== "core") return [];
  const command = ["docker", ...composeArgs(installPath, withOverrides, installMode, role), "config", "--services"]
    .map(shellQuote)
    .join(" ");
  return execSync(command, { cwd: installPath, encoding: "utf-8" })
    .split("\n")
    .map((service) => service.trim())
    .filter((service) => service && service !== "cms-database");
}

async function promptText(question: string, defaultValue = ""): Promise<string> {
  const rl = createPromptInterface({ input: process.stdin, output: process.stderr });
  try {
    const suffix = defaultValue ? ` (${defaultValue})` : "";
    const answer = await rl.question(`${question}${suffix}: `);
    return answer.trim() || defaultValue;
  } finally {
    rl.close();
  }
}

async function promptChoice(question: string, choices: Array<{ value: string; label: string }>, defaultValue: string): Promise<string> {
  console.error(question);
  choices.forEach((choice, index) => {
    const marker = choice.value === defaultValue ? " [default]" : "";
    console.error(`  ${index + 1}. ${choice.label}${marker}`);
  });
  const answer = await promptText("Choose number or value", defaultValue);
  const numeric = Number.parseInt(answer, 10);
  if (Number.isInteger(numeric) && numeric >= 1 && numeric <= choices.length) {
    return choices[numeric - 1].value;
  }
  const direct = choices.find((choice) => choice.value === answer || choice.label.toLowerCase() === answer.toLowerCase());
  return direct?.value ?? answer;
}

async function fetchLocalModelIds(baseUrl: string, apiKey: string): Promise<string[]> {
  const response = await fetch(`${baseUrl.replace(/\/+$/, "")}/models`, {
    headers: { Authorization: `Bearer ${apiKey || "local"}` },
  });
  if (!response.ok) throw new Error(`Failed to fetch local models: HTTP ${response.status}`);
  const body = await response.json() as { data?: Array<{ id?: string }> };
  return (body.data ?? []).map((model) => model.id).filter((id): id is string => Boolean(id));
}

async function testLocalModel(baseUrl: string, apiKey: string, modelId: string): Promise<string> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 30_000);
  try {
    const response = await fetch(`${baseUrl.replace(/\/+$/, "")}/chat/completions`, {
      method: "POST",
      signal: controller.signal,
      headers: {
        Authorization: `Bearer ${apiKey || "local"}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model: modelId,
        messages: [
          { role: "system", content: "Answer with only the number." },
          { role: "user", content: "1+2?" },
        ],
        stream: false,
        temperature: 0,
      }),
    });
    if (!response.ok) throw new Error(`HTTP ${response.status}: ${await response.text()}`);
    const body = await response.json() as { choices?: Array<{ message?: { content?: string } }> };
    return body.choices?.[0]?.message?.content?.trim() ?? "";
  } finally {
    clearTimeout(timeout);
  }
}

function upsertLocalModel(path: string, providerId: string, providerName: string, model: Record<string, unknown>): void {
  const overlay = readLocalModelOverlay(path);
  let provider = overlay.providers.find((item) => item.provider_id === providerId);
  if (!provider) {
    provider = {
      provider_id: providerId,
      name: providerName,
      description: `Local self-hosted models for ${providerName}.`,
      models: [],
    };
    overlay.providers.push(provider);
  }
  const modelId = model.id;
  provider.models = provider.models.filter((existing) => existing.id !== modelId);
  provider.models.push(model);
  writeLocalModelOverlay(path, overlay);
}

function removeLocalModel(path: string, fullModelId: string): boolean {
  const [providerId, modelId] = fullModelId.split("/", 2);
  if (!providerId || !modelId) throw new Error("Use provider/model-id format.");
  const overlay = readLocalModelOverlay(path);
  const provider = overlay.providers.find((item) => item.provider_id === providerId);
  if (!provider) return false;
  const before = provider.models.length;
  provider.models = provider.models.filter((model) => model.id !== modelId);
  writeLocalModelOverlay(path, overlay);
  return provider.models.length !== before;
}

function localModelsFromOverlay(overlay: LocalModelOverlay): Array<{ providerId: string; model: Record<string, unknown> }> {
  return overlay.providers.flatMap((provider) => provider.models.map((model) => ({ providerId: provider.provider_id, model })));
}

