async function serverStatus(flags: Record<string, string | boolean>): Promise<void> {
  requireDocker();
  const installPath = resolveServerPath(flags);
  ensureGitWorkDirEnv(installPath);
  const config = loadConfigForInstallPath(installPath);
  const role = getServerRole(flags, config);
  const withOverrides = config?.composeProfile === "full";
  const args = [...composeArgs(installPath, withOverrides, getInstallMode(installPath, config), role), "ps"];
  const selection = lifecycleServiceSelection(role, flags, config);

  if (flags.json === true) {
    args.push("--format", "json");
  }
  if (selection.requested) args.push(...selection.services);

  if (flags.json === true) {
    const output = execFileSync("docker", args, { cwd: installPath, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }).trim();
    const containers: unknown[] = [];
    if (output) {
      if (output.startsWith("[")) containers.push(...JSON.parse(output));
      else for (const line of output.split("\n")) containers.push(JSON.parse(line));
    }
    printJson({ command: "status", path: installPath, role, containers,
      storageMigration: readStorageMigrationProgress(installPath, role, getInstallMode(installPath, config), withOverrides) });
    return;
  }
  const code = await runInteractive("docker", args, installPath);
  if (code !== 0) process.exit(code);
  const migration = readStorageMigrationProgress(installPath, role, getInstallMode(installPath, config), withOverrides);
  const outcome = migration.automatic;
  console.log(`Storage migration: ${outcome.status}${outcome.reason ? ` (${outcome.reason})` : ""}${outcome.retry_seconds ? `; retry in ${outcome.retry_seconds}s` : ""}`);
  if (migration.legacy_full_graph) console.log(`Legacy full graph migration: ${migration.legacy_full_graph.status} (${migration.legacy_full_graph.reason ?? "policy_pending"})`);
  if (migration.message_segments) console.log(`Message segments: ${JSON.stringify(migration.message_segments)}`);
  if (migration.message_pages) console.log(`Message pages: ${JSON.stringify(migration.message_pages)}`);
  if (migration.version_rows) console.log(`Version rows: ${JSON.stringify(migration.version_rows)}`);
}

function sourceBuildCommitSha(installPath: string): string {
  try {
    if (exec("git status --porcelain", installPath).trim()) return "";
    const revision = exec("git rev-parse HEAD", installPath).trim();
    return /^[a-f0-9]{40}$/i.test(revision) ? revision.toLowerCase() : "";
  } catch {
    // Starting custom/dirty code stays supported, without release attestation.
    return "";
  }
}

async function serverStart(flags: Record<string, string | boolean>): Promise<void> {
  requireDocker();
  const installPath = resolveServerPath(flags);
  ensureGitWorkDirEnv(installPath);
  ensureRuntimeMetricsDirectory(installPath);
  warnIfMissingLlmCredentials(installPath);

  let config = loadConfigForInstallPath(installPath);
  if (flags["with-overrides"] === true && !config && !loadServerConfig()) {
    // An unregistered source checkout otherwise treats --with-overrides as a
    // one-shot Compose choice. A later command from an agent worktree can then
    // recreate CMS without its host port and strand the control-plane hooks.
    await serverRegister({ path: installPath, "with-overrides": true });
    config = loadConfigForInstallPath(installPath);
  }
  const withOverrides = flags["with-overrides"] === true || config?.composeProfile === "full";
  const role = getServerRole(flags, config);
  const installMode = getInstallMode(installPath, config);
  const deploymentMode = getInstallDeploymentMode(installPath, config);
  const selection = lifecycleServiceSelection(role, flags, config);
  const pullArgs = [...composeArgs(installPath, withOverrides, installMode, role), "pull"];
  const args = [...composeArgs(installPath, withOverrides, installMode, role), "up", "-d"];
  if (selection.requested) {
    pullArgs.push(...selection.services);
    args.push(...selection.services);
  }

  // Update saved profile if starting with overrides
  if (config && withOverrides && config.composeProfile !== "full") {
    saveServerConfig({ ...config, composeProfile: "full" });
  }

  console.error("Starting OpenMates server...");
  let code = 0;
  if (installMode === "image" && shouldPullImages()) {
    code = await runInteractive("docker", pullArgs, installPath);
    if (code !== 0) process.exit(code);
  }
  if (installMode === "source") {
    const buildArgs = [...composeArgs(installPath, withOverrides, installMode, role),
      "build", "--build-arg", `BUILD_COMMIT_SHA=${sourceBuildCommitSha(installPath)}`];
    if (selection.requested) buildArgs.push(...selection.services);
    console.error("Building source containers...");
    code = await runInteractive("docker", buildArgs, installPath);
    if (code !== 0) process.exit(code);
  }
  code = await runInteractive("docker", args, installPath);
  if (code !== 0) process.exit(code);

  if (flags.json === true) {
    printJson({ command: "start", status: "success", path: installPath });
  } else {
    console.log("\nServer started.");
    console.log("API:     http://localhost:8000");
    if (deploymentMode === "official_cloud") {
      console.log("Web app: deployed separately for official cloud");
    } else {
      console.log("Web app: http://localhost:5173");
    }
    if (withOverrides) {
      console.log("Directus CMS: http://localhost:8055");
      console.log("Grafana:      http://localhost:3000");
    }
    console.log(renderSupportStartReminder());
  }
}

async function serverStop(flags: Record<string, string | boolean>): Promise<void> {
  requireDocker();
  const installPath = resolveServerPath(flags);
  ensureGitWorkDirEnv(installPath);
  const config = loadConfigForInstallPath(installPath);
  const role = getServerRole(flags, config);
  const withOverrides = config?.composeProfile === "full";
  const selection = lifecycleServiceSelection(role, flags, config);
  const args = selection.requested
    ? [...composeArgs(installPath, withOverrides, getInstallMode(installPath, config), role), "stop", ...selection.services]
    : [...composeArgs(installPath, withOverrides, getInstallMode(installPath, config), role), "down"];

  console.error("Stopping OpenMates server...");
  const code = await runInteractive("docker", args, installPath);
  if (code !== 0) process.exit(code);

  if (flags.json === true) {
    printJson({ command: "stop", status: "success", path: installPath });
  } else {
    console.log("Server stopped.");
  }
}

async function serverRestart(flags: Record<string, string | boolean>): Promise<void> {
  requireDocker();
  const installPath = resolveServerPath(flags);
  ensureGitWorkDirEnv(installPath);
  ensureRuntimeMetricsDirectory(installPath);
  const config = loadConfigForInstallPath(installPath);
  const role = getServerRole(flags, config);
  const withOverrides = config?.composeProfile === "full";
  const installMode = getInstallMode(installPath, config);
  const selection = lifecycleServiceSelection(role, flags, config);

  await withEngineeringRuntimeOperation(
    installPath,
    flags.rebuild === true ? "product_server_rebuild" : "product_server_restart",
    selection.services,
    async () => {
      if (flags.rebuild === true) {
        if (installMode === "image") {
          throw new Error(
            "Image-mode installs use prebuilt images and cannot rebuild locally. " +
            "Run 'openmates server update' to pull newer images, or reinstall with --from-source to build from source.",
          );
        }
        // Full rebuild: down → optional cache reset → selected build → selected up
        console.error("Rebuilding OpenMates server (this may take a few minutes)...");
        const downArgs = [...composeArgs(installPath, withOverrides, installMode, role), "down"];
        let code = await runInteractive("docker", downArgs, installPath);
        if (code !== 0) throw new Error(`Docker Compose down failed with exit code ${code}.`);

        if (flags["reset-cache"] === true) {
          try {
            exec("docker volume rm openmates-cache-data", installPath);
          } catch {
            // Volume may not exist — that's fine.
          }
        }

        const buildArgs = appendSelectedServices(
          [...composeArgs(installPath, withOverrides, installMode, role), "build"],
          selection.services,
          selection.requested,
        );
        code = await runInteractive("docker", buildArgs, installPath);
        if (code !== 0) throw new Error(`Docker Compose build failed with exit code ${code}.`);

        const upArgs = appendSelectedServices(
          [...composeArgs(installPath, withOverrides, installMode, role), "up", "-d"],
          selection.services,
          selection.requested,
        );
        code = await runInteractive("docker", upArgs, installPath);
        if (code !== 0) throw new Error(`Docker Compose up failed with exit code ${code}.`);
      } else {
        // Graceful restart (no rebuild)
        console.error("Restarting OpenMates server...");
        const args = [...composeArgs(installPath, withOverrides, installMode, role), "restart"];
        if (selection.requested) args.push(...selection.services);
        const code = await runInteractive("docker", args, installPath);
        if (code !== 0) throw new Error(`Docker Compose restart failed with exit code ${code}.`);
      }
    },
  );

  if (flags.json === true) {
    printJson({ command: "restart", status: "success", path: installPath, rebuild: flags.rebuild === true });
  } else {
    console.log("Server restarted.");
  }
}

async function serverLogs(flags: Record<string, string | boolean>): Promise<void> {
  requireDocker();
  const installPath = resolveServerPath(flags);
  ensureGitWorkDirEnv(installPath);
  const config = loadConfigForInstallPath(installPath);
  const role = getServerRole(flags, config);
  const withOverrides = config?.composeProfile === "full";
  const selection = lifecycleServiceSelection(role, flags, config);
  const args = [...composeArgs(installPath, withOverrides, getInstallMode(installPath, config), role), "logs"];

  if (flags.follow === true || flags.f === true) {
    args.push("--follow");
  }

  args.push(...planServerLogRangeArgs(flags));

  const container = flags.container;
  if (typeof container === "string" && !hasServiceFilter(flags)) {
    args.push(container);
  } else if (selection.requested) {
    args.push(...selection.services);
  }

  const code = await runInteractive("docker", args, installPath);
  if (code !== 0) process.exit(code);
}

async function serverRegister(flags: Record<string, string | boolean>): Promise<void> {
  requireDocker();
  requireGit();
  const installPath = resolveServerPath(
    typeof flags.path === "string" ? flags : { ...flags, path: process.cwd() },
  );
  const envPath = join(installPath, ".env");
  if (!existsSync(join(installPath, SOURCE_COMPOSE_FILE))) {
    throw new Error(`Source Compose file not found: ${join(installPath, SOURCE_COMPOSE_FILE)}`);
  }
  if (!existsSync(envPath)) {
    throw new Error(`Runtime env file not found: ${envPath}`);
  }

  const gitRoot = resolve(exec("git rev-parse --show-toplevel", installPath));
  if (gitRoot !== installPath) {
    throw new Error(`--path must point to the OpenMates Git checkout root (${gitRoot}).`);
  }

  const existing = loadServerConfig();
  if (existing?.installPath && resolve(existing.installPath) !== installPath && flags.yes !== true) {
    throw new Error(
      `Another server is registered at ${existing.installPath}. ` +
      "Rerun with --yes to replace the local CLI registration; no server data will be changed.",
    );
  }

  const role = getServerRole(flags, null);
  const profile = getCoreProfile(flags, null);
  const deploymentFlagSpecified = flags["official-cloud"] === true || typeof flags["deployment-mode"] === "string";
  const deploymentMode = deploymentFlagSpecified
    ? getServerDeploymentMode(flags, null)
    : getInstallDeploymentMode(installPath, null);
  if (deploymentMode === "official_cloud" && role !== "core") {
    throw new Error("Official-cloud overlay registration is only supported for the core server role.");
  }
  const overlayPath = getOpenMatesCloudOverlayPath(flags, null)
    ?? readEnvMap(installPath).OPENMATES_CLOUD_OVERLAY_PATH
    ?? defaultOpenMatesCloudOverlayPath(installPath);
  const overlayComposeFile = defaultOpenMatesCloudComposeFile(overlayPath);
  if (deploymentMode === "official_cloud" && (!existsSync(overlayPath) || !existsSync(overlayComposeFile))) {
    throw new Error(`OpenMatesCloud overlay path is required for official-cloud mode: ${overlayPath}`);
  }

  const runtimePlan = planServerRuntime({
    role,
    profile,
    withAlerts: flags["with-alerts"] === true,
    includeWebapp: deploymentMode !== "official_cloud",
  });
  const defaultServices = hasServiceFilter(flags)
    ? selectedComposeServices(role, flags)
    : runtimePlan.defaultServices;
  const cliUrls = deriveSelfHostCliUrls(readFileSync(envPath, "utf-8"));
  const config: ServerConfig = {
    installPath,
    installedAt: existing?.installPath === installPath ? existing.installedAt : Date.now(),
    composeProfile: flags["with-overrides"] === true ? "full" : "core",
    serverRole: role,
    serverProfile: profile,
    defaultServices,
    composeFiles: [SOURCE_COMPOSE_FILE],
    installMode: "source",
    sourceStrategy: "working_tree",
    deploymentMode,
    openMatesCloudOverlayPath: deploymentMode === "official_cloud" ? overlayPath : undefined,
    ...cliUrls,
  };
  saveServerConfig(config);

  if (flags.json === true) {
    printJson({ command: "register", status: "success", ...config });
  } else {
    console.log(`Registered existing OpenMates checkout at ${installPath}.`);
    console.log("Mode: source (current working tree; Git is never pulled automatically)");
    console.log(`Deployment: ${deploymentMode === "official_cloud" ? "official cloud backend" : "self-host"}`);
    console.log(`Services: ${defaultServices.join(", ")}`);
  }
}

async function serverInstall(flags: Record<string, string | boolean>): Promise<void> {
  const installPath = typeof flags.path === "string" ? resolve(flags.path) : DEFAULT_INSTALL_PATH;
  const sourcePath = typeof flags["source-path"] === "string" ? resolve(flags["source-path"]) : null;
  const fromSource = flags["from-source"] === true || sourcePath !== null;
  const role = getServerRole(flags, null);
  const profile = getCoreProfile(flags, null);
  const deploymentMode = getServerDeploymentMode(flags, null);
  const requestedOverlayPath = getOpenMatesCloudOverlayPath(flags, null);
  if (deploymentMode === "official_cloud" && role !== "core") {
    throw new Error("Official-cloud overlay installs are only supported for the core server role.");
  }
  const runtimePlan = planServerRuntime({
    role,
    profile,
    withAlerts: flags["with-alerts"] === true,
    includeWebapp: deploymentMode !== "official_cloud",
  });

  // Check if already installed
  if (existsSync(join(installPath, SOURCE_COMPOSE_FILE)) || Object.values(ROLE_IMAGE_COMPOSE_FILES).some((composeFile) => existsSync(join(installPath, composeFile)))) {
    console.error(`OpenMates already exists at ${installPath}.`);
    console.error("Use 'openmates server update' to update, or choose a different --path.");
    process.exit(1);
  }

  if (!fromSource) {
    requireDocker();
    mkdirSync(installPath, { recursive: true });
    ensureRuntimeMetricsDirectory(installPath);

    // Copy custom .env if provided before generated defaults are filled in.
    if (typeof flags["env-path"] === "string") {
      const envSource = resolve(flags["env-path"]);
      if (!existsSync(envSource)) {
        throw new Error(`Env file not found: ${envSource}`);
      }
      writeServerEnvFile(join(installPath, ".env"), readFileSync(envSource, "utf8"));
      console.error(`Copied ${envSource} to ${installPath}/.env`);
    }

    const requestedImageTag = typeof flags["image-tag"] === "string" ? flags["image-tag"] : getDefaultImageTag();
    const imageTag = requestedImageTag === "stable" ? await resolveStableImageTag() : requestedImageTag;
    console.error(`Preparing OpenMates image-mode install at ${installPath}...`);
    await writeImageModeRuntimeFiles(installPath, imageTag, role);
    const overlay = writeDeploymentModeEnv(installPath, deploymentMode, requestedOverlayPath);
    const cliUrls = deriveSelfHostCliUrls(readFileSync(join(installPath, ".env"), "utf-8"));
    try {
      exec("docker network create openmates", installPath);
    } catch {
      // Network already exists.
    }

    saveServerConfig({
      installPath,
      installedAt: Date.now(),
      composeProfile: role === "core" ? "core" : "core",
      serverRole: role,
      serverProfile: profile,
      defaultServices: runtimePlan.defaultServices,
      composeFiles: runtimePlan.composeFiles,
      installMode: "image",
      deploymentMode,
      openMatesCloudOverlayPath: overlay.overlayPath ?? undefined,
      imageTag,
      imageChannel: requestedImageTag === "stable" ? "stable" : undefined,
      ...cliUrls,
    });
    try {
      await autoInstallRuntimeMonitoringServices(installPath, role);
    } catch (error) {
      throw new Error(`Server files were installed but runtime monitoring service installation failed: ${error instanceof Error ? error.message : String(error)}`);
    }

    if (flags.json === true) {
      printJson({ command: "install", status: "success", path: installPath, mode: "image", imageTag });
    } else {
      const firstInvite = getEnvVar(readFileSync(join(installPath, ".env"), "utf-8"), "SELF_HOST_FIRST_INVITE_CODE");
      console.log(`\nOpenMates installed at ${installPath}`);
      console.log(`Mode: image (${DEFAULT_IMAGE_REGISTRY}, tag ${imageTag})`);
      console.log(`Deployment: ${deploymentMode === "official_cloud" ? "official cloud overlay" : "self-host core"}`);
      console.log("\nNext steps:");
      console.log("  1. Run: openmates server start");
      console.log("  2. Open http://localhost:5173");
      if (firstInvite) console.log(`  3. Sign up with invite code: ${firstInvite}`);
      console.log("  4. After signup, make yourself admin: openmates server make-admin your@email.com");
      console.log(`\nCLI default API: ${cliUrls.apiUrl}`);
      console.log("\nOptional: edit .env first to add LLM provider API keys. Source builds are available with --from-source.");
    }
    return;
  }

  requireGit();

  // Clone the repository. CI can pass --source-path to test the checked-out branch
  // instead of whatever is currently published on the default remote branch.
  const cloneSource = sourcePath ?? REPO_URL;
  const cloneBranch = sourcePath ? null : defaultCloneBranchForVersion(getPackageVersion());
  const cloneArgs = ["clone"];
  if (cloneBranch) {
    cloneArgs.push("--branch", cloneBranch);
  }
  cloneArgs.push(cloneSource, installPath);
  console.error(`Cloning OpenMates from ${cloneSource} to ${installPath}...`);
  if (cloneBranch) {
    console.error(`Using ${cloneBranch} branch for this prerelease CLI.`);
  }
  const cloneCode = await runInteractive(
    "git",
    cloneArgs,
    process.cwd(),
  );
  if (cloneCode !== 0) {
    throw new Error("Failed to clone the OpenMates repository.");
  }
  ensureRuntimeMetricsDirectory(installPath);

  // Copy custom .env if provided
  if (typeof flags["env-path"] === "string") {
    const envSource = resolve(flags["env-path"]);
    if (!existsSync(envSource)) {
      throw new Error(`Env file not found: ${envSource}`);
    }
    writeServerEnvFile(join(installPath, ".env"), readFileSync(envSource, "utf8"));
    console.error(`Copied ${envSource} to ${installPath}/.env`);
  }

  const translationResult = ensureSourceInstallTranslations(installPath, sourcePath);
  if (translationResult.status === "copied") {
    console.error(`Prepared ${translationResult.copiedFiles} generated locale JSON files for source install.`);
  } else if (translationResult.status === "built") {
    console.error("Generated locale JSON files for source install.");
  }

  // Run setup.sh
  console.error("\nRunning setup script...");
  const setupCode = await runInteractive(
    "bash",
    ["setup.sh"],
    installPath,
  );
  if (setupCode !== 0) {
    console.error("Setup script failed. Check the output above for details.");
    process.exit(setupCode);
  }

  // Save config
  const envPath = join(installPath, ".env");
  const overlay = writeDeploymentModeEnv(installPath, deploymentMode, requestedOverlayPath);
  const cliUrls = deriveSelfHostCliUrls(existsSync(envPath) ? readFileSync(envPath, "utf-8") : "");
  saveServerConfig({
    installPath,
    installedAt: Date.now(),
    composeProfile: "core",
    serverRole: role,
    serverProfile: profile,
    defaultServices: runtimePlan.defaultServices,
    composeFiles: runtimePlan.composeFiles,
      installMode: "source",
      sourceStrategy: "managed_clone",
      deploymentMode,
    openMatesCloudOverlayPath: overlay.overlayPath ?? undefined,
    ...cliUrls,
  });
  try {
    await autoInstallRuntimeMonitoringServices(installPath, role);
  } catch (error) {
    throw new Error(`Server files were installed but runtime monitoring service installation failed: ${error instanceof Error ? error.message : String(error)}`);
  }

  if (flags.json === true) {
    printJson({ command: "install", status: "success", path: installPath, mode: "source" });
  } else {
    console.log(`\nOpenMates installed at ${installPath}`);
    console.log(`Deployment: ${deploymentMode === "official_cloud" ? "official cloud overlay" : "self-host core"}`);
    console.log("\nNext steps:");
    console.log("  1. Run: openmates server start");
    console.log("  2. Open http://localhost:5173");
    console.log("  3. After signup, make yourself admin: openmates server make-admin your@email.com");
    console.log(`\nCLI default API: ${cliUrls.apiUrl}`);
    console.log("\nOptional: edit .env first to add LLM provider API keys. Without keys, the web app and backend still start, but AI model processing is unavailable.");
  }
}

async function installContinuousUpdateService(flags: Record<string, string | boolean>): Promise<void> {
  const config = loadServerConfig();
  const role = getServerRole(flags, config);
  const channel = typeof flags.channel === "string" ? flags.channel : config?.imageChannel ?? "stable";
  const window = typeof flags.window === "string" ? flags.window : "02:00-04:00 UTC";
  const plan = planContinuousUpdateService({ role, channel, window });
  const servicePath = join("/etc", "systemd", "system", plan.serviceName);
  const timerPath = join("/etc", "systemd", "system", plan.timerName);

  if (flags["dry-run"] === true || flags.json === true) {
    printJson({ command: "update install-service", status: "planned", role, servicePath, timerPath, unit: plan.unit, timer: plan.timer });
    return;
  }

  try {
    writeFileSync(servicePath, plan.unit, { mode: 0o644 });
    writeFileSync(timerPath, plan.timer, { mode: 0o644 });
    execSync("systemctl daemon-reload", { stdio: "pipe" });
    execSync(`systemctl enable --now ${shellQuote(plan.timerName)}`, { stdio: "pipe" });
  } catch (error) {
    throw new Error(
      `Could not install systemd updater. Run with sudo or use --dry-run to inspect generated units. ${error instanceof Error ? error.message : String(error)}`,
    );
  }

  console.log(`Installed ${plan.timerName}.`);
}

type RuntimeVerifierOutput = {
  status: "passed" | "failed";
  role: ServerRole;
  completed_at: number;
  checks: Array<RuntimeCheckResult & { required: boolean; duration_ms: number; sanitized_reason?: string; failure_class?: string }>;
  restoreCommand?: string | null;
  restoreStatus?: "available" | "restore_unavailable";
};

function inspectCmsCacheConsistency(
  installPath: string,
  withOverrides: boolean,
  installMode: NonNullable<ServerConfig["installMode"]>,
): RuntimeVerifierOutput["checks"][number] {
  const composeResult = spawnSync(
    "docker",
    [...composeArgs(installPath, withOverrides, installMode, "core"), "ps", "-q", "cms"],
    { cwd: installPath, encoding: "utf-8", timeout: 5_000 },
  );
  const containerIds = composeResult.status === 0 ? composeResult.stdout.trim().split(/\s+/).filter(Boolean) : [];
  const containerId = containerIds.length === 1 ? containerIds[0] : undefined;
  if (!containerId) {
    return evaluateCmsCacheConsistency({ containerFound: false, inspectionSucceeded: false, filteredEnvironment: "" });
  }
  const inspectResult = spawnSync(
    "docker",
    ["inspect", "--format", CMS_CACHE_INSPECT_FORMAT, containerId],
    { cwd: installPath, encoding: "utf-8", timeout: 5_000 },
  );
  return evaluateCmsCacheConsistency({
    containerFound: true,
    inspectionSucceeded: inspectResult.status === 0,
    filteredEnvironment: inspectResult.status === 0 ? inspectResult.stdout : "",
  });
}

function runRuntimeVerification(installPath: string, role: ServerRole, config: ServerConfig | null): RuntimeVerifierOutput {
  const envText = existsSync(join(installPath, ".env")) ? readFileSync(join(installPath, ".env"), "utf-8") : "";
  const mode = resolveRuntimeDeploymentMode({
    envText,
    overlayExists: existsSync(config?.openMatesCloudOverlayPath ?? defaultOpenMatesCloudOverlayPath(installPath)),
  });
  const backupPath = join(roleBackupDir(installPath, role), `latest-pre-update-${role}.tar.gz`);
  const plan = planRuntimeVerification({ role, deploymentMode: mode.effectiveMode, hasVerifiedBackup: existsSync(backupPath) });
  const verifierService = { core: "api", upload: "app-uploads", preview: "preview" }[role];
  const installMode = getInstallMode(installPath, config);
  const withOverrides = config?.composeProfile === "full";

  console.error("Post-update runtime contract:");
  for (const check of plan.checks) console.error(`  [ ] ${check.id}`);
  const result = spawnSync(
    "docker",
    [...composeArgs(installPath, withOverrides, installMode, role), "exec", "-T", verifierService, "python", "-m", "backend.scripts.runtime_health_verifier", "--role", role, "--json"],
    { cwd: installPath, encoding: "utf-8", timeout: (plan.globalDeadlineSeconds + 5) * 1000 },
  );
  if (result.error) throw result.error;
  let output: RuntimeVerifierOutput;
  try {
    output = JSON.parse(result.stdout.trim()) as RuntimeVerifierOutput;
  } catch {
    throw new Error(`Runtime verifier returned invalid output (${result.status ?? "unknown"}).`);
  }
  output.checks = output.checks.map((check) => ({ ...check, failureClass: check.failureClass ?? check.failure_class }));
  if (role === "core") {
    const cmsCacheCheck = inspectCmsCacheConsistency(installPath, withOverrides, installMode);
    output.checks.push(cmsCacheCheck);
    if (cmsCacheCheck.status !== "passed") output.status = "failed";
  }
  if (mode.effectiveMode === "official_cloud") {
    const notificationCheck = evaluateNotificationDestinationConfiguration(runtimeNotificationConfig(installPath));
    // Emit success too so the durable incident writer can close a repaired check.
    output.checks.push(notificationCheck);
    if (notificationCheck.status === "failed") output.status = "failed";
  }
  for (const check of output.checks) {
    const marker = check.status === "passed" ? "x" : "!";
    console.error(`  [${marker}] ${check.id}${check.sanitized_reason ? ` (${check.sanitized_reason})` : ""}`);
  }
  return { ...output, restoreCommand: plan.restoreCommand, restoreStatus: plan.restoreStatus };
}

function runtimeNotificationConfig(installPath: string) {
  const env = readEnvMap(installPath);
  const value = (key: string): string | undefined => process.env[key] || env[key] || undefined;
  const serverConfig = loadConfigForInstallPath(installPath);
  const deploymentMode = getInstallDeploymentMode(installPath, serverConfig);
  const serverEnvironment = value("SERVER_ENVIRONMENT") === "production" ? "production" : "development";
  const environment: RuntimeNotificationPayload["environment"] = deploymentMode === "self_host" ? "self_host" : serverEnvironment;
  const destinations = resolveHostNotificationDestinations(value, deploymentMode, serverEnvironment);
  const webhookUrl = value("OPENMATES_RUNTIME_HEALTH_WEBHOOK_URL");
  const webhookSecret = value("OPENMATES_RUNTIME_HEALTH_WEBHOOK_SECRET");
  const allowLocalDevelopmentFixture = value("SERVER_ENVIRONMENT") === "development"
    && value("OPENMATES_RUNTIME_HEALTH_ALLOW_LOCAL_WEBHOOK_FIXTURE") === "true";
  const genericWebhook = webhookUrl && webhookSecret
    ? { url: webhookUrl, secret: webhookSecret, allowLocalDevelopmentFixture }
    : undefined;
  return {
    environment,
    deploymentMode,
    serverName: value("OPENMATES_RUNTIME_SERVER_NAME"),
    version: value("OPENMATES_IMAGE_TAG") || serverConfig?.imageTag || "source",
    ...destinations,
    genericWebhook,
  };
}

async function runUpdateCompletionEmailGate(input: {
  installPath: string;
  role: ServerRole;
  updateMode: "image" | "source";
  installedVersion: string;
  sourceLinks: UpdateSourceLinks;
  previousStatus: Record<string, unknown>;
  deduplicateAcceptedVersion: boolean;
}): Promise<UpdateCompletionOutcome & { completedAt: string; deliveryId?: string; deliveryPendingAt?: string }> {
  const completedAt = new Date().toISOString();
  const source = selectUpdateSourceLink(input.sourceLinks);
  if (!source) {
    return {
      ...buildUpdateCompletionOutcome({ status: "unavailable", attempts: 0, sanitizedReason: "public_source_link_unavailable" }),
      completedAt,
    };
  }
  const deliveryPlan = planUpdateCompletionDelivery({
    previousStatus: input.previousStatus,
    updateMode: input.updateMode,
    installedVersion: input.installedVersion,
    continuousUpdate: input.deduplicateAcceptedVersion,
    now: new Date(completedAt),
  });
  if (deliveryPlan.action === "blocked") {
    return {
      ...buildUpdateCompletionOutcome({ status: "unavailable", attempts: 0, sanitizedReason: deliveryPlan.reason }),
      completedAt,
      deliveryId: deliveryPlan.deliveryId,
      deliveryPendingAt: deliveryPlan.pendingAt,
    };
  }
  if (deliveryPlan.action === "reuse_accepted") {
    return {
      ...buildUpdateCompletionOutcome({ status: "accepted", attempts: deliveryPlan.attempts, sanitizedReason: "unchanged_version_already_notified" }),
      completedAt,
      deliveryId: deliveryPlan.deliveryId,
    };
  }
  const deliveryId = deliveryPlan.deliveryId ?? randomUUID();
  const deliveryPendingAt = deliveryPlan.pendingAt ?? completedAt;
  const previousAttempts = deliveryPlan.previousAttempts ?? 0;
  const { role: _role, updated_at: _updatedAt, ...currentStatus } = readUpdateStatus(input.installPath, input.role);
  writeUpdateStatus(input.installPath, input.role, {
    ...currentStatus,
    status: "in_progress",
    step: "completion-email",
    updateMode: input.updateMode,
    installedVersion: input.installedVersion,
    sourceLink: source.url,
    completionEmailDeliveryId: deliveryId,
    completionEmailPendingAt: deliveryPendingAt,
    completionEmailDelivery: { status: "pending", attempts: previousAttempts },
  });
  const payload = {
    deliveryId,
    updateMode: input.updateMode,
    installedVersion: input.installedVersion,
    role: input.role,
    completedAt,
    source,
  };
  const delivery = await deliverUpdateCompletionEmail(
    runtimeNotificationConfig(input.installPath).email,
    payload,
    undefined,
    previousAttempts,
    (attempts) => {
      const { role: _role, updated_at: _updatedAt, ...latestStatus } = readUpdateStatus(input.installPath, input.role);
      writeUpdateStatus(input.installPath, input.role, {
        ...latestStatus,
        status: "in_progress",
        step: "completion-email",
        completionEmailDeliveryId: deliveryId,
        completionEmailPendingAt: deliveryPendingAt,
        completionEmailDelivery: { status: "pending", attempts },
      });
    },
  );
  return { ...buildUpdateCompletionOutcome(delivery), completedAt, deliveryId, deliveryPendingAt };
}

async function dispatchRuntimeEvent(
  installPath: string,
  role: ServerRole,
  kind: RuntimeNotificationPayload["kind"],
  checks: RuntimeVerifierOutput["checks"],
  occurredAt: string,
): Promise<RuntimeNotificationDelivery[]> {
  const failedChecks = checks.filter((check) => check.status === "failed");
  const notificationConfig = runtimeNotificationConfig(installPath);
  const reportedChecks = failedChecks.length ? failedChecks : checks;
  return deliverRuntimeNotification(notificationConfig, {
    role,
    kind,
    occurredAt,
    environment: notificationConfig.environment,
    serverName: notificationConfig.serverName || `${notificationConfig.environment}-${role}`,
    deploymentMode: notificationConfig.deploymentMode,
    version: notificationConfig.version,
    checkIds: reportedChecks.map((check) => check.id),
    checkDetails: reportedChecks.map((check) => ({
      id: check.id,
      failureClass: check.failureClass,
      reason: check.sanitized_reason,
    })),
    sanitizedReason: failedChecks[0]?.sanitized_reason ?? (kind === "recovery" ? "required_checks_recovered" : "runtime_health_event"),
  });
}

async function persistRuntimeResult(installPath: string, role: ServerRole, output: RuntimeVerifierOutput): Promise<RuntimeNotificationDelivery[]> {
  const previous = await readRuntimeIncidentState(installPath, role);
  const applied = applyRuntimeCheckResults(previous, output.checks, new Date(output.completed_at * 1000).toISOString());
  await writeRuntimeIncidentState(installPath, role, applied.state);
  const deliveries = await Promise.all(applied.events.map((event) => dispatchRuntimeEvent(
    installPath,
    role,
    event.type === "recovered" ? "recovery" : event.type === "service_critical" ? "critical" : "incident",
    output.checks.filter((check) => check.id === event.checkId),
    new Date(output.completed_at * 1000).toISOString(),
  )));
  return deliveries.flat();
}

async function installRuntimeMonitoringServices(installPath: string, role: ServerRole): Promise<void> {
  const executablePath = resolve(process.argv[1] ?? "/usr/local/bin/openmates");
  const plan = planRuntimeMonitoringServices({ role, installPath, executablePath });
  const notificationConfig = runtimeNotificationConfig(installPath);
  const emailServiceAvailable = notificationConfig.email
    ? await probeRuntimeEmailService(notificationConfig.email)
    : false;
  if (notificationConfig.email && !emailServiceAvailable) {
    console.error("Operational email reports remain disabled because the configured email service is unavailable.");
  }
  const deploymentMode = getInstallDeploymentMode(installPath, loadConfigForInstallPath(installPath));
  const operationalPlan = planOperationalMonitoring({
    environment: deploymentMode === "official_cloud"
      ? (readEnvMap(installPath).SERVER_ENVIRONMENT === "production" ? "production" : "development")
      : "self_host",
    role,
    installPath,
    executablePath,
    adminEmail: notificationConfig.email?.to,
    emailServiceAvailable,
    discordConfigured: Boolean(notificationConfig.discordWebhookUrl),
  });
  const files = [
    [plan.serviceName, plan.unit],
    [plan.timerName, plan.timer],
    [plan.watchdogServiceName, plan.watchdogUnit],
    [plan.watchdogTimerName, plan.watchdogTimer],
    ...(operationalPlan.scheduleEnabled ? [
      [operationalPlan.digestServiceName, operationalPlan.digestUnit],
      [operationalPlan.digestTimerName, operationalPlan.digestTimer],
      [operationalPlan.watchdogServiceName, operationalPlan.watchdogUnit],
      [operationalPlan.watchdogTimerName, operationalPlan.watchdogTimer],
    ] : []),
  ].filter((entry): entry is [string, string] => Boolean(entry[0] && entry[1]));
  const reportStatePath = join(installPath, ".openmates", "runtime-health", `${role}-operational-report.json`);
  const reportMetricsDir = join(installPath, ".openmates", "runtime-health", "metrics");
  const startedMetricPath = join(reportMetricsDir, "operational-report-started.prom");
  const successMetricPath = join(reportMetricsDir, "operational-report.prom");
  const operationalUnitNames = [
    operationalPlan.digestServiceName,
    operationalPlan.digestTimerName,
    operationalPlan.watchdogServiceName,
    operationalPlan.watchdogTimerName,
  ];
  if (operationalPlan.scheduleEnabled) {
    mkdirSync(dirname(reportStatePath), { recursive: true, mode: 0o700 });
    mkdirSync(reportMetricsDir, { recursive: true, mode: 0o700 });
    if (!existsSync(reportStatePath)) {
      writeFileSync(
        reportStatePath,
        `${JSON.stringify({ incidentOpen: false, monitoringStartedAt: new Date().toISOString() }, null, 2)}\n`,
        { mode: 0o600 },
      );
    }
    if (!existsSync(startedMetricPath)) {
      writeFileSync(
        startedMetricPath,
        `operational_report_monitoring_started_timestamp_seconds{environment="${operationalPlan.environment}"} ${Math.floor(Date.now() / 1000)}\n`,
        { mode: 0o600 },
      );
    }
  } else {
    const installedOperationalUnits = operationalUnitNames.filter((name) => existsSync(join("/etc", "systemd", "system", name)));
    const installedOperationalTimers = installedOperationalUnits.filter((name) => name.endsWith(".timer"));
    if (installedOperationalTimers.length) {
      execFileSync("systemctl", ["disable", "--now", ...installedOperationalTimers], { stdio: "pipe" });
    }
    for (const name of installedOperationalUnits) rmSync(join("/etc", "systemd", "system", name));
    for (const path of [reportStatePath, startedMetricPath, successMetricPath]) {
      if (existsSync(path)) rmSync(path);
    }
  }
  for (const [name, content] of files) writeFileSync(join("/etc", "systemd", "system", name), content, { mode: 0o644 });
  execSync("systemctl daemon-reload", { stdio: "pipe" });
  const timers = files.filter(([name]) => name.endsWith(".timer")).map(([name]) => name);
  execSync(`systemctl enable --now ${timers.map(shellQuote).join(" ")}`, { stdio: "pipe" });
  // Reload the new cadence even when these timers were already active.
  execFileSync("systemctl", ["restart", plan.timerName], { stdio: "pipe" });
  // An in-flight oneshot may still execute the previous installed CLI code.
  // Restart it without waiting for the health run; inactive oneshots stay idle.
  execFileSync("systemctl", ["--no-block", "try-restart", plan.serviceName], { stdio: "pipe" });
  for (const timer of timers) execFileSync("systemctl", ["is-active", "--quiet", timer], { stdio: "pipe" });
}

async function autoInstallRuntimeMonitoringServices(installPath: string, role: ServerRole): Promise<"installed" | "skipped"> {
  if (!shouldAutoInstallRuntimeMonitoringServices(process.env)) {
    console.error("Skipping runtime monitoring service installation because OPENMATES_SKIP_RUNTIME_MONITORING=1.");
    return "skipped";
  }
  await installRuntimeMonitoringServices(installPath, role);
  return "installed";
}

export function caddyUpdatePlan(installPath: string, role: ServerRole, config: ServerConfig | null, flags: Record<string, string | boolean>) {
  if (flags["caddy-config"] === true) throw new Error("Provide --caddy-config <file>.");
  const explicit = typeof flags["caddy-config"] === "string" ? flags["caddy-config"] : undefined;
  const configPath = detectCaddyConfigPath(explicit) ?? "/etc/caddy/Caddyfile";
  if (explicit && !existsSync(configPath)) throw new Error("caddy_explicit_config_missing");
  const required = role === "core" && getInstallDeploymentMode(installPath, config) === "official_cloud";
  if (!existsSync(configPath) && required) throw new Error("Managed cloud Caddyfile is missing; update cannot proceed.");
  const prior = role === "upload" ? readCaddyUpdateState(join(installPath, ".openmates", "caddy", `${role}.json`), configPath, null) : undefined;
  const profile = resolveCaddyProfile(role, flags["caddy-profile"], prior ? prior.profile ?? "self-host" : undefined);
  if (profile === "official-upload" && !existsSync(configPath)) throw new Error("caddy_official_upload_host_missing");
  if (role === "upload" && existsSync(configPath)) {
    const live = caddyHostOperation({ action: "read", configPath }).content!;
    if (profile === "official-upload") validateOfficialUploadCaddy(live);
    else if (live.includes("@prod_origin") || live.includes("@dev_origin")) throw new Error("caddy_profile_required_official_upload");
  }
  return { configPath, status: existsSync(configPath) ? "planned" : "not_installed", profile };
}

async function updateServerCaddy(input: {
  installPath: string; role: ServerRole; config: ServerConfig | null;
  flags: Record<string, string | boolean>; mode: "image" | "source"; withOverrides: boolean;
}): Promise<CaddyUpdateResult> {
  const plan = caddyUpdatePlan(input.installPath, input.role, input.config, input.flags);
  if (plan.status === "not_installed") return { status: "not_installed" };
  const live = caddyHostOperation({ action: "read", configPath: plan.configPath }).content!;
  const cloud = getInstallDeploymentMode(input.installPath, input.config) === "official_cloud";
  let site: string | null = null;
  let templatePath = `frontend/packages/openmates-cli/templates/caddy/${input.role}/Caddyfile`;
  if (cloud && input.role === "core") {
    const sites = ["api.openmates.org", "api.dev.openmates.org"].filter(name => live.split("\n").some(line => line.trim() === `${name} {`));
    if (sites.length !== 1) throw new Error("caddy_managed_site_ambiguous");
    site = sites[0];
    templatePath = site === "api.openmates.org" ? "deployment/prod_server/Caddyfile" : "deployment/dev_server/Caddyfile";
  } else if (cloud) {
    templatePath = `deployment/${input.role}_server/Caddyfile`;
  } else if (plan.profile === "official-upload") {
    templatePath = "deployment/upload_server/Caddyfile";
  }
  const revision = input.mode === "image"
    ? installedImageLabels(input)["org.opencontainers.image.revision"]?.trim()
    : exec("git rev-parse HEAD", input.installPath).trim();
  if (!revision || !/^[a-f0-9]{40}$/i.test(revision)) throw new Error("caddy_release_revision_invalid");
  let target: string;
  if (input.mode === "source") {
    target = readFileSync(join(input.installPath, templatePath), "utf8");
  } else {
    // Never use the installed CLI's old packaged routes or a moving branch.
    const response = await fetch(`https://raw.githubusercontent.com/glowingkitty/OpenMates/${revision}/${templatePath}`, { signal: AbortSignal.timeout(15_000), redirect: "error" });
    if (!response.ok) throw new Error("caddy_release_template_unavailable");
    target = await response.text();
  }
  const env = readEnvMap(input.installPath);
  const urls = deriveSelfHostCliUrls(readEnvContent(input.installPath));
  const domain = env[`DEPLOY_${input.role.toUpperCase()}_DOMAIN`];
  const liveHostname = live.split("\n").map(line => /^([^\s{$]+)\s+\{$/.exec(line)?.[1]).find(Boolean);
  const hostname = site ?? (plan.profile === "official-upload" ? liveHostname : domain ?? liveHostname);
  if (!hostname) throw new Error("caddy_public_endpoint_unavailable");
  if (plan.profile === "official-upload") {
    const email = /^\s*email\s+(\S+)\s*$/m.exec(live)?.[1];
    if (!email) throw new Error("caddy_official_upload_email_missing");
    target = renderOfficialUploadCaddyTemplate(target, hostname, email);
    validateOfficialUploadCaddy(live, officialUploadOrigins(target));
  }
  const baseUrl = hostname.includes("://") ? hostname : `https://${hostname}`;
  const endpoint = new URL(baseUrl);
  if (!["http:", "https:"].includes(endpoint.protocol) || endpoint.username || endpoint.password) throw new Error("caddy_public_endpoint_invalid");
  return applyCaddyPathUpdate({
    installPath: input.installPath, role: input.role, configPath: plan.configPath,
    site, target, revision, profile: plan.profile,
    verify: async () => {
      if (input.role === "core") await verifyCaddyCoreRoutes(baseUrl, new URL(urls.appUrl).origin);
      else if (plan.profile === "official-upload") await verifyCaddyUploadRoutes(baseUrl, officialUploadOrigins(target));
      else {
        const response = await fetch(`${baseUrl}/health`, { redirect: "error", signal: AbortSignal.timeout(5_000) });
        if (!response.ok) throw new Error("caddy_health_route_failed");
      }
    },
  });
}

async function runCaddyUpdateStep(input: Parameters<typeof updateServerCaddy>[0]): Promise<CaddyUpdateResult> {
  writeUpdateStatus(input.installPath, input.role, { status: "in_progress", step: "caddy-update" });
  try {
    const result = await updateServerCaddy(input);
    console.error(`Caddy: ${result.status}${result.revision ? ` (${result.revision.slice(0, 12)})` : ""}`);
    return result;
  } catch (error) {
    const reason = error instanceof Error && /^caddy_[a-z_:-]+$/.test(error.message) ? error.message : "caddy_update_failed";
    writeUpdateStatus(input.installPath, input.role, { status: "degraded", step: "caddy-update", caddy: { status: "failed", sanitizedReason: reason } });
    const command = caddyRetryForInstall(input.installPath, input.role, input.flags, reason);
    throw new Error(`Caddy update failed (${reason}); update is degraded. Updated containers remain running.\nAfter resolving the reported problem, run:\n${command}`);
  }
}

function caddyRetryForInstall(installPath: string, role: ServerRole, flags: Record<string, string | boolean>, reason?: string): string {
  const explicit = typeof flags["caddy-config"] === "string" ? flags["caddy-config"] : undefined;
  let configPath = explicit ?? "/path/to/active/Caddyfile";
  try { configPath = detectCaddyConfigPath(explicit) ?? "/etc/caddy/Caddyfile"; } catch { /* Require the active path when detection is unavailable. */ }
  return caddyUpdateRetryCommand({ installPath, role, configPath,
    profile: flags["caddy-profile"] === "official-upload" || reason === "caddy_profile_required_official_upload" ? "official-upload" : undefined });
}

async function updateCaddyOnly(installPath: string, role: ServerRole, config: ServerConfig | null, flags: Record<string, string | boolean>): Promise<CaddyUpdateResult> {
  const release = acquireServerUpdateLock(installPath);
  let result: CaddyUpdateResult | undefined;
  try {
    await withEngineeringRuntimeOperation(installPath, "caddy-update", ["caddy"], async () => {
      result = await updateServerCaddy({ installPath, role, config, flags, mode: getInstallMode(installPath, config), withOverrides: flags["with-overrides"] === true || config?.composeProfile === "full" });
    });
    return result!;
  } finally { release(); }
}

export async function updateCaddyAfterCliUpgrade(flags: Record<string, string | boolean>): Promise<CaddyUpdateResult | { status: "pending" | "planned"; retryCommand: string; reason?: string } | undefined> {
  let installPath: string;
  try { installPath = resolveServerPath(flags); } catch (error) {
    if (flags.path !== undefined) throw error;
    return undefined;
  }
  const config = loadConfigForInstallPath(installPath);
  const role = getServerRole(flags, config);
  let configPath: string | undefined;
  try { configPath = detectCaddyConfigPath(typeof flags["caddy-config"] === "string" ? flags["caddy-config"] : undefined); }
  catch { return { status: "pending", reason: "caddy_running_config_requires_explicit_path", retryCommand: caddyUpdateRetryCommand({ installPath, role, configPath: "/path/to/active/Caddyfile" }) }; }
  if (!configPath) return undefined;
  const retryCommand = caddyUpdateRetryCommand({ installPath, role, configPath,
    profile: flags["caddy-profile"] === "official-upload" ? "official-upload" : undefined });
  // An unregistered checkout is not permission to mutate its host during a
  // package upgrade. Its exact follow-up still uses the installed server release.
  if (flags["dry-run"] === true || (!config && typeof flags.path !== "string")) {
    return { status: flags["dry-run"] === true ? "planned" : "pending", retryCommand };
  }
  try {
    return await updateCaddyOnly(installPath, role, config, { ...flags, "caddy-config": configPath });
  } catch (error) {
    const reason = error instanceof Error && /^caddy_[a-z_:-]+$/.test(error.message) ? error.message : "caddy_update_failed";
    return { status: "pending", retryCommand: reason === "caddy_profile_required_official_upload"
      ? caddyUpdateRetryCommand({ installPath, role, configPath, profile: "official-upload" }) : retryCommand, reason };
  }
}

async function serverUpdate(client: OpenMatesClient, rest: string[], flags: Record<string, string | boolean>): Promise<void> {
  if (rest[0] === "status") {
    const installPath = resolveServerPath(flags);
    const config = loadConfigForInstallPath(installPath);
    const role = getServerRole(flags, config);
    const filePath = updateStatusFile(installPath, role);
    const status = readUpdateStatus(installPath, role);
    if (flags.json === true) {
      printJson(existsSync(filePath) ? status : { role, status: "unknown" });
      return;
    }
    if (!existsSync(filePath)) {
      console.log(`No update status recorded for ${role}.`);
      return;
    }
    console.log(JSON.stringify(status, null, 2));
    return;
  }

  if (rest[0] === "install-service") {
    if (flags.continuous !== true) throw new Error("Usage: openmates server update install-service --continuous [--channel main|dev|stable]");
    await installContinuousUpdateService(flags);
    return;
  }

  if (flags.continuous === true) {
    const intervalMinutes = typeof flags.interval === "string" ? Number.parseInt(flags.interval, 10) : 30;
    if (!Number.isFinite(intervalMinutes) || intervalMinutes < 5) throw new Error("--interval must be at least 5 minutes.");
    console.error(`Running continuous updater every ${intervalMinutes} minutes. Use Ctrl+C to stop.`);
    while (true) {
      try {
        await serverUpdate(client, [], { ...flags, continuous: false, "continuous-update": true });
      } catch (error) {
        console.error(`Continuous update iteration degraded: ${error instanceof Error ? error.message : String(error)}`);
      }
      await sleep(intervalMinutes * 60_000);
    }
  }

  const installPath = resolveServerPath(flags);
  const dryRun = flags["dry-run"] === true;
  const config = loadConfigForInstallPath(installPath);
  const role = getServerRole(flags, config);
  const withOverrides = config?.composeProfile === "full";
  const installMode = getInstallMode(installPath, config);
  const reuseCompletedSetup = flags["reuse-completed-setup"] === true;
  if (flags["reuse-completed-setup"] !== undefined && !reuseCompletedSetup) {
    throw new Error("--reuse-completed-setup does not take a value.");
  }
  let guardedTarget: { tag: string; channel?: "stable" | "dev" | "main" } | undefined;
  if (reuseCompletedSetup) {
    const selection = lifecycleServiceSelection(role, flags, config);
    const requested = resolveTargetImageTag(flags, getImageTagFromEnv(installPath, config), getPackageVersion());
    guardedTarget = requested.channel === "stable" ? { ...requested, tag: await resolveStableImageTag() } : requested;
    validateReuseCompletedSetupScope({
      role,
      installMode,
      servicesFlag: flags.services,
      excludeFlag: flags.exclude,
      selectedServices: selection.services,
      targetTag: guardedTarget.tag,
      registry: DEFAULT_IMAGE_REGISTRY,
    });
    if (!dryRun) {
      requireDocker();
      verifyReuseCompletedSetup(installPath, withOverrides, {
        role, installMode, servicesFlag: flags.services, excludeFlag: flags.exclude,
        selectedServices: selection.services, targetTag: guardedTarget.tag,
        registry: readEnvMap(installPath).OPENMATES_IMAGE_REGISTRY || DEFAULT_IMAGE_REGISTRY,
      });
    }
  }
  if (!dryRun) {
    ensureGitWorkDirEnv(installPath);
    ensureRuntimeMetricsDirectory(installPath);
  }

  const deploymentMode = getInstallDeploymentMode(installPath, config);
  const caddyPlan = caddyUpdatePlan(installPath, role, config, flags);
  const releaseUpdateLock = dryRun ? () => undefined : acquireServerUpdateLock(installPath);
  try {
  const previousUpdateStatus = readUpdateStatus(installPath, role);
  const selection = lifecycleServiceSelection(role, flags, config);
  const filterRequested = selection.requested;
  const selectedServices = selection.services;
  const coreSetupPlan = planCoreSetupUpdate(role, selectedServices, filterRequested, reuseCompletedSetup);
  const sourceStrategy = config?.sourceStrategy ?? "managed_clone";
  const missingEnvKeys = missingRequiredEnvKeys(installPath, role);
  const secretPreflight = runtimeSecretPreflight(installPath, role);
  const missingOrUnverifiedSecrets = [
    ...missingEnvKeys,
    ...secretPreflight.importedVaultMissing,
    ...secretPreflight.importedVaultUnavailable,
  ];

  if (installMode === "source" && (flags["image-tag"] !== undefined || flags.channel !== undefined)) {
    throw new Error("--image-tag and --channel only apply to image-mode installs. Source-mode installs update from Git.");
  }

  if (!dryRun) requireDocker();

  console.error("Updating OpenMates...");

  if (installMode === "image") {
    const currentTag = getImageTagFromEnv(installPath, config);
    const requestedTarget = resolveTargetImageTag(flags, currentTag, getPackageVersion());
    const target = guardedTarget ?? (requestedTarget.channel === "stable"
      ? { ...requestedTarget, tag: await resolveStableImageTag() }
      : requestedTarget);
    const templateRef = templateRefForImageTag(target.tag, getPackageVersion());
    const sourceLinks = targetSourceLinks(target.tag, templateRef);
    const safetyPlan = planServerUpdate({ role, selectedServices, dryRun, skipBackup: flags["skip-backup"] === true, continuous: false, missingRequiredSecrets: missingOrUnverifiedSecrets });
    const plan = {
      command: "update",
      role,
      path: installPath,
      mode: "image",
      currentImageTag: currentTag || null,
      targetImageTag: target.tag,
      channel: target.channel ?? null,
      templateRef,
      caddy: caddyPlan,
      selectedServices: filterRequested ? coreSetupPlan.startServices : "all",
      requestedServices: filterRequested ? selectedServices : "all",
      preparedServices: filterRequested ? coreSetupPlan.pullOrBuildServices : "all",
      setupMigration: coreSetupPlan.required ? (reuseCompletedSetup ? "verified_reuse" : "automatic") : "not_applicable",
      stoppedBeforeSetup: coreSetupPlan.stopServices,
      coreSetupGate: {
        required: coreSetupPlan.required,
        stopServices: coreSetupPlan.stopServices,
        setupService: "cms-setup",
        failurePolicy: "keep-email-consumers-stopped",
      },
      steps: safetyPlan.steps,
      backupName: safetyPlan.backupName,
      missingRequiredEnvKeys: missingEnvKeys,
      secretPreflight,
      providerKeyReminders: secretPreflight.emptySecretEnvKeys,
      sourceLinks,
      reuseCompletedSetup,
      blocked: safetyPlan.blocked,
      blockReason: safetyPlan.blockReason,
      dryRun,
    };

    if (dryRun) {
      if (flags.json === true) {
        printJson({ ...plan, status: "planned" });
      } else {
        console.log("Update plan:");
        console.log(`  Mode:          image`);
        console.log(`  Current tag:   ${currentTag || "unknown"}`);
        console.log(`  Target tag:    ${target.tag}`);
        console.log(`  Template ref:  ${templateRef}`);
        console.log(`  Source:        ${sourceLinks.releaseUrl ?? sourceLinks.sourceUrl}`);
        console.log(`  Role:          ${role}`);
        console.log(`  Services:      ${filterRequested ? coreSetupPlan.startServices.join(", ") : "all"}`);
        if (filterRequested && coreSetupPlan.required) console.log(`  Prepared:      ${coreSetupPlan.pullOrBuildServices.join(", ")}`);
        if (coreSetupPlan.required) console.log(`  Setup:         stop ${coreSetupPlan.stopServices.join(", ")}, ${reuseCompletedSetup ? "verify completed" : "run target"} cms-setup, then start target services`);
        console.log(`  Backup:        ${safetyPlan.backupName ?? "none"}`);
        console.log(`  Steps:         ${safetyPlan.steps.join(" -> ")}`);
        console.log(`  Env preflight: ${missingEnvKeys.length ? `missing ${missingEnvKeys.join(", ")}` : "ok"}`);
        console.log(`  Vault secrets: ${formatSecretPreflight(secretPreflight)}`);
        if (secretPreflight.emptySecretEnvKeys.length) {
          console.log(`  Provider keys: add ${secretPreflight.emptySecretEnvKeys.join(", ")} to activate those providers`);
        }
        console.log(`  Commands:      refresh compose, docker compose pull, ${coreSetupPlan.required ? "stop email consumers, cms-setup, " : ""}docker compose up -d, health checks`);
      }
      return;
    }

    if (safetyPlan.blocked) throw new Error(safetyPlan.blockReason ?? "Update blocked by preflight.");
    if (missingOrUnverifiedSecrets.length && flags.yes !== true) {
      throw new Error(
        `Required runtime secret checks failed: ${missingOrUnverifiedSecrets.join(", ")}. ` +
        "Add missing values with 'openmates server env set <KEY>', ensure IMPORTED_TO_VAULT markers exist in Vault, or rerun with --yes after reviewing.",
      );
    }

    console.error(`Mode: image`);
    console.error(`Current image tag: ${currentTag || "unknown"}`);
    console.error(`Target image tag: ${target.tag}`);
    console.error(`Source: ${sourceLinks.releaseUrl ?? sourceLinks.sourceUrl}`);
    if (secretPreflight.emptySecretEnvKeys.length) {
      console.error(`Provider key reminders: add ${secretPreflight.emptySecretEnvKeys.join(", ")} to activate those providers.`);
    }
    writeUpdateStatus(installPath, role, { status: "in_progress", targetImageTag: target.tag, sourceLinks, providerKeyReminders: secretPreflight.emptySecretEnvKeys, step: "backup" });
    if (safetyPlan.backupName) {
      console.error(`Creating rotating pre-update backup: ${safetyPlan.backupName}`);
      createServerBackup(installPath, role, { preUpdate: true });
    } else {
      console.error("Skipping pre-update backup for this role or because --skip-backup was passed.");
    }
    console.error(`Refreshing self-host runtime files from ${templateRef}...`);
    await writeImageModeRuntimeFiles(installPath, target.tag, role);

    const pullArgs = appendSelectedServices(
      [...composeArgs(installPath, withOverrides, installMode, role), "pull"],
      coreSetupPlan.pullOrBuildServices,
      filterRequested,
    );
    let code = 0;
    if (shouldPullImages()) {
      writeUpdateStatus(installPath, role, { status: "in_progress", targetImageTag: target.tag, sourceLinks, providerKeyReminders: secretPreflight.emptySecretEnvKeys, step: "pull" });
      console.error("Pulling prebuilt images...");
      code = await runInteractive("docker", pullArgs, installPath);
      if (code !== 0) throw new Error(`Docker image pull failed with exit code ${code}.`);
    } else {
      console.error("Skipping image pull because OPENMATES_SKIP_IMAGE_PULL=1.");
    }

    const compose = composeArgs(installPath, withOverrides, installMode, role);
    const upArgs = imageUpdateUpArgs(compose, coreSetupPlan.startServices, filterRequested, reuseCompletedSetup);
    if (coreSetupPlan.required) {
      let updateStep = "stop-email-consumers";
      try {
        await runCoreSetupUpdate({
          compose,
          stopServices: coreSetupPlan.stopServices,
          upArgs,
          reuseCompletedSetup,
          run: (args) => runInteractive("docker", args, installPath),
          verifySetup: () => {
            verifyCoreSetupResult(installPath, withOverrides, "image", target.tag);
            if (reuseCompletedSetup) verifyReuseCompletedSetup(installPath, withOverrides, {
              role, installMode, servicesFlag: flags.services, excludeFlag: flags.exclude,
              selectedServices, targetTag: target.tag,
              registry: readEnvMap(installPath).OPENMATES_IMAGE_REGISTRY || DEFAULT_IMAGE_REGISTRY,
            });
          },
          step: (step) => {
            updateStep = step;
            writeUpdateStatus(installPath, role, { status: "in_progress", targetImageTag: target.tag, sourceLinks, step });
          },
        });
      } catch (error) {
        writeUpdateStatus(installPath, role, { status: "degraded", targetImageTag: target.tag, sourceLinks, step: updateStep });
        throw error;
      }
    } else {
      writeUpdateStatus(installPath, role, { status: "in_progress", targetImageTag: target.tag, sourceLinks, step: "up" });
      code = await runInteractive("docker", upArgs, installPath);
      if (code !== 0) throw new Error(`Docker image restart failed with exit code ${code}.`);
    }

    console.error("Waiting for role health checks...");
    let successfulRuntimeOutput: RuntimeVerifierOutput | null = null;
    let caddy: CaddyUpdateResult | null = null;
    try {
      writeUpdateStatus(installPath, role, { status: "in_progress", targetImageTag: target.tag, sourceLinks, providerKeyReminders: secretPreflight.emptySecretEnvKeys, step: "health-check" });
      await waitForServerHealth(installPath, role, {
        checkWebApp: shouldCheckWebHealth({ role, deploymentMode, selectedServices, filterRequested }),
      });
      caddy = await runCaddyUpdateStep({ installPath, role, config, flags, mode: "image", withOverrides });
      const runtimeOutput = runRuntimeVerification(installPath, role, config);
      await persistRuntimeResult(installPath, role, runtimeOutput);
      if (runtimeOutput.status !== "passed") {
        const notificationDelivery = await dispatchRuntimeEvent(installPath, role, "post_update_failed", runtimeOutput.checks, new Date().toISOString());
        let monitoringProvision = "installed";
        try {
          monitoringProvision = await autoInstallRuntimeMonitoringServices(installPath, role);
        } catch {
          monitoringProvision = "failed";
        }
        writeUpdateStatus(installPath, role, {
          status: "degraded",
          targetImageTag: target.tag,
          step: "runtime-verification",
          caddy,
          checks: runtimeOutput.checks,
          restoreStatus: runtimeOutput.restoreStatus,
          restoreCommand: runtimeOutput.restoreCommand,
          notificationDelivery,
          monitoringProvision,
        });
        const restore = runtimeOutput.restoreCommand ? ` Restore with: ${runtimeOutput.restoreCommand}` : " restore_unavailable";
        throw new Error(`Post-update runtime verification failed; updated containers remain running.${restore}`);
      }
      successfulRuntimeOutput = runtimeOutput;
    } catch (error) {
      await runInteractive("docker", [...composeArgs(installPath, withOverrides, installMode, role), "ps"], installPath);
      throw error;
    }

    const automaticStorageMigration = runAutomaticStorageMigration(installPath, role, installMode, withOverrides);
    console.error(`Storage migration: ${automaticStorageMigration.status}${automaticStorageMigration.reason ? ` (${automaticStorageMigration.reason})` : ""}`);

    if (config) {
      saveServerConfig({ ...config, imageTag: target.tag, imageChannel: target.channel });
    }
    try {
      await autoInstallRuntimeMonitoringServices(installPath, role);
    } catch (error) {
      const restoreCommand = safetyPlan.backupName
        ? `openmates server restore --role ${role} --file ${join(roleBackupDir(installPath, role), safetyPlan.backupName)}`
        : null;
      writeUpdateStatus(installPath, role, {
        status: "degraded",
        targetImageTag: target.tag,
        step: "monitoring-service",
        restoreStatus: restoreCommand ? "available" : "restore_unavailable",
        restoreCommand,
      });
      throw new Error(`Runtime checks passed but monitoring service installation failed: ${error instanceof Error ? error.message : String(error)}`);
    }
    const quickTest = await maybeRunQuickServerTest(client, installPath, role, config, flags);
    persistQuickServerTestOutcome(installPath, role, quickTest);
    if (quickTest.status === "failed") {
      if (flags.json === true) {
        printJson({ ...plan, status: "degraded", dryRun: false, runtimeVerification: successfulRuntimeOutput, quickTest });
      }
      throw new Error("Authenticated quick server test failed; updated containers remain running.");
    }
    let imageMetadata: ReturnType<typeof installedImageMetadata>;
    try {
      imageMetadata = installedImageMetadata({ installPath, role, withOverrides, templateRef, requestedTag: target.tag });
    } catch {
      const completion = buildUpdateCompletionOutcome({ status: "unavailable", attempts: 0, sanitizedReason: "image_provenance_unavailable" });
      writeUpdateStatus(installPath, role, {
        status: completion.updateStatus,
        targetImageTag: target.tag,
        updateMode: "image",
        step: "completion-email",
        checks: successfulRuntimeOutput?.checks ?? [],
        runtimeCompletedAt: successfulRuntimeOutput?.completed_at,
        quickTest,
        automaticStorageMigration,
        completionEmailDelivery: completion.delivery,
      });
      if (flags.json === true) {
        printJson({ ...plan, status: completion.updateStatus, dryRun: false, runtimeVerification: successfulRuntimeOutput, quickTest, completionEmailDelivery: completion.delivery });
      }
      throw new Error("Server update completed but installed image provenance could not be resolved for the admin completion email; updated containers remain running.");
    }
    const completion = await runUpdateCompletionEmailGate({
      installPath,
      role,
      updateMode: "image",
      installedVersion: imageMetadata.installedVersion,
      sourceLinks: imageMetadata.sourceLinks,
      previousStatus: previousUpdateStatus,
      deduplicateAcceptedVersion: flags["continuous-update"] === true,
    });
    writeUpdateStatus(installPath, role, {
      status: completion.updateStatus,
      targetImageTag: target.tag,
      installedVersion: imageMetadata.installedVersion,
      caddy,
      updateMode: "image",
      sourceLinks: imageMetadata.sourceLinks,
      sourceLink: selectUpdateSourceLink(imageMetadata.sourceLinks)?.url,
      providerKeyReminders: secretPreflight.emptySecretEnvKeys,
      step: completion.updateStatus === "success" ? "complete" : "completion-email",
      checks: successfulRuntimeOutput?.checks ?? [],
      runtimeCompletedAt: successfulRuntimeOutput?.completed_at,
      quickTest,
      automaticStorageMigration,
      completionEmailDelivery: completion.delivery,
      completionEmailDeliveryId: completion.deliveryId,
      completionEmailPendingAt: completion.deliveryPendingAt,
      completedAt: completion.completedAt,
    });
    if (flags.json === true) {
      printJson({
        ...plan,
        status: completion.updateStatus,
        dryRun: false,
        installedVersion: imageMetadata.installedVersion,
        sourceLinks: imageMetadata.sourceLinks,
        runtimeVerification: successfulRuntimeOutput,
        caddy,
        quickTest,
        automaticStorageMigration,
        completionEmailDelivery: completion.delivery,
        completedAt: completion.completedAt,
      });
    }
    if (completion.updateStatus === "degraded") {
      throw new Error("Server update completed but the admin completion email was not accepted; updated containers remain running.");
    }
    if (flags.json !== true) {
      console.log("Server images updated, containers restarted, health checks passed, and the admin completion email was accepted.");
    }
    return;
  }

  if (dryRun) {
    if (flags.json === true) {
      printJson({
        command: "update",
        status: "planned",
        path: installPath,
        mode: "source",
        sourceStrategy,
        caddy: caddyPlan,
        selectedServices: filterRequested ? coreSetupPlan.startServices : "all",
        requestedServices: filterRequested ? selectedServices : "all",
        preparedServices: filterRequested ? coreSetupPlan.pullOrBuildServices : "all",
        setupMigration: coreSetupPlan.required ? "automatic" : "not_applicable",
        coreSetupGate: {
          required: coreSetupPlan.required,
          stopServices: coreSetupPlan.stopServices,
          setupService: "cms-setup",
          failurePolicy: "keep-email-consumers-stopped",
        },
        checkWebApp: shouldCheckWebHealth({ role, deploymentMode, selectedServices, filterRequested }),
        dryRun: true,
      });
    } else {
      console.log("Update plan:");
      console.log(`  Mode:          source (${sourceStrategy === "working_tree" ? "current working tree" : "managed clone"})`);
      console.log(`  Services:      ${filterRequested ? coreSetupPlan.startServices.join(", ") : "all"}`);
      if (filterRequested && coreSetupPlan.required) console.log(`  Prepared:      ${coreSetupPlan.pullOrBuildServices.join(", ")}`);
      if (coreSetupPlan.required) console.log(`  Setup:         stop ${coreSetupPlan.stopServices.join(", ")}, run target cms-setup, then start target services`);
      console.log(`  Web health:    ${shouldCheckWebHealth({ role, deploymentMode, selectedServices, filterRequested }) ? "enabled" : "skipped"}`);
      console.log(`  Commands:      ${sourceStrategy === "working_tree" ? "docker compose build" : "git pull --ff-only, docker compose build"}, ${coreSetupPlan.required ? "stop email consumers, cms-setup, " : ""}docker compose up -d, health checks`);
    }
    return;
  }

  if (sourceStrategy === "working_tree") {
    if (flags.force === true) {
      throw new Error("--force is not supported for registered working-tree servers; commit or resolve local changes explicitly.");
    }
    console.error("Using the registered working tree without pulling or changing Git state.");
  } else {
    requireGit();
    if (flags.force === true) {
      throw new Error("--force is disabled because automated git stash is unsafe. Resolve local changes explicitly, then rerun update.");
    }
    try {
      const pullOutput = exec("git pull --ff-only", installPath);
      console.error(pullOutput || "Already up to date.");
    } catch {
      throw new Error(
        "Failed to pull updates. Your local branch may have diverged or contain local changes.\n" +
        "Resolve the working tree explicitly, then rerun update.",
      );
    }
  }

  // Bake only clean source provenance into every rebuilt API/worker image;
  // a dirty development tree keeps automatic archive advancement paused.
  let sourceBuildRevision = "";
  try {
    if (!exec("git status --porcelain", installPath).trim()) {
      const revision = exec("git rev-parse HEAD", installPath).trim();
      if (/^[a-f0-9]{40}$/i.test(revision)) sourceBuildRevision = revision.toLowerCase();
    }
  } catch { /* A build without verified provenance remains supported. */ }
  // Rebuild and restart
  const buildArgs = appendSelectedServices(
    [...composeArgs(installPath, withOverrides, installMode, role), "build", "--build-arg", `BUILD_COMMIT_SHA=${sourceBuildRevision}`],
    coreSetupPlan.pullOrBuildServices,
    filterRequested,
  );
  console.error("Rebuilding containers...");
  let code = await runInteractive("docker", buildArgs, installPath);
  if (code !== 0) throw new Error(`Docker source build failed with exit code ${code}.`);

  const compose = composeArgs(installPath, withOverrides, installMode, role);
  const upArgs = appendSelectedServices([...compose, "up", "-d"], coreSetupPlan.startServices, filterRequested);
  if (coreSetupPlan.required) {
    let updateStep = "stop-email-consumers";
    try {
      await runCoreSetupUpdate({
        compose,
        stopServices: coreSetupPlan.stopServices,
        upArgs,
        reuseCompletedSetup: false,
        run: (args) => runInteractive("docker", args, installPath),
        verifySetup: () => verifyCoreSetupResult(installPath, withOverrides, "source"),
        step: (step) => {
          updateStep = step;
          writeUpdateStatus(installPath, role, { status: "in_progress", step });
        },
      });
    } catch (error) {
      writeUpdateStatus(installPath, role, { status: "degraded", step: updateStep });
      throw error;
    }
  } else {
    code = await runInteractive("docker", upArgs, installPath);
    if (code !== 0) throw new Error(`Docker source restart failed with exit code ${code}.`);
  }

  const checkWebApp = shouldCheckWebHealth({ role, deploymentMode, selectedServices, filterRequested });
  console.error(checkWebApp ? "Waiting for API and web health checks..." : "Waiting for API health checks...");
  let successfulRuntimeOutput: RuntimeVerifierOutput | null = null;
  let caddy: CaddyUpdateResult | null = null;
  try {
    await waitForServerHealth(installPath, role, { checkWebApp });
    caddy = await runCaddyUpdateStep({ installPath, role, config, flags, mode: "source", withOverrides });
    const runtimeOutput = runRuntimeVerification(installPath, role, config);
    await persistRuntimeResult(installPath, role, runtimeOutput);
    if (runtimeOutput.status !== "passed") {
      const notificationDelivery = await dispatchRuntimeEvent(installPath, role, "post_update_failed", runtimeOutput.checks, new Date().toISOString());
      let monitoringProvision = "installed";
      try {
        monitoringProvision = await autoInstallRuntimeMonitoringServices(installPath, role);
      } catch {
        monitoringProvision = "failed";
      }
      writeUpdateStatus(installPath, role, {
        status: "degraded",
        step: "runtime-verification",
        caddy,
        checks: runtimeOutput.checks,
        restoreStatus: runtimeOutput.restoreStatus,
        restoreCommand: runtimeOutput.restoreCommand,
        notificationDelivery,
        monitoringProvision,
      });
      const restore = runtimeOutput.restoreCommand ? ` Restore with: ${runtimeOutput.restoreCommand}` : " restore_unavailable";
      throw new Error(`Post-update runtime verification failed; updated containers remain running.${restore}`);
    }
    successfulRuntimeOutput = runtimeOutput;
  } catch (error) {
    await runInteractive("docker", [...composeArgs(installPath, withOverrides, installMode, role), "ps"], installPath);
    throw error;
  }

  const automaticStorageMigration = runAutomaticStorageMigration(installPath, role, installMode, withOverrides);
  console.error(`Storage migration: ${automaticStorageMigration.status}${automaticStorageMigration.reason ? ` (${automaticStorageMigration.reason})` : ""}`);

  try {
    await autoInstallRuntimeMonitoringServices(installPath, role);
  } catch (error) {
    writeUpdateStatus(installPath, role, { status: "degraded", step: "monitoring-service", restoreStatus: "restore_unavailable", restoreCommand: null });
    throw new Error(`Runtime checks passed but monitoring service installation failed: ${error instanceof Error ? error.message : String(error)}`);
  }
  const quickTest = await maybeRunQuickServerTest(client, installPath, role, config, flags);
  persistQuickServerTestOutcome(installPath, role, quickTest);
  if (quickTest.status === "failed") {
    if (flags.json === true) {
      printJson({ command: "update", status: "degraded", path: installPath, mode: "source", runtimeVerification: successfulRuntimeOutput, quickTest });
    }
    throw new Error("Authenticated quick server test failed; updated containers remain running.");
  }
  let sourceMetadata: ReturnType<typeof sourceUpdateMetadata>;
  try {
    sourceMetadata = sourceUpdateMetadata(installPath);
  } catch {
    const completion = buildUpdateCompletionOutcome({ status: "unavailable", attempts: 0, sanitizedReason: "source_revision_unavailable" });
    writeUpdateStatus(installPath, role, {
      status: completion.updateStatus,
      updateMode: "source",
      step: "completion-email",
      checks: successfulRuntimeOutput?.checks ?? [],
      runtimeCompletedAt: successfulRuntimeOutput?.completed_at,
      quickTest,
      automaticStorageMigration,
      completionEmailDelivery: completion.delivery,
    });
    if (flags.json === true) {
      printJson({ command: "update", status: completion.updateStatus, path: installPath, mode: "source", runtimeVerification: successfulRuntimeOutput, quickTest, completionEmailDelivery: completion.delivery });
    }
    throw new Error("Server update completed but its source revision could not be resolved for the admin completion email; updated containers remain running.");
  }
  const completion = await runUpdateCompletionEmailGate({
    installPath,
    role,
    updateMode: "source",
    installedVersion: sourceMetadata.installedVersion,
    sourceLinks: sourceMetadata.sourceLinks,
    previousStatus: previousUpdateStatus,
    deduplicateAcceptedVersion: flags["continuous-update"] === true,
  });
  writeUpdateStatus(installPath, role, {
    status: completion.updateStatus,
    installedVersion: sourceMetadata.installedVersion,
    caddy,
    updateMode: "source",
    sourceLinks: sourceMetadata.sourceLinks,
    sourceLink: selectUpdateSourceLink(sourceMetadata.sourceLinks)?.url,
    step: completion.updateStatus === "success" ? "complete" : "completion-email",
    checks: successfulRuntimeOutput?.checks ?? [],
    runtimeCompletedAt: successfulRuntimeOutput?.completed_at,
    quickTest,
    automaticStorageMigration,
    completionEmailDelivery: completion.delivery,
    completionEmailDeliveryId: completion.deliveryId,
    completionEmailPendingAt: completion.deliveryPendingAt,
    completedAt: completion.completedAt,
  });
  if (flags.json === true) {
    printJson({
      command: "update",
      status: completion.updateStatus,
      path: installPath,
      mode: "source",
      installedVersion: sourceMetadata.installedVersion,
      sourceLinks: sourceMetadata.sourceLinks,
      runtimeVerification: successfulRuntimeOutput,
      caddy,
      quickTest,
      automaticStorageMigration,
      completionEmailDelivery: completion.delivery,
      completedAt: completion.completedAt,
    });
  }
  if (completion.updateStatus === "degraded") {
    throw new Error("Server update completed but the admin completion email was not accepted; updated containers remain running.");
  }
  if (flags.json !== true) {
    console.log("Server updated, restarted, health checks passed, and the admin completion email was accepted.");
  }
  } finally {
    releaseUpdateLock();
  }
}

async function serverTest(
  client: OpenMatesClient,
  flags: Record<string, string | boolean>,
): Promise<void> {
  if (flags.quick !== true && flags["quick-test"] !== true) {
    throw new Error("Usage: openmates server test --quick [--confirm-spend-credits] [--json]");
  }
  const installPath = resolveServerPath(flags);
  const config = loadConfigForInstallPath(installPath);
  const role = getServerRole(flags, config);
  const result = await maybeRunQuickServerTest(client, installPath, role, config, flags, true);
  if (flags.json === true) printJson({ command: "test", role, quickTest: result });
  else if (result.status === "passed") console.log("Authenticated quick server test passed.");
  if (result.status === "failed") throw new Error("Authenticated quick server test failed.");
}

async function serverVerify(flags: Record<string, string | boolean>): Promise<void> {
  requireDocker();
  const installPath = resolveServerPath(flags);
  const config = loadConfigForInstallPath(installPath);
  const role = getServerRole(flags, config);
  const output = runRuntimeVerification(installPath, role, config);
  await persistRuntimeResult(installPath, role, output);
  if (flags.json === true) printJson(output);
  else console.log(`Runtime verification ${output.status} for ${role}.`);
  if (output.status !== "passed") throw new Error("One or more required runtime checks failed.");
}

async function serverMonitoring(rest: string[], flags: Record<string, string | boolean>): Promise<void> {
  const installPath = resolveServerPath(flags);
  const config = loadConfigForInstallPath(installPath);
  const role = getServerRole(flags, config);
  if (rest[0] === "install-service") {
    const plan = planRuntimeMonitoringServices({ role, installPath, executablePath: resolve(process.argv[1] ?? "/usr/local/bin/openmates") });
    const files = [
      [plan.serviceName, plan.unit],
      [plan.timerName, plan.timer],
      [plan.watchdogServiceName, plan.watchdogUnit],
      [plan.watchdogTimerName, plan.watchdogTimer],
    ].filter((entry): entry is [string, string] => Boolean(entry[0] && entry[1]));
    if (flags["dry-run"] === true || flags.json === true) {
      printJson({ command: "monitoring install-service", status: "planned", role, files: files.map(([name, content]) => ({ name, content })) });
      return;
    }
    await installRuntimeMonitoringServices(installPath, role);
    console.log(`Installed runtime monitor and independent watchdog for ${role}.`);
    return;
  }

  if (rest[0] === "digest") {
    requireDocker();
    const deploymentMode = getInstallDeploymentMode(installPath, config);
    const environment = deploymentMode === "official_cloud"
      ? (readEnvMap(installPath).SERVER_ENVIRONMENT === "production" ? "production" : "development")
      : "self_host";
    const channel = typeof flags.channel === "string" ? flags.channel : "email,discord";
    const result = spawnSync(
      "docker",
      [
        ...composeArgs(installPath, config?.composeProfile === "full", getInstallMode(installPath, config), role),
        "exec", "-T", "api", "python", "-m", "backend.scripts.operational_monitoring",
        "--environment", environment, "--channels", channel,
        ...(flags.test === true ? ["--test"] : []),
      ],
      { cwd: installPath, encoding: "utf-8", timeout: 120_000 },
    );
    const outputLine = result.stdout.trim().split("\n").filter(Boolean).at(-1);
    if (!outputLine) throw new Error("Operational report command returned no structured output.");
    const output = JSON.parse(outputLine) as {
      delivery_state: string;
      report_id: string;
      report_sha256: string;
      receipts: Array<{ environment: "development" | "production" | "self_host"; channel: "email" | "discord"; state: "queued" | "accepted" | "failed" | "unavailable"; attempt_count: number; occurred_at: string; sanitized_failure_class?: string; destination_source?: string; fallback_used?: boolean }>;
    };
    const accepted = output.delivery_state === "accepted";
    const state = await readOperationalReportState(installPath, role);
    const nextState = accepted
      ? { ...state, incidentOpen: false, incidentOpenedAt: undefined, lastAcceptedReportAt: new Date().toISOString() }
      : state;
    await writeOperationalReportState(installPath, role, nextState);
    const metricsDir = join(installPath, ".openmates", "runtime-health", "metrics");
    mkdirSync(metricsDir, { recursive: true, mode: 0o700 });
    if (accepted) {
      writeFileSync(
        join(metricsDir, "operational-report.prom"),
        `operational_report_last_success_timestamp_seconds{environment="${output.receipts[0]?.environment ?? environment}"} ${Math.floor(Date.now() / 1000)}\n`,
        { mode: 0o600 },
      );
    }
    const redactedReceipts = output.receipts.map((receipt) => buildOperationalDeliveryReceipt({
      environment: receipt.environment,
      reportId: output.report_id,
      reportSha256: output.report_sha256,
      channel: receipt.channel,
      state: receipt.state,
      attemptCount: receipt.attempt_count,
      occurredAt: receipt.occurred_at,
      sanitizedFailureClass: receipt.sanitized_failure_class,
      destinationSource: receipt.destination_source,
      fallbackUsed: receipt.fallback_used,
    }));
    const receiptDir = join(installPath, ".openmates", "runtime-health", "receipts");
    mkdirSync(receiptDir, { recursive: true, mode: 0o700 });
    const receiptMonth = new Date().toISOString().slice(0, 7);
    for (const receipt of redactedReceipts) {
      appendFileSync(join(receiptDir, `${receiptMonth}.jsonl`), `${JSON.stringify(receipt)}\n`, { mode: 0o600 });
    }
    const displayed = { command: "monitoring digest", reportId: output.report_id, reportSha256: output.report_sha256, deliveryState: output.delivery_state, receipts: redactedReceipts };
    if (flags.json === true) printJson(displayed);
    else console.log(JSON.stringify(displayed, null, 2));
    if (result.status !== 0 || output.delivery_state !== "accepted") throw new Error("Operational report delivery did not succeed on every requested channel.");
    return;
  }

  if (rest[0] === "report-watchdog") {
    const reportState = await readOperationalReportState(installPath, role);
    const evaluated = evaluateOperationalReportFreshness(reportState, new Date());
    await writeOperationalReportState(installPath, role, evaluated.state);
    const delivery = evaluated.event
      ? await dispatchRuntimeEvent(
          installPath,
          role,
          evaluated.event.type === "operational_report_recovered" ? "recovery" : "monitor_stale",
          [{ id: "operational.report", status: evaluated.event.type === "operational_report_recovered" ? "passed" : "failed", required: true, duration_ms: 0, sanitized_reason: evaluated.event.reason }],
          new Date().toISOString(),
        )
      : [];
    if (flags.json === true) printJson({ command: "monitoring report-watchdog", event: evaluated.event, delivery, state: evaluated.state });
    else console.log(JSON.stringify({ event: evaluated.event, delivery, state: evaluated.state }, null, 2));
    return;
  }

  const state = await readRuntimeIncidentState(installPath, role);
  if (rest[0] === "status") {
    const watchdog = evaluateRuntimeWatchdog(state, new Date());
    const output = { role, ...state, stale: watchdog.notification?.kind === "stale" };
    if (flags.json === true) printJson(output);
    else console.log(JSON.stringify(output, null, 2));
    return;
  }
  if (rest[0] !== "run") throw new Error("Usage: openmates server monitoring run|status|install-service|digest|report-watchdog [--role core|upload|preview]");

  if (flags.watchdog === true) {
    const evaluated = evaluateRuntimeWatchdog(state, new Date());
    await writeRuntimeIncidentState(installPath, role, evaluated.state);
    const delivery = evaluated.notification
      ? await dispatchRuntimeEvent(installPath, role, "monitor_stale", [], new Date().toISOString())
      : [];
    if (flags.json === true) printJson({ role, notification: evaluated.notification, delivery, state: evaluated.state });
    return;
  }

  let output: RuntimeVerifierOutput;
  try {
    requireDocker();
    const inventoryRefreshed = refreshStorageRuntimeInventory(
      installPath, role, getInstallMode(installPath, config), config?.composeProfile === "full",
    );
    output = runRuntimeVerification(installPath, role, config);
    if (!inventoryRefreshed) {
      output.checks.push({ id: "core.storage_migration_inventory", status: "failed", required: false,
        duration_ms: 0, failureClass: "configuration", sanitized_reason: "runtime_inventory_refresh_unavailable" });
    }
  } catch (error) {
    console.error(`Runtime verifier unavailable: ${error instanceof Error ? error.name : "UnknownError"}`);
    output = {
      status: "failed",
      role,
      completed_at: Date.now() / 1000,
      checks: [{
        id: `${role}.runtime_verifier_available`,
        status: "failed",
        required: true,
        duration_ms: 0,
        failureClass: "critical_availability",
        sanitized_reason: "runtime_verifier_unavailable",
      }],
    };
  }
  await persistRuntimeResult(installPath, role, output);
  let nextState = await readRuntimeIncidentState(installPath, role);
  const heartbeat = evaluateRuntimeHeartbeat(nextState, new Date());
  nextState = heartbeat.state;
  await writeRuntimeIncidentState(installPath, role, nextState);
  const heartbeatDelivery = heartbeat.notification
    ? await dispatchRuntimeEvent(installPath, role, "daily_heartbeat", output.checks, new Date().toISOString())
    : [];
  if (flags.json === true) printJson({ ...output, notification: heartbeat.notification, notificationDelivery: heartbeatDelivery });
  if (output.status !== "passed") throw new Error("Runtime monitor found required check failures.");
}

async function serverNotifications(rest: string[], flags: Record<string, string | boolean>): Promise<void> {
  if (rest[0] !== "test") throw new Error("Usage: openmates server notifications test --channel email|discord|webhook|all [--json]");
  const installPath = resolveServerPath(flags);
  const config = loadConfigForInstallPath(installPath);
  const role = getServerRole(flags, config);
  const channel = typeof flags.channel === "string" ? flags.channel : "all";
  if (!new Set(["email", "discord", "webhook", "all"]).has(channel)) throw new Error("--channel must be email, discord, webhook, or all.");
  const eventKind = typeof flags["event-kind"] === "string" ? flags["event-kind"] : "delivery_test";
  if (!new Set(["delivery_test", "incident", "critical", "recovery"]).has(eventKind)) {
    throw new Error("--event-kind must be delivery_test, incident, critical, or recovery.");
  }
  if (eventKind !== "delivery_test" && readEnvMap(installPath).SERVER_ENVIRONMENT !== "development") {
    throw new Error("Synthetic notification event kinds are restricted to development.");
  }
  const notificationConfig = runtimeNotificationConfig(installPath);
  if (channel !== "all") {
    if (channel !== "email") notificationConfig.email = undefined;
    if (channel !== "discord") notificationConfig.discordWebhookUrl = undefined;
    if (channel !== "webhook") notificationConfig.genericWebhook = undefined;
  }
  const deliveries = await deliverRuntimeNotification(notificationConfig, {
    role,
    kind: eventKind as RuntimeNotificationPayload["kind"],
    occurredAt: new Date().toISOString(),
    environment: notificationConfig.environment,
    serverName: notificationConfig.serverName || `${notificationConfig.environment}-${role}`,
    deploymentMode: notificationConfig.deploymentMode,
    version: notificationConfig.version,
    checkIds: [eventKind === "delivery_test" ? "monitor" : "core.object_storage"],
    sanitizedReason: eventKind === "recovery" ? "storage_available" : eventKind === "delivery_test" ? "operator_requested_delivery_test" : "storage_unavailable",
  });
  const output = {
    command: "notifications test",
    role,
    eventKind,
    configured: deliveries.length > 0,
    discordDestination: channel === "discord" || channel === "all"
      ? { source: notificationConfig.discordDestinationSource, fallbackUsed: notificationConfig.discordFallbackUsed }
      : undefined,
    deliveries,
  };
  if (flags.json === true && flags.compact === true) console.log(JSON.stringify(output));
  else if (flags.json === true) printJson(output);
  else console.log(JSON.stringify(output, null, 2));
  if (deliveries.some((delivery) => delivery.status === "exhausted")) throw new Error("One or more notification delivery tests failed.");
}

async function serverReset(flags: Record<string, string | boolean>): Promise<void> {
  requireDocker();
  const installPath = resolveServerPath(flags);
  ensureGitWorkDirEnv(installPath);
  ensureRuntimeMetricsDirectory(installPath);
  const config = loadConfigForInstallPath(installPath);
  const role = getServerRole(flags, config);
  const withOverrides = config?.composeProfile === "full";
  const installMode = getInstallMode(installPath, config);

  const userDataOnly = flags["delete-user-data-only"] === true;

  if (userDataOnly) {
    console.error("\nWARNING: This will delete all user data (database and cache).");
    console.error("Server configuration and code will be preserved.\n");
  } else {
    console.error("\nWARNING: This will stop the server and delete ALL data including:");
    console.error("  - Database (all user accounts, chats, settings)");
    console.error("  - Cache");
    console.error("  - All Docker volumes\n");
  }

  if (flags.yes !== true) {
    const confirmed = await confirmDestructive("DELETE ALL DATA");
    if (!confirmed) {
      console.error("Reset cancelled.");
      return;
    }
  }

  console.error("Resetting server...");

  if (userDataOnly) {
    // Stop, remove specific volumes, restart
    const downArgs = [...composeArgs(installPath, withOverrides, installMode, role), "down"];
    let code = await runInteractive("docker", downArgs, installPath);
    if (code !== 0) process.exit(code);

    // Remove data volumes. Keep the legacy database volume name for older installs.
    for (const vol of ["openmates-cache-data", "openmates-postgres-data", "openmates-cms-database-data"]) {
      try {
        exec(`docker volume rm ${vol}`, installPath);
        console.error(`  Removed volume: ${vol}`);
      } catch {
        // Volume may not exist
      }
    }

    // Source installs rebuild after clearing data. Image installs restart from pulled images.
    if (installMode === "source") {
      const buildArgs = [...composeArgs(installPath, withOverrides, installMode, role), "build"];
      code = await runInteractive("docker", buildArgs, installPath);
      if (code !== 0) process.exit(code);
    }

    const upArgs = [...composeArgs(installPath, withOverrides, installMode, role), "up", "-d"];
    code = await runInteractive("docker", upArgs, installPath);
    if (code !== 0) process.exit(code);
  } else {
    // Full reset: remove everything
    const args = [...composeArgs(installPath, withOverrides, installMode, role), "down", "-v"];
    const code = await runInteractive("docker", args, installPath);
    if (code !== 0) process.exit(code);
  }

  if (flags.json === true) {
    printJson({ command: "reset", status: "success", path: installPath, userDataOnly });
  } else {
    console.log("Server reset complete.");
    if (!userDataOnly) {
      console.log("Run 'openmates server start' to start fresh.");
    }
  }
}

async function serverMakeAdmin(
  rest: string[],
  flags: Record<string, string | boolean>,
): Promise<void> {
  requireDocker();
  const installPath = resolveServerPath(flags);

  const email = rest[0];
  if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    throw new Error(
      "Usage: openmates server make-admin <email>\n" +
      "Provide a valid email address of the user to grant admin privileges.",
    );
  }

  console.error(`Granting admin privileges to ${email}...`);
  const code = await runInteractive(
    "docker",
    ["exec", "api", "python", "/app/backend/scripts/create_admin.py", email],
    installPath,
  );
  if (code !== 0) {
    throw new Error(
      "Failed to grant admin privileges. Make sure:\n" +
      "  - The server is running ('openmates server status')\n" +
      "  - The user has signed up with this email address",
    );
  }

  if (flags.json === true) {
    printJson({ command: "make-admin", status: "success", email });
  } else {
    console.log(`Admin privileges granted to ${email}.`);
  }
}

async function serverFeatures(rest: string[], flags: Record<string, string | boolean>): Promise<void> {
  const action = rest[0] ?? "list";
  const featureId = rest[1];
  const installPath = resolveServerPath(flags);
  const installMode = getInstallMode(installPath);
  if (installMode === "image") ensureImageRuntimeConfig(installPath);
  const configPath = installMode === "image" ? imageBackendConfigPath(installPath) : join(installPath, BACKEND_CONFIG_FILE);
  if (!existsSync(configPath)) {
    throw new Error(`Backend config not found at ${configPath}. Run 'openmates server install' first or pass --path <dir>.`);
  }

  const content = readFileSync(configPath, "utf-8");
  const overrides = parseFeatureOverrides(content);
  const writeOverrides = (nextOverrides: FeatureOverrides) => {
    writeFileSync(configPath, updateFeatureOverridesContent(content, nextOverrides));
    console.log(`Updated ${configPath}`);
    console.log("Restart the server for feature changes to take effect: openmates server restart");
  };

  if (action === "list") {
    console.log("Feature overrides:");
    console.log(`  enabled: ${overrides.enabled.length ? overrides.enabled.join(", ") : "none"}`);
    console.log(`  disabled: ${overrides.disabled.length ? overrides.disabled.join(", ") : "none"}`);
    console.log("\nKnown off-by-default features:");
    for (const [id, reason] of OFF_BY_DEFAULT_FEATURES.entries()) {
      const override = overrides.enabled.includes(id) ? "enabled override" : overrides.disabled.includes(id) ? "disabled override" : "default off";
      console.log(`  ${id} (${featureKind(id)}): ${override} - ${reason}`);
    }
    return;
  }

  if (!featureId) {
    throw new Error(`Usage: openmates server features ${action} <feature-id>`);
  }

  if (action === "enable") {
    writeOverrides({
      enabled: normalizeFeatureList([...overrides.enabled, featureId]),
      disabled: overrides.disabled.filter((id) => id !== featureId),
    });
    return;
  }

  if (action === "disable") {
    writeOverrides({
      enabled: overrides.enabled.filter((id) => id !== featureId),
      disabled: normalizeFeatureList([...overrides.disabled, featureId]),
    });
    return;
  }

  if (action === "reset") {
    writeOverrides({
      enabled: overrides.enabled.filter((id) => id !== featureId),
      disabled: overrides.disabled.filter((id) => id !== featureId),
    });
    return;
  }

  if (action === "explain") {
    const defaultReason = OFF_BY_DEFAULT_FEATURES.get(featureId);
    const override = overrides.enabled.includes(featureId) ? "enabled" : overrides.disabled.includes(featureId) ? "disabled" : "none";
    const defaultState = defaultReason ? "off" : "on";
    const effective = override === "enabled" ? "enabled" : override === "disabled" ? "disabled" : defaultState === "on" ? "enabled" : "disabled";
    console.log(`Feature: ${featureId}`);
    console.log(`Kind: ${featureKind(featureId)}`);
    console.log(`Default: ${defaultState}${defaultReason ? ` (${defaultReason})` : ""}`);
    console.log(`Override: ${override}`);
    console.log(`Effective after restart: ${effective}`);
    return;
  }

  throw new Error(`Unknown server features command '${action}'. Use list, enable, disable, reset, or explain.`);
}

async function serverAiModelsAdd(flags: Record<string, string | boolean>): Promise<void> {
  const installPath = resolveServerPath(flags);
  const installMode = getInstallMode(installPath);
  const overlayPath = localModelsOverlayPath(installPath, installMode);

  const runtimeInput = typeof flags.runtime === "string"
    ? flags.runtime
    : await promptChoice(
        "Which local runtime should OpenMates use?",
        [
          { value: "ollama", label: "Ollama" },
          { value: "lm-studio", label: "LM Studio" },
          { value: "custom", label: "Custom OpenAI-compatible API" },
        ],
        "ollama",
      );
  const runtimeKey = normalizeRuntimeKey(runtimeInput);
  const runtime = LOCAL_MODEL_RUNTIME_DEFAULTS[runtimeKey];
  const baseUrl = typeof flags["base-url"] === "string"
    ? flags["base-url"]
    : await promptText("OpenAI-compatible base URL", runtime.baseUrl);
  const apiKey = typeof flags["api-key"] === "string"
    ? flags["api-key"]
    : runtimeKey === "custom"
      ? await promptText("API key", runtime.apiKey)
      : runtime.apiKey;

  let availableModels: string[] = [];
  try {
    availableModels = await fetchLocalModelIds(baseUrl, apiKey);
  } catch (error) {
    console.error(`Could not fetch /v1/models: ${error instanceof Error ? error.message : String(error)}`);
  }

  const rawModelId = typeof flags.model === "string"
    ? flags.model
    : availableModels.length
      ? await promptChoice(
          "Which installed model should OpenMates add?",
          [...availableModels.map((id) => ({ value: id, label: id })), { value: "manual", label: "Enter manually" }],
          availableModels[0],
        )
      : await promptText("Local model ID");
  const serverModelId = rawModelId === "manual" ? await promptText("Local model ID") : rawModelId;
  if (!serverModelId) throw new Error("Model ID is required.");

  const inferredCreator = inferCreatorId(serverModelId);
  const creatorInput = typeof flags.creator === "string"
    ? flags.creator
    : await promptChoice(
        "Who created the model?",
        MODEL_CREATOR_OPTIONS.map((option) => ({ value: option.id, label: option.name })),
        inferredCreator,
      );
  const providerId = creatorInput === "custom"
    ? normalizeCreatorId(await promptText("Custom creator/provider ID", "custom_local"))
    : normalizeCreatorId(creatorInput);
  const providerName = providerId === creatorInput ? creatorDisplayName(providerId) : providerId;
  const internalModelId = typeof flags.id === "string" ? sanitizeModelId(flags.id) : `${sanitizeModelId(serverModelId)}-local`;
  const displayName = typeof flags.name === "string" ? flags.name : await promptText("Display name", serverModelId);
  const supportsImages = boolFromFlag(flags.images ?? flags.image ?? flags.vision, false);
  const supportsTools = boolFromFlag(flags.tools ?? flags["tool-use"], false);
  const contextWindowInput = typeof flags["context-window"] === "string"
    ? flags["context-window"]
    : await promptText("Context window tokens", "32768");
  const contextWindow = Number.parseInt(contextWindowInput, 10) || 32768;

  if (flags["skip-test"] !== true) {
    console.error(`Testing ${runtime.label} model '${serverModelId}'...`);
    const testOutput = await testLocalModel(baseUrl, apiKey, serverModelId);
    if (!testOutput) throw new Error("Local model test returned no content. Not saving model.");
    console.error(`Test response: ${testOutput}`);
  }

  const model = {
    id: internalModelId,
    name: displayName,
    description: `${displayName} served locally through ${runtime.label}.`,
    country_origin: "local",
    for_app_skill: "ai.ask",
    allow_auto_select: false,
    local: true,
    self_hosted: true,
    input_types: supportsImages ? ["text", "image"] : ["text"],
    output_types: ["text"],
    default_server: runtime.serverId,
    servers: [
      {
        id: runtime.serverId,
        name: runtime.label,
        model_id: serverModelId,
        region: "local",
        base_url: baseUrl.replace(/\/+$/, ""),
        api_key: apiKey,
        supports_tools: supportsTools,
      },
    ],
    pricing: { fixed: { credits: 0 } },
    costs: {
      input_per_million_token: { price: 0, currency: "USD", max_context: contextWindow },
      output_per_million_token: { price: 0, currency: "USD", max_context: contextWindow },
    },
    features: {
      streaming: true,
      tool_use: supportsTools,
      max_context: contextWindow,
    },
  };

  upsertLocalModel(overlayPath, providerId, providerName, model);
  if (installMode === "image") ensureImageRuntimeConfig(installPath);

  if (flags.json === true) {
    printJson({ command: "server ai models add", status: "success", model: `${providerId}/${internalModelId}`, overlayPath });
  } else {
    console.log(`Added local model: ${providerId}/${internalModelId}`);
    console.log(`Updated ${overlayPath}`);
    console.log("Restart the server for model changes to take effect: openmates server restart");
    console.log("Self-hosted local models charge 0 credits; token usage may still be recorded in usage history.");
  }
}

async function serverAiModelsList(flags: Record<string, string | boolean>): Promise<void> {
  const installPath = resolveServerPath(flags);
  const overlayPath = localModelsOverlayPath(installPath);
  const overlay = readLocalModelOverlay(overlayPath);
  const models = localModelsFromOverlay(overlay).map(({ providerId, model }) => ({
    id: `${providerId}/${String(model.id ?? "")}`,
    name: model.name ?? model.id,
    server: Array.isArray(model.servers) ? (model.servers[0] as Record<string, unknown> | undefined)?.id : undefined,
    serverModelId: Array.isArray(model.servers) ? (model.servers[0] as Record<string, unknown> | undefined)?.model_id : undefined,
  }));
  if (flags.json === true) {
    printJson({ overlayPath, models });
    return;
  }
  if (!models.length) {
    console.log("No local AI models configured. Add one with: openmates server ai models add");
    return;
  }
  console.log("Local AI models:");
  for (const model of models) {
    console.log(`  ${model.id} (${model.server}: ${model.serverModelId})`);
  }
}

async function serverAiModelsTest(rest: string[], flags: Record<string, string | boolean>): Promise<void> {
  const installPath = resolveServerPath(flags);
  const overlayPath = localModelsOverlayPath(installPath);
  const fullModelId = rest[0];
  if (!fullModelId || !fullModelId.includes("/")) throw new Error("Usage: openmates server ai models test <provider/model-id>");
  const [providerId, modelId] = fullModelId.split("/", 2);
  const overlay = readLocalModelOverlay(overlayPath);
  const provider = overlay.providers.find((item) => item.provider_id === providerId);
  const model = provider?.models.find((item) => item.id === modelId);
  const server = Array.isArray(model?.servers) ? model.servers[0] as Record<string, unknown> | undefined : undefined;
  if (!server) throw new Error(`Local model not found in ${overlayPath}: ${fullModelId}`);
  const baseUrl = String(server.base_url ?? "");
  const apiKey = String(server.api_key ?? "local");
  const serverModelId = String(server.model_id ?? "");
  const output = await testLocalModel(baseUrl, apiKey, serverModelId);
  if (flags.json === true) {
    printJson({ model: fullModelId, status: "success", output });
  } else {
    console.log(`Model test succeeded: ${fullModelId}`);
    console.log(`Response: ${output}`);
  }
}

async function serverAiModelsRemove(rest: string[], flags: Record<string, string | boolean>): Promise<void> {
  const installPath = resolveServerPath(flags);
  const overlayPath = localModelsOverlayPath(installPath);
  const fullModelId = rest[0];
  if (!fullModelId) throw new Error("Usage: openmates server ai models remove <provider/model-id>");
  const removed = removeLocalModel(overlayPath, fullModelId);
  if (flags.json === true) {
    printJson({ command: "server ai models remove", status: removed ? "success" : "not_found", model: fullModelId });
  } else if (removed) {
    console.log(`Removed local model: ${fullModelId}`);
    console.log("Restart the server for model changes to take effect: openmates server restart");
  } else {
    console.log(`Local model not found: ${fullModelId}`);
  }
}

async function serverAi(rest: string[], flags: Record<string, string | boolean>): Promise<void> {
  const area = rest[0];
  const action = rest[1] ?? "list";
  const args = rest.slice(2);
  if (area !== "models") throw new Error("Usage: openmates server ai models <add|list|test|remove>");
  switch (action) {
    case "add":    return serverAiModelsAdd(flags);
    case "list":   return serverAiModelsList(flags);
    case "test":   return serverAiModelsTest(args, flags);
    case "remove": return serverAiModelsRemove(args, flags);
    default:
      throw new Error(`Unknown server ai models command '${action}'. Use add, list, test, or remove.`);
  }
}

async function serverBackup(rest: string[], flags: Record<string, string | boolean>): Promise<void> {
  const action = rest[0];
  const installPath = resolveServerPath(flags);
  const config = loadConfigForInstallPath(installPath);
  const role = getServerRole(flags, config);

  if (action === "list") {
    const dir = roleBackupDir(installPath, role);
    const files = existsSync(dir) ? readdirSync(dir).filter((item) => item.endsWith(".tar.gz")).sort() : [];
    if (flags.json === true) {
      printJson({ role, backupDir: dir, files });
      return;
    }
    console.log(`Backups for ${role}:`);
    if (!files.length) {
      console.log("  none");
      return;
    }
    for (const file of files) console.log(`  ${join(dir, file)}`);
    return;
  }

  requireDocker();
  const output = typeof flags.output === "string" ? flags.output : undefined;
  const archivePath = createServerBackup(installPath, role, {
    output,
    includeObservability: flags["include-observability"] === true,
  });

  if (flags.json === true) {
    printJson({ command: "backup", status: "success", role, file: archivePath });
  } else {
    console.log(`Backup created: ${archivePath}`);
  }
}

async function serverRestore(flags: Record<string, string | boolean>): Promise<void> {
  requireDocker();
  const installPath = resolveServerPath(flags);
  const config = loadConfigForInstallPath(installPath);
  const role = getServerRole(flags, config);
  const file = typeof flags.file === "string" ? flags.file : "";
  if (!file) throw new Error("Usage: openmates server restore --file <backup.tar.gz> [--role core|upload|preview] [--yes]");
  const restorePlan = planRestore({ role, file, yes: flags.yes === true });

  if (restorePlan.requiresConfirmation) {
    console.error(`\nWARNING: This will restore ${role} data from ${file}.`);
    const confirmed = await confirmDestructive("RESTORE OPENMATES BACKUP");
    if (!confirmed) {
      console.error("Restore cancelled.");
      return;
    }
  }

  // Reject invalid or unsafe archives before touching running services. The
  // restore path validates again after shutdown in case the archive changes.
  withValidatedServerBackup(installPath, role, file, () => {}, tmpdir());
  const withOverrides = config?.composeProfile === "full";
  const installMode = getInstallMode(installPath, config);
  const stopArgs = [...composeArgs(installPath, withOverrides, installMode, role), "stop", ...restoreStopServices(installPath, withOverrides, installMode, role)];
  let code = await runInteractive("docker", stopArgs, installPath);
  if (code !== 0) process.exit(code);
  restoreServerBackup(installPath, role, file);
  ensureRuntimeMetricsDirectory(installPath);
  code = await runInteractive("docker", [...composeArgs(installPath, withOverrides, installMode, role), "up", "-d"], installPath);
  if (code !== 0) process.exit(code);
  await waitForServerHealth(installPath, role);

  if (flags.json === true) {
    printJson({ command: "restore", status: "success", role, file });
  } else {
    console.log(`Restore completed for ${role}.`);
  }
}

async function serverUninstall(flags: Record<string, string | boolean>): Promise<void> {
  requireDocker();
  const installPath = resolveServerPath(flags);
  ensureGitWorkDirEnv(installPath);
  const config = loadConfigForInstallPath(installPath);
  const role = getServerRole(flags, config);
  const withOverrides = config?.composeProfile === "full";
  const keepData = flags["keep-data"] === true;

  console.error("\nWARNING: This will completely uninstall OpenMates:");
  console.error(`  - Stop and remove all containers`);
  if (!keepData) {
    console.error("  - Delete all Docker volumes (database, cache — ALL DATA LOST)");
  } else {
    console.error("  - Docker volumes will be PRESERVED (data can be restored)");
  }
  console.error("  - Remove locally built Docker images");
  console.error("  - Remove the Docker network");
  console.error(`  - Delete the installation directory: ${installPath}`);
  console.error("");

  if (flags.yes !== true) {
    const confirmed = await confirmDestructive("UNINSTALL OPENMATES");
    if (!confirmed) {
      console.error("Uninstall cancelled.");
      return;
    }
  }

  console.error("Uninstalling OpenMates...");

  // 1. Stop containers and remove volumes + locally built images
  const downArgs = [...composeArgs(installPath, withOverrides, getInstallMode(installPath, config), role), "down", "--rmi", "local"];
  if (!keepData) {
    downArgs.push("-v");
  }
  await runInteractive("docker", downArgs, installPath);

  // 2. Remove Docker network
  try {
    exec("docker network rm openmates", installPath);
    console.error("  Removed Docker network: openmates");
  } catch {
    // Network may not exist or may be in use
  }

  // 3. Remove installation directory
  try {
    rmSync(installPath, { recursive: true, force: true });
    console.error(`  Removed installation directory: ${installPath}`);
  } catch (e: unknown) {
    console.error(`  Could not remove ${installPath}: ${e instanceof Error ? e.message : e}`);
  }

  // 4. Remove server config
  removeServerConfig();

  if (flags.json === true) {
    printJson({ command: "uninstall", status: "success", path: installPath, keepData });
  } else {
    console.log("\nOpenMates has been uninstalled.");
    if (keepData) {
      console.log("Docker volumes were preserved. Reinstall and restart to recover data.");
    }
  }
}

async function serverPreflight(flags: Record<string, string | boolean>): Promise<void> {
  const installPath = resolveServerPath(flags);
  const config = loadConfigForInstallPath(installPath);
  const role = getServerRole(flags, config);
  const services = hasServiceFilter(flags) ? selectedComposeServices(role, flags) : [];
  const missingEnvKeys = missingRequiredEnvKeys(installPath, role);
  const secretPreflight = runtimeSecretPreflight(installPath, role);
  const missingOrUnverifiedSecrets = [
    ...missingEnvKeys,
    ...secretPreflight.importedVaultMissing,
    ...secretPreflight.importedVaultUnavailable,
  ];
  const updatePlan = planServerUpdate({ role, selectedServices: services, dryRun: true, continuous: true, missingRequiredSecrets: missingOrUnverifiedSecrets });
  const runtimePlan = planServerRuntime({
    role,
    profile: getCoreProfile(flags, config),
    withAlerts: flags["with-alerts"] === true,
  });
  const caddyPlan = planCaddyCommand({ role, action: "status" });
  const preflight = {
    command: "preflight",
    status: updatePlan.blocked ? "blocked" : "ok",
    path: installPath,
    role,
    profile: runtimePlan.profile,
    services: hasServiceFilter(flags) ? services : "all",
    healthChecks: runtimePlan.healthChecks,
    updateSteps: updatePlan.steps,
    backupName: updatePlan.backupName,
    missingRequiredEnvKeys: missingEnvKeys,
    secretPreflight,
    missingOrUnverifiedSecrets,
    blocked: updatePlan.blocked,
    blockReason: updatePlan.blockReason,
    caddy: caddyPlan,
  };

  if (flags.json === true) {
    printJson(preflight);
    return;
  }

  console.log("Server preflight plan:");
  console.log(`  Role:          ${role}`);
  console.log(`  Profile:       ${runtimePlan.profile ?? "n/a"}`);
  console.log(`  Services:      ${hasServiceFilter(flags) ? services.join(", ") : "all"}`);
  console.log(`  Backup:        ${updatePlan.backupName ?? "none"}`);
  console.log(`  Env preflight: ${missingEnvKeys.length ? `missing ${missingEnvKeys.join(", ")}` : "ok"}`);
  console.log(`  Vault secrets: ${formatSecretPreflight(secretPreflight)}`);
  if (updatePlan.blocked) console.log(`  Blocked:       ${updatePlan.blockReason}`);
  console.log(`  Health checks: ${runtimePlan.healthChecks.join(", ")}`);
  console.log(`  Caddy steps:   ${caddyPlan.steps.join(" -> ")}`);
}

async function serverCaddy(rest: string[], flags: Record<string, string | boolean>): Promise<void> {
  if (rest[0] === "update") {
    if (flags["caddy-config"] === true) throw new Error("Provide --caddy-config <file>.");
    const installPath = resolveServerPath(flags);
    const config = loadConfigForInstallPath(installPath);
    const role = getServerRole(flags, config);
    try {
      const plan = caddyUpdatePlan(installPath, role, config, flags);
      const retryCommand = caddyUpdateRetryCommand({ installPath, role, configPath: plan.configPath, profile: plan.profile });
      if (flags["dry-run"] === true) {
        if (flags.json === true) printJson({ command: "caddy update", ...plan, role, path: installPath, mode: getInstallMode(installPath, config), retryCommand });
        else console.log(`Caddy release update: ${plan.status}\nRun: ${retryCommand}`);
        return;
      }
      const result = plan.status === "not_installed" ? { status: "not_installed" } : await updateCaddyOnly(installPath, role, config, { ...flags, "caddy-config": plan.configPath });
      if (flags.json === true) printJson({ command: "caddy update", role, ...result });
      else console.log(`Caddy: ${result.status}`);
    } catch (error) {
      const reason = error instanceof Error && /^caddy_[a-z_:-]+$/.test(error.message) ? error.message : "caddy_update_failed";
      const retryCommand = caddyRetryForInstall(installPath, role, flags, reason);
      throw new Error(`Caddy update failed (${reason}).\nAfter resolving the reported problem, run:\n${retryCommand}`);
    }
    return;
  }
  const action = (rest[0] ?? "status") as CaddyAction;
  if (!["check", "status", "diff", "apply"].includes(action)) {
    throw new Error("Usage: openmates server caddy check|status|diff|apply|update [--role core|upload|preview]");
  }
  const config = loadServerConfig();
  const role = getServerRole(flags, config);
  const appliedPath = typeof flags.config === "string" ? flags.config : "/etc/caddy/Caddyfile";
  const templatePath = packagedCaddyTemplatePath(role);
  if (!existsSync(templatePath)) throw new Error(`Packaged Caddy template not found: ${templatePath}`);
  const plan = planCaddyCommand({ role, action, appliedPath });
  const payload = {
    ...plan,
    templatePath,
    templateHash: fileHash(templatePath),
    appliedHash: fileHash(appliedPath),
    drift: fileHash(templatePath) !== fileHash(appliedPath),
  };

  if (flags.json === true) {
    printJson(payload);
    return;
  }

  if (action === "check") {
    execSync(`caddy validate --config ${shellQuote(templatePath)}`, { stdio: "inherit" });
    console.log(`Caddy template is valid for ${role}.`);
    return;
  }

  if (action === "diff") {
    if (!existsSync(appliedPath)) throw new Error(`Applied Caddyfile not found: ${appliedPath}`);
    try {
      execSync(`diff -u ${shellQuote(appliedPath)} ${shellQuote(templatePath)}`, { stdio: "inherit" });
    } catch (error) {
      const status = typeof error === "object" && error !== null && "status" in error ? (error as { status?: number }).status : undefined;
      if (status !== 1) throw error;
    }
    return;
  }

  if (action === "apply") {
    execSync(`caddy validate --config ${shellQuote(templatePath)}`, { stdio: "inherit" });
    if (flags.yes !== true) {
      console.error(`\nWARNING: This will replace ${appliedPath} with the packaged ${role} Caddyfile.`);
      const confirmed = await confirmDestructive("APPLY CADDYFILE");
      if (!confirmed) {
        console.error("Caddy apply cancelled.");
        return;
      }
    }
    const backupPath = `${appliedPath}.openmates-backup-${nowStamp()}`;
    const hadExistingCaddyfile = existsSync(appliedPath);
    try {
      mkdirSync(dirname(appliedPath), { recursive: true });
      if (hadExistingCaddyfile) copyFileSync(appliedPath, backupPath);
      copyFileSync(templatePath, appliedPath);
      execSync("systemctl reload caddy", { stdio: "inherit" });
    } catch (error) {
      throw new Error(`Could not apply Caddyfile. Run with sudo or use --config <writable path>. ${error instanceof Error ? error.message : String(error)}`);
    }
    console.log(`Applied Caddyfile for ${role}. ${hadExistingCaddyfile ? `Backup: ${backupPath}` : "No previous Caddyfile existed."}`);
    return;
  }

  console.log(`Caddy ${action} plan:`);
  console.log(`  Role:          ${payload.role}`);
  console.log(`  Template:      ${payload.templatePath}`);
  console.log(`  Applied:       ${payload.appliedPath}`);
  console.log(`  Template hash: ${payload.templateHash ?? "missing"}`);
  console.log(`  Applied hash:  ${payload.appliedHash ?? "missing"}`);
  console.log(`  Drift:         ${payload.drift ? "yes" : "no"}`);
  console.log(`  Steps:         ${payload.steps.join(" -> ")}`);
}

async function serverEnv(rest: string[], flags: Record<string, string | boolean>): Promise<void> {
  const action = rest[0] ?? "list";
  const installPath = resolveServerPath(flags);
  const content = readEnvContent(installPath);
  const entries = parseEnvEntries(content);

  if (action === "list") {
    const category = typeof flags.category === "string" ? flags.category : rest[1];
    const filtered = category ? entries.filter((entry) => entry.category === category) : entries;
    if (flags.json === true) {
      printJson({ command: "env list", path: envPathForInstall(installPath), entries: filtered });
      return;
    }
    let lastCategory = "";
    for (const entry of filtered) {
      if (entry.category !== lastCategory) {
        lastCategory = entry.category;
        console.log(`\n${entry.category}:`);
      }
      console.log(`  ${entry.key}=${entry.redactedValue}`);
    }
    if (!filtered.length) console.log("No env entries found.");
    return;
  }

  if (action === "get") {
    const key = assertEnvKey(rest[1]);
    const entry = entries.find((item) => item.key === key);
    if (flags.json === true) {
      printJson({ command: "env get", key, value: entry ? redactEnvValue(key, entry.value) : null });
      return;
    }
    console.log(`${key}=${entry ? redactEnvValue(key, entry.value) : ""}`);
    return;
  }

  if (action === "set") {
    const key = assertEnvKey(rest[1]);
    const value = typeof flags.value === "string" ? flags.value : await promptHiddenValue(`Value for ${key}: `);
    writeEnvContent(installPath, upsertEnvValue(content, key, value));
    if (flags.json === true) {
      printJson({ command: "env set", status: "success", key });
      return;
    }
    console.log(`Updated ${key} in ${envPathForInstall(installPath)}.`);
    return;
  }

  if (action === "unset") {
    const key = assertEnvKey(rest[1]);
    if (flags.yes !== true) {
      const confirmed = await confirmDestructive(`UNSET ${key}`);
      if (!confirmed) {
        console.error("Env unset cancelled.");
        return;
      }
    }
    writeEnvContent(installPath, unsetEnvValue(content, key));
    if (flags.json === true) {
      printJson({ command: "env unset", status: "success", key });
      return;
    }
    console.log(`Removed ${key} from ${envPathForInstall(installPath)}.`);
    return;
  }

  if (action === "check" || action === "doctor") {
    const config = loadConfigForInstallPath(installPath);
    const role = getServerRole(flags, config);
    const missingRuntime = missingRequiredEnvKeys(installPath, role);
    const secretPreflight = runtimeSecretPreflight(installPath, role);
    const missingSecrets = [...secretPreflight.emptySecretEnvKeys, ...secretPreflight.importedVaultMissing, ...secretPreflight.importedVaultUnavailable];
    if (flags.json === true) {
      printJson({ command: `env ${action}`, role, missingRuntime, secretPreflight, ok: missingRuntime.length === 0 && missingSecrets.length === 0 });
      return;
    }
    console.log(`Env file: ${envPathForInstall(installPath)}`);
    console.log(`Runtime required keys: ${missingRuntime.length ? `missing ${missingRuntime.join(", ")}` : "ok"}`);
    console.log(`Provider/Vault secrets: ${formatSecretPreflight(secretPreflight)}`);
    if (action === "doctor" && missingSecrets.length) {
      console.log("\nAdd missing provider secrets with:");
      for (const key of missingSecrets) console.log(`  openmates server env set ${key}`);
    }
    return;
  }

  if (action === "edit") {
    const category = rest[1];
    if (category) {
      const keys = entries.filter((entry) => entry.category === category).map((entry) => entry.key);
      console.error(keys.length ? `Focused ${category} keys: ${keys.join(", ")}` : `No existing ${category} keys found; opening canonical .env.`);
    }
    const editor = process.env.EDITOR || "nano";
    const code = await editServerEnvFile(envPathForInstall(installPath), (temporary) => runInteractive(editor, [temporary], installPath));
    if (code !== 0) process.exit(code);
    return;
  }

  throw new Error("Usage: openmates server env list|get|set|unset|check|doctor|edit [key|category]");
}

